const TypeLayoutResolver = codegen_abi.TypeLayoutResolver;
const ResolvedSumDetail = codegen_abi.ResolvedSumDetail;
const AbiClassifier = codegen_abi.AbiClassifier;
const AbiFnRecipe = codegen_abi.AbiFnRecipe;
