/// Monotonic atomic counter ensuring concurrent in-process LLVM driver runs use distinct scratch dirs.
var next_llvm_scratch_seq = std.atomic.Value(u32).init(1);

// -------------------------------------- INTERNALS --------------------------------------

// --------------- Target, Type & Layout Queries ----------------

/// Returns the LLVM pointer-sized integer type (`"i32"` on `wasm32`, `"i64"` on 64-bit targets).
fn ptrIntType(emitter: *const LlvmModuleEmitter) []const u8 {
    return if (emitter.cfg.target.isWasm()) "i32" else "i64";
}

/// Returns the function attribute suffix (`"nounwind"` on `wasm32`, `"nounwind uwtable(sync)"` on native).
fn fnUnwindAttrs(emitter: *const LlvmModuleEmitter) []const u8 {
    return if (emitter.cfg.target.isWasm()) "nounwind" else "nounwind uwtable(sync)";
}

/// Returns `true` when `raw_ty` resolves to a sized zero-byte type (`size_bytes == 0` and not `opaque`).
fn isZeroSizedType(emitter: *LlvmModuleEmitter, raw_ty: TypeId) !bool {
    const unwrapped = emitter.input.pool.unwrapUnderlyingType(raw_ty);
    if (unwrapped == .opaque_ty) return false;
    if (unwrapped.isError() or unwrapped == .unit_ty or unwrapped == .never_ty) return true;
    const resolved = try emitter.resolver.resolveType(unwrapped);
    return resolved.size_bytes == 0 and !resolved.reprFlags().is_unsized;
}

/// Returns `true` when `ty` is a built-in runtime type lowered directly without a `%_cx_ty_<id>` declaration.
fn isBuiltInRuntimeTypeLlvm(pool: *const type_system.InternPool, ty: TypeId) bool {
    return ty == .source_loc_ty or
        ty == .fmt_spec_ty or
        ty == .fmt_args_ty or
        ty == .bencher_ty or
        ty == .task_group_base_ty or
        ty == .task_handle_base_ty or
        pool.isTaskGroupType(ty) or
        pool.isTaskHandleType(ty);
}

/// Resolves `(byte_offset, field_ty, align_bytes)` inside static `SourceLocData` for field ordinal `fld_ord`.
fn resolveSourceLocFieldLayout(
    ptr_bytes: u32,
    fld_ord: u32,
) struct { byte_offset: u64, field_ty: TypeId, align_bytes: u32 } {
    return switch (fld_ord) {
        0 => .{ .byte_offset = 0, .field_ty = .str_ty, .align_bytes = ptr_bytes },
        1 => .{ .byte_offset = 2 * @as(u64, ptr_bytes), .field_ty = .str_ty, .align_bytes = ptr_bytes },
        2 => .{ .byte_offset = 4 * @as(u64, ptr_bytes), .field_ty = .u32_ty, .align_bytes = 4 },
        else => .{ .byte_offset = 4 * @as(u64, ptr_bytes) + 4, .field_ty = .u32_ty, .align_bytes = 4 },
    };
}

/// Resolves scalar integer bit-width and signedness for `raw_ty`, or `null` if non-integer.
fn resolveIntegerInfo(emitter: *const LlvmModuleEmitter, raw_ty: TypeId) ?IntScalarInfo {
    var ty = emitter.input.pool.unwrapUnderlyingType(raw_ty);
    if (!ty.isPrimitiveOrSentinel()) {
        const cur_node = emitter.input.pool.getNode(ty);
        if (cur_node.tag == .bit_field_ty) {
            ty = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(cur_node.lhs));
        } else if (cur_node.tag == .enum_ty) {
            if (emitter.input.pool.getEnumBackingIntType(ty)) |backing_ty| {
                ty = emitter.input.pool.unwrapUnderlyingType(backing_ty);
            }
        }
    }
    const ptr_bits: u16 = @as(u16, emitter.cfg.target.ptrBytes()) * 8;
    return switch (ty) {
        .i8_ty => .{ .bits = 8, .is_signed = true },
        .u8_ty => .{ .bits = 8, .is_signed = false },
        .i16_ty => .{ .bits = 16, .is_signed = true },
        .u16_ty => .{ .bits = 16, .is_signed = false },
        .i32_ty => .{ .bits = 32, .is_signed = true },
        .u32_ty, .char_ty => .{ .bits = 32, .is_signed = false },
        .i64_ty, .untyped_int_ty => .{ .bits = 64, .is_signed = true },
        .u64_ty => .{ .bits = 64, .is_signed = false },
        .i128_ty => .{ .bits = 128, .is_signed = true },
        .u128_ty => .{ .bits = 128, .is_signed = false },
        .isize_ty => .{ .bits = ptr_bits, .is_signed = true },
        .usize_ty => .{ .bits = ptr_bits, .is_signed = false },
        else => null,
    };
}

/// Unwraps transparent `Result[T, never]`, `bit_field` backing types, and type aliases/newtypes.
fn unwrapTransparentType(emitter: *LlvmModuleEmitter, raw_ty: TypeId) !TypeId {
    var cur_ty = emitter.input.pool.unwrapUnderlyingType(raw_ty);
    while (!cur_ty.isPrimitiveOrSentinel()) {
        const cur_node = emitter.input.pool.getNode(cur_ty);
        if (cur_node.tag == .bit_field_ty) {
            cur_ty = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(cur_node.lhs));
            continue;
        }
        if (cur_node.tag == .result_ty) {
            if (try emitter.resolver.getSumDetail(cur_ty)) |detail| {
                if (detail.repr == .transparent_ok) {
                    cur_ty = emitter.input.pool.unwrapUnderlyingType(detail.payload_ty);
                    continue;
                }
            }
        }
        break;
    }
    return cur_ty;
}

/// Returns `true` when `ty` requires a named `%_cx_ty_<id>` composite struct declaration.
fn isNamedCompositeType(emitter: *LlvmModuleEmitter, raw_ty: TypeId) !bool {
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (try isZeroSizedType(emitter, ty)) return false;
    if (ty.isPrimitiveOrSentinel() or isBuiltInRuntimeTypeLlvm(emitter.input.pool, ty)) return false;
    const node = emitter.input.pool.getNode(ty);
    if (node.tag == .enum_ty and emitter.input.pool.getEnumBackingIntType(ty) != null) return false;
    return switch (node.tag) {
        .struct_ty,
        .tuple_ty,
        .soa_array_ty,
        .soa_vec_ty,
        .union_ty,
        .enum_ty,
        .optional_ty,
        .result_ty,
        .future_ty,
        => true,
        else => false,
    };
}

/// Formats the LLVM slice value struct (`{ ptr, i64 }` vs 4-word `{ ptr, i64, i64, i64 }` for `#soa [S]`).
fn formatSliceLlvmStructType(emitter: *LlvmModuleEmitter, raw_ty: TypeId) ![]u8 {
    const ptr_int = ptrIntType(emitter);
    if (emitter.input.pool.isSoaSliceOrRefType(raw_ty)) {
        return std.fmt.allocPrint(
            emitter.allocator,
            "{{ ptr, {s}, {s}, {s} }}",
            .{ ptr_int, ptr_int, ptr_int },
        );
    }
    return std.fmt.allocPrint(emitter.allocator, "{{ ptr, {s} }}", .{ptr_int});
}

/// Returns the pointer-sized word count (`4` for `#soa [S]` / `&#soa [S]`, `2` for `[T]` / `&[T]` / `str`).
inline fn sliceDescriptorWordCount(pool: *const type_system.InternPool, raw_ty: TypeId) u32 {
    return if (pool.isSoaSliceOrRefType(raw_ty)) 4 else 2;
}

/// Formats the canonical LLVM SSA value type for `raw_ty` (caller owns returned slice).
fn formatLlvmValueType(emitter: *LlvmModuleEmitter, raw_ty: TypeId) ![]u8 {
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (ty == .opaque_ty) return emitter.allocator.dupe(u8, "i8");
    if (try isZeroSizedType(emitter, ty)) {
        return emitter.allocator.dupe(u8, "void");
    }
    if (ty == .bool_ty) return emitter.allocator.dupe(u8, "i1");
    if (ty == .f32_ty) return emitter.allocator.dupe(u8, "float");
    if (ty == .f64_ty or ty == .untyped_float_ty) return emitter.allocator.dupe(u8, "double");
    if (ty == .str_ty or ty == .bencher_ty) {
        return std.fmt.allocPrint(emitter.allocator, "{{ ptr, {s} }}", .{ptrIntType(emitter)});
    }
    if (ty == .source_loc_ty or
        ty == .task_group_base_ty or
        ty == .task_handle_base_ty or
        emitter.input.pool.isTaskGroupType(ty) or
        emitter.input.pool.isTaskHandleType(ty))
    {
        return emitter.allocator.dupe(u8, "ptr");
    }
    if (ty == .fmt_spec_ty) {
        return emitter.allocator.dupe(u8, "{ i32, i16, i16 }");
    }
    if (ty == .fmt_args_ty) {
        return std.fmt.allocPrint(
            emitter.allocator,
            "{{ ptr, {s}, ptr, {s} }}",
            .{ ptrIntType(emitter), ptrIntType(emitter) },
        );
    }
    if (resolveIntegerInfo(emitter, ty)) |int_info| {
        return std.fmt.allocPrint(emitter.allocator, "i{d}", .{int_info.bits});
    }
    if (ty.isPrimitiveOrSentinel()) return emitter.allocator.dupe(u8, "i8");

    const node = emitter.input.pool.getNode(ty);
    return switch (node.tag) {
        .ref_ty, .mut_ref_ty => if (emitter.input.pool.isSliceRefType(ty))
            formatSliceLlvmStructType(emitter, ty)
        else
            emitter.allocator.dupe(u8, "ptr"),
        .raw_ptr_ty, .fn_ty => emitter.allocator.dupe(u8, "ptr"),
        .closure_ty => emitter.allocator.dupe(
            u8,
            if (codegen_abi.isThreeWordClosureType(emitter.input.pool, ty))
                "{ ptr, ptr, ptr }"
            else
                "{ ptr, ptr }",
        ),
        .slice_ty, .soa_slice_ty => formatSliceLlvmStructType(emitter, ty),
        .array_ty => {
            const elem_ty = TypeId.fromInt(node.lhs);
            const elem_count: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            const elem_mem = try formatLlvmMemoryType(emitter, elem_ty);
            defer emitter.allocator.free(elem_mem);
            return std.fmt.allocPrint(emitter.allocator, "[{d} x {s}]", .{ elem_count, elem_mem });
        },
        else => std.fmt.allocPrint(emitter.allocator, "%_cx_ty_{d}", .{ty.toU32()}),
    };
}

/// Formats the canonical LLVM in-memory storage type (`i8` for `bool`, `[0 x i8]` for ZST).
fn formatLlvmMemoryType(emitter: *LlvmModuleEmitter, raw_ty: TypeId) anyerror![]u8 {
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (try isZeroSizedType(emitter, ty)) {
        return emitter.allocator.dupe(u8, "[0 x i8]");
    }
    if (ty == .bool_ty) return emitter.allocator.dupe(u8, "i8");
    return formatLlvmValueType(emitter, ty);
}

/// Resolves the zero literal (`0`, `false`, `0.0`, `null`, `zeroinitializer`) for an LLVM type string.
fn resolveZeroLiteralForLlvmType(llvm_ty: []const u8) []const u8 {
    if (std.mem.eql(u8, llvm_ty, "i1")) return "false";
    if (std.mem.eql(u8, llvm_ty, "ptr")) return "null";
    if (std.mem.eql(u8, llvm_ty, "float") or std.mem.eql(u8, llvm_ty, "double")) return "0.0";
    if (llvm_ty.len >= 2 and llvm_ty[0] == 'i' and std.ascii.isDigit(llvm_ty[1])) return "0";
    return "zeroinitializer";
}

/// Computes the alignment guaranteed for `byte_offset` relative to a base pointer (`<= natural_align`).
fn effectiveOffsetAlign(byte_offset: u64, natural_align: u32) u32 {
    const nat = @max(natural_align, 1);
    if (byte_offset == 0) return nat;
    const low_bit_u64: u64 = byte_offset & (~byte_offset +% 1);
    const low_bit: u32 = if (low_bit_u64 > @as(u64, nat)) nat else @intCast(low_bit_u64);
    return @max(@min(nat, low_bit), 1);
}

/// Recursively registers composite types reachable from `raw_ty` in deterministic topological order.
fn collectCompositeType(emitter: *LlvmModuleEmitter, raw_ty: TypeId, depth: u32) anyerror!void {
    if (depth > MAX_COMPOSITE_COLLECT_DEPTH) return;
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (try isZeroSizedType(emitter, ty)) return;
    if (ty.isPrimitiveOrSentinel() or isBuiltInRuntimeTypeLlvm(emitter.input.pool, ty)) return;

    const node = emitter.input.pool.getNode(ty);
    if (node.tag == .enum_ty and emitter.input.pool.getEnumBackingIntType(ty) != null) return;
    switch (node.tag) {
        .ref_ty, .mut_ref_ty, .raw_ptr_ty, .slice_ty, .soa_slice_ty, .fn_ty, .closure_ty => return,
        .array_ty => {
            try collectCompositeType(emitter, TypeId.fromInt(node.lhs), depth + 1);
            return;
        },
        .struct_ty, .tuple_ty => {
            if (emitter.composite_set.contains(ty.toU32())) return;
            try emitter.composite_set.put(emitter.allocator, ty.toU32(), {});
            const lay = try emitter.resolver.resolveType(ty);
            var fld_i: u32 = 0;
            while (fld_i < lay.aux_len) : (fld_i += 1) {
                const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                if (fld.size_bytes > 0) {
                    try collectCompositeType(emitter, fld.field_ty, depth + 1);
                }
            }
            try emitter.ordered_composites.append(emitter.allocator, ty);
        },
        .soa_array_ty, .soa_vec_ty, .union_ty, .enum_ty, .optional_ty, .result_ty, .future_ty => {
            if (emitter.composite_set.contains(ty.toU32())) return;
            try emitter.composite_set.put(emitter.allocator, ty.toU32(), {});
            if (node.tag == .soa_array_ty or node.tag == .soa_vec_ty) {
                if (node.tag == .soa_vec_ty) emitter.has_soa_vec = true;
                try collectCompositeType(emitter, TypeId.fromInt(node.lhs), depth + 1);
                const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
                const elem_lay = try emitter.resolver.resolveType(elem_struct);
                var fld_i: u32 = 0;
                while (fld_i < elem_lay.aux_len) : (fld_i += 1) {
                    const fld = emitter.resolver.fields_by_decl.items[elem_lay.aux_start + fld_i];
                    if (fld.size_bytes > 0) try collectCompositeType(emitter, fld.field_ty, depth + 1);
                }
            } else if (node.tag == .optional_ty) {
                try collectCompositeType(emitter, TypeId.fromInt(node.lhs), depth + 1);
            } else if (node.tag == .future_ty) {
                try collectCompositeType(emitter, TypeId.fromInt(node.lhs), depth + 1);
                if (emitter.has_async_ops) {
                    try registerDropTypeRecursive(emitter, ty, depth + 1);
                }
            } else if (node.tag == .result_ty) {
                try collectCompositeType(emitter, TypeId.fromInt(node.lhs), depth + 1);
                try collectCompositeType(emitter, TypeId.fromInt(node.rhs), depth + 1);
            } else if (node.tag == .enum_ty or node.tag == .union_ty) {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (!sym_idx.isNone() and sym_idx.asInt() < emitter.input.sym_table.symbols.items.len) {
                    const sym_rec = emitter.input.sym_table.getSymbol(sym_idx).*;
                    if (!sym_rec.target_scope.isNone()) {
                        const subst = type_system.NominalTypeSubst.init(
                            emitter.input.pool,
                            emitter.input.sym_table,
                            ty,
                        );
                        for (emitter.input.sym_table.getScopeMembers(sym_rec.target_scope)) |mem_idx| {
                            const mem_sym = emitter.input.sym_table.getSymbol(mem_idx).*;
                            if ((mem_sym.kind == .enum_variant_sym or mem_sym.kind == .field_sym) and
                                !mem_sym.type_id.isNone())
                            {
                                try collectCompositeType(emitter, subst.resolve(mem_sym.type_id), depth + 1);
                            }
                        }
                    }
                }
            }
            try emitter.ordered_composites.append(emitter.allocator, ty);
        },
        else => {},
    }
}

/// Emits deterministic `%_cx_ty_<id> = type <{ … }>` declarations matching `TypeLayoutResolver` byte-for-byte.
fn emitCompositeTypeDeclarations(emitter: *LlvmModuleEmitter) !void {
    if (emitter.ordered_composites.items.len == 0) return;
    for (emitter.ordered_composites.items) |ty| {
        const lay = try emitter.resolver.resolveType(ty);
        if (lay.size_bytes == 0) continue;
        const node = emitter.input.pool.getNode(ty);
        if (node.tag == .struct_ty or node.tag == .tuple_ty) {
            const pad_spans_raw = try emitter.resolver.getPaddingSpans(ty);
            const pad_spans = try emitter.allocator.dupe(codegen_abi.PaddingSpan, pad_spans_raw);
            defer if (pad_spans.len > 0) emitter.allocator.free(pad_spans);

            try emitter.print("%_cx_ty_{d} = type <{{ ", .{ty.toU32()});
            var pad_cursor: usize = 0;
            var emitted_count: usize = 0;
            var phys_i: u32 = 0;
            while (phys_i < lay.aux_len) : (phys_i += 1) {
                const decl_ord = emitter.resolver.phys_to_decl.items[lay.aux_start + phys_i];
                const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + decl_ord];
                while (pad_cursor < pad_spans.len and
                    pad_spans[pad_cursor].byte_offset <= fld.byte_offset)
                {
                    const pad = pad_spans[pad_cursor];
                    pad_cursor += 1;
                    if (emitted_count > 0) try emitter.writeAll(", ");
                    try emitter.print("[{d} x i8]", .{pad.byte_len});
                    emitted_count += 1;
                }
                if (fld.size_bytes == 0) continue;
                const fld_mem = try formatLlvmMemoryType(emitter, fld.field_ty);
                defer emitter.allocator.free(fld_mem);
                if (emitted_count > 0) try emitter.writeAll(", ");
                try emitter.writeAll(fld_mem);
                emitted_count += 1;
            }
            while (pad_cursor < pad_spans.len) {
                const pad = pad_spans[pad_cursor];
                pad_cursor += 1;
                if (emitted_count > 0) try emitter.writeAll(", ");
                try emitter.print("[{d} x i8]", .{pad.byte_len});
                emitted_count += 1;
            }
            if (emitted_count == 0) {
                try emitter.print("[{d} x i8]", .{lay.size_bytes});
            }
            try emitter.writeAll(" }>\n");
        } else if (node.tag == .soa_vec_ty) {
            try emitter.print(
                "%_cx_ty_{d} = type <{{ ptr, i32, i32, {s} }}>\n",
                .{ ty.toU32(), ptrIntType(emitter) },
            );
        } else {
            try emitter.print("%_cx_ty_{d} = type <{{ [{d} x i8] }}>\n", .{ ty.toU32(), lay.size_bytes });
        }
    }
    try emitter.writeAll("\n");
}

// ------------ Module Indexing, ABI & Global Rodata ------------

/// Sanitizes a raw identifier so it contains only `[A-Za-z0-9_]` characters for internal symbol suffixes.
fn sanitizeLlvmIdentAlloc(allocator: std.mem.Allocator, raw_name: []const u8) ![]u8 {
    if (raw_name.len == 0) return allocator.dupe(u8, "anon");
    var buf = try allocator.alloc(u8, raw_name.len);
    for (raw_name, 0..) |ch, idx| {
        buf[idx] = if (std.ascii.isAlphanumeric(ch) or ch == '_') ch else '_';
    }
    return buf;
}

/// Escapes `raw_text` for an LLVM string/metadata literal `"…"` (caller owns returned slice).
fn escapeMetadataStringAlloc(allocator: std.mem.Allocator, raw_text: []const u8) ![]u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    errdefer buf.deinit(allocator);
    for (raw_text) |ch_b| {
        if (ch_b >= 0x20 and ch_b <= 0x7E and ch_b != '"' and ch_b != '\\') {
            try buf.append(allocator, ch_b);
        } else {
            const hex_esc = try std.fmt.allocPrint(allocator, "\\{X:0>2}", .{ch_b});
            defer allocator.free(hex_esc);
            try buf.appendSlice(allocator, hex_esc);
        }
    }
    return buf.toOwnedSlice(allocator);
}

/// Formats `raw_name` as a valid LLVM global identifier (`@foo` when bare-safe, else `@"…"`).
fn formatLlvmGlobalIdent(allocator: std.mem.Allocator, raw_name: []const u8) ![]u8 {
    var is_bare_ok = raw_name.len > 0 and !std.ascii.isDigit(raw_name[0]);
    if (is_bare_ok) {
        for (raw_name) |ch_b| {
            if (!std.ascii.isAlphanumeric(ch_b) and ch_b != '_' and ch_b != '.' and ch_b != '$') {
                is_bare_ok = false;
                break;
            }
        }
    }
    if (is_bare_ok) {
        return std.fmt.allocPrint(allocator, "@{s}", .{raw_name});
    }
    const escaped = try escapeMetadataStringAlloc(allocator, raw_name);
    defer allocator.free(escaped);
    return std.fmt.allocPrint(allocator, "@\"{s}\"", .{escaped});
}

/// Resolves `(def_id, sym_idx)` to a 0-based index in `emitter.input.bodies` (`null` if external).
fn resolveBodyIndex(
    emitter: *const LlvmModuleEmitter,
    def_id: DefId,
    sym_idx: SymbolIndex,
) ?u32 {
    if (!sym_idx.isNone()) {
        if (emitter.sym_to_body.get(sym_idx.asInt())) |found_sym| return found_sym;
        if (sym_idx.asInt() < emitter.input.sym_table.symbols.items.len) {
            const sym_rec = emitter.input.sym_table.getSymbol(sym_idx).*;
            if (!sym_rec.def_id.isNone()) {
                if (emitter.def_to_body.get(sym_rec.def_id.asInt())) |found_def| return found_def;
            }
        }
    }
    if (!def_id.isNone()) {
        if (emitter.def_to_body.get(def_id.asInt())) |found_by_def| return found_by_def;
    }
    return null;
}

/// Extracts Phase 8 FFI, WebAssembly, TLS, and section metadata for `sym_idx`.
fn extractSymFfiMetaLlvm(emitter: *const LlvmModuleEmitter, sym_idx: SymbolIndex) SymFfiMetaLlvm {
    if (sym_idx.isNone() or sym_idx.asInt() >= emitter.input.sym_table.symbols.items.len) return .{};
    const sym_rec = emitter.input.sym_table.getSymbol(sym_idx).*;
    var meta = SymFfiMetaLlvm{
        .is_export = sym_rec.contract_flags.is_export,
        .link_name = if (sym_rec.contract_flags.has_link_name) sym_rec.link_name_text else "",
        .link_section = if (sym_rec.contract_flags.has_link_section) sym_rec.link_section_name else "",
    };
    if (emitter.input.sym_table.getFfiContract(sym_idx)) |ffi_c| {
        meta.is_thread_local = ffi_c.is_thread_local;
        if (ffi_c.wasm_import_module != .empty and !ffi_c.wasm_import_module.isNone()) {
            meta.wasm_import_module = emitter.input.interner.get(ffi_c.wasm_import_module);
        }
        if (ffi_c.wasm_import_name != .empty and !ffi_c.wasm_import_name.isNone()) {
            meta.wasm_import_name = emitter.input.interner.get(ffi_c.wasm_import_name);
        }
        if (ffi_c.wasm_export_name != .empty and !ffi_c.wasm_export_name.isNone()) {
            meta.wasm_export_name = emitter.input.interner.get(ffi_c.wasm_export_name);
        }
        if (ffi_c.link_lib_name != .empty and !ffi_c.link_lib_name.isNone()) {
            meta.link_lib_name = emitter.input.interner.get(ffi_c.link_lib_name);
        }
    }
    return meta;
}

/// Appends `lib_name` from `@link_lib("…")` into `emitter.collected_link_libs` without duplicates.
fn recordCollectedLinkLibLlvm(emitter: *LlvmModuleEmitter, lib_name: []const u8) !void {
    if (lib_name.len == 0) return;
    for (emitter.collected_link_libs.items) |existing| {
        if (std.mem.eql(u8, existing, lib_name)) return;
    }
    try emitter.collected_link_libs.append(emitter.allocator, lib_name);
}

/// Returns `true` if `body` carries `@export`, `@wasm_export`, or `@link_name` external symbol visibility.
fn isBodyExternallyVisible(emitter: *const LlvmModuleEmitter, body: *const MirBody) bool {
    if (body.symbol_index.isNone() or
        body.symbol_index.asInt() >= emitter.input.sym_table.symbols.items.len) return false;
    const sym_rec = emitter.input.sym_table.getSymbol(body.symbol_index).*;
    if (sym_rec.contract_flags.is_export or sym_rec.contract_flags.has_link_name) return true;
    return extractSymFfiMetaLlvm(emitter, body.symbol_index).wasm_export_name.len > 0;
}

/// Returns `true` if `body` is an `@export`, `@wasm_export`, `@link_name`, or `extern "C"` C-ABI boundary (`Fix-07`).
fn isBodyCAbiBoundaryLlvm(emitter: *const LlvmModuleEmitter, body: *const MirBody) bool {
    if (body.symbol_index.isNone() or
        body.symbol_index.asInt() >= emitter.input.sym_table.symbols.items.len) return false;
    const sym_rec = emitter.input.sym_table.getSymbol(body.symbol_index).*;
    if (sym_rec.flags.is_extern or
        sym_rec.contract_flags.is_export or
        sym_rec.contract_flags.has_link_name) return true;
    if (extractSymFfiMetaLlvm(emitter, body.symbol_index).wasm_export_name.len > 0) return true;
    if (emitter.input.pool.getFnSignatureView(sym_rec.type_id)) |sig_view| {
        if (sig_view.is_c_abi or sig_view.is_variadic) return true;
    }
    return false;
}

/// Classifies `body`'s machine calling convention via `AbiClassifier.classifyFn`.
fn classifyBodyAbi(emitter: *LlvmModuleEmitter, body: *const MirBody) !AbiFnRecipe {
    var param_specs = try emitter.allocator.alloc(FnParamSpec, body.param_count);
    defer if (param_specs.len > 0) emitter.allocator.free(param_specs);

    var param_i: u32 = 0;
    while (param_i < body.param_count) : (param_i += 1) {
        const loc_decl = body.locals.items[1 + param_i];
        param_specs[param_i] = .{
            .type_id = loc_decl.type_id,
            .mode = loc_decl.mode(),
            .is_non_escaping = true,
        };
    }
    const is_variadic_body = if (!body.symbol_index.isNone() and
        body.symbol_index.asInt() < emitter.input.sym_table.symbols.items.len)
        if (emitter.input.pool.getFnSignatureView(
            emitter.input.sym_table.getSymbol(body.symbol_index).type_id,
        )) |sig_view| sig_view.is_variadic else false
    else
        false;
    const is_c_abi = isBodyCAbiBoundaryLlvm(emitter, body) or is_variadic_body;
    return AbiClassifier.classifyFn(emitter.allocator, &emitter.resolver, .{
        .params = param_specs,
        .ret_ty = body.ret_ty,
        .is_extern_c = is_c_abi,
        .is_contextless = body.is_contextless or is_c_abi,
        .is_variadic = is_variadic_body,
    });
}

/// Classifies an `InternPool` `fn_ty` or `closure_ty` signature via `AbiClassifier.classifyFn`.
fn classifyFnTypeAbi(
    emitter: *LlvmModuleEmitter,
    fn_ty: TypeId,
    is_extern_c: bool,
    force_contextless: ?bool,
) !AbiFnRecipe {
    const unwrapped = emitter.input.pool.unwrapUnderlyingType(fn_ty);
    const sig_view = emitter.input.pool.getFnSignatureView(unwrapped) orelse {
        return AbiClassifier.classifyFn(emitter.allocator, &emitter.resolver, .{
            .params = &.{},
            .ret_ty = .unit_ty,
            .is_extern_c = is_extern_c,
            .is_contextless = true,
        });
    };
    const arity = sig_view.paramCount();
    var param_specs = try emitter.allocator.alloc(FnParamSpec, arity);
    defer if (arity > 0) emitter.allocator.free(param_specs);

    for (0..arity) |idx| {
        param_specs[idx] = .{
            .type_id = sig_view.getParamType(idx),
            .mode = sig_view.getParamMode(idx),
            .is_non_escaping = true,
        };
    }
    const is_ext = is_extern_c or sig_view.is_c_abi or sig_view.is_variadic;
    const is_ctxless = force_contextless orelse
        (is_ext or sig_view.contracts.has_no_alloc);
    return AbiClassifier.classifyFn(emitter.allocator, &emitter.resolver, .{
        .params = param_specs,
        .ret_ty = sig_view.ret_ty,
        .is_extern_c = is_ext,
        .is_contextless = is_ctxless,
        .is_variadic = sig_view.is_variadic,
    });
}

/// Computes a deterministic 128-bit deduplication key for `MirConst.source_loc`.
fn computeSourceLocKey(sloc: mir.SourceLocConst) u128 {
    return (@as(u128, sloc.file_sym.asInt()) << 96) |
        (@as(u128, sloc.fn_sym.asInt()) << 64) |
        (@as(u128, sloc.line) << 32) |
        @as(u128, sloc.col);
}

/// Registers `raw_ty` and its constituent fields/elements/variants for `@_cx_drop_ty_<id>` generation.
fn registerDropTypeRecursive(emitter: *LlvmModuleEmitter, raw_ty: TypeId, depth: u32) !void {
    if (depth >= 64) return;
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (try isZeroSizedType(emitter, ty)) return;
    if (ty.isPrimitiveOrSentinel()) return;

    if ((try emitter.drop_type_set.getOrPut(emitter.allocator, ty.toU32())).found_existing) return;

    try collectCompositeType(emitter, ty, 0);
    const node = emitter.input.pool.getNode(ty);
    switch (node.tag) {
        .struct_ty, .tuple_ty => {
            const lay = try emitter.resolver.resolveType(ty);
            var fld_i: u32 = 0;
            while (fld_i < lay.aux_len) : (fld_i += 1) {
                const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                try registerDropTypeRecursive(emitter, fld.field_ty, depth + 1);
            }
        },
        .array_ty => {
            try registerDropTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
        },
        .soa_array_ty, .soa_vec_ty => {
            if (node.tag == .soa_vec_ty) emitter.has_soa_vec = true;
            const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
            const lay = try emitter.resolver.resolveType(elem_struct);
            var fld_i: u32 = 0;
            while (fld_i < lay.aux_len) : (fld_i += 1) {
                const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                try registerDropTypeRecursive(emitter, fld.field_ty, depth + 1);
            }
        },
        .optional_ty => {
            try registerDropTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
        },
        .result_ty => {
            try registerDropTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
            try registerDropTypeRecursive(emitter, TypeId.fromInt(node.rhs), depth + 1);
        },
        .future_ty => {
            try registerDropTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
        },
        .enum_ty => {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            if (!sym_idx.isNone() and sym_idx.asInt() < emitter.input.sym_table.symbols.items.len) {
                const enum_sym = emitter.input.sym_table.getSymbol(sym_idx).*;
                if (!enum_sym.target_scope.isNone()) {
                    var var_ord: u32 = 0;
                    for (emitter.input.sym_table.getScopeMembers(enum_sym.target_scope)) |mem_idx| {
                        if (emitter.input.sym_table.getSymbol(mem_idx).kind != .enum_variant_sym) continue;
                        const var_pay = resolveEnumVariantPayloadType(emitter, ty, var_ord);
                        try registerDropTypeRecursive(emitter, var_pay, depth + 1);
                        var_ord += 1;
                    }
                }
            }
        },
        else => {},
    }
    try emitter.drop_type_list.append(emitter.allocator, ty);
}

/// Registers `raw_ty` and any recursively formatted child types for `@_cx_fmt_fn_ty_<id>` generation.
fn registerFmtTypeRecursive(emitter: *LlvmModuleEmitter, raw_ty: TypeId, depth: u32) !void {
    if (depth >= 64) return;
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (ty.isError()) return;
    if ((try emitter.fmt_type_set.getOrPut(emitter.allocator, ty.toU32())).found_existing) return;

    emitter.has_fmt_rt_helpers = true;
    try collectCompositeType(emitter, ty, 0);
    if (!ty.isPrimitiveOrSentinel() and !isBuiltInRuntimeTypeLlvm(emitter.input.pool, ty)) {
        const node = emitter.input.pool.getNode(ty);
        switch (node.tag) {
            .ref_ty, .mut_ref_ty => {
                try registerFmtTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
            },
            .slice_ty, .array_ty => {
                try registerFmtTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
            },
            .soa_array_ty, .soa_slice_ty, .soa_vec_ty => {
                const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
                const lay = try emitter.resolver.resolveType(elem_struct);
                var fld_i: u32 = 0;
                while (fld_i < lay.aux_len) : (fld_i += 1) {
                    const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                    try registerFmtTypeRecursive(emitter, fld.field_ty, depth + 1);
                }
            },
            .struct_ty, .tuple_ty => {
                const lay = try emitter.resolver.resolveType(ty);
                var fld_i: u32 = 0;
                while (fld_i < lay.aux_len) : (fld_i += 1) {
                    const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                    try registerFmtTypeRecursive(emitter, fld.field_ty, depth + 1);
                }
            },
            .optional_ty => {
                try registerFmtTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
            },
            .result_ty => {
                try registerFmtTypeRecursive(emitter, TypeId.fromInt(node.lhs), depth + 1);
                try registerFmtTypeRecursive(emitter, TypeId.fromInt(node.rhs), depth + 1);
            },
            .enum_ty => {
                const sym_idx = SymbolIndex.fromInt(node.rhs);
                if (!sym_idx.isNone() and sym_idx.asInt() < emitter.input.sym_table.symbols.items.len) {
                    const enum_sym = emitter.input.sym_table.getSymbol(sym_idx).*;
                    if (!enum_sym.target_scope.isNone()) {
                        var var_ord: u32 = 0;
                        for (emitter.input.sym_table.getScopeMembers(enum_sym.target_scope)) |mem_idx| {
                            if (emitter.input.sym_table.getSymbol(mem_idx).kind != .enum_variant_sym) continue;
                            const var_pay = resolveEnumVariantPayloadType(emitter, ty, var_ord);
                            if (var_pay != .unit_ty) {
                                try registerFmtTypeRecursive(emitter, var_pay, depth + 1);
                            }
                            var_ord += 1;
                        }
                    }
                }
            },
            else => {},
        }
    } else if (ty == .fmt_args_ty) {
        try registerFmtTypeRecursive(emitter, .str_ty, depth + 1);
    }
    try emitter.fmt_type_list.append(emitter.allocator, ty);
}

/// Records an `extern` function or `extern static` global symbol if referenced without a local `MirBody`.
fn maybeRegisterExternSymbol(
    emitter: *LlvmModuleEmitter,
    seen_set: *std.AutoHashMapUnmanaged(u32, void),
    def_id: DefId,
    sym_idx: SymbolIndex,
) !void {
    if (resolveBodyIndex(emitter, def_id, sym_idx) != null) return;
    if (sym_idx.isNone() or sym_idx.asInt() >= emitter.input.sym_table.symbols.items.len) return;
    const sym_rec = emitter.input.sym_table.getSymbol(sym_idx).*;
    const ffi_meta = extractSymFfiMetaLlvm(emitter, sym_idx);
    try recordCollectedLinkLibLlvm(emitter, ffi_meta.link_lib_name);
    if (sym_rec.kind == .fn_sym) {
        if (!(try seen_set.getOrPut(emitter.allocator, sym_idx.asInt())).found_existing) {
            try emitter.extern_syms.append(emitter.allocator, sym_idx);
            if (emitter.input.pool.getFnSignatureView(sym_rec.type_id)) |sig| {
                try collectCompositeType(emitter, sig.ret_ty, 0);
                for (0..sig.paramCount()) |idx| {
                    try collectCompositeType(emitter, sig.getParamType(idx), 0);
                }
            }
        }
    } else if (sym_rec.kind == .extern_static_sym or sym_rec.flags.is_extern or
        (sym_rec.kind == .const_sym and blk_unbacked_const: {
            const resolved_def = if (!def_id.isNone()) def_id else sym_rec.def_id;
            if (emitter.input.const_rodata_map) |crm| {
                break :blk_unbacked_const !crm.contains(resolved_def.asInt());
            }
            break :blk_unbacked_const true;
        }))
    {
        if (!(try emitter.extern_global_sym_set.getOrPut(emitter.allocator, sym_idx.asInt())).found_existing) {
            try emitter.extern_global_syms.append(emitter.allocator, sym_idx);
            try collectCompositeType(emitter, sym_rec.type_id, 0);
        }
    }
}

/// Returns `true` when `target_b` is contextless (`!has_implicit_context`) while `fn_ty` is a stateful `fn(…)`.
fn isFnAddrCtxWrapperNeeded(emitter: *const LlvmModuleEmitter, target_b: u32, fn_ty: TypeId) bool {
    if (target_b >= emitter.body_recipes.items.len) return false;
    if (emitter.body_recipes.items[target_b].has_implicit_context) return false;
    const unwrapped = emitter.input.pool.unwrapUnderlyingType(fn_ty);
    if (emitter.input.pool.getNode(unwrapped).tag != .fn_ty) return false;
    const sig_view = emitter.input.pool.getFnSignatureView(unwrapped) orelse return false;
    return !sig_view.is_c_abi and !sig_view.is_variadic and !sig_view.contracts.has_no_alloc;
}

/// Returns `true` when `MirOp.fn_addr` value `fn_val_raw` in `body_ptr` is reified beyond a direct `callee_val`.
fn isFnAddrUsedAsValue(body_ptr: *const MirBody, fn_val_raw: u32) bool {
    for (0..body_ptr.insts.len) |other_raw| {
        const other_inst = body_ptr.insts.get(other_raw);
        switch (other_inst.op) {
            .copy_val, .unary_op, .aggregate_extract, .bitfield_extract => {
                if (other_inst.operands.lhs == fn_val_raw) return true;
            },
            .bin_op => {
                if (other_inst.operands.lhs == fn_val_raw or other_inst.operands.rhs == fn_val_raw) return true;
            },
            .place_store => {
                if (other_inst.operands.rhs == fn_val_raw) return true;
            },
            .aggregate_insert => {
                if (other_inst.operands.lhs == fn_val_raw) return true;
                if (other_inst.operands.rhs + 1 < body_ptr.extra_args.items.len and
                    body_ptr.extra_args.items[other_inst.operands.rhs + 1] == fn_val_raw)
                {
                    return true;
                }
            },
            .bitfield_insert => {
                if (other_inst.operands.lhs + 1 < body_ptr.extra_args.items.len and
                    (body_ptr.extra_args.items[other_inst.operands.lhs] == fn_val_raw or
                        body_ptr.extra_args.items[other_inst.operands.lhs + 1] == fn_val_raw))
                {
                    return true;
                }
            },
            .aggregate_make => {
                const agg_kind: mir.AggregateKind = @fromBackingInt(
                    @intCast(@as(u8, @truncate(other_inst.aux_u16))),
                );
                switch (agg_kind) {
                    .closure_make => {
                        const cap_len: usize = if (other_inst.operands.rhs < body_ptr.extra_args.items.len)
                            body_ptr.extra_args.items[other_inst.operands.rhs]
                        else
                            0;
                        for (0..cap_len) |cap_i| {
                            if (other_inst.operands.rhs + 1 + cap_i < body_ptr.extra_args.items.len and
                                body_ptr.extra_args.items[other_inst.operands.rhs + 1 + cap_i] == fn_val_raw)
                            {
                                return true;
                            }
                        }
                    },
                    .array_repeat => {
                        if (other_inst.operands.lhs == fn_val_raw) return true;
                    },
                    .tagged_variant => {
                        for (0..(other_inst.operands.rhs & 0xFFFF)) |arg_i| {
                            if (other_inst.operands.lhs + arg_i < body_ptr.extra_args.items.len and
                                body_ptr.extra_args.items[other_inst.operands.lhs + arg_i] == fn_val_raw)
                            {
                                return true;
                            }
                        }
                    },
                    .tuple_agg, .struct_agg, .array_elems, .str_concat, .fmt_args_make => {
                        for (0..other_inst.operands.rhs) |elem_i| {
                            if (other_inst.operands.lhs + elem_i < body_ptr.extra_args.items.len and
                                body_ptr.extra_args.items[other_inst.operands.lhs + elem_i] == fn_val_raw)
                            {
                                return true;
                            }
                        }
                    },
                }
            },
            .intrinsic_op => {
                if (@as(mir.MirIntrinsicKind, @fromBackingInt(other_inst.aux_u16)).hasExtraArgs()) {
                    for (0..other_inst.operands.rhs) |arg_i| {
                        if (other_inst.operands.lhs + arg_i < body_ptr.extra_args.items.len and
                            body_ptr.extra_args.items[other_inst.operands.lhs + arg_i] == fn_val_raw)
                        {
                            return true;
                        }
                    }
                }
            },
            else => {},
        }
    }
    for (body_ptr.calls.items) |call_site| {
        if (call_site.direct_def_id.isNone() and call_site.direct_symbol.isNone() and
            call_site.callee_val.asInt() == fn_val_raw)
        {
            return true;
        }
        for (0..call_site.args_len) |arg_i| {
            const mode: type_system.ParamMode = if (call_site.modes_start + arg_i < body_ptr.call_arg_modes.items.len)
                body_ptr.call_arg_modes.items[call_site.modes_start + arg_i]
            else
                .let_mode;
            if (mode != .inout_mode and mode != .set_mode and
                call_site.args_start + arg_i < body_ptr.extra_args.items.len and
                body_ptr.extra_args.items[call_site.args_start + arg_i] == fn_val_raw)
            {
                return true;
            }
        }
    }
    for (body_ptr.blocks.items) |blk_rec| {
        switch (blk_rec.terminator.kind) {
            .ret, .cond_br, .switch_int => {
                if (blk_rec.terminator.cond_or_val == fn_val_raw) return true;
            },
            else => {},
        }
    }
    for (body_ptr.extra_edges.items) |edge_rec| {
        for (0..edge_rec.args_len) |edge_arg_i| {
            if (edge_rec.args_start + edge_arg_i < body_ptr.extra_args.items.len and
                body_ptr.extra_args.items[edge_rec.args_start + edge_arg_i] == fn_val_raw)
            {
                return true;
            }
        }
    }
    for (body_ptr.projections.items) |proj_rec| {
        if (proj_rec.kind == .index and proj_rec.payload == fn_val_raw) return true;
    }
    return false;
}

/// Registers a non-transparent `Result[T, E]` type for `@_cx_res_is_err_<id>` synthesis (`DR-08`).
fn maybeRegisterResultErrCheckTypeLlvm(emitter: *LlvmModuleEmitter, raw_ty: TypeId) !void {
    const unwrapped = emitter.input.pool.unwrapUnderlyingType(raw_ty);
    if (unwrapped.isPrimitiveOrSentinel() or emitter.input.pool.getNode(unwrapped).tag != .result_ty) return;
    if (try isZeroSizedType(emitter, unwrapped)) return;
    const detail = (try emitter.resolver.getSumDetail(unwrapped)) orelse return;
    if (detail.repr == .not_sum or detail.repr == .transparent_ok) return;
    if (!(try emitter.res_err_check_set.getOrPut(emitter.allocator, unwrapped.toU32())).found_existing) {
        try collectCompositeType(emitter, unwrapped, 0);
        try emitter.ordered_res_err_types.append(emitter.allocator, unwrapped);
    }
}

/// Indexes all `MirBody` functions, composite types, string/blob constants, externs, closures, and drops.
fn indexModuleEntities(emitter: *LlvmModuleEmitter) !void {
    var seen_llvm_exports: std.StringHashMapUnmanaged(SymbolIndex) = .empty;
    defer seen_llvm_exports.deinit(emitter.allocator);

    for (emitter.input.bodies, 0..) |*body_ptr, body_i| {
        const b_idx: u32 = @intCast(body_i);
        if (!body_ptr.def_id.isNone()) {
            try emitter.def_to_body.put(emitter.allocator, body_ptr.def_id.asInt(), b_idx);
        }
        if (!body_ptr.symbol_index.isNone()) {
            try emitter.sym_to_body.put(emitter.allocator, body_ptr.symbol_index.asInt(), b_idx);
        }

        const raw_name = emitter.input.interner.get(body_ptr.name);
        var is_export_sym = false;
        var has_wasm_export = false;
        var wasm_export_slice: []const u8 = "";
        var link_name_override: ?[]const u8 = null;
        if (!body_ptr.symbol_index.isNone() and
            body_ptr.symbol_index.asInt() < emitter.input.sym_table.symbols.items.len)
        {
            const ffi_meta = extractSymFfiMetaLlvm(emitter, body_ptr.symbol_index);
            try recordCollectedLinkLibLlvm(emitter, ffi_meta.link_lib_name);
            is_export_sym = ffi_meta.is_export;
            has_wasm_export = ffi_meta.wasm_export_name.len > 0;
            wasm_export_slice = ffi_meta.wasm_export_name;
            if (ffi_meta.link_name.len > 0) {
                link_name_override = ffi_meta.link_name;
            }
        }
        const is_exported_main = std.mem.eql(u8, raw_name, "main") and (is_export_sym or has_wasm_export);
        if (codegen_c.isRootEntryMainCandidate(body_ptr, emitter.input.sym_table, raw_name, is_exported_main)) {
            emitter.entry_main_body_idx = b_idx;
        }

        var is_unmangled_linker_sym = false;
        const llvm_name = if (link_name_override) |lnk_str| blk_lnk: {
            is_unmangled_linker_sym = true;
            if (std.mem.eql(u8, lnk_str, "main") and !is_exported_main) {
                break :blk_lnk try emitter.allocator.dupe(u8, "_cx_user_main");
            }
            break :blk_lnk try emitter.allocator.dupe(u8, lnk_str);
        } else if ((is_export_sym or has_wasm_export) and
            (!std.mem.eql(u8, raw_name, "main") or emitter.cfg.target.isWasm()))
        blk_exp: {
            is_unmangled_linker_sym = true;
            break :blk_exp try emitter.allocator.dupe(u8, raw_name);
        } else blk: {
            const clean_suffix = try sanitizeLlvmIdentAlloc(emitter.allocator, raw_name);
            defer emitter.allocator.free(clean_suffix);
            break :blk try codegen_c.formatInternalBodySymbolAlloc(
                emitter.allocator,
                emitter.input.sym_table,
                emitter.input.interner,
                body_ptr,
                b_idx,
                clean_suffix,
            );
        };
        try emitter.body_llvm_names.append(emitter.allocator, llvm_name);
        if (is_unmangled_linker_sym) {
            try codegen_c.checkAndRecordExportedLinkerSymbol(
                emitter.allocator,
                &seen_llvm_exports,
                emitter.input.sym_table,
                emitter.input.diagnostic_sink,
                llvm_name,
                body_ptr,
            );
        }
        if (has_wasm_export and !std.mem.eql(u8, wasm_export_slice, llvm_name)) {
            try codegen_c.checkAndRecordExportedLinkerSymbol(
                emitter.allocator,
                &seen_llvm_exports,
                emitter.input.sym_table,
                emitter.input.diagnostic_sink,
                wasm_export_slice,
                body_ptr,
            );
        }
        try emitter.body_recipes.append(emitter.allocator, try classifyBodyAbi(emitter, body_ptr));
    }

    var str_set: std.AutoHashMapUnmanaged(u32, void) = .empty;
    defer str_set.deinit(emitter.allocator);
    var blob_set: std.AutoHashMapUnmanaged(u32, void) = .empty;
    defer blob_set.deinit(emitter.allocator);
    var extern_set: std.AutoHashMapUnmanaged(u32, void) = .empty;
    defer extern_set.deinit(emitter.allocator);
    var candidate_types: std.ArrayListUnmanaged(TypeId) = .empty;
    defer candidate_types.deinit(emitter.allocator);
    var cand_set: std.AutoHashMapUnmanaged(u32, void) = .empty;
    defer cand_set.deinit(emitter.allocator);

    for (emitter.input.bodies, 0..) |*body_ptr, body_i| {
        const b_idx: u32 = @intCast(body_i);
        if (!(try cand_set.getOrPut(emitter.allocator, body_ptr.ret_ty.toU32())).found_existing) {
            try candidate_types.append(emitter.allocator, body_ptr.ret_ty);
        }
        if (emitter.has_async_ops and body_ptr.is_async) {
            try maybeRegisterResultErrCheckTypeLlvm(emitter, body_ptr.ret_ty);
        }
        for (body_ptr.locals.items, 0..) |loc_decl, loc_i| {
            if (!(try cand_set.getOrPut(emitter.allocator, loc_decl.type_id.toU32())).found_existing) {
                try candidate_types.append(emitter.allocator, loc_decl.type_id);
            }
            if (emitter.has_async_ops and body_ptr.is_async and
                loc_i >= 1 and loc_i <= body_ptr.param_count)
            {
                const param_mode = loc_decl.mode();
                if (param_mode != .inout_mode and param_mode != .set_mode) {
                    const unwrapped_param = emitter.input.pool.unwrapUnderlyingType(loc_decl.type_id);
                    if (!emitter.input.pool.getFlags(unwrapped_param).is_copy) {
                        try registerDropTypeRecursive(emitter, unwrapped_param, 0);
                    }
                }
            }
        }
        for (body_ptr.consts.items) |mir_const| {
            switch (mir_const) {
                .str_val, .bytes_val => |sym_id| {
                    if (!(try str_set.getOrPut(emitter.allocator, sym_id.asInt())).found_existing) {
                        try emitter.str_sym_ids.append(emitter.allocator, sym_id.asInt());
                    }
                },
                .raw_blob => |rb_const| {
                    if (!(try blob_set.getOrPut(emitter.allocator, rb_const.blob_id)).found_existing) {
                        try emitter.blob_ids.append(emitter.allocator, rb_const.blob_id);
                    }
                },
                .source_loc => |sloc| {
                    if (!(try str_set.getOrPut(emitter.allocator, sloc.file_sym.asInt())).found_existing) {
                        try emitter.str_sym_ids.append(emitter.allocator, sloc.file_sym.asInt());
                    }
                    if (!(try str_set.getOrPut(emitter.allocator, sloc.fn_sym.asInt())).found_existing) {
                        try emitter.str_sym_ids.append(emitter.allocator, sloc.fn_sym.asInt());
                    }
                    const loc_key = computeSourceLocKey(sloc);
                    if (!emitter.source_loc_map.contains(loc_key)) {
                        const loc_idx: u32 = @intCast(emitter.source_loc_consts.items.len);
                        try emitter.source_loc_consts.append(emitter.allocator, sloc);
                        try emitter.source_loc_map.put(emitter.allocator, loc_key, loc_idx);
                    }
                },
                else => {},
            }
        }
        for (0..body_ptr.insts.len) |inst_raw| {
            const inst = body_ptr.insts.get(inst_raw);
            if (!(try cand_set.getOrPut(emitter.allocator, inst.type_id.toU32())).found_existing) {
                try candidate_types.append(emitter.allocator, inst.type_id);
            }
            if (inst.op == .fn_addr) {
                const fn_def_id = DefId.fromInt(inst.operands.lhs);
                const fn_sym_idx = SymbolIndex.fromInt(inst.operands.rhs);
                try maybeRegisterExternSymbol(
                    emitter,
                    &extern_set,
                    fn_def_id,
                    fn_sym_idx,
                );
                if (resolveBodyIndex(emitter, fn_def_id, fn_sym_idx)) |target_b| {
                    if (isFnAddrCtxWrapperNeeded(emitter, target_b, inst.type_id) and
                        isFnAddrUsedAsValue(body_ptr, @intCast(inst_raw)))
                    {
                        const gop = try emitter.ctx_wrap_map.getOrPut(emitter.allocator, target_b);
                        if (!gop.found_existing) {
                            gop.value_ptr.* = emitter.input.pool.unwrapUnderlyingType(inst.type_id);
                            try emitter.ctx_wrap_bodies.append(emitter.allocator, target_b);
                        }
                    }
                }
            } else if (inst.op == .aggregate_make) {
                const agg_kind: mir.AggregateKind = @fromBackingInt(
                    @intCast(@as(u8, @truncate(inst.aux_u16))),
                );
                if (agg_kind == .closure_make) {
                    if (resolveBodyIndex(emitter, DefId.fromInt(inst.operands.lhs), .none)) |callee_b| {
                        const key: u64 = (@as(u64, b_idx) << 32) | @as(u64, @intCast(inst_raw));
                        if (!emitter.closure_thunk_map.contains(key)) {
                            const clos_ty = emitter.input.pool.unwrapUnderlyingType(inst.type_id);
                            const is_three_w = codegen_abi.isThreeWordClosureType(emitter.input.pool, clos_ty);
                            const cap_len: usize = if (inst.operands.rhs < body_ptr.extra_args.items.len)
                                body_ptr.extra_args.items[inst.operands.rhs]
                            else
                                0;
                            const cap_tys = try emitter.allocator.alloc(TypeId, cap_len);
                            for (0..cap_len) |cap_i| {
                                const cap_val = MirValueId.fromInt(
                                    body_ptr.extra_args.items[inst.operands.rhs + 1 + cap_i],
                                );
                                cap_tys[cap_i] = body_ptr.getInst(cap_val).type_id;
                                if (!(try cand_set.getOrPut(emitter.allocator, cap_tys[cap_i].toU32())).found_existing) {
                                    try candidate_types.append(emitter.allocator, cap_tys[cap_i]);
                                }
                                if (is_three_w) {
                                    try registerDropTypeRecursive(emitter, cap_tys[cap_i], 0);
                                }
                            }
                            if (is_three_w) {
                                try registerDropTypeRecursive(emitter, clos_ty, 0);
                            }
                            const thunk_idx: u32 = @intCast(emitter.closure_thunks.items.len);
                            try emitter.closure_thunks.append(emitter.allocator, .{
                                .owner_body_idx = b_idx,
                                .inst_val_raw = @intCast(inst_raw),
                                .callee_body_idx = callee_b,
                                .closure_ty = clos_ty,
                                .capture_types = cap_tys,
                                .is_three_word = is_three_w,
                            });
                            try emitter.closure_thunk_map.put(emitter.allocator, key, thunk_idx);
                        }
                    }
                } else if (agg_kind == .fmt_args_make) {
                    if (!emitter.cfg.target.isFreestanding()) {
                        emitter.has_fmt_rt_helpers = true;
                    }
                    if (inst.operands.rhs >= 1 and
                        inst.operands.lhs + inst.operands.rhs <= body_ptr.extra_args.items.len)
                    {
                        const words = body_ptr.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
                        const p_inst = body_ptr.getInst(MirValueId.fromInt(words[0]));
                        var piece_count: usize = 0;
                        if (p_inst.op == .const_scalar and p_inst.operands.lhs < body_ptr.consts.items.len) {
                            switch (body_ptr.consts.items[p_inst.operands.lhs]) {
                                .int_val => |iv| piece_count = @intCast(@as(u128, @bitCast(iv))),
                                else => {},
                            }
                        }
                        if (1 + piece_count <= words.len) {
                            const hole_count = (words.len - 1 - piece_count) / 3;
                            var hole_j: usize = 0;
                            while (hole_j < hole_count) : (hole_j += 1) {
                                const href_raw = words[1 + piece_count + hole_j * 3];
                                const href_ty = try unwrapTransparentType(
                                    emitter,
                                    body_ptr.getInst(MirValueId.fromInt(href_raw)).type_id,
                                );
                                const href_node = emitter.input.pool.getNode(href_ty);
                                const hval_ty = if ((href_node.tag == .ref_ty or
                                    href_node.tag == .mut_ref_ty or
                                    href_node.tag == .raw_ptr_ty) and
                                    !emitter.input.pool.isSliceRefType(href_ty))
                                    TypeId.fromInt(href_node.lhs)
                                else
                                    href_ty;
                                try registerFmtTypeRecursive(emitter, hval_ty, 0);
                            }
                        }
                    }
                }
            } else if (inst.op == .intrinsic_op) {
                const ikind: mir.MirIntrinsicKind = @fromBackingInt(inst.aux_u16);
                if (ikind == .fmt_value or ikind == .derive_debug_fmt) {
                    emitter.has_fmt_rt_helpers = true;
                    if (inst.operands.rhs >= 1 and inst.operands.lhs < body_ptr.extra_args.items.len) {
                        const val_raw = body_ptr.extra_args.items[inst.operands.lhs];
                        try registerFmtTypeRecursive(emitter, body_ptr.getInst(MirValueId.fromInt(val_raw)).type_id, 0);
                    }
                } else if (ikind == .panic and !emitter.cfg.target.isFreestanding()) {
                    if (inst.operands.rhs >= 1 and inst.operands.lhs < body_ptr.extra_args.items.len) {
                        const p_raw = body_ptr.extra_args.items[inst.operands.lhs];
                        if ((try unwrapTransparentType(emitter, body_ptr.getInst(MirValueId.fromInt(p_raw)).type_id)) == .fmt_args_ty) {
                            emitter.has_fmt_rt_helpers = true;
                        }
                    }
                } else if (ikind == .drop_in_place or ikind == .drop_if_live) {
                    const place_ty = resolvePlaceResultType(emitter, body_ptr, PlaceId.fromInt(inst.operands.lhs));
                    const dropped_ty = if (inst.type_id != .unit_ty and !inst.type_id.isError())
                        inst.type_id
                    else
                        place_ty;
                    try registerDropTypeRecursive(emitter, dropped_ty, 0);
                } else if (ikind == .ptr_drop_in_place) {
                    const drop_args = body_ptr.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
                    if (drop_args.len >= 1) {
                        const ptr_ty = emitter.input.pool.unwrapUnderlyingType(
                            body_ptr.getInst(MirValueId.fromInt(drop_args[0])).type_id,
                        );
                        if (!ptr_ty.isPrimitiveOrSentinel()) {
                            try registerDropTypeRecursive(
                                emitter,
                                TypeId.fromInt(emitter.input.pool.getNode(ptr_ty).lhs),
                                0,
                            );
                        }
                    }
                } else if (ikind == .soa_vec_clear) {
                    emitter.has_soa_vec = true;
                    const clr_args = body_ptr.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
                    if (clr_args.len >= 1) {
                        const ref_ty = emitter.input.pool.unwrapUnderlyingType(
                            body_ptr.getInst(MirValueId.fromInt(clr_args[0])).type_id,
                        );
                        if (!ref_ty.isPrimitiveOrSentinel()) {
                            try registerDropTypeRecursive(
                                emitter,
                                TypeId.fromInt(emitter.input.pool.getNode(ref_ty).lhs),
                                0,
                            );
                        }
                    }
                } else if (ikind == .soa_vec_new or
                    ikind == .soa_vec_with_cap or
                    ikind == .soa_vec_push or
                    ikind == .soa_vec_reserve or
                    ikind == .soa_vec_as_slice)
                {
                    emitter.has_soa_vec = true;
                    if (ikind == .soa_vec_push) {
                        const push_args = body_ptr.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
                        if (push_args.len >= 2) {
                            try registerDropTypeRecursive(
                                emitter,
                                body_ptr.getInst(MirValueId.fromInt(push_args[1])).type_id,
                                0,
                            );
                        }
                    }
                } else if (ikind == .ctx_next_rng_seed) {
                    if (emitter.cfg.target.ptrBytes() < 8) {
                        emitter.ctx_wide_slot_sizes[2] = @max(emitter.ctx_wide_slot_sizes[2], 8);
                        emitter.ctx_wide_slot_aligns[2] = @max(emitter.ctx_wide_slot_aligns[2], 8);
                    }
                } else if (ikind == .tls_scratch_ptr) {
                    emitter.has_tls_scratch = true;
                } else if (ikind == .tls_alloc_state) {
                    emitter.has_tls_alloc = true;
                } else if (ikind == .sys_mmap or ikind == .sys_munmap) {
                    emitter.has_sys_mmap = true;
                } else if (ikind == .fmt_write) {
                    emitter.has_fmt_write = true;
                    if (!emitter.cfg.target.isFreestanding()) {
                        emitter.has_fmt_rt_helpers = true;
                    }
                } else if (ikind == .type_name) {
                    const refl_raw = inst.operands.lhs;
                    var has_tn = false;
                    for (emitter.type_name_ids.items) |existing_tn| {
                        if (existing_tn == refl_raw) {
                            has_tn = true;
                            break;
                        }
                    }
                    if (!has_tn) {
                        try emitter.type_name_ids.append(emitter.allocator, refl_raw);
                    }
                } else if (ikind == .ctx_get or ikind == .ctx_set) {
                    const call_args = body_ptr.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
                    const slot_val_ty = if (ikind == .ctx_get)
                        inst.type_id
                    else if (call_args.len >= 2)
                        body_ptr.getInst(MirValueId.fromInt(call_args[1])).type_id
                    else
                        .unit_ty;
                    const slot_lay = try emitter.resolver.resolveType(slot_val_ty);
                    const ctx_stride: u64 = emitter.cfg.target.ptrBytes();
                    if (slot_lay.size_bytes > ctx_stride and call_args.len >= 1) {
                        const ord_inst = body_ptr.getInst(MirValueId.fromInt(call_args[0]));
                        if (ord_inst.op == .const_scalar and ord_inst.operands.lhs < body_ptr.consts.items.len) {
                            switch (body_ptr.consts.items[ord_inst.operands.lhs]) {
                                .int_val => |iv| {
                                    const ord_u: usize = @intCast(@as(u128, @bitCast(iv)) % 10);
                                    emitter.ctx_wide_slot_sizes[ord_u] = @max(
                                        emitter.ctx_wide_slot_sizes[ord_u],
                                        slot_lay.size_bytes,
                                    );
                                    emitter.ctx_wide_slot_aligns[ord_u] = @max(
                                        emitter.ctx_wide_slot_aligns[ord_u],
                                        slot_lay.alignBytes(),
                                    );
                                },
                                else => {},
                            }
                        } else {
                            for (0..10) |ord_u| {
                                emitter.ctx_wide_slot_sizes[ord_u] = @max(
                                    emitter.ctx_wide_slot_sizes[ord_u],
                                    slot_lay.size_bytes,
                                );
                                emitter.ctx_wide_slot_aligns[ord_u] = @max(
                                    emitter.ctx_wide_slot_aligns[ord_u],
                                    slot_lay.alignBytes(),
                                );
                            }
                        }
                    }
                } else if (ikind == .async_spawn and emitter.has_async_ops) {
                    const spawn_args = body_ptr.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
                    if (spawn_args.len >= 3) {
                        const fut_ty = emitter.input.pool.unwrapUnderlyingType(
                            body_ptr.getInst(MirValueId.fromInt(spawn_args[2])).type_id,
                        );
                        if (emitter.input.pool.isFutureType(fut_ty)) {
                            try maybeRegisterResultErrCheckTypeLlvm(
                                emitter,
                                emitter.input.pool.getFutureOutputType(fut_ty) orelse .unit_ty,
                            );
                        }
                    }
                }
            }
        }
        for (body_ptr.calls.items) |call_site| {
            if (!(try cand_set.getOrPut(emitter.allocator, call_site.ret_ty.toU32())).found_existing) {
                try candidate_types.append(emitter.allocator, call_site.ret_ty);
            }
            if (!call_site.direct_def_id.isNone() or !call_site.direct_symbol.isNone()) {
                try maybeRegisterExternSymbol(
                    emitter,
                    &extern_set,
                    call_site.direct_def_id,
                    call_site.direct_symbol,
                );
            }
        }
    }

    // Sort candidate types ascending by `TypeId.toU32()` before topological DFS (`DR-01`).
    std.mem.sort(TypeId, candidate_types.items, {}, struct {
        /// Orders candidate `TypeId` handles ascending by raw integer ID.
        fn lessThan(_: void, lhs_id: TypeId, rhs_id: TypeId) bool {
            return lhs_id.toU32() < rhs_id.toU32();
        }
    }.lessThan);
    for (candidate_types.items) |cand_ty| {
        try collectCompositeType(emitter, cand_ty, 0);
    }

    std.mem.sort(u32, emitter.str_sym_ids.items, {}, std.sort.asc(u32));
    std.mem.sort(u32, emitter.type_name_ids.items, {}, std.sort.asc(u32));
    std.mem.sort(u32, emitter.blob_ids.items, {}, std.sort.asc(u32));
    std.mem.sort(SymbolIndex, emitter.extern_syms.items, {}, struct {
        /// Orders external `SymbolIndex` handles ascending by raw integer index.
        fn lessThan(_: void, lhs_s: SymbolIndex, rhs_s: SymbolIndex) bool {
            return lhs_s.asInt() < rhs_s.asInt();
        }
    }.lessThan);
    std.mem.sort(SymbolIndex, emitter.extern_global_syms.items, {}, struct {
        /// Orders external global `SymbolIndex` handles ascending by raw integer index.
        fn lessThan(_: void, lhs_s: SymbolIndex, rhs_s: SymbolIndex) bool {
            return lhs_s.asInt() < rhs_s.asInt();
        }
    }.lessThan);
}

// --------------- ABI Signature & Coercion Layer ---------------

/// Resolves the LLVM calling-convention prefix (`"swiftcc "` or `""`) for `recipe`.
fn resolveCallingConvPrefix(recipe: *const AbiFnRecipe) []const u8 {
    return switch (recipe.calling_conv) {
        .cx_native, .cx_result_cc => "swiftcc ",
        .c_system, .wasm_mvp => "",
    };
}

/// Formats the lowered LLVM register/pointer type for `param_rec` and CoreX `raw_ty`.
fn formatAbiParamOrRetType(
    emitter: *LlvmModuleEmitter,
    raw_ty: TypeId,
    param_rec: AbiParamRecipe,
) ![]u8 {
    const ty = try unwrapTransparentType(emitter, raw_ty);
    return switch (param_rec.pass_mode) {
        .ignore_zst => emitter.allocator.dupe(u8, "void"),
        .indirect_by_ref, .indirect_byval, .sret_ptr, .swifterror_ptr => emitter.allocator.dupe(u8, "ptr"),
        .direct_scalar => {
            if (ty == .bool_ty) return emitter.allocator.dupe(u8, "i1");
            if (ty == .f32_ty) return emitter.allocator.dupe(u8, "float");
            if (ty == .f64_ty or ty == .untyped_float_ty) return emitter.allocator.dupe(u8, "double");
            if (resolveIntegerInfo(emitter, ty)) |int_info| {
                if (int_info.bits <= 64) {
                    return std.fmt.allocPrint(emitter.allocator, "i{d}", .{int_info.bits});
                }
            }
            if (ty == .source_loc_ty or
                ty == .task_group_base_ty or
                ty == .task_handle_base_ty or
                emitter.input.pool.isTaskGroupType(ty) or
                emitter.input.pool.isTaskHandleType(ty))
            {
                return emitter.allocator.dupe(u8, "ptr");
            }
            if (ty == .fmt_spec_ty) {
                return emitter.allocator.dupe(u8, "i64");
            }
            if (!ty.isPrimitiveOrSentinel()) {
                const tag = emitter.input.pool.getNode(ty).tag;
                if ((tag == .ref_ty or tag == .mut_ref_ty or tag == .raw_ptr_ty or tag == .fn_ty) and
                    !emitter.input.pool.isSliceRefType(ty))
                {
                    return emitter.allocator.dupe(u8, "ptr");
                }
                if (emitter.cfg.target.isWasm() and
                    !emitter.input.pool.isSoaSliceOrRefType(ty) and
                    (tag == .slice_ty or tag == .closure_ty or
                        emitter.input.pool.isSliceRefType(ty)))
                {
                    return emitter.allocator.dupe(u8, "i64");
                }
            }
            if ((ty == .str_ty or ty == .bencher_ty) and emitter.cfg.target.isWasm()) {
                return emitter.allocator.dupe(u8, "i64");
            }
            if (param_rec.bank_0 == .xmm_vec) {
                return emitter.allocator.dupe(
                    u8,
                    if (param_rec.lowered_size_bytes <= 4) "float" else "double",
                );
            }
            if (emitter.cfg.target.arch == .aarch64 and
                emitter.cfg.target.isWindows() and
                resolveIntegerInfo(emitter, ty) == null and
                ty != .bool_ty and
                ty != .char_ty)
            {
                return emitter.allocator.dupe(u8, "i64");
            }
            const sz = param_rec.lowered_size_bytes;
            if (sz <= 1) return emitter.allocator.dupe(u8, "i8");
            if (sz == 2) return emitter.allocator.dupe(u8, "i16");
            if (sz <= 4) return emitter.allocator.dupe(u8, "i32");
            return emitter.allocator.dupe(u8, "i64");
        },
        .direct_pair => {
            if (resolveIntegerInfo(emitter, ty)) |int_info| {
                if (int_info.bits == 128) {
                    return emitter.allocator.dupe(u8, "i128");
                }
            }
            if (!emitter.cfg.target.isWasm()) {
                if (ty == .str_ty or ty == .bencher_ty) return emitter.allocator.dupe(u8, "{ ptr, i64 }");
                if (!ty.isPrimitiveOrSentinel()) {
                    const tag = emitter.input.pool.getNode(ty).tag;
                    if (!emitter.input.pool.isSoaSliceOrRefType(ty) and
                        (tag == .slice_ty or emitter.input.pool.isSliceRefType(ty)))
                    {
                        return emitter.allocator.dupe(u8, "{ ptr, i64 }");
                    }
                    if (tag == .closure_ty) {
                        return emitter.allocator.dupe(u8, "{ ptr, ptr }");
                    }
                }
            }
            if (emitter.cfg.target.arch == .aarch64 and
                param_rec.bank_0 == .gpr and
                param_rec.bank_1 == .gpr)
            {
                return emitter.allocator.dupe(u8, "[2 x i64]");
            }
            const p0 = if (param_rec.bank_0 == .xmm_vec) "double" else "i64";
            const p1 = if (param_rec.bank_1 == .xmm_vec)
                (if (param_rec.lowered_size_bytes == 12) "float" else "double")
            else
                "i64";
            return std.fmt.allocPrint(emitter.allocator, "{{ {s}, {s} }}", .{ p0, p1 });
        },
        .direct_quad => {
            if (!ty.isPrimitiveOrSentinel() and
                emitter.input.pool.getNode(ty).tag == .closure_ty and
                param_rec.piece_count <= 3)
            {
                return emitter.allocator.dupe(u8, "{ ptr, ptr, ptr }");
            }
            if (ty == .fmt_args_ty) {
                return emitter.allocator.dupe(
                    u8,
                    if (emitter.cfg.target.isWasm()) "{ ptr, i32, ptr, i32 }" else "{ ptr, i64, ptr, i64 }",
                );
            }
            if (param_rec.piece_count <= 3) {
                return emitter.allocator.dupe(
                    u8,
                    if (param_rec.lowered_size_bytes <= 12) "{ i32, i32, i32 }" else "{ i64, i64, i64 }",
                );
            }
            return emitter.allocator.dupe(u8, "{ i64, i64, i64, i64 }");
        },
        .direct_hfa => {
            const lane_count: u32 = @max(param_rec.piece_count, 1);
            const lane_str = if (param_rec.lowered_size_bytes == lane_count * 4) "float" else "double";
            return std.fmt.allocPrint(emitter.allocator, "[{d} x {s}]", .{ lane_count, lane_str });
        },
    };
}

/// Computes the byte size of an ABI register piece/aggregate type string in O(1).
fn computeAbiTypeByteSize(emitter: *const LlvmModuleEmitter, abi_ty: []const u8) u64 {
    const ptr_bytes: u64 = emitter.cfg.target.ptrBytes();
    if (std.mem.eql(u8, abi_ty, "ptr")) return ptr_bytes;
    if (std.mem.eql(u8, abi_ty, "{ ptr, ptr }")) return 2 * ptr_bytes;
    if (std.mem.eql(u8, abi_ty, "{ ptr, ptr, ptr }")) return 3 * ptr_bytes;
    if (ABI_TYPE_BYTE_SIZE_MAP.get(abi_ty)) |fixed_sz| return fixed_sz;
    if (abi_ty.len > 4 and abi_ty[0] == '[') {
        if (std.mem.indexOfScalar(u8, abi_ty, ' ')) |sp_idx| {
            const count = std.fmt.parseInt(u64, abi_ty[1..sp_idx], 10) catch 1;
            const is_f32 = std.mem.indexOf(u8, abi_ty, "float") != null;
            return count * (if (is_f32) @as(u64, 4) else @as(u64, 8));
        }
    }
    return 16;
}

/// Formats LLVM parameter attributes for `param_rec` (`ptr noalias nonnull …` or `i32 zeroext …`).
fn formatAbiParamDeclPiece(
    emitter: *LlvmModuleEmitter,
    raw_ty: TypeId,
    param_rec: AbiParamRecipe,
    maybe_name: ?[]const u8,
) ![]u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    errdefer buf.deinit(emitter.allocator);
    const attrs = param_rec.attrs();

    switch (param_rec.pass_mode) {
        .ignore_zst => return buf.toOwnedSlice(emitter.allocator),
        .swifterror_ptr => {
            // Emit bare `ptr swifterror` with zero extra pointer attributes:
            try buf.appendSlice(emitter.allocator, "ptr swifterror");
        },
        .sret_ptr => {
            const mem_ty = try formatLlvmMemoryType(emitter, raw_ty);
            defer emitter.allocator.free(mem_ty);
            const part = try std.fmt.allocPrint(
                emitter.allocator,
                "ptr noalias nonnull writeonly nocapture align {d} sret({s})",
                .{ @max(param_rec.pointee_align_bytes, 1), mem_ty },
            );
            defer emitter.allocator.free(part);
            try buf.appendSlice(emitter.allocator, part);
        },
        .indirect_byval => {
            const mem_ty = try formatLlvmMemoryType(emitter, raw_ty);
            defer emitter.allocator.free(mem_ty);
            const part = try std.fmt.allocPrint(
                emitter.allocator,
                "ptr byval({s}) align {d}",
                .{ mem_ty, @max(param_rec.pointee_align_bytes, 1) },
            );
            defer emitter.allocator.free(part);
            try buf.appendSlice(emitter.allocator, part);
        },
        .indirect_by_ref => {
            try buf.appendSlice(emitter.allocator, "ptr");
            if (attrs.is_noalias) try buf.appendSlice(emitter.allocator, " noalias");
            if (attrs.is_nonnull) try buf.appendSlice(emitter.allocator, " nonnull");
            if (attrs.is_noundef) try buf.appendSlice(emitter.allocator, " noundef");
            if (attrs.is_readonly) try buf.appendSlice(emitter.allocator, " readonly");
            if (attrs.is_writeonly) try buf.appendSlice(emitter.allocator, " writeonly");
            if (attrs.is_nocapture) try buf.appendSlice(emitter.allocator, " nocapture");
            const align_part = try std.fmt.allocPrint(
                emitter.allocator,
                " align {d}",
                .{@max(param_rec.pointee_align_bytes, 1)},
            );
            defer emitter.allocator.free(align_part);
            try buf.appendSlice(emitter.allocator, align_part);
            if (param_rec.lowered_size_bytes > 0 and !attrs.is_writeonly) {
                const deref_part = try std.fmt.allocPrint(
                    emitter.allocator,
                    " dereferenceable({d})",
                    .{param_rec.lowered_size_bytes},
                );
                defer emitter.allocator.free(deref_part);
                try buf.appendSlice(emitter.allocator, deref_part);
            }
        },
        .direct_scalar, .direct_pair, .direct_quad, .direct_hfa => {
            const abi_ty = try formatAbiParamOrRetType(emitter, raw_ty, param_rec);
            defer emitter.allocator.free(abi_ty);
            try buf.appendSlice(emitter.allocator, abi_ty);
            const is_ptr_ty = std.mem.eql(u8, abi_ty, "ptr");
            const is_int_ty = abi_ty.len >= 2 and abi_ty[0] == 'i' and std.ascii.isDigit(abi_ty[1]);
            if (is_int_ty and attrs.is_zext) try buf.appendSlice(emitter.allocator, " zeroext");
            if (is_int_ty and attrs.is_sext) try buf.appendSlice(emitter.allocator, " signext");
            if (is_ptr_ty and attrs.is_nonnull) try buf.appendSlice(emitter.allocator, " nonnull");
            if ((is_ptr_ty or is_int_ty or std.mem.eql(u8, abi_ty, "float") or
                std.mem.eql(u8, abi_ty, "double")) and attrs.is_noundef)
            {
                try buf.appendSlice(emitter.allocator, " noundef");
            }
        },
    }

    if (maybe_name) |arg_name| {
        try buf.append(emitter.allocator, ' ');
        try buf.appendSlice(emitter.allocator, arg_name);
    }
    return buf.toOwnedSlice(emitter.allocator);
}

/// Formats the LLVM return attribute + type prefix (e.g., `"zeroext i8"` or `"void"`) for `recipe`.
fn formatAbiReturnDecl(
    emitter: *LlvmModuleEmitter,
    sig_ret_ty: TypeId,
    recipe: *const AbiFnRecipe,
) !struct { full_decl: []u8, bare_ty: []u8 } {
    if (recipe.has_sret or recipe.ret_recipe.pass_mode == .ignore_zst) {
        return .{
            .full_decl = try emitter.allocator.dupe(u8, "void"),
            .bare_ty = try emitter.allocator.dupe(u8, "void"),
        };
    }
    const eff_ty = if (recipe.calling_conv == .cx_result_cc) recipe.ok_ty else sig_ret_ty;
    const bare_ty = try formatAbiParamOrRetType(emitter, eff_ty, recipe.ret_recipe);
    errdefer emitter.allocator.free(bare_ty);

    const attrs = recipe.ret_recipe.attrs();
    var prefix: std.ArrayListUnmanaged(u8) = .empty;
    errdefer prefix.deinit(emitter.allocator);

    const is_ptr_ty = std.mem.eql(u8, bare_ty, "ptr");
    const is_int_ty = bare_ty.len >= 2 and bare_ty[0] == 'i' and std.ascii.isDigit(bare_ty[1]);
    if (is_int_ty and attrs.is_zext) try prefix.appendSlice(emitter.allocator, "zeroext ");
    if (is_int_ty and attrs.is_sext) try prefix.appendSlice(emitter.allocator, "signext ");
    if (is_ptr_ty and attrs.is_nonnull) try prefix.appendSlice(emitter.allocator, "nonnull ");
    if ((is_ptr_ty or is_int_ty or std.mem.eql(u8, bare_ty, "float") or
        std.mem.eql(u8, bare_ty, "double")) and attrs.is_noundef)
    {
        try prefix.appendSlice(emitter.allocator, "noundef ");
    }
    try prefix.appendSlice(emitter.allocator, bare_ty);
    return .{
        .full_decl = try prefix.toOwnedSlice(emitter.allocator),
        .bare_ty = bare_ty,
    };
}

/// Emits `@llvm.memset.p0.i64` zeroing `size_bytes` at `ptr_str`.
fn emitMemsetZero(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    ptr_str: []const u8,
    size_bytes: u64,
    align_bytes: u32,
) !void {
    if (size_bytes == 0) return;
    try emitter.requireIntrinsicDecl(
        "declare void @llvm.memset.p0.i64(ptr nocapture writeonly, i8, i64, i1 immarg)",
    );
    try state.print(
        "  call void @llvm.memset.p0.i64(ptr align {d} {s}, i8 0, i64 {d}, i1 false)\n",
        .{ @max(align_bytes, 1), ptr_str, size_bytes },
    );
}

/// Emits `@llvm.memcpy.p0.p0.i64` copying `size_bytes` from `src_ptr` to `dst_ptr`.
fn emitMemcpyBytes(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    dst_ptr: []const u8,
    dst_align: u32,
    src_ptr: []const u8,
    src_align: u32,
    size_bytes: u64,
) !void {
    if (size_bytes == 0) return;
    try emitter.requireIntrinsicDecl(
        "declare void @llvm.memcpy.p0.p0.i64(ptr noalias nocapture writeonly, " ++
            "ptr noalias nocapture readonly, i64, i1 immarg)",
    );
    try state.print(
        "  call void @llvm.memcpy.p0.p0.i64(ptr align {d} {s}, ptr align {d} {s}, i64 {d}, i1 false)\n",
        .{ @max(dst_align, 1), dst_ptr, @max(src_align, 1), src_ptr, size_bytes },
    );
}

/// Packs a CoreX SSA value `val_str` of `raw_ty` into `abi_ty` (zero-copy when types already match).
fn emitCoerceValueToAbi(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    raw_ty: TypeId,
    val_str: []const u8,
    abi_ty: []const u8,
) ![]u8 {
    const val_ty = try formatLlvmValueType(emitter, raw_ty);
    defer emitter.allocator.free(val_ty);
    if (std.mem.eql(u8, val_ty, abi_ty)) {
        return emitter.allocator.dupe(u8, val_str);
    }

    const lay = try emitter.resolver.resolveType(raw_ty);
    const scratch_sz = @max(lay.size_bytes, computeAbiTypeByteSize(emitter, abi_ty));
    const eff_align = @max(lay.alignBytes(), 8);
    const slot = try state.allocEntryBytes(scratch_sz, eff_align);
    defer emitter.allocator.free(slot);

    try emitMemsetZero(emitter, state, slot, scratch_sz, eff_align);
    try emitStoreValueToPtr(emitter, state, raw_ty, val_str, slot, eff_align, 0, 0, 0);

    const out_tmp = state.nextTmp();
    try state.print(
        "  %_abi_pk_{d} = load {s}, ptr {s}, align {d}\n",
        .{ out_tmp, abi_ty, slot, eff_align },
    );
    return std.fmt.allocPrint(emitter.allocator, "%_abi_pk_{d}", .{out_tmp});
}

/// Unpacks an ABI register value `abi_val_str` of `abi_ty` into a CoreX SSA value of `raw_ty`.
fn emitCoerceAbiToValue(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    raw_ty: TypeId,
    abi_ty: []const u8,
    abi_val_str: []const u8,
) ![]u8 {
    const val_ty = try formatLlvmValueType(emitter, raw_ty);
    defer emitter.allocator.free(val_ty);
    if (std.mem.eql(u8, val_ty, abi_ty)) {
        return emitter.allocator.dupe(u8, abi_val_str);
    }

    const lay = try emitter.resolver.resolveType(raw_ty);
    const scratch_sz = @max(lay.size_bytes, computeAbiTypeByteSize(emitter, abi_ty));
    const eff_align = @max(lay.alignBytes(), 8);
    const slot = try state.allocEntryBytes(scratch_sz, eff_align);
    defer emitter.allocator.free(slot);

    try emitMemsetZero(emitter, state, slot, scratch_sz, eff_align);
    if (abi_ty.len > 0 and !std.mem.eql(u8, abi_ty, "void")) {
        try state.print(
            "  store {s} {s}, ptr {s}, align {d}\n",
            .{ abi_ty, abi_val_str, slot, eff_align },
        );
    }
    return emitLoadValueFromPtr(emitter, state, raw_ty, slot, eff_align, null, 0, 0, 0);
}

// ---------- Global `.rodata`, `--dev` Seam & Runtime ----------

/// Appends an LLVM byte-array literal `c"…"` (escaping non-printable bytes as `\XX`) to `emitter.out`.
fn writeLlvmByteStringLiteral(emitter: *LlvmModuleEmitter, bytes: []const u8) !void {
    try emitter.writeAll("c\"");
    for (bytes) |byte_val| {
        if (byte_val >= 0x20 and byte_val <= 0x7E and byte_val != '"' and byte_val != '\\') {
            try emitter.out.append(emitter.allocator, byte_val);
        } else {
            try emitter.print("\\{X:0>2}", .{byte_val});
        }
    }
    try emitter.writeAll("\"");
}

/// Appends an LLVM NUL-terminated byte-array literal `c"…\00"` (`bytes.len + 1` bytes) to `emitter.out`.
fn writeLlvmNullTerminatedStringLiteral(emitter: *LlvmModuleEmitter, bytes: []const u8) !void {
    try emitter.writeAll("c\"");
    for (bytes) |byte_val| {
        if (byte_val >= 0x20 and byte_val <= 0x7E and byte_val != '"' and byte_val != '\\') {
            try emitter.out.append(emitter.allocator, byte_val);
        } else {
            try emitter.print("\\{X:0>2}", .{byte_val});
        }
    }
    try emitter.writeAll("\\00\"");
}

/// Builds serialized `.cx_dev_meta` binary metadata (`DR-19` §1.2) for `--dev` GOT builds.
fn buildDevSeamBytes(emitter: *LlvmModuleEmitter) ![]u8 {
    var got_slots = try emitter.allocator.alloc(
        codegen_dev_seam.CxGotSlotMeta,
        emitter.input.bodies.len,
    );
    defer if (got_slots.len > 0) emitter.allocator.free(got_slots);

    var total_loop_contracts: u32 = 0;
    for (emitter.input.bodies, 0..) |*body_ptr, body_i| {
        total_loop_contracts +|= @intCast(body_ptr.loop_contracts.items.len);
        const body_rec = &emitter.body_recipes.items[body_i];
        got_slots[body_i] = .{
            .def_id = body_ptr.def_id,
            .got_idx = @intCast(body_i),
            .abi_sig_hash64 = body_rec.abiSigHash64(),
            .slot_kind = .direct_fn,
        };
    }

    const type_records = try query_db.collectModuleDevTypeRecords(
        emitter.allocator,
        emitter.input.bodies,
        emitter.input.pool,
        emitter.input.sym_table,
        emitter.target_layout,
    );
    defer if (type_records.len > 0) emitter.allocator.free(type_records);

    const header = codegen_dev_seam.CxDevSeamHeader{
        .arch_os_tag = emitter.cfg.target.archOsTag(),
        .got_slot_count = @intCast(got_slots.len),
        .type_record_count = @intCast(type_records.len),
        .loop_contract_count = total_loop_contracts,
    };
    return codegen_dev_seam.serializeDevSeamMeta(
        emitter.allocator,
        header,
        got_slots,
        type_records,
    );
}

/// Emits `.rodata` constants, `--dev` GOT / `ErrorReturnTrace` globals, and self-contained runtime helpers.
fn emitRodataAndRuntimeHelpers(
    emitter: *LlvmModuleEmitter,
    dev_seam_out: *?[]u8,
) !void {
    const ptr_int = ptrIntType(emitter);

    // [1] Default 10-slot thread-local `Context` storage (`80B` on 64-bit, `40B` on `wasm32`):
    const ctx_tls_kw = if (emitter.cfg.target.isWasm()) "internal global" else "internal thread_local global";
    const ctx_ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const ctx_bytes = type_system.ContextFieldLayout.byteSizeForPtrWidth(emitter.cfg.target.ptrBytes());
    try emitter.print(
        "@_cx_default_ctx = {s} [{d} x i8] zeroinitializer, align {d}\n",
        .{ ctx_tls_kw, ctx_bytes, ctx_ptr_bytes },
    );
    for (emitter.ctx_wide_slot_sizes, 0..) |wide_sz, slot_i| {
        if (wide_sz > ctx_ptr_bytes) {
            try emitter.print(
                "@_cx_ctx_wide_{d} = {s} [{d} x i8] zeroinitializer, align {d}\n",
                .{ slot_i, ctx_tls_kw, wide_sz, emitter.ctx_wide_slot_aligns[slot_i] },
            );
        }
    }

    // [2] Interned string and byte literals (`@_cx_str_bytes_<id>`) & `@type_name` tables:
    try emitter.writeAll("@_cx_empty_cstr = private unnamed_addr constant [1 x i8] zeroinitializer, align 1\n");
    for (emitter.str_sym_ids.items) |sym_raw| {
        const bytes = emitter.input.interner.get(SymbolId.fromInt(sym_raw));
        if (bytes.len == 0) continue;
        try emitter.print(
            "@_cx_str_bytes_{d} = private unnamed_addr constant [{d} x i8] ",
            .{ sym_raw, bytes.len + 1 },
        );
        try writeLlvmNullTerminatedStringLiteral(emitter, bytes);
        try emitter.writeAll(", align 1\n");
    }
    for (emitter.type_name_ids.items) |ty_u32| {
        var name_buf: [512]u8 = undefined;
        const rendered = emitter.input.pool.formatType(
            TypeId.fromInt(ty_u32),
            emitter.input.sym_table,
            &name_buf,
        );
        if (rendered.len == 0) continue;
        try emitter.print(
            "@_cx_tyname_{d} = private unnamed_addr constant [{d} x i8] ",
            .{ ty_u32, rendered.len + 1 },
        );
        try writeLlvmNullTerminatedStringLiteral(emitter, rendered);
        try emitter.writeAll(", align 1\n");
    }
    for (emitter.source_loc_consts.items, 0..) |sloc, loc_idx| {
        const file_bytes = emitter.input.interner.get(sloc.file_sym);
        const fn_bytes = emitter.input.interner.get(sloc.fn_sym);
        const file_ptr_s = if (file_bytes.len == 0)
            try emitter.allocator.dupe(u8, "@_cx_empty_cstr")
        else
            try std.fmt.allocPrint(emitter.allocator, "@_cx_str_bytes_{d}", .{sloc.file_sym.asInt()});
        defer emitter.allocator.free(file_ptr_s);
        const fn_ptr_s = if (fn_bytes.len == 0)
            try emitter.allocator.dupe(u8, "@_cx_empty_cstr")
        else
            try std.fmt.allocPrint(emitter.allocator, "@_cx_str_bytes_{d}", .{sloc.fn_sym.asInt()});
        defer emitter.allocator.free(fn_ptr_s);
        try emitter.print(
            "@_cx_loc_{d} = private unnamed_addr constant " ++
                "{{ {{ ptr, {s} }}, {{ ptr, {s} }}, i32, i32 }} " ++
                "{{ {{ ptr, {s} }} {{ ptr {s}, {s} {d} }}, " ++
                "{{ ptr, {s} }} {{ ptr {s}, {s} {d} }}, i32 {d}, i32 {d} }}, align {d}\n",
            .{
                loc_idx,
                ptr_int,
                ptr_int,
                ptr_int,
                file_ptr_s,
                ptr_int,
                file_bytes.len,
                ptr_int,
                fn_ptr_s,
                ptr_int,
                fn_bytes.len,
                sloc.line,
                sloc.col,
                emitter.cfg.target.ptrBytes(),
            },
        );
    }

    // [3] `@embed_bytes` raw binary blobs (`MirBlobStore`, `DR-20` `D-03`):
    if (emitter.input.blob_store) |bstore| {
        for (emitter.blob_ids.items) |blob_id| {
            const payload = bstore.getBytes(blob_id) orelse &[_]u8{};
            var align_log2: u8 = 0;
            for (emitter.input.bodies) |*body_ptr| {
                for (body_ptr.consts.items) |mc| {
                    if (mc == .raw_blob and mc.raw_blob.blob_id == blob_id) {
                        align_log2 = @max(align_log2, mc.raw_blob.align_log2);
                    }
                }
            }
            const align_bytes: u32 = @as(u32, 1) << @intCast(align_log2);
            if (payload.len > 0) {
                try emitter.print(
                    "@_cx_blob_{d} = private unnamed_addr constant [{d} x i8] ",
                    .{ blob_id, payload.len },
                );
                try writeLlvmByteStringLiteral(emitter, payload);
                try emitter.print(", align {d}\n", .{align_bytes});
                try emitter.print(
                    "@_cx_blob_slice_{d} = internal constant {{ ptr, {s} }} " ++
                        "{{ ptr @_cx_blob_{d}, {s} {d} }}, align {d}\n",
                    .{ blob_id, ptr_int, blob_id, ptr_int, payload.len, emitter.cfg.target.ptrBytes() },
                );
            } else {
                try emitter.print(
                    "@_cx_blob_slice_{d} = internal constant {{ ptr, {s} }} " ++
                        "{{ ptr inttoptr ({s} {d} to ptr), {s} 0 }}, align {d}\n",
                    .{ blob_id, ptr_int, ptr_int, align_bytes, ptr_int, emitter.cfg.target.ptrBytes() },
                );
            }
        }
    }

    // [4] Promoted `RodataPool` blobs:
    if (emitter.input.rodata_pool) |rpool| {
        for (rpool.blobs.items, 0..) |rblob, r_idx| {
            const align_bytes: u32 = @as(u32, 1) << @intCast(rblob.align_log2);
            const eff_bytes = if (rblob.bytes.len > 0) rblob.bytes else &[_]u8{0};
            try emitter.print(
                "@_cx_rodata_{d} = private unnamed_addr constant [{d} x i8] ",
                .{ r_idx, eff_bytes.len },
            );
            try writeLlvmByteStringLiteral(emitter, eff_bytes);
            try emitter.print(", align {d}\n", .{align_bytes});
        }
    }

    // [5] `--dev` 16-slot thread-local `ErrorReturnTrace` (`0` bytes in `--release`, `D-06B`):
    if (!emitter.cfg.is_release_mode) {
        const tls_kw = if (emitter.cfg.target.isWasm()) "internal global" else "internal thread_local global";
        try emitter.print(
            "@_cx_err_trace = {s} {{ [16 x {s}], i32, i32 }} zeroinitializer, align 8\n",
            .{ tls_kw, ptr_int },
        );
    }

    // [6] `--dev` hot-reload GOT table (`@_cx_dev_got`) and control block (`@_cx_reload_ctrl`, `DR-19`):
    if (emitter.input.is_dev_got_enabled) {
        const slot_count = @max(emitter.input.bodies.len, 1);
        try emitter.print("@_cx_dev_got = internal global [{d} x ptr] [", .{slot_count});
        if (emitter.input.bodies.len == 0) {
            try emitter.writeAll("ptr null");
        } else {
            for (emitter.body_llvm_names.items, 0..) |fn_name, idx| {
                if (idx > 0) try emitter.writeAll(", ");
                const fn_ident = try formatLlvmGlobalIdent(emitter.allocator, fn_name);
                defer emitter.allocator.free(fn_ident);
                try emitter.print("ptr {s}", .{fn_ident});
            }
        }
        try emitter.print("], align {d}\n", .{emitter.cfg.target.ptrBytes()});
        try emitter.writeAll(
            "@_cx_reload_ctrl = internal global { i64, i64, i64, i32, i32, i32, i32, i64, i32, i32, i64 } " ++
                "{ i64 0, i64 0, i64 0, i32 1, i32 0, i32 0, i32 0, i64 0, i32 -1, i32 0, i64 0 }, align 64\n",
        );
        dev_seam_out.* = try buildDevSeamBytes(emitter);
    }

    // [7] Runtime string constants & libc declarations for oracle tracing, panic, trap, and syscalls:
    const fn_attrs = fnUnwindAttrs(emitter);
    if (emitter.cfg.target.isFreestanding()) {
        if (emitter.has_fmt_rt_helpers) {
            try emitter.writeAll(
                \\@.cx_str_true = private unnamed_addr constant [4 x i8] c"true", align 1
                \\@.cx_str_false = private unnamed_addr constant [5 x i8] c"false", align 1
                \\@.cx_fmt_i64 = private unnamed_addr constant [5 x i8] c"%lld\00", align 1
                \\@.cx_fmt_u64 = private unnamed_addr constant [5 x i8] c"%llu\00", align 1
                \\
            );
            _ = try emitter.markExternDeclared("snprintf");
            try emitter.print("declare i32 @snprintf(ptr, {s}, ptr, ...) nounwind\n", .{ptr_int});
        }
        try emitter.writeAll("declare void @llvm.trap() cold noreturn nounwind\n\n");
        try emitter.print(
            "define internal void @_cx_rt_init() {s} {{\nentry:\n  ret void\n}}\n\n" ++
                "define internal void @_cx_rt_trace_append(ptr %line_ptr, {s} %line_len) {s} {{\n" ++
                "entry:\n  ret void\n}}\n\n" ++
                "define internal void @_cx_rt_trap(i32 %reason) cold noreturn {s} {{\n" ++
                "entry:\n  call void @llvm.trap()\n  unreachable\n}}\n\n" ++
                "define internal {s} @_cx_rt_sys_write(i32 %fd, ptr %buf, {s} %len) {s} {{\n" ++
                "entry:\n  ret {s} -1\n}}\n\n" ++
                "define internal void @_cx_rt_panic(ptr %msg_ptr, {s} %msg_len) cold noreturn {s} {{\n" ++
                "entry:\n  call void @llvm.trap()\n  unreachable\n}}\n\n" ++
                "define internal void @_cx_rt_sys_exit(i32 %code) noreturn {s} {{\n" ++
                "entry:\n  call void @llvm.trap()\n  unreachable\n}}\n\n",
            .{
                fn_attrs,
                ptr_int,
                fn_attrs,
                fn_attrs,
                ptr_int,
                ptr_int,
                fn_attrs,
                ptr_int,
                ptr_int,
                fn_attrs,
                fn_attrs,
            },
        );
    } else {
        try emitter.writeAll(
            \\@.cx_env_oracle = private unnamed_addr constant [24 x i8] c"COREX_ORACLE_TRACE_FILE\00", align 1
            \\@.cx_fmode_ab = private unnamed_addr constant [3 x i8] c"ab\00", align 1
            \\@.cx_msg_trap = private unnamed_addr constant [8 x i8] c"TRAP:1\0A\00", align 1
            \\@.cx_msg_ret0 = private unnamed_addr constant [7 x i8] c"RET:0\0A\00", align 1
            \\@.cx_msg_err1 = private unnamed_addr constant [7 x i8] c"ERR:1\0A\00", align 1
            \\@.cx_fmt_ret_s = private unnamed_addr constant [10 x i8] c"RET:%lld\0A\00", align 1
            \\@.cx_fmt_ret_u = private unnamed_addr constant [10 x i8] c"RET:%llu\0A\00", align 1
            \\@.cx_fmt_drop = private unnamed_addr constant [11 x i8] c"DROP:%lld\0A\00", align 1
            \\@.cx_fmt_exit = private unnamed_addr constant [9 x i8] c"EXIT:%d\0A\00", align 1
            \\@.cx_panic_pfx = private unnamed_addr constant [7 x i8] c"panic: ", align 1
            \\@.cx_panic_nl = private unnamed_addr constant [1 x i8] c"\0A", align 1
            \\@.cx_str_true = private unnamed_addr constant [4 x i8] c"true", align 1
            \\@.cx_str_false = private unnamed_addr constant [5 x i8] c"false", align 1
            \\@.cx_fmt_i64 = private unnamed_addr constant [5 x i8] c"%lld\00", align 1
            \\@.cx_fmt_u64 = private unnamed_addr constant [5 x i8] c"%llu\00", align 1
            \\
            \\declare void @llvm.trap() cold noreturn nounwind
            \\declare ptr @getenv(ptr) nounwind
            \\declare ptr @fopen(ptr, ptr) nounwind
            \\declare i32 @fflush(ptr) nounwind
            \\declare i32 @fclose(ptr) nounwind
            \\declare void @_exit(i32) noreturn nounwind
            \\
        );
        _ = try emitter.markExternDeclared("getenv");
        _ = try emitter.markExternDeclared("fopen");
        _ = try emitter.markExternDeclared("fflush");
        _ = try emitter.markExternDeclared("fclose");
        _ = try emitter.markExternDeclared("_exit");
        _ = try emitter.markExternDeclared("fwrite");
        _ = try emitter.markExternDeclared("snprintf");
        try emitter.print(
            "declare {s} @fwrite(ptr, {s}, {s}, ptr) nounwind\n" ++
                "declare i32 @snprintf(ptr, {s}, ptr, ...) nounwind\n",
            .{ ptr_int, ptr_int, ptr_int, ptr_int },
        );
        if (emitter.cfg.target.isWindows()) {
            _ = try emitter.markExternDeclared("_setmode");
            _ = try emitter.markExternDeclared("_write");
            try emitter.writeAll(
                "declare i32 @_setmode(i32, i32) nounwind\n" ++
                    "declare i32 @_write(i32, ptr, i32) nounwind\n\n",
            );
        } else {
            _ = try emitter.markExternDeclared("write");
            try emitter.print("declare {s} @write(i32, ptr, {s}) nounwind\n\n", .{ ptr_int, ptr_int });
        }

        // `@_cx_rt_init` sets `_O_BINARY` (`0x8000`) on Windows `stdout`/`stderr` so `\n` is never mangled:
        try emitter.print("define internal void @_cx_rt_init() {s} {{\nentry:\n", .{fn_attrs});
        if (emitter.cfg.target.isWindows()) {
            try emitter.writeAll(
                "  %_sm1 = call i32 @_setmode(i32 1, i32 32768)\n" ++
                    "  %_sm2 = call i32 @_setmode(i32 2, i32 32768)\n",
            );
        }
        try emitter.writeAll("  ret void\n}\n\n");

        // `@_cx_rt_trace_append(ptr %line_ptr, <usize> %line_len)`:
        try emitter.print(
            "define internal void @_cx_rt_trace_append(ptr %line_ptr, {s} %line_len) {s} {{\n" ++
                "entry:\n" ++
                "  %path = call ptr @getenv(ptr @.cx_env_oracle)\n" ++
                "  %has_p = icmp ne ptr %path, null\n" ++
                "  br i1 %has_p, label %chk_nonempty, label %done\n" ++
                "chk_nonempty:\n" ++
                "  %ch0 = load i8, ptr %path, align 1\n" ++
                "  %ok0 = icmp ne i8 %ch0, 0\n" ++
                "  br i1 %ok0, label %open_f, label %done\n" ++
                "open_f:\n" ++
                "  %fp = call ptr @fopen(ptr %path, ptr @.cx_fmode_ab)\n" ++
                "  %ok_fp = icmp ne ptr %fp, null\n" ++
                "  br i1 %ok_fp, label %do_wr, label %done\n" ++
                "do_wr:\n" ++
                "  %_w = call {s} @fwrite(ptr %line_ptr, {s} 1, {s} %line_len, ptr %fp)\n" ++
                "  %_f = call i32 @fflush(ptr %fp)\n" ++
                "  %_c = call i32 @fclose(ptr %fp)\n" ++
                "  br label %done\n" ++
                "done:\n" ++
                "  ret void\n" ++
                "}}\n\n",
            .{ ptr_int, fn_attrs, ptr_int, ptr_int, ptr_int },
        );

        // `@_cx_rt_trap(i32 %reason)` writes `TRAP:1\n` + `_exit(101)` under oracle mode, else `@llvm.trap()`:
        try emitter.print(
            "define internal void @_cx_rt_trap(i32 %reason) cold noreturn {s} {{\n" ++
                "entry:\n" ++
                "  %path = call ptr @getenv(ptr @.cx_env_oracle)\n" ++
                "  %has_p = icmp ne ptr %path, null\n" ++
                "  br i1 %has_p, label %chk_ch, label %hard_trap\n" ++
                "chk_ch:\n" ++
                "  %ch0 = load i8, ptr %path, align 1\n" ++
                "  %ok0 = icmp ne i8 %ch0, 0\n" ++
                "  br i1 %ok0, label %oracle_exit, label %hard_trap\n" ++
                "oracle_exit:\n" ++
                "  call void @_cx_rt_trace_append(ptr @.cx_msg_trap, {s} 7)\n" ++
                "  %_fl_t = call i32 @fflush(ptr null)\n" ++
                "  call void @_exit(i32 101)\n" ++
                "  unreachable\n" ++
                "hard_trap:\n" ++
                "  call void @llvm.trap()\n" ++
                "  unreachable\n" ++
                "}}\n\n",
            .{ fn_attrs, ptr_int },
        );

        // `@_cx_rt_sys_write(i32 %fd, ptr %buf, <usize> %len) -> <isize>`:
        try emitter.print(
            "define internal {s} @_cx_rt_sys_write(i32 %fd, ptr %buf, {s} %len) {s} {{\nentry:\n",
            .{ ptr_int, ptr_int, fn_attrs },
        );
        if (emitter.cfg.target.isWindows()) {
            try emitter.writeAll(
                "  %is_z = icmp eq i64 %len, 0\n" ++
                    "  br i1 %is_z, label %ret_z, label %do_w\n" ++
                    "ret_z:\n" ++
                    "  ret i64 0\n" ++
                    "do_w:\n" ++
                    "  %clamped = call i64 @llvm.umin.i64(i64 %len, i64 2147483647)\n" ++
                    "  %len32 = trunc i64 %clamped to i32\n" ++
                    "  %res32 = call i32 @_write(i32 %fd, ptr %buf, i32 %len32)\n" ++
                    "  %res64 = sext i32 %res32 to i64\n" ++
                    "  ret i64 %res64\n}\n\n",
            );
            try emitter.requireIntrinsicDecl("declare i64 @llvm.umin.i64(i64, i64)");
        } else {
            try emitter.print(
                "  %res = call {s} @write(i32 %fd, ptr %buf, {s} %len)\n  ret {s} %res\n}}\n\n",
                .{ ptr_int, ptr_int, ptr_int },
            );
        }

        // `@_cx_rt_panic(ptr %msg_ptr, <usize> %msg_len)` and `@_cx_rt_sys_exit(i32 %code)`:
        try emitter.print(
            "define internal void @_cx_rt_panic(ptr %msg_ptr, {s} %msg_len) cold noreturn {s} {{\n" ++
                "entry:\n" ++
                "  %_pfx = call {s} @_cx_rt_sys_write(i32 2, ptr @.cx_panic_pfx, {s} 7)\n" ++
                "  %has_m = icmp ne ptr %msg_ptr, null\n" ++
                "  %has_l = icmp ne {s} %msg_len, 0\n" ++
                "  %do_p = and i1 %has_m, %has_l\n" ++
                "  br i1 %do_p, label %wr_m, label %go_trap\n" ++
                "wr_m:\n" ++
                "  %_ign = call {s} @_cx_rt_sys_write(i32 2, ptr %msg_ptr, {s} %msg_len)\n" ++
                "  br label %go_trap\n" ++
                "go_trap:\n" ++
                "  %_nl = call {s} @_cx_rt_sys_write(i32 2, ptr @.cx_panic_nl, {s} 1)\n" ++
                "  call void @_cx_rt_trap(i32 1)\n" ++
                "  unreachable\n" ++
                "}}\n\n" ++
                "define internal void @_cx_rt_sys_exit(i32 %code) noreturn {s} {{\n" ++
                "entry:\n" ++
                "  %ebuf = alloca [64 x i8], align 8\n" ++
                "  %en32 = call i32 (ptr, {s}, ptr, ...) @snprintf(ptr %ebuf, {s} 64, ptr @.cx_fmt_exit, i32 %code)\n" ++
                "  %eok = icmp sgt i32 %en32, 0\n" ++
                "  %ecl = select i1 %eok, i32 %en32, i32 0\n",
            .{
                ptr_int,
                fn_attrs,
                ptr_int,
                ptr_int,
                ptr_int,
                ptr_int,
                ptr_int,
                ptr_int,
                ptr_int,
                fn_attrs,
                ptr_int,
                ptr_int,
            },
        );
        if (emitter.cfg.target.isWasm()) {
            try emitter.writeAll(
                "  call void @_cx_rt_trace_append(ptr %ebuf, i32 %ecl)\n" ++
                    "  %_fl = call i32 @fflush(ptr null)\n" ++
                    "  call void @_exit(i32 %code)\n" ++
                    "  unreachable\n}\n\n",
            );
        } else {
            try emitter.writeAll(
                "  %eln = zext i32 %ecl to i64\n" ++
                    "  call void @_cx_rt_trace_append(ptr %ebuf, i64 %eln)\n" ++
                    "  %_fl = call i32 @fflush(ptr null)\n" ++
                    "  call void @_exit(i32 %code)\n" ++
                    "  unreachable\n}\n\n",
            );
        }
    }

    // `@_cx_record_err_ret(<usize> %site_tag)` in `--dev` mode:
    if (!emitter.cfg.is_release_mode) {
        try emitter.print(
            "define internal void @_cx_record_err_ret({s} %site_tag) {s} {{\n" ++
                "entry:\n" ++
                "  %w_ptr = getelementptr inbounds {{ [16 x {s}], i32, i32 }}, ptr @_cx_err_trace, i32 0, i32 1\n" ++
                "  %w_val = load i32, ptr %w_ptr, align 4\n" ++
                "  %slot_i = and i32 %w_val, 15\n" ++
                "  %pc_ptr = getelementptr inbounds {{ [16 x {s}], i32, i32 }}, " ++
                "ptr @_cx_err_trace, i32 0, i32 0, i32 %slot_i\n" ++
                "  store {s} %site_tag, ptr %pc_ptr, align {d}\n" ++
                "  %w_next = add i32 %w_val, 1\n" ++
                "  store i32 %w_next, ptr %w_ptr, align 4\n" ++
                "  %c_ptr = getelementptr inbounds {{ [16 x {s}], i32, i32 }}, ptr @_cx_err_trace, i32 0, i32 2\n" ++
                "  %c_val = load i32, ptr %c_ptr, align 4\n" ++
                "  %lt16 = icmp ult i32 %c_val, 16\n" ++
                "  %c_inc = add i32 %c_val, 1\n" ++
                "  %c_new = select i1 %lt16, i32 %c_inc, i32 %c_val\n" ++
                "  store i32 %c_new, ptr %c_ptr, align 4\n" ++
                "  ret void\n" ++
                "}}\n\n",
            .{
                ptr_int,                       fn_attrs, ptr_int, ptr_int, ptr_int,
                emitter.cfg.target.ptrBytes(), ptr_int,
            },
        );
    }

    if (emitter.has_tls_scratch) {
        const tls_kw = if (emitter.cfg.target.isWasm()) "internal global" else "internal thread_local global";
        try emitter.print("@_cx_tls_scratch_buf = {s} [8 x i64] zeroinitializer, align 16\n", .{tls_kw});
    }
    if (emitter.has_tls_alloc) {
        const tls_kw = if (emitter.cfg.target.isWasm()) "internal global" else "internal thread_local global";
        try emitter.print("@_cx_tls_alloc_buf = {s} [32 x i64] zeroinitializer, align 16\n", .{tls_kw});
    }
    if (emitter.has_sys_mmap) {
        try emitSysMmapHelpersLlvm(emitter);
    }
    if (emitter.has_soa_vec) {
        try emitSoaSlabHelpersLlvm(emitter);
    }
    if (emitter.has_async_ops) {
        try emitAsyncRuntimeHelpersLlvm(emitter);
    }
}

/// Emits OS-specific anonymous page mapping helpers (`@_cx_sys_mmap` / `@_cx_sys_munmap`) in LLVM IR.
fn emitSysMmapHelpersLlvm(emitter: *LlvmModuleEmitter) !void {
    const ptr_int = ptrIntType(emitter);
    const fn_attrs = fnUnwindAttrs(emitter);
    if (emitter.cfg.target.isWasm()) {
        try emitter.requireIntrinsicDecl("declare i32 @llvm.wasm.memory.grow.i32(i32, i32) nounwind");
        try emitter.print(
            "define internal ptr @_cx_sys_mmap(i32 %_len) {s} {{\n" ++
                "entry:\n" ++
                "  %_isz = icmp eq i32 %_len, 0\n" ++
                "  br i1 %_isz, label %ret_null, label %grow\n" ++
                "grow:\n" ++
                "  %_add = add i32 %_len, 65535\n" ++
                "  %_pgs = lshr i32 %_add, 16\n" ++
                "  %_prv = call i32 @llvm.wasm.memory.grow.i32(i32 0, i32 %_pgs)\n" ++
                "  %_bad = icmp eq i32 %_prv, -1\n" ++
                "  br i1 %_bad, label %ret_null, label %ok\n" ++
                "ok:\n" ++
                "  %_off = shl i32 %_prv, 16\n" ++
                "  %_out = inttoptr i32 %_off to ptr\n" ++
                "  ret ptr %_out\n" ++
                "ret_null:\n" ++
                "  ret ptr null\n" ++
                "}}\n\n" ++
                "define internal void @_cx_sys_munmap(ptr %_p, i32 %_l) {s} {{\nentry:\n  ret void\n}}\n\n",
            .{ fn_attrs, fn_attrs },
        );
    } else if (emitter.cfg.target.isWindows()) {
        if (try emitter.markExternDeclared("VirtualAlloc")) {
            try emitter.writeAll("declare ptr @VirtualAlloc(ptr, i64, i32, i32) nounwind\n");
        }
        if (try emitter.markExternDeclared("VirtualFree")) {
            try emitter.writeAll("declare i32 @VirtualFree(ptr, i64, i32) nounwind\n");
        }
        try emitter.print(
            "define internal ptr @_cx_sys_mmap(i64 %_len) {s} {{\n" ++
                "entry:\n" ++
                "  %_isz = icmp eq i64 %_len, 0\n" ++
                "  br i1 %_isz, label %ret_null, label %map\n" ++
                "map:\n" ++
                "  %_res = call ptr @VirtualAlloc(ptr null, i64 %_len, i32 12288, i32 4)\n" ++
                "  ret ptr %_res\n" ++
                "ret_null:\n" ++
                "  ret ptr null\n" ++
                "}}\n\n" ++
                "define internal void @_cx_sys_munmap(ptr %_p, i64 %_len) {s} {{\n" ++
                "entry:\n" ++
                "  %_nn = icmp ne ptr %_p, null\n" ++
                "  br i1 %_nn, label %do_free, label %done\n" ++
                "do_free:\n" ++
                "  %_vf = call i32 @VirtualFree(ptr %_p, i64 0, i32 32768)\n" ++
                "  br label %done\n" ++
                "done:\n" ++
                "  ret void\n" ++
                "}}\n\n",
            .{ fn_attrs, fn_attrs },
        );
    } else {
        const map_flags: u32 = if (emitter.cfg.target.isDarwin()) 0x1002 else 0x22;
        if (try emitter.markExternDeclared("mmap")) {
            try emitter.print("declare ptr @mmap(ptr, {s}, i32, i32, i32, i64) nounwind\n", .{ptr_int});
        }
        if (try emitter.markExternDeclared("munmap")) {
            try emitter.print("declare i32 @munmap(ptr, {s}) nounwind\n", .{ptr_int});
        }
        try emitter.print(
            "define internal ptr @_cx_sys_mmap({s} %_len) {s} {{\n" ++
                "entry:\n" ++
                "  %_isz = icmp eq {s} %_len, 0\n" ++
                "  br i1 %_isz, label %ret_null, label %map\n" ++
                "map:\n" ++
                "  %_res = call ptr @mmap(ptr null, {s} %_len, i32 3, i32 {d}, i32 -1, i64 0)\n" ++
                "  %_ri = ptrtoint ptr %_res to {s}\n" ++
                "  %_bad = icmp eq {s} %_ri, -1\n" ++
                "  %_out = select i1 %_bad, ptr null, ptr %_res\n" ++
                "  ret ptr %_out\n" ++
                "ret_null:\n" ++
                "  ret ptr null\n" ++
                "}}\n\n" ++
                "define internal void @_cx_sys_munmap(ptr %_p, {s} %_len) {s} {{\n" ++
                "entry:\n" ++
                "  %_nn = icmp ne ptr %_p, null\n" ++
                "  %_nz = icmp ne {s} %_len, 0\n" ++
                "  %_ok = and i1 %_nn, %_nz\n" ++
                "  br i1 %_ok, label %do_un, label %done\n" ++
                "do_un:\n" ++
                "  %_u = call i32 @munmap(ptr %_p, {s} %_len)\n" ++
                "  br label %done\n" ++
                "done:\n" ++
                "  ret void\n" ++
                "}}\n\n",
            .{ ptr_int, fn_attrs, ptr_int, ptr_int, map_flags, ptr_int, ptr_int, ptr_int, fn_attrs, ptr_int, ptr_int },
        );
    }
}

/// Resolves `AllocatorHandle.alloc` and `AllocatorHandle.dealloc` body indices inside `emitter.input.bodies`.
fn lookupAllocatorHandleBodiesLlvm(emitter: *const LlvmModuleEmitter) ?struct {
    alloc_b: u32,
    dealloc_b: u32,
    handle_ty: TypeId,
    layout_ty: TypeId,
    ptr_ty: TypeId,
    res_ty: TypeId,
} {
    var alloc_b_opt: ?u32 = null;
    var dealloc_b_opt: ?u32 = null;
    for (emitter.input.sym_table.symbols.items) |cand_sym| {
        if (cand_sym.kind == .struct_sym and
            std.mem.eql(u8, cand_sym.name_text, "AllocatorHandle") and
            !cand_sym.target_scope.isNone())
        {
            for (emitter.input.sym_table.getScopeMembers(cand_sym.target_scope)) |mem_idx| {
                const mem_sym = emitter.input.sym_table.getSymbol(mem_idx).*;
                if (mem_sym.kind != .fn_sym) continue;
                if (std.mem.eql(u8, mem_sym.name_text, "alloc")) {
                    if (resolveBodyIndex(emitter, mem_sym.def_id, mem_idx)) |found_b| {
                        if (emitter.input.bodies[found_b].param_count == 2) alloc_b_opt = found_b;
                    }
                } else if (std.mem.eql(u8, mem_sym.name_text, "dealloc")) {
                    if (resolveBodyIndex(emitter, mem_sym.def_id, mem_idx)) |found_b| {
                        if (emitter.input.bodies[found_b].param_count == 3) dealloc_b_opt = found_b;
                    }
                }
            }
            break;
        }
    }
    const alloc_b = alloc_b_opt orelse return null;
    const dealloc_b = dealloc_b_opt orelse return null;
    const alloc_body = &emitter.input.bodies[alloc_b];
    const dealloc_body = &emitter.input.bodies[dealloc_b];
    if (alloc_body.locals.items.len < 3 or dealloc_body.locals.items.len < 4) return null;
    return .{
        .alloc_b = alloc_b,
        .dealloc_b = dealloc_b,
        .handle_ty = emitter.input.pool.unwrapUnderlyingType(alloc_body.locals.items[1].type_id),
        .layout_ty = emitter.input.pool.unwrapUnderlyingType(alloc_body.locals.items[2].type_id),
        .ptr_ty = emitter.input.pool.unwrapUnderlyingType(dealloc_body.locals.items[2].type_id),
        .res_ty = emitter.input.pool.unwrapUnderlyingType(alloc_body.ret_ty),
    };
}

/// Formats and appends ABI call argument pieces from stack slots `slot_ptrs[0..param_count]` into `call_args`.
fn appendAbiArgsFromStackSlotsLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    recipe: *const AbiFnRecipe,
    param_types: []const TypeId,
    slot_ptrs: []const []const u8,
    call_args: *std.ArrayListUnmanaged(u8),
    arg_cnt: *usize,
) !void {
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    for (param_types, 0..) |p_ty, idx| {
        if (idx >= recipe.param_recipes.len) break;
        const p_rec = recipe.param_recipes[idx];
        if (p_rec.pass_mode == .ignore_zst) continue;
        const slot_p = slot_ptrs[idx];
        const op_s = if (p_rec.pass_mode == .indirect_by_ref or p_rec.pass_mode == .indirect_byval)
            try emitter.allocator.dupe(u8, slot_p)
        else blk_ld: {
            const p_abi_ty = try formatAbiParamOrRetType(emitter, p_ty, p_rec);
            defer emitter.allocator.free(p_abi_ty);
            const ld_id = state.nextTmp();
            try state.print(
                "  %_sah_ld_{d} = load {s}, ptr {s}, align {d}\n",
                .{ ld_id, p_abi_ty, slot_p, @max(ptr_bytes, 8) },
            );
            break :blk_ld try std.fmt.allocPrint(emitter.allocator, "%_sah_ld_{d}", .{ld_id});
        };
        defer emitter.allocator.free(op_s);
        const piece = try formatAbiParamDeclPiece(emitter, p_ty, p_rec, op_s);
        defer emitter.allocator.free(piece);
        if (arg_cnt.* > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, piece);
        arg_cnt.* += 1;
    }
}

/// Emits over-aligned zeroed slab helpers (`@_cx_soa_zalloc` / `@_cx_soa_free`) for `#soa Vec[S]` in LLVM IR.
fn emitSoaSlabHelpersLlvm(emitter: *LlvmModuleEmitter) !void {
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const fn_attrs = fnUnwindAttrs(emitter);
    if (lookupAllocatorHandleBodiesLlvm(emitter)) |ah| {
        try emitter.requireIntrinsicDecl(
            "declare void @llvm.memset.p0.i64(ptr nocapture writeonly, i8, i64, i1 immarg)",
        );
        // [1] `@_cx_soa_zalloc` routing through `AllocatorHandle.alloc`:
        {
            var state = try BodyEmitState.initSynthetic(emitter.allocator, ptr_int);
            defer state.deinit();
            try emitter.print(
                "define internal ptr @_cx_soa_zalloc({s} %_alloc, {s} %_raw_n, {s} %_raw_al, i1 %_is_try) {s} {{\n" ++
                    "entry:\n",
                .{ ptr_int, ptr_int, ptr_int, fn_attrs },
            );
            const h_slot = try state.allocEntryBytes(ptr_bytes, @max(ptr_bytes, 8));
            defer emitter.allocator.free(h_slot);
            const ly_slot = try state.allocEntryBytes(2 * ptr_bytes, @max(ptr_bytes, 8));
            defer emitter.allocator.free(ly_slot);
            const res_lay = try emitter.resolver.resolveType(ah.res_ty);
            const res_align = @max(res_lay.alignBytes(), 8);
            const res_slot = try state.allocEntryBytes(@max(res_lay.size_bytes, 8), res_align);
            defer emitter.allocator.free(res_slot);
            try emitMemsetZero(emitter, &state, res_slot, @max(res_lay.size_bytes, 8), res_align);

            try state.print(
                "  %_lt = icmp ult {s} %_raw_al, 16\n" ++
                    "  %_al = select i1 %_lt, {s} 16, {s} %_raw_al\n" ++
                    "  store {s} %_alloc, ptr {s}, align {d}\n" ++
                    "  store {s} %_raw_n, ptr {s}, align {d}\n" ++
                    "  %_ly_a = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                    "  store {s} %_al, ptr %_ly_a, align {d}\n",
                .{
                    ptr_int, ptr_int,   ptr_int,
                    ptr_int, h_slot,    ptr_bytes,
                    ptr_int, ly_slot,   ptr_bytes,
                    ly_slot, ptr_int,   ptr_bytes,
                    ptr_int, ptr_bytes,
                },
            );

            const alloc_rec = &emitter.body_recipes.items[ah.alloc_b];
            const alloc_ident = try formatLlvmGlobalIdent(emitter.allocator, emitter.body_llvm_names.items[ah.alloc_b]);
            defer emitter.allocator.free(alloc_ident);

            var call_args: std.ArrayListUnmanaged(u8) = .empty;
            defer call_args.deinit(emitter.allocator);
            var arg_cnt: usize = 0;

            var sret_slot: ?[]u8 = null;
            defer if (sret_slot) |sret_buf| emitter.allocator.free(sret_buf);
            if (alloc_rec.has_sret) {
                sret_slot = try state.allocEntryBytes(
                    res_lay.size_bytes,
                    @max(res_lay.alignBytes(), alloc_rec.sret_recipe.pointee_align_bytes),
                );
                const sret_p = try formatAbiParamDeclPiece(emitter, ah.res_ty, alloc_rec.sret_recipe, sret_slot.?);
                defer emitter.allocator.free(sret_p);
                try call_args.appendSlice(emitter.allocator, sret_p);
                arg_cnt += 1;
            }
            if (alloc_rec.has_implicit_context) {
                const ctx_p = try formatAbiParamDeclPiece(emitter, .usize_ty, alloc_rec.context_recipe, "@_cx_default_ctx");
                defer emitter.allocator.free(ctx_p);
                if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
                try call_args.appendSlice(emitter.allocator, ctx_p);
                arg_cnt += 1;
            }
            try appendAbiArgsFromStackSlotsLlvm(
                emitter,
                &state,
                alloc_rec,
                &[2]TypeId{ ah.handle_ty, ah.layout_ty },
                &[2][]const u8{ h_slot, ly_slot },
                &call_args,
                &arg_cnt,
            );
            if (alloc_rec.swifterror_kind != .none) {
                try state.ensureSwifterrorCallSlot();
                if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
                try call_args.appendSlice(emitter.allocator, "ptr swifterror %_cx_call_err");
                try state.writeAll("  store ptr null, ptr %_cx_call_err, align 8\n");
            }

            const ret_decl = try formatAbiReturnDecl(emitter, ah.res_ty, alloc_rec);
            defer emitter.allocator.free(ret_decl.full_decl);
            defer emitter.allocator.free(ret_decl.bare_ty);
            const is_void = std.mem.eql(u8, ret_decl.bare_ty, "void");
            if (is_void) {
                try state.print(
                    "  call {s}void {s}({s})\n",
                    .{ resolveCallingConvPrefix(alloc_rec), alloc_ident, call_args.items },
                );
            } else {
                try state.print(
                    "  %_ah_rv = call {s}{s} {s}({s})\n",
                    .{ resolveCallingConvPrefix(alloc_rec), ret_decl.full_decl, alloc_ident, call_args.items },
                );
            }

            const sum_detail = (try emitter.resolver.getSumDetail(ah.res_ty)).?;
            if (alloc_rec.swifterror_kind != .none) {
                try state.writeAll(
                    "  %_ah_ce = load ptr, ptr %_cx_call_err, align 8\n" ++
                        "  %_ah_he = icmp ne ptr %_ah_ce, null\n" ++
                        "  br i1 %_ah_he, label %oom, label %ok\n" ++
                        "ok:\n",
                );
                state.setLabelOwned(try emitter.allocator.dupe(u8, "ok"));
                const unpacked_ok = try emitCoerceAbiToValue(emitter, &state, alloc_rec.ok_ty, ret_decl.bare_ty, "%_ah_rv");
                defer emitter.allocator.free(unpacked_ok);
                const ok_pay = if (sum_detail.payload_offset == 0)
                    try emitter.allocator.dupe(u8, res_slot)
                else blk_op: {
                    try state.print("  %_ah_op = getelementptr inbounds i8, ptr {s}, {s} {d}\n", .{ res_slot, ptr_int, sum_detail.payload_offset });
                    break :blk_op try emitter.allocator.dupe(u8, "%_ah_op");
                };
                defer emitter.allocator.free(ok_pay);
                try emitStoreValueToPtr(emitter, &state, alloc_rec.ok_ty, unpacked_ok, ok_pay, ptr_bytes, 0, 0, 0);
            } else {
                if (alloc_rec.has_sret) {
                    try emitMemcpyBytes(emitter, &state, res_slot, res_align, sret_slot.?, res_align, res_lay.size_bytes);
                } else if (!is_void) {
                    const unpacked = try emitCoerceAbiToValue(emitter, &state, ah.res_ty, ret_decl.bare_ty, "%_ah_rv");
                    defer emitter.allocator.free(unpacked);
                    try emitStoreValueToPtr(emitter, &state, ah.res_ty, unpacked, res_slot, res_align, 0, 0, 0);
                }
                const discr_s = try emitReadSumDiscriminantFromPtr(emitter, &state, ah.res_ty, res_slot, res_align);
                defer emitter.allocator.free(discr_s);
                try state.print(
                    "  %_ah_ie = icmp ne i32 {s}, 0\n" ++
                        "  br i1 %_ah_ie, label %oom, label %ok\n" ++
                        "ok:\n",
                    .{discr_s},
                );
                state.setLabelOwned(try emitter.allocator.dupe(u8, "ok"));
            }
            const pay_p = if (sum_detail.payload_offset == 0)
                try emitter.allocator.dupe(u8, res_slot)
            else blk_pp: {
                try state.print("  %_ah_pp = getelementptr inbounds i8, ptr {s}, {s} {d}\n", .{ res_slot, ptr_int, sum_detail.payload_offset });
                break :blk_pp try emitter.allocator.dupe(u8, "%_ah_pp");
            };
            defer emitter.allocator.free(pay_p);
            try state.print("  %_out = load ptr, ptr {s}, align {d}\n", .{ pay_p, ptr_bytes });
            if (ptr_bytes == 4) {
                try state.writeAll("  %_n64 = zext i32 %_raw_n to i64\n");
            } else {
                try state.writeAll("  %_n64 = add i64 %_raw_n, 0\n");
            }
            try state.writeAll(
                "  %_hz = icmp ugt i64 %_n64, 0\n" ++
                    "  %_hn = icmp ne ptr %_out, null\n" ++
                    "  %_dz = and i1 %_hz, %_hn\n" ++
                    "  br i1 %_dz, label %do_zero, label %ret_ok\n" ++
                    "do_zero:\n" ++
                    "  call void @llvm.memset.p0.i64(ptr align 1 %_out, i8 0, i64 %_n64, i1 false)\n" ++
                    "  br label %ret_ok\n" ++
                    "ret_ok:\n" ++
                    "  ret ptr %_out\n" ++
                    "oom:\n" ++
                    "  br i1 %_is_try, label %ret_null, label %trap\n" ++
                    "trap:\n",
            );
            if (emitter.cfg.target.isFreestanding()) {
                try state.writeAll("  call void @llvm.trap()\n  unreachable\n");
            } else {
                try state.writeAll("  call void @_cx_rt_trap(i32 0)\n  unreachable\n");
            }
            try state.writeAll("ret_null:\n  ret ptr null\n");
            if (state.entry_allocas.items.len > 0) try emitter.writeAll(state.entry_allocas.items);
            try emitter.writeAll(state.cur_buf.items);
            try emitter.writeAll("}\n\n");
        }

        // [2] `@_cx_soa_free` routing through `AllocatorHandle.dealloc`:
        {
            var state = try BodyEmitState.initSynthetic(emitter.allocator, ptr_int);
            defer state.deinit();
            try emitter.print(
                "define internal void @_cx_soa_free({s} %_alloc, ptr %_p, {s} %_old_n, {s} %_raw_al) {s} {{\n" ++
                    "entry:\n",
                .{ ptr_int, ptr_int, ptr_int, fn_attrs },
            );
            const h_slot = try state.allocEntryBytes(ptr_bytes, @max(ptr_bytes, 8));
            defer emitter.allocator.free(h_slot);
            const p_slot = try state.allocEntryBytes(ptr_bytes, @max(ptr_bytes, 8));
            defer emitter.allocator.free(p_slot);
            const ly_slot = try state.allocEntryBytes(2 * ptr_bytes, @max(ptr_bytes, 8));
            defer emitter.allocator.free(ly_slot);

            try state.print(
                "  %_nn = icmp ne ptr %_p, null\n" ++
                    "  %_nz = icmp ugt {s} %_old_n, 0\n" ++
                    "  %_tg = and {s} %_alloc, 7\n" ++
                    "  %_ig = icmp eq {s} %_tg, 0\n" ++
                    "  %_c1 = and i1 %_nn, %_nz\n" ++
                    "  %_go = and i1 %_c1, %_ig\n" ++
                    "  br i1 %_go, label %do_f, label %done\n" ++
                    "do_f:\n" ++
                    "  %_lt = icmp ult {s} %_raw_al, 16\n" ++
                    "  %_al = select i1 %_lt, {s} 16, {s} %_raw_al\n" ++
                    "  store {s} %_alloc, ptr {s}, align {d}\n" ++
                    "  store ptr %_p, ptr {s}, align {d}\n" ++
                    "  store {s} %_old_n, ptr {s}, align {d}\n" ++
                    "  %_ly_a = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                    "  store {s} %_al, ptr %_ly_a, align {d}\n",
                .{
                    ptr_int,   ptr_int,   ptr_int,
                    ptr_int,   ptr_int,   ptr_int,
                    ptr_int,   h_slot,    ptr_bytes,
                    p_slot,    ptr_bytes, ptr_int,
                    ly_slot,   ptr_bytes, ly_slot,
                    ptr_int,   ptr_bytes, ptr_int,
                    ptr_bytes,
                },
            );

            const dealloc_rec = &emitter.body_recipes.items[ah.dealloc_b];
            const dealloc_ident = try formatLlvmGlobalIdent(emitter.allocator, emitter.body_llvm_names.items[ah.dealloc_b]);
            defer emitter.allocator.free(dealloc_ident);

            var call_args: std.ArrayListUnmanaged(u8) = .empty;
            defer call_args.deinit(emitter.allocator);
            var arg_cnt: usize = 0;
            if (dealloc_rec.has_implicit_context) {
                const ctx_p = try formatAbiParamDeclPiece(emitter, .usize_ty, dealloc_rec.context_recipe, "@_cx_default_ctx");
                defer emitter.allocator.free(ctx_p);
                try call_args.appendSlice(emitter.allocator, ctx_p);
                arg_cnt += 1;
            }
            try appendAbiArgsFromStackSlotsLlvm(
                emitter,
                &state,
                dealloc_rec,
                &[3]TypeId{ ah.handle_ty, ah.ptr_ty, ah.layout_ty },
                &[3][]const u8{ h_slot, p_slot, ly_slot },
                &call_args,
                &arg_cnt,
            );
            try state.print(
                "  call {s}void {s}({s})\n" ++
                    "  br label %done\n" ++
                    "done:\n" ++
                    "  ret void\n",
                .{ resolveCallingConvPrefix(dealloc_rec), dealloc_ident, call_args.items },
            );
            if (state.entry_allocas.items.len > 0) try emitter.writeAll(state.entry_allocas.items);
            try emitter.writeAll(state.cur_buf.items);
            try emitter.writeAll("}\n\n");
        }
        return;
    }

    if (emitter.cfg.target.isFreestanding()) {
        try emitter.requireIntrinsicDecl("declare i32 @llvm.wasm.memory.grow.i32(i32, i32) nounwind");
        try emitter.requireIntrinsicDecl(
            "declare void @llvm.memset.p0.i64(ptr nocapture writeonly, i8, i64, i1 immarg)",
        );
        try emitter.print(
            "define internal ptr @_cx_soa_zalloc(i32 %_alloc, i32 %_raw_n, i32 %_raw_al, i1 %_is_try) {s} {{\n" ++
                "entry:\n" ++
                "  %_z0 = icmp eq i32 %_raw_n, 0\n" ++
                "  %_n = select i1 %_z0, i32 16, i32 %_raw_n\n" ++
                "  %_lt = icmp ult i32 %_raw_al, 16\n" ++
                "  %_al = select i1 %_lt, i32 16, i32 %_raw_al\n" ++
                "  %_s1 = add i32 %_n, %_al\n" ++
                "  %_s2 = add i32 %_s1, 65535\n" ++
                "  %_pgs = lshr i32 %_s2, 16\n" ++
                "  %_prv = call i32 @llvm.wasm.memory.grow.i32(i32 0, i32 %_pgs)\n" ++
                "  %_bad = icmp eq i32 %_prv, -1\n" ++
                "  br i1 %_bad, label %oom, label %ok\n" ++
                "oom:\n" ++
                "  br i1 %_is_try, label %ret_null, label %trap\n" ++
                "trap:\n" ++
                "  call void @llvm.trap()\n" ++
                "  unreachable\n" ++
                "ret_null:\n" ++
                "  ret ptr null\n" ++
                "ok:\n" ++
                "  %_base = shl i32 %_prv, 16\n" ++
                "  %_m1 = sub i32 %_al, 1\n" ++
                "  %_nm1 = xor i32 %_m1, -1\n" ++
                "  %_ad = add i32 %_base, %_m1\n" ++
                "  %_ap = and i32 %_ad, %_nm1\n" ++
                "  %_out = inttoptr i32 %_ap to ptr\n" ++
                "  %_n64 = zext i32 %_n to i64\n" ++
                "  call void @llvm.memset.p0.i64(ptr align 16 %_out, i8 0, i64 %_n64, i1 false)\n" ++
                "  ret ptr %_out\n" ++
                "}}\n\n" ++
                "define internal void @_cx_soa_free(i32 %_alloc, ptr %_p, i32 %_old_n, i32 %_raw_al) {s} {{\nentry:\n  ret void\n}}\n\n",
            .{ fn_attrs, fn_attrs },
        );
    } else {
        if (!emitter.declared_externs.contains("calloc")) {
            try emitter.requireIntrinsicDecl(
                if (emitter.cfg.target.isWasm())
                    "declare ptr @calloc(i32, i32) nounwind"
                else
                    "declare ptr @calloc(i64, i64) nounwind",
            );
        }
        if (!emitter.declared_externs.contains("free")) {
            try emitter.requireIntrinsicDecl("declare void @free(ptr) nounwind");
        }
        try emitter.print(
            "define internal ptr @_cx_soa_zalloc({s} %_alloc, {s} %_raw_n, {s} %_raw_al, i1 %_is_try) {s} {{\n" ++
                "entry:\n" ++
                "  %_z0 = icmp eq {s} %_raw_n, 0\n" ++
                "  %_n = select i1 %_z0, {s} 16, {s} %_raw_n\n" ++
                "  %_lt = icmp ult {s} %_raw_al, 16\n" ++
                "  %_al = select i1 %_lt, {s} 16, {s} %_raw_al\n" ++
                "  %_tot1 = add {s} %_n, %_al\n" ++
                "  %_tot = add {s} %_tot1, %_al\n" ++
                "  %_ov = icmp ult {s} %_tot, %_n\n" ++
                "  br i1 %_ov, label %oom, label %do_alloc\n" ++
                "do_alloc:\n" ++
                "  %_raw = call ptr @calloc({s} 1, {s} %_tot)\n" ++
                "  %_is_null = icmp eq ptr %_raw, null\n" ++
                "  br i1 %_is_null, label %oom, label %ok\n" ++
                "oom:\n" ++
                "  br i1 %_is_try, label %ret_null, label %trap\n" ++
                "trap:\n" ++
                "  call void @_cx_rt_trap(i32 0)\n" ++
                "  unreachable\n" ++
                "ret_null:\n" ++
                "  ret ptr null\n" ++
                "ok:\n" ++
                "  %_ri = ptrtoint ptr %_raw to {s}\n" ++
                "  %_rh = add {s} %_ri, %_al\n" ++
                "  %_m1 = sub {s} %_al, 1\n" ++
                "  %_nm1 = xor {s} %_m1, -1\n" ++
                "  %_ad = add {s} %_rh, %_m1\n" ++
                "  %_ap = and {s} %_ad, %_nm1\n" ++
                "  %_out = inttoptr {s} %_ap to ptr\n" ++
                "  %_hp = getelementptr inbounds i8, ptr %_out, {s} -{d}\n" ++
                "  store ptr %_raw, ptr %_hp, align {d}\n" ++
                "  ret ptr %_out\n" ++
                "}}\n\n",
            .{
                ptr_int,   ptr_int, ptr_int, fn_attrs,
                ptr_int,   ptr_int, ptr_int, ptr_int,
                ptr_int,   ptr_int, ptr_int, ptr_int,
                ptr_int,   ptr_int, ptr_int, ptr_int,
                ptr_int,   ptr_int, ptr_int, ptr_int,
                ptr_int,   ptr_int, ptr_int, ptr_bytes,
                ptr_bytes,
            },
        );
        try emitter.print(
            "define internal void @_cx_soa_free({s} %_alloc, ptr %_p, {s} %_old_n, {s} %_raw_al) {s} {{\n" ++
                "entry:\n" ++
                "  %_nn = icmp ne ptr %_p, null\n" ++
                "  br i1 %_nn, label %do_f, label %done\n" ++
                "do_f:\n" ++
                "  %_hp = getelementptr inbounds i8, ptr %_p, {s} -{d}\n" ++
                "  %_raw = load ptr, ptr %_hp, align {d}\n" ++
                "  call void @free(ptr %_raw)\n" ++
                "  br label %done\n" ++
                "done:\n" ++
                "  ret void\n" ++
                "}}\n\n",
            .{ ptr_int, ptr_int, ptr_int, fn_attrs, ptr_int, ptr_bytes, ptr_bytes },
        );
    }
}

/// Emits LLVM 20–23 stackless coroutine runtime types, FIFO `TaskGroup` scheduler, and `ReactorVTable` yield seam.
fn emitAsyncRuntimeHelpersLlvm(emitter: *LlvmModuleEmitter) !void {
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const fn_attrs = fnUnwindAttrs(emitter);
    const is_wasm = emitter.cfg.target.isWasm();
    const is_freestanding = emitter.cfg.target.isFreestanding();
    const tls_kw = if (is_wasm) "internal global" else "internal thread_local global";
    const ctx_bytes: u64 = type_system.ContextFieldLayout.byteSizeForPtrWidth(emitter.cfg.target.ptrBytes());

    var total_ctx_save_bytes: u64 = ctx_bytes;
    for (emitter.ctx_wide_slot_sizes) |wide_sz| {
        if (wide_sz > ptr_bytes) total_ctx_save_bytes += wide_sz;
    }

    try emitter.requireIntrinsicDecl(
        "declare void @llvm.memcpy.p0.p0.i64(ptr noalias nocapture writeonly, " ++
            "ptr noalias nocapture readonly, i64, i1 immarg)",
    );
    if (is_freestanding) {
        try emitter.requireIntrinsicDecl(
            "declare void @llvm.memset.p0.i64(ptr nocapture writeonly, i8, i64, i1 immarg)",
        );
    } else {
        if (!emitter.declared_externs.contains("calloc")) {
            try emitter.requireIntrinsicDecl(
                if (is_wasm)
                    "declare ptr @calloc(i32, i32) nounwind"
                else
                    "declare ptr @calloc(i64, i64) nounwind",
            );
        }
        if (!emitter.declared_externs.contains("realloc")) {
            try emitter.requireIntrinsicDecl(
                if (is_wasm)
                    "declare ptr @realloc(ptr, i32) nounwind"
                else
                    "declare ptr @realloc(ptr, i64) nounwind",
            );
        }
        if (!emitter.declared_externs.contains("free")) {
            try emitter.requireIntrinsicDecl("declare void @free(ptr) nounwind");
        }
    }

    try emitter.print(
        "%_cx_fut_raw_t = type {{ ptr, {s}, {s}, {s} }}\n" ++
            "%_cx_task_node_t = type {{ ptr, %_cx_fut_raw_t, ptr, {s}, ptr, [{d} x i8], {s}, i8, i8, i8 }}\n" ++
            "%_cx_task_group_t = type {{ ptr, {s}, {s}, i8, i8 }}\n" ++
            "@_cx_exec_q = {s} ptr null, align {d}\n" ++
            "@_cx_exec_q_len = {s} {s} 0, align {d}\n" ++
            "@_cx_exec_q_cap = {s} {s} 0, align {d}\n" ++
            "@_cx_active_poll_item = {s} {s} 1, align {d}\n" ++
            "@_cx_coro_is_canceling = {s} i8 0, align 1\n",
        .{
            ptr_int,   ptr_int,              ptr_int,
            ptr_int,   total_ctx_save_bytes, ptr_int,
            ptr_int,   ptr_int,              tls_kw,
            ptr_bytes, tls_kw,               ptr_int,
            ptr_bytes, tls_kw,               ptr_int,
            ptr_bytes, tls_kw,               ptr_int,
            ptr_bytes, tls_kw,
        },
    );
    if (is_freestanding) {
        try emitter.print(
            "@_cx_wasm_async_heap = internal global [65536 x i8] zeroinitializer, align 16\n" ++
                "@_cx_wasm_async_heap_off = internal global i32 0, align 4\n\n" ++
                "define internal ptr @_cx_async_zalloc(i32 %raw_n) {s} {{\n" ++
                "entry:\n" ++
                "  %z0 = icmp eq i32 %raw_n, 0\n" ++
                "  %n = select i1 %z0, i32 16, i32 %raw_n\n" ++
                "  %cur = load i32, ptr @_cx_wasm_async_heap_off, align 4\n" ++
                "  %ov0 = icmp ugt i32 %cur, 65520\n" ++
                "  br i1 %ov0, label %trap, label %align_ok\n" ++
                "align_ok:\n" ++
                "  %c15 = add i32 %cur, 15\n" ++
                "  %aoff = and i32 %c15, -16\n" ++
                "  %rem = sub i32 65536, %aoff\n" ++
                "  %ov1 = icmp ugt i32 %n, %rem\n" ++
                "  br i1 %ov1, label %trap, label %ok\n" ++
                "trap:\n" ++
                "  call void @llvm.trap()\n" ++
                "  unreachable\n" ++
                "ok:\n" ++
                "  %out = getelementptr inbounds [65536 x i8], ptr @_cx_wasm_async_heap, i32 0, i32 %aoff\n" ++
                "  %n64 = zext i32 %n to i64\n" ++
                "  call void @llvm.memset.p0.i64(ptr align 16 %out, i8 0, i64 %n64, i1 false)\n" ++
                "  %next = add i32 %aoff, %n\n" ++
                "  store i32 %next, ptr @_cx_wasm_async_heap_off, align 4\n" ++
                "  ret ptr %out\n" ++
                "}}\n\n" ++
                "define internal ptr @_cx_async_grow_buf(ptr %old_p, i32 %old_b, i32 %new_b) {s} {{\n" ++
                "entry:\n" ++
                "  %np = call ptr @_cx_async_zalloc(i32 %new_b)\n" ++
                "  %hn = icmp ne ptr %old_p, null\n" ++
                "  %hz = icmp ne i32 %old_b, 0\n" ++
                "  %do_cp = and i1 %hn, %hz\n" ++
                "  br i1 %do_cp, label %cp, label %done\n" ++
                "cp:\n" ++
                "  %lt = icmp ult i32 %old_b, %new_b\n" ++
                "  %min_b = select i1 %lt, i32 %old_b, i32 %new_b\n" ++
                "  %m64 = zext i32 %min_b to i64\n" ++
                "  call void @llvm.memcpy.p0.p0.i64(ptr align 1 %np, ptr align 1 %old_p, i64 %m64, i1 false)\n" ++
                "  br label %done\n" ++
                "done:\n" ++
                "  ret ptr %np\n" ++
                "}}\n\n" ++
                "define internal void @_cx_async_free(ptr %unused_p) {s} {{\n" ++
                "entry:\n" ++
                "  ret void\n" ++
                "}}\n\n",
            .{ fn_attrs, fn_attrs, fn_attrs },
        );
    } else {
        try emitter.print(
            "\ndefine internal ptr @_cx_async_zalloc({s} %raw_n) {s} {{\n" ++
                "entry:\n" ++
                "  %z0 = icmp eq {s} %raw_n, 0\n" ++
                "  %n = select i1 %z0, {s} 1, {s} %raw_n\n" ++
                "  %out = call ptr @calloc({s} 1, {s} %n)\n" ++
                "  %oom = icmp eq ptr %out, null\n" ++
                "  br i1 %oom, label %trap, label %ok\n" ++
                "trap:\n" ++
                "  call void @_cx_rt_trap(i32 0)\n" ++
                "  unreachable\n" ++
                "ok:\n" ++
                "  ret ptr %out\n" ++
                "}}\n\n" ++
                "define internal ptr @_cx_async_grow_buf(ptr %old_p, {s} %old_b, {s} %new_b) {s} {{\n" ++
                "entry:\n" ++
                "  %z0 = icmp eq {s} %new_b, 0\n" ++
                "  %nb = select i1 %z0, {s} 1, {s} %new_b\n" ++
                "  %np = call ptr @realloc(ptr %old_p, {s} %nb)\n" ++
                "  %oom = icmp eq ptr %np, null\n" ++
                "  br i1 %oom, label %trap, label %ok\n" ++
                "trap:\n" ++
                "  call void @_cx_rt_trap(i32 0)\n" ++
                "  unreachable\n" ++
                "ok:\n" ++
                "  ret ptr %np\n" ++
                "}}\n\n" ++
                "define internal void @_cx_async_free(ptr %raw_p) {s} {{\n" ++
                "entry:\n" ++
                "  call void @free(ptr %raw_p)\n" ++
                "  ret void\n" ++
                "}}\n\n",
            .{
                ptr_int,  fn_attrs, ptr_int,  ptr_int, ptr_int, ptr_int, ptr_int,
                ptr_int,  ptr_int,  fn_attrs, ptr_int, ptr_int, ptr_int, ptr_int,
                fn_attrs,
            },
        );
    }

    // `@_cx_ctx_save(ptr %dst)` and `@_cx_ctx_restore(ptr %src)`:
    try emitter.print(
        "define internal void @_cx_ctx_save(ptr %dst) {s} {{\nentry:\n" ++
            "  call void @llvm.memcpy.p0.p0.i64(ptr align 1 %dst, ptr align {d} @_cx_default_ctx, i64 {d}, i1 false)\n",
        .{ fn_attrs, ptr_bytes, ctx_bytes },
    );
    var wide_off: u64 = ctx_bytes;
    for (emitter.ctx_wide_slot_sizes, 0..) |wide_sz, slot_i| {
        if (wide_sz > ptr_bytes) {
            try emitter.print(
                "  %wdst_{d} = getelementptr inbounds i8, ptr %dst, {s} {d}\n" ++
                    "  call void @llvm.memcpy.p0.p0.i64(ptr align 1 %wdst_{d}, ptr align {d} @_cx_ctx_wide_{d}, i64 {d}, i1 false)\n",
                .{ slot_i, ptr_int, wide_off, slot_i, emitter.ctx_wide_slot_aligns[slot_i], slot_i, wide_sz },
            );
            wide_off += wide_sz;
        }
    }
    try emitter.writeAll("  ret void\n}\n\n");

    try emitter.print(
        "define internal void @_cx_ctx_restore(ptr %src) {s} {{\nentry:\n" ++
            "  call void @llvm.memcpy.p0.p0.i64(ptr align {d} @_cx_default_ctx, ptr align 1 %src, i64 {d}, i1 false)\n",
        .{ fn_attrs, ptr_bytes, ctx_bytes },
    );
    wide_off = ctx_bytes;
    for (emitter.ctx_wide_slot_sizes, 0..) |wide_sz, slot_i| {
        if (wide_sz > ptr_bytes) {
            try emitter.print(
                "  %wsrc_{d} = getelementptr inbounds i8, ptr %src, {s} {d}\n" ++
                    "  call void @llvm.memcpy.p0.p0.i64(ptr align {d} @_cx_ctx_wide_{d}, ptr align 1 %wsrc_{d}, i64 {d}, i1 false)\n",
                .{ slot_i, ptr_int, wide_off, emitter.ctx_wide_slot_aligns[slot_i], slot_i, slot_i, wide_sz },
            );
            wide_off += wide_sz;
        }
    }
    try emitter.writeAll("  ret void\n}\n\n");

    // `@_cx_exec_push(<ptr_int> %item)` and `@_cx_reactor_notify_yield(i8 %reason)`:
    const max_q_elems: u64 = if (is_wasm)
        (std.math.maxInt(u32) / ptr_bytes)
    else
        (std.math.maxInt(u64) / @as(u64, ptr_bytes));
    const reactor_slot_off: u64 = 8 * @as(u64, ptr_bytes);
    const reactor_ctx_off: u64 = 9 * @as(u64, ptr_bytes);
    try emitter.print(
        "define internal void @_cx_exec_push({s} %item) {s} {{\n" ++
            "entry:\n" ++
            "  %len = load {s}, ptr @_cx_exec_q_len, align {d}\n" ++
            "  %cap = load {s}, ptr @_cx_exec_q_cap, align {d}\n" ++
            "  %need = icmp uge {s} %len, %cap\n" ++
            "  br i1 %need, label %grow, label %push\n" ++
            "grow:\n" ++
            "  %isz = icmp eq {s} %cap, 0\n" ++
            "  %dbl = mul {s} %cap, 2\n" ++
            "  %nc = select i1 %isz, {s} 64, {s} %dbl\n" ++
            "  %ov1 = icmp ule {s} %nc, %cap\n" ++
            "  %ov2 = icmp ugt {s} %nc, {d}\n" ++
            "  %ov = or i1 %ov1, %ov2\n" ++
            "  br i1 %ov, label %trap, label %do_realloc\n" ++
            "do_realloc:\n" ++
            "  %oldb = mul {s} %cap, {d}\n" ++
            "  %nb = mul {s} %nc, {d}\n" ++
            "  %oldq = load ptr, ptr @_cx_exec_q, align {d}\n" ++
            "  %newq = call ptr @_cx_async_grow_buf(ptr %oldq, {s} %oldb, {s} %nb)\n" ++
            "  br label %grown\n" ++
            "trap:\n" ++
            "  call void @_cx_rt_trap(i32 0)\n" ++
            "  unreachable\n" ++
            "grown:\n" ++
            "  store ptr %newq, ptr @_cx_exec_q, align {d}\n" ++
            "  store {s} %nc, ptr @_cx_exec_q_cap, align {d}\n" ++
            "  br label %push\n" ++
            "push:\n" ++
            "  %q = load ptr, ptr @_cx_exec_q, align {d}\n" ++
            "  %ep = getelementptr inbounds {s}, ptr %q, {s} %len\n" ++
            "  store {s} %item, ptr %ep, align {d}\n" ++
            "  %nlen = add {s} %len, 1\n" ++
            "  store {s} %nlen, ptr @_cx_exec_q_len, align {d}\n" ++
            "  ret void\n" ++
            "}}\n\n",
        .{
            ptr_int,   fn_attrs,
            ptr_int,   ptr_bytes,
            ptr_int,   ptr_bytes,
            ptr_int,   ptr_int,
            ptr_int,   ptr_int,
            ptr_int,   ptr_int,
            ptr_int,   max_q_elems,
            ptr_int,   ptr_bytes,
            ptr_int,   ptr_bytes,
            ptr_bytes, ptr_int,
            ptr_int,   ptr_bytes,
            ptr_int,   ptr_bytes,
            ptr_bytes, ptr_int,
            ptr_int,   ptr_int,
            ptr_bytes, ptr_int,
            ptr_int,   ptr_bytes,
        },
    );
    try emitter.print(
        "define internal void @_cx_reactor_notify_yield(i8 %reason) {s} {{\n" ++
            "entry:\n" ++
            "  %vtp = getelementptr inbounds i8, ptr @_cx_default_ctx, {s} {d}\n" ++
            "  %rcp = getelementptr inbounds i8, ptr @_cx_default_ctx, {s} {d}\n" ++
            "  %vt = load ptr, ptr %vtp, align {d}\n" ++
            "  %rctx = load ptr, ptr %rcp, align {d}\n" ++
            "  %hvt = icmp ne ptr %vt, null\n" ++
            "  br i1 %hvt, label %chk_fn, label %done\n" ++
            "chk_fn:\n" ++
            "  %yfnp = getelementptr inbounds ptr, ptr %vt, {s} 6\n" ++
            "  %yfn = load ptr, ptr %yfnp, align {d}\n" ++
            "  %hfn = icmp ne ptr %yfn, null\n" ++
            "  br i1 %hfn, label %do_call, label %done\n" ++
            "do_call:\n" ++
            "  call void %yfn(ptr %rctx, i8 %reason)\n" ++
            "  br label %done\n" ++
            "done:\n" ++
            "  ret void\n" ++
            "}}\n\n",
        .{
            fn_attrs,
            ptr_int,
            reactor_slot_off,
            ptr_int,
            reactor_ctx_off,
            ptr_bytes,
            ptr_bytes,
            ptr_int,
            ptr_bytes,
        },
    );

    // `@_cx_coro_alloc`, `@_cx_coro_free`, `@_cx_async_fut_cancel`, and `@_cx_async_fut_poll`:
    const res_sz_i64_conv = if (is_wasm)
        "  %rsz64 = zext i32 %rsz to i64\n"
    else
        "  %rsz64 = add i64 %rsz, 0\n";
    try emitter.print(
        "define internal ptr @_cx_coro_alloc(i32 %b_idx) {s} {{\n" ++
            "entry:\n" ++
            "  %raw_sz = call {s} @_cx_coro_frame_size(i32 %b_idx)\n" ++
            "  %raw_al = call {s} @_cx_coro_frame_align(i32 %b_idx)\n" ++
            "  %lt16_s = icmp ult {s} %raw_sz, 16\n" ++
            "  %sz = select i1 %lt16_s, {s} 16, {s} %raw_sz\n" ++
            "  %lt16_a = icmp ult {s} %raw_al, 16\n" ++
