            2 * @as(u64, ptr_bytes), ptr_int,                     2 * @as(u64, ptr_bytes) + 4,
            ptr_int,                 2 * @as(u64, ptr_bytes) + 6, ptr_int,
            ptr_int,                 ptr_bytes,
        },
    );
    try emitter.print(
        "define internal void @_cx_rt_fmt_args_spec(ptr %b, ptr %fa, i32 %spec_lo, i32 %spec_hi) {s} {{\n" ++
            "entry:\n" ++
            "  %tb = alloca {{ ptr, i64, i64 }}, align 8\n" ++
            "  store {{ ptr, i64, i64 }} zeroinitializer, ptr %tb, align 8\n" ++
            "  call void @_cx_rt_fmt_args_into(ptr %tb, ptr %fa)\n" ++
            "  %td = load ptr, ptr %tb, align 8\n" ++
            "  %tlp = getelementptr inbounds {{ ptr, i64, i64 }}, ptr %tb, i32 0, i32 1\n" ++
            "  %tl = load i64, ptr %tlp, align 8\n" ++
            "  call void @_cx_rt_buf_pad_str(ptr %b, ptr %td, i64 %tl, i32 %spec_lo, i32 %spec_hi, i32 0)\n" ++
            "  call void @free(ptr %td)\n" ++
            "  ret void\n" ++
            "}}\n\n" ++
            "define internal {{ ptr, {s} }} @_cx_rt_buf_finish(ptr %b) {s} {{\n" ++
            "entry:\n" ++
            "  %lp = getelementptr inbounds {{ ptr, i64, i64 }}, ptr %b, i32 0, i32 1\n" ++
            "  %len = load i64, ptr %lp, align 8\n" ++
            "  %isz = icmp eq i64 %len, 0\n" ++
            "  br i1 %isz, label %empty, label %non_empty\n" ++
            "empty:\n" ++
            "  %ed = load ptr, ptr %b, align 8\n" ++
            "  call void @free(ptr %ed)\n" ++
            "  %e0 = insertvalue {{ ptr, {s} }} zeroinitializer, ptr @_cx_empty_cstr, 0\n" ++
            "  %e1 = insertvalue {{ ptr, {s} }} %e0, {s} 0, 1\n" ++
            "  ret {{ ptr, {s} }} %e1\n" ++
            "non_empty:\n" ++
            "  call void @_cx_rt_buf_push_byte(ptr %b, i8 0)\n" ++
            "  %d = load ptr, ptr %b, align 8\n" ++
            "  store i64 %len, ptr %lp, align 8\n" ++
            "{s}" ++
            "  %r0 = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %d, 0\n" ++
            "  %r1 = insertvalue {{ ptr, {s} }} %r0, {s} %len_pt, 1\n" ++
            "  ret {{ ptr, {s} }} %r1\n" ++
            "}}\n\n" ++
            "define internal void @_cx_rt_panic_fmt_args(ptr %fa) cold noreturn {s} {{\n" ++
            "entry:\n" ++
            "  %tb = alloca {{ ptr, i64, i64 }}, align 8\n" ++
            "  store {{ ptr, i64, i64 }} zeroinitializer, ptr %tb, align 8\n" ++
            "  call void @_cx_rt_fmt_args_into(ptr %tb, ptr %fa)\n" ++
            "  %d = load ptr, ptr %tb, align 8\n" ++
            "  %lp = getelementptr inbounds {{ ptr, i64, i64 }}, ptr %tb, i32 0, i32 1\n" ++
            "  %len = load i64, ptr %lp, align 8\n" ++
            "{s}" ++
            "  call void @_cx_rt_panic(ptr %d, {s} %len_pt)\n" ++
            "  unreachable\n" ++
            "}}\n\n",
        .{
            fn_attrs, ptr_int, fn_attrs,      ptr_int,       ptr_int,
            ptr_int,  ptr_int, i64_to_pt_fin, ptr_int,       ptr_int,
            ptr_int,  ptr_int, fn_attrs,      i64_to_pt_fin, ptr_int,
        },
    );
}

/// Emits monomorphic `@_cx_fmt_ty_<id>(ptr %_out_b, ptr %_val_p, i32 %_spec_lo, i32 %_spec_hi)`.
fn emitFmtHelperForType(emitter: *LlvmModuleEmitter, raw_ty: TypeId) !void {
    const fmt_ty = try unwrapTransparentType(emitter, raw_ty);
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const fn_attrs = fnUnwindAttrs(emitter);
    const is_wasm = emitter.cfg.target.isWasm();

    try emitter.print(
        "define internal void @_cx_fmt_ty_{d}(ptr %_out_b, ptr %_val_p, i32 %_spec_lo, i32 %_spec_hi) {s} {{\n" ++
            "entry:\n",
        .{ fmt_ty.toU32(), fn_attrs },
    );

    if (fmt_ty == .unit_ty) {
        try emitBufPushStringLiteralPadAndRet(emitter, "()");
        return;
    }
    if (fmt_ty == .bool_ty) {
        try emitter.writeAll(
            "  %_bv = load i8, ptr %_val_p, align 1\n" ++
                "  call void @_cx_rt_fmt_bool_spec(ptr %_out_b, i8 %_bv, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}\n\n",
        );
        return;
    }
    if (fmt_ty == .char_ty) {
        try emitter.writeAll(
            "  %_cp = load i32, ptr %_val_p, align 1\n" ++
                "  call void @_cx_rt_fmt_char_spec(ptr %_out_b, i32 %_cp, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}\n\n",
        );
        return;
    }
    if (fmt_ty == .str_ty) {
        const len_conv = if (is_wasm) "  %_sl64 = zext i32 %_sl_pt to i64\n" else "  %_sl64 = add i64 %_sl_pt, 0\n";
        try emitter.print(
            "  %_sp = load ptr, ptr %_val_p, align 1\n" ++
                "  %_slp = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                "  %_sl_pt = load {s}, ptr %_slp, align 1\n" ++
                "{s}" ++
                "  call void @_cx_rt_fmt_str_spec(ptr %_out_b, ptr %_sp, i64 %_sl64, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}}\n\n",
            .{ ptr_int, ptr_bytes, ptr_int, len_conv },
        );
        return;
    }
    if (fmt_ty == .f32_ty) {
        try emitter.writeAll(
            "  %_fv32 = load float, ptr %_val_p, align 1\n" ++
                "  %_fv64 = fpext float %_fv32 to double\n" ++
                "  call void @_cx_rt_fmt_f64_spec(ptr %_out_b, double %_fv64, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}\n\n",
        );
        return;
    }
    if (fmt_ty == .f64_ty or fmt_ty == .untyped_float_ty) {
        try emitter.writeAll(
            "  %_fv64 = load double, ptr %_val_p, align 1\n" ++
                "  call void @_cx_rt_fmt_f64_spec(ptr %_out_b, double %_fv64, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}\n\n",
        );
        return;
    }
    if (fmt_ty == .source_loc_ty) {
        try emitter.writeAll(
            "  %_sl = load ptr, ptr %_val_p, align 1\n" ++
                "  call void @_cx_rt_fmt_source_loc_spec(ptr %_out_b, ptr %_sl, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}\n\n",
        );
        return;
    }
    if (fmt_ty == .fmt_args_ty) {
        try emitter.writeAll(
            "  call void @_cx_rt_fmt_args_spec(ptr %_out_b, ptr %_val_p, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}\n\n",
        );
        return;
    }
    if (fmt_ty == .fmt_spec_ty) {
        try emitBufPushStringLiteralPadAndRet(emitter, "FmtSpec");
        return;
    }
    if (fmt_ty == .task_group_base_ty or
        fmt_ty == .task_handle_base_ty or
        emitter.input.pool.isTaskGroupType(fmt_ty) or
        emitter.input.pool.isTaskHandleType(fmt_ty))
    {
        try emitter.writeAll(
            "  %_pv = load ptr, ptr %_val_p, align 1\n" ++
                "  call void @_cx_rt_fmt_ptr_spec(ptr %_out_b, ptr %_pv, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n}\n\n",
        );
        return;
    }

    // Backed `enum` (`getSumDetail == null`): variant name under Display/Debug, backing int under radix verbs:
    if (!fmt_ty.isPrimitiveOrSentinel() and
        emitter.input.pool.getNode(fmt_ty).tag == .enum_ty and
        (try emitter.resolver.getSumDetail(fmt_ty)) == null)
    {
        if (try isZeroSizedType(emitter, fmt_ty)) {
            try emitBufPushStringLiteralPadAndRet(emitter, resolveEnumVariantNameLlvm(emitter, fmt_ty, 0));
            return;
        }
        if (resolveIntegerInfo(emitter, fmt_ty)) |enum_int| {
            try emitter.print(
                "  %_ev = load i{d}, ptr %_val_p, align 1\n" ++
                    "  %_evb = call i32 @_cx_rt_eff_verb(i32 %_spec_lo)\n" ++
                    "  %_is_dd = icmp ule i32 %_evb, 1\n" ++
                    "  br i1 %_is_dd, label %_en_chk_0, label %_en_as_int\n",
                .{enum_int.bits},
            );
            const var_count = countEnumVariantsLlvm(emitter, fmt_ty);
            if (var_count == 0) {
                try emitter.writeAll("_en_chk_0:\n  br label %_en_as_int\n");
            } else {
                var var_ord: u32 = 0;
                while (var_ord < var_count) : (var_ord += 1) {
                    const disc_lit = try formatScalarIntLiteralAlloc(
                        emitter.allocator,
                        enum_int.bits,
                        resolveScalarEnumDiscrimI128(emitter, fmt_ty, var_ord),
                    );
                    defer emitter.allocator.free(disc_lit);
                    const var_name = resolveEnumVariantNameLlvm(emitter, fmt_ty, var_ord);
                    const vn_ptr = try emitSynthConstBytesPtr(emitter, var_name);
                    defer emitter.allocator.free(vn_ptr);
                    const next_lbl = if (var_ord + 1 < var_count)
                        try std.fmt.allocPrint(emitter.allocator, "_en_chk_{d}", .{var_ord + 1})
                    else
                        try emitter.allocator.dupe(u8, "_en_as_int");
                    defer emitter.allocator.free(next_lbl);
                    try emitter.print(
                        "_en_chk_{d}:\n" ++
                            "  %_em_{d} = icmp eq i{d} %_ev, {s}\n" ++
                            "  br i1 %_em_{d}, label %_en_hit_{d}, label %{s}\n" ++
                            "_en_hit_{d}:\n" ++
                            "  call void @_cx_rt_buf_pad_str(ptr %_out_b, ptr {s}, i64 {d}, i32 %_spec_lo, i32 %_spec_hi, i32 0)\n" ++
                            "  ret void\n",
                        .{
                            var_ord, var_ord,      enum_int.bits, disc_lit,
                            var_ord, var_ord,      next_lbl,      var_ord,
                            vn_ptr,  var_name.len,
                        },
                    );
                }
            }
            try emitter.writeAll("_en_as_int:\n");
            try emitFormatLoadedScalarInt(emitter, enum_int, "%_ev");
            try emitter.writeAll("}\n\n");
            return;
        }
    }

    if (resolveIntegerInfo(emitter, fmt_ty)) |int_info| {
        try emitter.print("  %_iv = load i{d}, ptr %_val_p, align 1\n", .{int_info.bits});
        try emitFormatLoadedScalarInt(emitter, int_info, "%_iv");
        try emitter.writeAll("}\n\n");
        return;
    }

    if (fmt_ty.isPrimitiveOrSentinel()) {
        try emitter.writeAll("  ret void\n}\n\n");
        return;
    }

    const node = emitter.input.pool.getNode(fmt_ty);
    switch (node.tag) {
        .ref_ty, .mut_ref_ty => {
            const pointee_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
            const val_arg_s = if (emitter.input.pool.isSliceRefType(fmt_ty)) "%_val_p" else "%_rp";
            try emitter.print(
                "  %_rp = load ptr, ptr %_val_p, align 1\n" ++
                    "  %_vsh = lshr i32 %_spec_lo, 27\n" ++
                    "  %_vc = and i32 %_vsh, 15\n" ++
                    "  %_is_p = icmp eq i32 %_vc, 9\n" ++
                    "  br i1 %_is_p, label %_as_p, label %_as_val\n" ++
                    "_as_p:\n" ++
                    "  call void @_cx_rt_fmt_ptr_spec(ptr %_out_b, ptr %_rp, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                    "  ret void\n" ++
                    "_as_val:\n" ++
                    "  call void @_cx_fmt_ty_{d}(ptr %_out_b, ptr {s}, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                    "  ret void\n}}\n\n",
                .{ pointee_ty.toU32(), val_arg_s },
            );
        },
        .raw_ptr_ty, .fn_ty => {
            try emitter.writeAll(
                "  %_pv = load ptr, ptr %_val_p, align 1\n" ++
                    "  call void @_cx_rt_fmt_ptr_spec(ptr %_out_b, ptr %_pv, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                    "  ret void\n}\n\n",
            );
        },
        .struct_ty => {
            const sym_idx = SymbolIndex.fromInt(node.rhs);
            const st_name = if (!sym_idx.isNone() and sym_idx.asInt() < emitter.input.sym_table.symbols.items.len)
                emitter.input.sym_table.getSymbol(sym_idx).name_text
            else
                "struct";
            const lay = try emitter.resolver.resolveType(fmt_ty);
            try emitter.writeAll(
                "  %_cb = alloca { ptr, i64, i64 }, align 8\n" ++
                    "  store { ptr, i64, i64 } zeroinitializer, ptr %_cb, align 8\n" ++
                    "  %_ev = call i32 @_cx_rt_eff_verb(i32 %_spec_lo)\n" ++
                    "  %_id = icmp eq i32 %_ev, 1\n" ++
                    "  %_fspec = select i1 %_id, i32 134217728, i32 0\n",
            );
            try emitBufPushStringLiteralLlvm(emitter, "%_cb", st_name);
            try emitBufPushStringLiteralLlvm(emitter, "%_cb", " { ");
            var fld_i: u32 = 0;
            while (fld_i < lay.aux_len) : (fld_i += 1) {
                if (fld_i > 0) try emitBufPushStringLiteralLlvm(emitter, "%_cb", ", ");
                const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                const fld_ty = try unwrapTransparentType(emitter, fld.field_ty);
                try emitBufPushStringLiteralLlvm(emitter, "%_cb", resolveStructFieldNameLlvm(emitter, fmt_ty, fld_i));
                try emitBufPushStringLiteralLlvm(emitter, "%_cb", ": ");
                try emitter.print(
                    "  %_fp_{d} = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                        "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_fp_{d}, i32 %_fspec, i32 -1)\n",
                    .{ fld_i, ptr_int, fld.byte_offset, fld_ty.toU32(), fld_i },
                );
            }
            try emitBufPushStringLiteralLlvm(emitter, "%_cb", " }");
            try emitFinishScratchBufPadAndRet(emitter);
        },
        .tuple_ty => {
            const lay = try emitter.resolver.resolveType(fmt_ty);
            try emitter.writeAll(
                "  %_cb = alloca { ptr, i64, i64 }, align 8\n" ++
                    "  store { ptr, i64, i64 } zeroinitializer, ptr %_cb, align 8\n" ++
                    "  %_ev = call i32 @_cx_rt_eff_verb(i32 %_spec_lo)\n" ++
                    "  %_id = icmp eq i32 %_ev, 1\n" ++
                    "  %_fspec = select i1 %_id, i32 134217728, i32 0\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 40)\n",
            );
            var fld_i: u32 = 0;
            while (fld_i < lay.aux_len) : (fld_i += 1) {
                if (fld_i > 0) try emitBufPushStringLiteralLlvm(emitter, "%_cb", ", ");
                const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                const fld_ty = try unwrapTransparentType(emitter, fld.field_ty);
                try emitter.print(
                    "  %_tp_{d} = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                        "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_tp_{d}, i32 %_fspec, i32 -1)\n",
                    .{ fld_i, ptr_int, fld.byte_offset, fld_ty.toU32(), fld_i },
                );
            }
            if (lay.aux_len == 1) {
                try emitter.writeAll("  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 44)\n");
            }
            try emitter.writeAll("  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 41)\n");
            try emitFinishScratchBufPadAndRet(emitter);
        },
        .array_ty => {
            const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
            const elem_lay = try emitter.resolver.resolveType(elem_ty);
            const arr_len: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            const sep_ptr = try emitSynthConstBytesPtr(emitter, ", ");
            defer emitter.allocator.free(sep_ptr);
            try emitter.print(
                "  %_cb = alloca {{ ptr, i64, i64 }}, align 8\n" ++
                    "  %_ai_s = alloca i64, align 8\n" ++
                    "  store {{ ptr, i64, i64 }} zeroinitializer, ptr %_cb, align 8\n" ++
                    "  %_ev = call i32 @_cx_rt_eff_verb(i32 %_spec_lo)\n" ++
                    "  %_id = icmp eq i32 %_ev, 1\n" ++
                    "  %_fspec = select i1 %_id, i32 134217728, i32 0\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 91)\n" ++
                    "  store i64 0, ptr %_ai_s, align 8\n" ++
                    "  br label %_al_hdr\n" ++
                    "_al_hdr:\n" ++
                    "  %_ai = load i64, ptr %_ai_s, align 8\n" ++
                    "  %_alt = icmp ult i64 %_ai, {d}\n" ++
                    "  br i1 %_alt, label %_al_b, label %_al_end\n" ++
                    "_al_b:\n" ++
                    "  %_agz = icmp ugt i64 %_ai, 0\n" ++
                    "  br i1 %_agz, label %_al_sep, label %_al_el\n" ++
                    "_al_sep:\n" ++
                    "  call void @_cx_rt_buf_push_bytes(ptr %_cb, ptr {s}, i64 2)\n" ++
                    "  br label %_al_el\n" ++
                    "_al_el:\n" ++
                    "  %_aoff = mul i64 %_ai, {d}\n" ++
                    "  %_aep = getelementptr inbounds i8, ptr %_val_p, i64 %_aoff\n" ++
                    "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_aep, i32 %_fspec, i32 -1)\n" ++
                    "  %_anx = add i64 %_ai, 1\n" ++
                    "  store i64 %_anx, ptr %_ai_s, align 8\n" ++
                    "  br label %_al_hdr\n" ++
                    "_al_end:\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 93)\n",
                .{ arr_len, sep_ptr, elem_lay.stride_bytes, elem_ty.toU32() },
            );
            try emitFinishScratchBufPadAndRet(emitter);
        },
        .slice_ty => {
            const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
            const elem_lay = try emitter.resolver.resolveType(elem_ty);
            const sep_ptr = try emitSynthConstBytesPtr(emitter, ", ");
            defer emitter.allocator.free(sep_ptr);
            const sl_conv = if (is_wasm) "  %_sln = zext i32 %_sl_pt to i64\n" else "  %_sln = add i64 %_sl_pt, 0\n";
            try emitter.print(
                "  %_cb = alloca {{ ptr, i64, i64 }}, align 8\n" ++
                    "  %_ai_s = alloca i64, align 8\n" ++
                    "  store {{ ptr, i64, i64 }} zeroinitializer, ptr %_cb, align 8\n" ++
                    "  %_sl_p = load ptr, ptr %_val_p, align 1\n" ++
                    "  %_sll_p = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                    "  %_sl_pt = load {s}, ptr %_sll_p, align 1\n" ++
                    "{s}" ++
                    "  %_ev = call i32 @_cx_rt_eff_verb(i32 %_spec_lo)\n" ++
                    "  %_id = icmp eq i32 %_ev, 1\n" ++
                    "  %_fspec = select i1 %_id, i32 134217728, i32 0\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 91)\n" ++
                    "  store i64 0, ptr %_ai_s, align 8\n" ++
                    "  br label %_sl_hdr\n" ++
                    "_sl_hdr:\n" ++
                    "  %_ai = load i64, ptr %_ai_s, align 8\n" ++
                    "  %_alt = icmp ult i64 %_ai, %_sln\n" ++
                    "  br i1 %_alt, label %_sl_b, label %_sl_end\n" ++
                    "_sl_b:\n" ++
                    "  %_agz = icmp ugt i64 %_ai, 0\n" ++
                    "  br i1 %_agz, label %_sl_sep, label %_sl_el\n" ++
                    "_sl_sep:\n" ++
                    "  call void @_cx_rt_buf_push_bytes(ptr %_cb, ptr {s}, i64 2)\n" ++
                    "  br label %_sl_el\n" ++
                    "_sl_el:\n" ++
                    "  %_aoff = mul i64 %_ai, {d}\n" ++
                    "  %_aep = getelementptr inbounds i8, ptr %_sl_p, i64 %_aoff\n" ++
                    "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_aep, i32 %_fspec, i32 -1)\n" ++
                    "  %_anx = add i64 %_ai, 1\n" ++
                    "  store i64 %_anx, ptr %_ai_s, align 8\n" ++
                    "  br label %_sl_hdr\n" ++
                    "_sl_end:\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 93)\n",
                .{ ptr_int, ptr_bytes, ptr_int, sl_conv, sep_ptr, elem_lay.stride_bytes, elem_ty.toU32() },
            );
            try emitFinishScratchBufPadAndRet(emitter);
        },
        .optional_ty => {
            const some_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
            const sum_detail = (try emitter.resolver.getSumDetail(fmt_ty)) orelse {
                try emitter.writeAll("  ret void\n}\n\n");
                return;
            };
            var state = try initScratchFmtBodyState(emitter);
            defer state.deinit();
            const discr_s = try emitReadSumDiscriminantFromPtr(emitter, &state, fmt_ty, "%_val_p", 1);
            defer emitter.allocator.free(discr_s);
            if (state.entry_allocas.items.len > 0) try emitter.writeAll(state.entry_allocas.items);
            try emitter.writeAll(
                "  %_cb = alloca { ptr, i64, i64 }, align 8\n" ++
                    "  store { ptr, i64, i64 } zeroinitializer, ptr %_cb, align 8\n",
            );
            try emitter.writeAll(state.cur_buf.items);
            try emitter.print(
                "  %_is_none = icmp eq i32 {s}, 0\n" ++
                    "  br i1 %_is_none, label %_opt_none, label %_opt_some\n" ++
                    "_opt_none:\n",
                .{discr_s},
            );
            try emitBufPushStringLiteralLlvm(emitter, "%_cb", "None");
            try emitter.writeAll("  br label %_opt_end\n_opt_some:\n");
            try emitBufPushStringLiteralLlvm(emitter, "%_cb", "Some(");
            try emitter.print(
                "  %_osp = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                    "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_osp, i32 134217728, i32 -1)\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 41)\n" ++
                    "  br label %_opt_end\n" ++
                    "_opt_end:\n",
                .{ ptr_int, sum_detail.payload_offset, some_ty.toU32() },
            );
            try emitFinishScratchBufPadAndRet(emitter);
        },
        .result_ty => {
            if (try isZeroSizedType(emitter, fmt_ty)) {
                try emitBufPushStringLiteralPadAndRet(emitter, "Ok(())");
                return;
            }
            const ok_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
            const err_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.rhs));
            const sum_detail = (try emitter.resolver.getSumDetail(fmt_ty)) orelse {
                try emitter.writeAll("  ret void\n}\n\n");
                return;
            };
            var state = try initScratchFmtBodyState(emitter);
            defer state.deinit();
            const discr_s = try emitReadSumDiscriminantFromPtr(emitter, &state, fmt_ty, "%_val_p", 1);
            defer emitter.allocator.free(discr_s);
            if (state.entry_allocas.items.len > 0) try emitter.writeAll(state.entry_allocas.items);
            try emitter.writeAll(
                "  %_cb = alloca { ptr, i64, i64 }, align 8\n" ++
                    "  store { ptr, i64, i64 } zeroinitializer, ptr %_cb, align 8\n",
            );
            try emitter.writeAll(state.cur_buf.items);
            try emitter.print(
                "  %_is_ok = icmp eq i32 {s}, 0\n" ++
                    "  br i1 %_is_ok, label %_res_ok, label %_res_err\n" ++
                    "_res_ok:\n",
                .{discr_s},
            );
            try emitBufPushStringLiteralLlvm(emitter, "%_cb", "Ok(");
            try emitter.print(
                "  %_rop = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                    "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_rop, i32 134217728, i32 -1)\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 41)\n" ++
                    "  br label %_res_end\n" ++
                    "_res_err:\n",
                .{ ptr_int, sum_detail.payload_offset, ok_ty.toU32() },
            );
            try emitBufPushStringLiteralLlvm(emitter, "%_cb", "Err(");
            try emitter.print(
                "  %_rep = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                    "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_rep, i32 134217728, i32 -1)\n" ++
                    "  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 41)\n" ++
                    "  br label %_res_end\n" ++
                    "_res_end:\n",
                .{ ptr_int, sum_detail.payload_offset, err_ty.toU32() },
            );
            try emitFinishScratchBufPadAndRet(emitter);
        },
        .enum_ty => {
            if (try isZeroSizedType(emitter, fmt_ty)) {
                try emitBufPushStringLiteralPadAndRet(emitter, resolveEnumVariantNameLlvm(emitter, fmt_ty, 0));
                return;
            }
            const sum_detail = (try emitter.resolver.getSumDetail(fmt_ty)) orelse {
                try emitter.writeAll("  ret void\n}\n\n");
                return;
            };
            var state = try initScratchFmtBodyState(emitter);
            defer state.deinit();
            const discr_s = try emitReadSumDiscriminantFromPtr(emitter, &state, fmt_ty, "%_val_p", 1);
            defer emitter.allocator.free(discr_s);
            if (state.entry_allocas.items.len > 0) try emitter.writeAll(state.entry_allocas.items);
            try emitter.writeAll(
                "  %_cb = alloca { ptr, i64, i64 }, align 8\n" ++
                    "  store { ptr, i64, i64 } zeroinitializer, ptr %_cb, align 8\n",
            );
            try emitter.writeAll(state.cur_buf.items);
            const var_count = countEnumVariantsLlvm(emitter, fmt_ty);
            if (var_count > 0) {
                try emitter.writeAll("  br label %_ev_chk_0\n");
                var var_ord: u32 = 0;
                while (var_ord < var_count) : (var_ord += 1) {
                    const next_lbl = if (var_ord + 1 < var_count)
                        try std.fmt.allocPrint(emitter.allocator, "_ev_chk_{d}", .{var_ord + 1})
                    else
                        try emitter.allocator.dupe(u8, "_ev_end");
                    defer emitter.allocator.free(next_lbl);
                    try emitter.print(
                        "_ev_chk_{d}:\n" ++
                            "  %_evc_{d} = icmp eq i32 {s}, {d}\n" ++
                            "  br i1 %_evc_{d}, label %_ev_hit_{d}, label %{s}\n" ++
                            "_ev_hit_{d}:\n",
                        .{ var_ord, var_ord, discr_s, var_ord, var_ord, var_ord, next_lbl, var_ord },
                    );
                    try emitBufPushStringLiteralLlvm(emitter, "%_cb", resolveEnumVariantNameLlvm(emitter, fmt_ty, var_ord));
                    const var_pay = try unwrapTransparentType(
                        emitter,
                        resolveEnumVariantPayloadType(emitter, fmt_ty, var_ord),
                    );
                    if (var_pay != .unit_ty and !var_pay.isError()) {
                        try emitter.writeAll("  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 40)\n");
                        if (!var_pay.isPrimitiveOrSentinel() and emitter.input.pool.getNode(var_pay).tag == .tuple_ty) {
                            const tup_lay = try emitter.resolver.resolveType(var_pay);
                            var tf_i: u32 = 0;
                            while (tf_i < tup_lay.aux_len) : (tf_i += 1) {
                                if (tf_i > 0) try emitBufPushStringLiteralLlvm(emitter, "%_cb", ", ");
                                const tf = emitter.resolver.fields_by_decl.items[tup_lay.aux_start + tf_i];
                                const tf_ty = try unwrapTransparentType(emitter, tf.field_ty);
                                try emitter.print(
                                    "  %_evtp_{d}_{d} = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                                        "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_evtp_{d}_{d}, i32 134217728, i32 -1)\n",
                                    .{
                                        var_ord,                                    tf_i,          ptr_int,
                                        sum_detail.payload_offset + tf.byte_offset, tf_ty.toU32(), var_ord,
                                        tf_i,
                                    },
                                );
                            }
                        } else {
                            try emitter.print(
                                "  %_evp_{d} = getelementptr inbounds i8, ptr %_val_p, {s} {d}\n" ++
                                    "  call void @_cx_fmt_ty_{d}(ptr %_cb, ptr %_evp_{d}, i32 134217728, i32 -1)\n",
                                .{ var_ord, ptr_int, sum_detail.payload_offset, var_pay.toU32(), var_ord },
                            );
                        }
                        try emitter.writeAll("  call void @_cx_rt_buf_push_byte(ptr %_cb, i8 41)\n");
                    }
                    try emitter.writeAll("  br label %_ev_end\n");
                }
                try emitter.writeAll("_ev_end:\n");
            }
            try emitFinishScratchBufPadAndRet(emitter);
        },
        else => {
            var name_buf: [256]u8 = undefined;
            const rendered = emitter.input.pool.formatType(fmt_ty, emitter.input.sym_table, &name_buf);
            try emitBufPushStringLiteralPadAndRet(emitter, rendered);
        },
    }
}

/// Initializes an empty `BodyEmitState` for discriminant extraction inside `@_cx_fmt_ty_<id>`.
fn initScratchFmtBodyState(emitter: *LlvmModuleEmitter) !BodyEmitState {
    return BodyEmitState{
        .allocator = emitter.allocator,
        .cur_label = try emitter.allocator.dupe(u8, "entry"),
        .local_ptrs = try emitter.allocator.alloc([]u8, 0),
        .local_aligns = try emitter.allocator.alloc(u32, 0),
        .edge_pred_labels = try emitter.allocator.alloc([]u8, 0),
        .edge_call_ret_vals = try emitter.allocator.alloc([]u8, 0),
        .edge_trampoline = try emitter.allocator.alloc(?u32, 0),
        .block_access_group = try emitter.allocator.alloc(u32, 0),
    };
}

/// Pads a constant literal `text` into `%_out_b` and closes `@_cx_fmt_ty_<id>`.
fn emitBufPushStringLiteralPadAndRet(emitter: *LlvmModuleEmitter, text: []const u8) !void {
    const str_ptr = try emitSynthConstBytesPtr(emitter, text);
    defer emitter.allocator.free(str_ptr);
    try emitter.print(
        "  call void @_cx_rt_buf_pad_str(ptr %_out_b, ptr {s}, i64 {d}, i32 %_spec_lo, i32 %_spec_hi, i32 0)\n" ++
            "  ret void\n}}\n\n",
        .{ str_ptr, text.len },
    );
}

/// Pads `%_cb` into `%_out_b`, frees `%_cb.data`, and closes `@_cx_fmt_ty_<id>`.
fn emitFinishScratchBufPadAndRet(emitter: *LlvmModuleEmitter) !void {
    try emitter.writeAll(
        "  %_cbd = load ptr, ptr %_cb, align 8\n" ++
            "  %_cblp = getelementptr inbounds { ptr, i64, i64 }, ptr %_cb, i32 0, i32 1\n" ++
            "  %_cbl = load i64, ptr %_cblp, align 8\n" ++
            "  call void @_cx_rt_buf_pad_str(ptr %_out_b, ptr %_cbd, i64 %_cbl, i32 %_spec_lo, i32 %_spec_hi, i32 0)\n" ++
            "  call void @free(ptr %_cbd)\n" ++
            "  ret void\n}\n\n",
    );
}

/// Emits signed/unsigned scalar integer formatting (`i8..i128` / `u8..u128`) into `%_out_b`.
fn emitFormatLoadedScalarInt(
    emitter: *LlvmModuleEmitter,
    int_info: IntScalarInfo,
    ssa_name: []const u8,
) !void {
    if (int_info.bits == 128) {
        if (int_info.is_signed) {
            try emitter.print(
                "  call void @_cx_rt_fmt_i128_spec(ptr %_out_b, i128 {s}, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                    "  ret void\n",
                .{ssa_name},
            );
        } else {
            try emitter.print(
                "  call void @_cx_rt_fmt_u128_spec(ptr %_out_b, i128 {s}, i32 0, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                    "  ret void\n",
                .{ssa_name},
            );
        }
        return;
    }
    if (!int_info.is_signed) {
        try emitter.print(
            "  %_iu128 = zext i{d} {s} to i128\n" ++
                "  call void @_cx_rt_fmt_u128_spec(ptr %_out_b, i128 %_iu128, i32 0, i32 %_spec_lo, i32 %_spec_hi)\n" ++
                "  ret void\n",
            .{ int_info.bits, ssa_name },
        );
        return;
    }
    try emitter.print(
        "  %_ivsh = lshr i32 %_spec_lo, 27\n" ++
            "  %_ivc = and i32 %_ivsh, 15\n" ++
            "  %_ige2 = icmp uge i32 %_ivc, 2\n" ++
            "  %_ile5 = icmp ule i32 %_ivc, 5\n" ++
            "  %_irad = and i1 %_ige2, %_ile5\n" ++
            "  br i1 %_irad, label %_int_rad, label %_int_sgn\n" ++
            "_int_rad:\n" ++
            "  %_iu128 = zext i{d} {s} to i128\n" ++
            "  call void @_cx_rt_fmt_u128_spec(ptr %_out_b, i128 %_iu128, i32 0, i32 %_spec_lo, i32 %_spec_hi)\n" ++
            "  ret void\n" ++
            "_int_sgn:\n" ++
            "  %_is128 = sext i{d} {s} to i128\n" ++
            "  call void @_cx_rt_fmt_i128_spec(ptr %_out_b, i128 %_is128, i32 %_spec_lo, i32 %_spec_hi)\n" ++
            "  ret void\n",
        .{ int_info.bits, ssa_name, int_info.bits, ssa_name },
    );
}

/// Emits `@_cx_drop_ty_<id>(ptr %_self_ptr)` helpers for all registered `drop_type_list` types.
fn emitDropHelpersAndClosureThunks(emitter: *LlvmModuleEmitter) !void {
    const ptr_int = ptrIntType(emitter);
    const fn_attrs = fnUnwindAttrs(emitter);

    // [1] Synthesized closure forwarding thunks `@_cx_cthunk_<idx>` and 3-word env drop thunks:
    for (emitter.closure_thunks.items, 0..) |thunk, thunk_idx| {
        try emitSingleClosureThunk(emitter, thunk, @intCast(thunk_idx));
        if (thunk.is_three_word) {
            try emitSingleClosureEnvDropThunk(emitter, thunk, @intCast(thunk_idx));
        }
    }

    // [1b] Synthesized stateful `fn(…)` `%_cx_ctx` adapter thunks `@_cx_fn_ctxwrap_<target_b>`:
    for (emitter.ctx_wrap_bodies.items) |target_b| {
        if (emitter.ctx_wrap_map.get(target_b)) |wrap_fn_ty| {
            try emitSingleFnCtxWrapper(emitter, target_b, wrap_fn_ty);
        }
    }

    // [2] Synthesized recursive drop glue `@_cx_drop_ty_<id>`:
    for (emitter.drop_type_list.items) |drop_ty| {
        if (try isZeroSizedType(emitter, drop_ty)) continue;
        try emitter.print(
            "define internal void @_cx_drop_ty_{d}(ptr %_self_ptr) {s} {{\n" ++
                "entry:\n" ++
                "  %_isn = icmp eq ptr %_self_ptr, null\n" ++
                "  br i1 %_isn, label %done_drop, label %run_drop\n",
            .{ drop_ty.toU32(), fn_attrs },
        );

        var state = BodyEmitState{
            .allocator = emitter.allocator,
            .cur_label = try emitter.allocator.dupe(u8, "run_drop"),
            .local_ptrs = try emitter.allocator.alloc([]u8, 0),
            .local_aligns = try emitter.allocator.alloc(u32, 0),
            .edge_pred_labels = try emitter.allocator.alloc([]u8, 0),
            .edge_call_ret_vals = try emitter.allocator.alloc([]u8, 0),
            .edge_trampoline = try emitter.allocator.alloc(?u32, 0),
            .block_access_group = try emitter.allocator.alloc(u32, 0),
        };
        defer state.deinit();

        if (lookupDropBodyIndexForType(emitter, drop_ty)) |drop_b| {
            const drop_body = &emitter.input.bodies[drop_b];
            const drop_rec = &emitter.body_recipes.items[drop_b];
            const p_decl = drop_body.locals.items[1];
            const p_unwrapped = emitter.input.pool.unwrapUnderlyingType(p_decl.type_id);
            const p_tag = emitter.input.pool.getNode(p_unwrapped).tag;
            const is_ptr_param = p_decl.mode() == .inout_mode or p_decl.mode() == .set_mode or
                p_tag == .ref_ty or p_tag == .mut_ref_ty or p_tag == .raw_ptr_ty;
            const drop_lay = try emitter.resolver.resolveType(drop_ty);

            var call_args: std.ArrayListUnmanaged(u8) = .empty;
            defer call_args.deinit(emitter.allocator);
            var arg_emitted: usize = 0;
            if (drop_rec.has_implicit_context) {
                const ctx_decl = try formatAbiParamDeclPiece(
                    emitter,
                    .usize_ty,
                    drop_rec.context_recipe,
                    "@_cx_default_ctx",
                );
                defer emitter.allocator.free(ctx_decl);
                try call_args.appendSlice(emitter.allocator, ctx_decl);
                arg_emitted += 1;
            }
            var bounce_slot_opt: ?[]u8 = null;
            var bounce_align: u32 = 1;
            defer if (bounce_slot_opt) |bs| emitter.allocator.free(bs);

            if (drop_rec.param_recipes.len >= 1 and drop_rec.param_recipes[0].pass_mode != .ignore_zst) {
                const p0_rec = drop_rec.param_recipes[0];
                const is_indirect_self = is_ptr_param or p0_rec.pass_mode == .indirect_by_ref or
                    p0_rec.pass_mode == .indirect_byval;
                const arg_op = if (is_indirect_self) blk: {
                    if (p0_rec.pointee_align_bytes > 1 and drop_lay.size_bytes > 0) {
                        bounce_align = @max(drop_lay.alignBytes(), p0_rec.pointee_align_bytes);
                        const bounce_slot = try state.allocEntryBytes(drop_lay.size_bytes, bounce_align);
                        try emitMemcpyBytes(
                            emitter,
                            &state,
                            bounce_slot,
                            bounce_align,
                            "%_self_ptr",
                            1,
                            drop_lay.size_bytes,
                        );
                        bounce_slot_opt = try emitter.allocator.dupe(u8, bounce_slot);
                        break :blk bounce_slot;
                    }
                    break :blk try emitter.allocator.dupe(u8, "%_self_ptr");
                } else blk: {
                    const loaded_v = try emitLoadValueFromPtr(
                        emitter,
                        &state,
                        p_decl.type_id,
                        "%_self_ptr",
                        1,
                        null,
                        0,
                        0,
                        0,
                    );
                    defer emitter.allocator.free(loaded_v);
                    const abi_ty = try formatAbiParamOrRetType(emitter, p_decl.type_id, p0_rec);
                    defer emitter.allocator.free(abi_ty);
                    break :blk try emitCoerceValueToAbi(emitter, &state, p_decl.type_id, loaded_v, abi_ty);
                };
                defer emitter.allocator.free(arg_op);
                const piece_decl = try formatAbiParamDeclPiece(emitter, p_decl.type_id, p0_rec, arg_op);
                defer emitter.allocator.free(piece_decl);
                if (arg_emitted > 0) try call_args.appendSlice(emitter.allocator, ", ");
                try call_args.appendSlice(emitter.allocator, piece_decl);
            }

            const callee_op = if (emitter.input.is_dev_got_enabled) blk: {
                const got_t = state.nextTmp();
                try state.print(
                    "  %_got_p_{d} = getelementptr inbounds [{d} x ptr], " ++
                        "ptr @_cx_dev_got, {s} 0, {s} {d}\n" ++
                        "  %_got_fn_{d} = load ptr, ptr %_got_p_{d}, align {d}\n",
                    .{
                        got_t,
                        @max(emitter.input.bodies.len, 1),
                        ptr_int,
                        ptr_int,
                        drop_b,
                        got_t,
                        got_t,
                        emitter.cfg.target.ptrBytes(),
                    },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_got_fn_{d}", .{got_t});
            } else try formatLlvmGlobalIdent(emitter.allocator, emitter.body_llvm_names.items[drop_b]);
            defer emitter.allocator.free(callee_op);

            try state.print(
                "  call {s}void {s}({s})\n",
                .{ resolveCallingConvPrefix(drop_rec), callee_op, call_args.items },
            );
            if (bounce_slot_opt) |bounce_slot| {
                if (is_ptr_param and !drop_rec.param_recipes[0].attrs().is_readonly) {
                    try emitMemcpyBytes(
                        emitter,
                        &state,
                        "%_self_ptr",
                        1,
                        bounce_slot,
                        bounce_align,
                        drop_lay.size_bytes,
                    );
                }
            }
        }

        const node = emitter.input.pool.getNode(drop_ty);
        switch (node.tag) {
            .struct_ty, .tuple_ty => {
                const lay = try emitter.resolver.resolveType(drop_ty);
                var rev_i: u32 = lay.aux_len;
                while (rev_i > 0) {
                    rev_i -= 1;
                    const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + rev_i];
                    const fld_ty = try unwrapTransparentType(emitter, fld.field_ty);
                    if (fld.size_bytes > 0 and emitter.drop_type_set.contains(fld_ty.toU32())) {
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_dfld_{d} = getelementptr inbounds i8, ptr %_self_ptr, {s} {d}\n" ++
                                "  call void @_cx_drop_ty_{d}(ptr %_dfld_{d})\n",
                            .{ t_id, ptr_int, fld.byte_offset, fld_ty.toU32(), t_id },
                        );
                    }
                }
            },
            .array_ty => {
                const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
                const arr_len: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                if (arr_len > 0 and emitter.drop_type_set.contains(elem_ty.toU32()) and
                    !(try isZeroSizedType(emitter, elem_ty)))
                {
                    const elem_lay = try emitter.resolver.resolveType(elem_ty);
                    var elem_k: u64 = arr_len;
                    while (elem_k > 0) {
                        elem_k -= 1;
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_darr_{d} = getelementptr inbounds i8, ptr %_self_ptr, {s} {d}\n" ++
                                "  call void @_cx_drop_ty_{d}(ptr %_darr_{d})\n",
                            .{ t_id, ptr_int, elem_k * elem_lay.stride_bytes, elem_ty.toU32(), t_id },
                        );
                    }
                }
            },
            .soa_vec_ty => {
                const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
                const st_lay = try emitter.resolver.resolveType(elem_struct);
                const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
                const t_id = state.nextTmp();
                try state.print(
                    "  %_svp_{d} = load ptr, ptr %_self_ptr, align 1\n" ++
                        "  %_svlp_{d} = getelementptr inbounds i8, ptr %_self_ptr, {s} {d}\n" ++
                        "  %_svl32_{d} = load i32, ptr %_svlp_{d}, align 1\n" ++
                        "  %_svcp_{d} = getelementptr inbounds i8, ptr %_self_ptr, {s} {d}\n" ++
                        "  %_svc32_{d} = load i32, ptr %_svcp_{d}, align 1\n" ++
                        "  %_svap_{d} = getelementptr inbounds i8, ptr %_self_ptr, {s} {d}\n" ++
                        "  %_sva_{d} = load {s}, ptr %_svap_{d}, align 1\n",
                    .{
                        t_id,
                        t_id,
                        ptr_int,
                        ptr_bytes,
                        t_id,
                        t_id,
                        t_id,
                        ptr_int,
                        ptr_bytes + 4,
                        t_id,
                        t_id,
                        t_id,
                        ptr_int,
                        ptr_bytes + 8,
                        t_id,
                        ptr_int,
                        t_id,
                    },
                );
                if (!type_system.isTrivialDropType(emitter.input.pool, emitter.input.sym_table, elem_struct)) {
                    const idx_slot = try state.allocEntryBytes(4, 4);
                    defer emitter.allocator.free(idx_slot);
                    const cap_ssa = if (ptr_bytes == 4)
                        try std.fmt.allocPrint(emitter.allocator, "%_svc32_{d}", .{t_id})
                    else blk_z: {
                        try state.print("  %_svcz_{d} = zext i32 %_svc32_{d} to i64\n", .{ t_id, t_id });
                        break :blk_z try std.fmt.allocPrint(emitter.allocator, "%_svcz_{d}", .{t_id});
                    };
                    defer emitter.allocator.free(cap_ssa);
                    try state.print(
                        "  %_sv_hn_{d} = icmp ne ptr %_svp_{d}, null\n" ++
                            "  %_sv_hl_{d} = icmp ugt i32 %_svl32_{d}, 0\n" ++
                            "  %_sv_go_{d} = and i1 %_sv_hn_{d}, %_sv_hl_{d}\n" ++
                            "  store i32 %_svl32_{d}, ptr {s}, align 4\n" ++
                            "  br i1 %_sv_go_{d}, label %_svd_lp_{d}, label %_svd_fr_{d}\n" ++
                            "_svd_lp_{d}:\n" ++
                            "  %_svd_cur_{d} = load i32, ptr {s}, align 4\n" ++
                            "  %_svd_more_{d} = icmp ugt i32 %_svd_cur_{d}, 0\n" ++
                            "  br i1 %_svd_more_{d}, label %_svd_bd_{d}, label %_svd_fr_{d}\n" ++
                            "_svd_bd_{d}:\n" ++
                            "  %_svd_nx_{d} = sub i32 %_svd_cur_{d}, 1\n" ++
                            "  store i32 %_svd_nx_{d}, ptr {s}, align 4\n",
                        .{
                            t_id,     t_id,     t_id, t_id,     t_id, t_id, t_id,
                            t_id,     idx_slot, t_id, t_id,     t_id, t_id, t_id,
                            idx_slot, t_id,     t_id, t_id,     t_id, t_id, t_id,
                            t_id,     t_id,     t_id, idx_slot,
                        },
                    );
                    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_svd_bd_{d}", .{t_id}));
                    const elem_i_ssa = if (ptr_bytes == 4)
                        try std.fmt.allocPrint(emitter.allocator, "%_svd_nx_{d}", .{t_id})
                    else blk_i64: {
                        try state.print("  %_svd_i64_{d} = zext i32 %_svd_nx_{d} to i64\n", .{ t_id, t_id });
                        break :blk_i64 try std.fmt.allocPrint(emitter.allocator, "%_svd_i64_{d}", .{t_id});
                    };
                    defer emitter.allocator.free(elem_i_ssa);
                    var rev_col: u32 = st_lay.aux_len;
                    while (rev_col > 0) {
                        rev_col -= 1;
                        const fld = emitter.resolver.fields_by_decl.items[st_lay.aux_start + rev_col];
                        const fld_ty = try unwrapTransparentType(emitter, fld.field_ty);
                        if (fld.size_bytes == 0 or !emitter.drop_type_set.contains(fld_ty.toU32())) continue;
                        const dyn_col = try emitDynamicSoaColByteOffset(emitter, &state, elem_struct, rev_col, cap_ssa);
                        defer emitter.allocator.free(dyn_col.off_ssa);
                        const sub_t = state.nextTmp();
                        try state.print(
                            "  %_svd_co_{d} = mul {s} {s}, {d}\n" ++
                                "  %_svd_bo_{d} = add {s} {s}, %_svd_co_{d}\n" ++
                                "  %_svd_fp_{d} = getelementptr inbounds i8, ptr %_svp_{d}, {s} %_svd_bo_{d}\n" ++
                                "  call void @_cx_drop_ty_{d}(ptr %_svd_fp_{d})\n",
                            .{
                                sub_t,          ptr_int, elem_i_ssa,      fld.size_bytes,
                                sub_t,          ptr_int, dyn_col.off_ssa, sub_t,
                                sub_t,          t_id,    ptr_int,         sub_t,
                                fld_ty.toU32(), sub_t,
                            },
                        );
                    }
                    try state.print("  br label %_svd_lp_{d}\n_svd_fr_{d}:\n", .{ t_id, t_id });
                    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_svd_fr_{d}", .{t_id}));
                }
                const slab_align: u32 = @max(
                    @as(u32, 1) << @intCast(@max(st_lay.align_log2, emitter.target_layout.simd_align_log2)),
                    16,
                );
                try state.print(
                    "  %_sv_nn_{d} = icmp ne ptr %_svp_{d}, null\n" ++
                        "  %_sv_hc_{d} = icmp ugt i32 %_svc32_{d}, 0\n" ++
                        "  %_sv_df_{d} = and i1 %_sv_nn_{d}, %_sv_hc_{d}\n" ++
                        "  br i1 %_sv_df_{d}, label %_svd_cf_{d}, label %_svd_zr_{d}\n" ++
                        "_svd_cf_{d}:\n",
                    .{
                        t_id, t_id, t_id, t_id, t_id,
                        t_id, t_id, t_id, t_id, t_id,
                        t_id,
                    },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_svd_cf_{d}", .{t_id}));
                const free_cap_ssa = if (ptr_bytes == 4)
                    try std.fmt.allocPrint(emitter.allocator, "%_svc32_{d}", .{t_id})
                else blk_fcz: {
                    try state.print("  %_sv_fcz_{d} = zext i32 %_svc32_{d} to i64\n", .{ t_id, t_id });
                    break :blk_fcz try std.fmt.allocPrint(emitter.allocator, "%_sv_fcz_{d}", .{t_id});
                };
                defer emitter.allocator.free(free_cap_ssa);
                var old_tot_ssa: []u8 = try emitter.allocator.dupe(u8, "0");
                defer emitter.allocator.free(old_tot_ssa);
                if (st_lay.aux_len > 0) {
                    const last_ord = st_lay.aux_len - 1;
                    const last_col = try emitDynamicSoaColByteOffset(emitter, &state, elem_struct, last_ord, free_cap_ssa);
                    defer emitter.allocator.free(last_col.off_ssa);
                    const last_fld = emitter.resolver.fields_by_decl.items[st_lay.aux_start + last_ord];
                    try state.print(
                        "  %_svd_lm_{d} = mul {s} {s}, {d}\n" ++
                            "  %_svd_tot_{d} = add {s} {s}, %_svd_lm_{d}\n",
                        .{ t_id, ptr_int, free_cap_ssa, last_fld.size_bytes, t_id, ptr_int, last_col.off_ssa, t_id },
                    );
                    emitter.allocator.free(old_tot_ssa);
                    old_tot_ssa = try std.fmt.allocPrint(emitter.allocator, "%_svd_tot_{d}", .{t_id});
                }
                try state.print(
                    "  call void @_cx_soa_free({s} %_sva_{d}, ptr %_svp_{d}, {s} {s}, {s} {d})\n" ++
                        "  br label %_svd_zr_{d}\n" ++
                        "_svd_zr_{d}:\n" ++
                        "  store ptr null, ptr %_self_ptr, align 1\n" ++
                        "  store i32 0, ptr %_svlp_{d}, align 1\n" ++
                        "  store i32 0, ptr %_svcp_{d}, align 1\n",
                    .{
                        ptr_int, t_id, t_id, ptr_int, old_tot_ssa, ptr_int, slab_align,
                        t_id,    t_id, t_id, t_id,
                    },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_svd_zr_{d}", .{t_id}));
            },
            .optional_ty, .result_ty, .enum_ty => {
                if (try emitter.resolver.getSumDetail(drop_ty)) |sum_detail| {
                    const discr_s = try emitReadSumDiscriminantFromPtr(emitter, &state, drop_ty, "%_self_ptr", 1);
                    defer emitter.allocator.free(discr_s);
                    const var_count: u32 = switch (node.tag) {
                        .optional_ty, .result_ty => 2,
                        .enum_ty => blk: {
                            const sym_idx = SymbolIndex.fromInt(node.rhs);
                            if (sym_idx.isNone() or sym_idx.asInt() >= emitter.input.sym_table.symbols.items.len) {
                                break :blk 0;
                            }
                            const enum_sym = emitter.input.sym_table.getSymbol(sym_idx).*;
                            if (enum_sym.target_scope.isNone()) break :blk 0;
                            var cnt: u32 = 0;
                            for (emitter.input.sym_table.getScopeMembers(enum_sym.target_scope)) |m_idx| {
                                if (emitter.input.sym_table.getSymbol(m_idx).kind == .enum_variant_sym) cnt += 1;
                            }
                            break :blk cnt;
                        },
                        else => 0,
                    };
                    var var_ord: u32 = 0;
                    while (var_ord < var_count) : (var_ord += 1) {
                        const v_pay = try unwrapTransparentType(
                            emitter,
                            resolveEnumVariantPayloadType(emitter, drop_ty, var_ord),
                        );
                        if (emitter.drop_type_set.contains(v_pay.toU32()) and
                            !(try isZeroSizedType(emitter, v_pay)))
                        {
                            const t_id = state.nextTmp();
                            try state.print(
                                "  %_dvc_{d} = icmp eq i32 {s}, {d}\n" ++
                                    "  br i1 %_dvc_{d}, label %_dv_hit_{d}, label %_dv_nxt_{d}\n" ++
                                    "_dv_hit_{d}:\n" ++
                                    "  %_dvp_{d} = getelementptr inbounds i8, ptr %_self_ptr, {s} {d}\n" ++
                                    "  call void @_cx_drop_ty_{d}(ptr %_dvp_{d})\n" ++
                                    "  br label %_dv_nxt_{d}\n" ++
                                    "_dv_nxt_{d}:\n",
                                .{
                                    t_id,
                                    discr_s,
                                    var_ord,
                                    t_id,
                                    t_id,
                                    t_id,
                                    t_id,
                                    t_id,
                                    ptr_int,
                                    sum_detail.payload_offset,
                                    v_pay.toU32(),
                                    t_id,
                                    t_id,
                                    t_id,
                                },
                            );
                        }
                    }
                }
            },
            .closure_ty => {
                if (codegen_abi.isThreeWordClosureType(emitter.input.pool, drop_ty)) {
                    const t_id = state.nextTmp();
                    const dfn_off: u64 = 2 * @as(u64, emitter.cfg.target.ptrBytes());
                    try state.print(
                        "  %_cl_env_{d} = load ptr, ptr %_self_ptr, align 1\n" ++
                            "  %_cl_dfp_{d} = getelementptr inbounds i8, ptr %_self_ptr, {s} {d}\n" ++
                            "  %_cl_dfn_{d} = load ptr, ptr %_cl_dfp_{d}, align 1\n" ++
                            "  %_cl_hdf_{d} = icmp ne ptr %_cl_dfn_{d}, null\n" ++
                            "  br i1 %_cl_hdf_{d}, label %_cl_do_{d}, label %_cl_nx_{d}\n" ++
                            "_cl_do_{d}:\n" ++
                            "  store ptr null, ptr %_cl_dfp_{d}, align 1\n" ++
                            "  call void %_cl_dfn_{d}(ptr %_cl_env_{d})\n" ++
                            "  br label %_cl_nx_{d}\n" ++
                            "_cl_nx_{d}:\n",
                        .{
                            t_id, t_id, ptr_int, dfn_off, t_id, t_id, t_id, t_id,
                            t_id, t_id, t_id,    t_id,    t_id, t_id, t_id, t_id,
                            t_id,
                        },
                    );
                }
            },
            .future_ty => {
                if (emitter.has_async_ops) {
                    try state.writeAll("  call void @_cx_async_fut_cancel(ptr %_self_ptr)\n");
                }
            },
            else => {},
        }

        try emitter.writeAll("run_drop:\n");
        if (state.entry_allocas.items.len > 0) {
            try emitter.writeAll(state.entry_allocas.items);
        }
        try emitter.writeAll(state.cur_buf.items);
        try emitter.writeAll("  br label %done_drop\ndone_drop:\n  ret void\n}\n\n");
    }

    // [3] Synthesized string interpolation & `FmtArgs` formatting helpers (`SE-12`):
    if (emitter.has_fmt_rt_helpers) {
        try ensureFmtRuntimeHelpers(emitter);
        for (emitter.fmt_type_list.items) |fmt_ty| {
            try emitFmtHelperForType(emitter, fmt_ty);
        }
    }
}

/// Adapts incoming parameter `param_name` (`src_rec`) into a callee argument declaration piece (`dst_rec`).
fn emitForwardAdaptedParamLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    param_ty: TypeId,
    src_rec: codegen_abi.AbiParamRecipe,
    dst_rec: codegen_abi.AbiParamRecipe,
    param_name: []const u8,
) ![]u8 {
    const src_abi_ty = try formatAbiParamOrRetType(emitter, param_ty, src_rec);
    defer emitter.allocator.free(src_abi_ty);
    const dst_abi_ty = try formatAbiParamOrRetType(emitter, param_ty, dst_rec);
    defer emitter.allocator.free(dst_abi_ty);

    const is_src_indirect = src_rec.pass_mode == .indirect_by_ref or src_rec.pass_mode == .indirect_byval;
    const is_dst_indirect = dst_rec.pass_mode == .indirect_by_ref or dst_rec.pass_mode == .indirect_byval;

    if (src_rec.pass_mode == dst_rec.pass_mode and
        std.mem.eql(u8, src_abi_ty, dst_abi_ty) and
        (!is_dst_indirect or src_rec.pointee_align_bytes >= dst_rec.pointee_align_bytes))
    {
        return formatAbiParamDeclPiece(emitter, param_ty, dst_rec, param_name);
    }

    const lay = try emitter.resolver.resolveType(param_ty);
    const slot_align = @max(@max(lay.alignBytes(), dst_rec.pointee_align_bytes), 8);
    const slot_ptr = try state.allocEntryBytes(@max(lay.size_bytes, 1), slot_align);
    defer emitter.allocator.free(slot_ptr);

    if (is_src_indirect) {
        try emitMemcpyBytes(
            emitter,
            state,
            slot_ptr,
            slot_align,
            param_name,
            @max(src_rec.pointee_align_bytes, 1),
            lay.size_bytes,
        );
    } else {
        const unpacked_v = try emitCoerceAbiToValue(emitter, state, param_ty, src_abi_ty, param_name);
        defer emitter.allocator.free(unpacked_v);
        try emitStoreValueToPtr(emitter, state, param_ty, unpacked_v, slot_ptr, slot_align, 0, 0, 0);
    }

    if (is_dst_indirect) {
        return formatAbiParamDeclPiece(emitter, param_ty, dst_rec, slot_ptr);
    }

    const loaded_v = try emitLoadValueFromPtr(
        emitter,
        state,
        param_ty,
        slot_ptr,
        slot_align,
        null,
        0,
        0,
        0,
    );
    defer emitter.allocator.free(loaded_v);
    const coerced_v = try emitCoerceValueToAbi(emitter, state, param_ty, loaded_v, dst_abi_ty);
    defer emitter.allocator.free(coerced_v);
    return formatAbiParamDeclPiece(emitter, param_ty, dst_rec, coerced_v);
}

/// Emits a synthesized 3-word heap-closure environment drop thunk `@_cx_cdrop_<idx>(ptr %_env)`.
fn emitSingleClosureEnvDropThunk(
    emitter: *LlvmModuleEmitter,
    thunk: ClosureThunkSpec,
    thunk_idx: u32,
) !void {
    if (!emitter.declared_externs.contains("free")) {
        try emitter.requireIntrinsicDecl("declare void @free(ptr) nounwind");
    }
    const ptr_int = ptrIntType(emitter);
    try emitter.print(
        "define internal void @_cx_cdrop_{d}(ptr %_env) {s} {{\n" ++
            "entry:\n" ++
            "  %_isn = icmp eq ptr %_env, null\n" ++
            "  br i1 %_isn, label %done_cdrop, label %run_cdrop\n" ++
            "run_cdrop:\n",
        .{ thunk_idx, fnUnwindAttrs(emitter) },
    );

    var cap_slots: std.ArrayListUnmanaged(CapDropSlot) = .empty;
    defer cap_slots.deinit(emitter.allocator);

    var cur_off: u64 = 0;
    for (thunk.capture_types) |cap_ty| {
        const cap_lay = try emitter.resolver.resolveType(cap_ty);
        if (cap_lay.size_bytes == 0) continue;
        cur_off = std.mem.alignForward(u64, cur_off, @max(@as(u64, cap_lay.alignBytes()), 1));
        const unwrapped_cap = try unwrapTransparentType(emitter, cap_ty);
        if (emitter.drop_type_set.contains(unwrapped_cap.toU32()) and
            !(try isZeroSizedType(emitter, unwrapped_cap)))
        {
            try cap_slots.append(emitter.allocator, .{
                .byte_offset = cur_off,
                .drop_ty = unwrapped_cap,
            });
        }
        cur_off += cap_lay.size_bytes;
    }

    var rev_i: usize = cap_slots.items.len;
    while (rev_i > 0) {
        rev_i -= 1;
        const slot = cap_slots.items[rev_i];
        try emitter.print(
            "  %_cenv_d_{d} = getelementptr inbounds i8, ptr %_env, {s} {d}\n" ++
                "  call void @_cx_drop_ty_{d}(ptr %_cenv_d_{d})\n",
            .{ rev_i, ptr_int, slot.byte_offset, slot.drop_ty.toU32(), rev_i },
        );
    }

    try emitter.writeAll(
        "  call void @free(ptr %_env)\n" ++
            "  br label %done_cdrop\n" ++
            "done_cdrop:\n" ++
            "  ret void\n" ++
            "}\n\n",
    );
}

/// Emits ABI-adapted return forwarding from `callee_ret_val` (`callee_ret_bare`) to `thunk_ret_bare`.
fn emitThunkAdaptedReturnLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    callee_ret_ty: TypeId,
    callee_has_sret: bool,
    callee_sret_slot: ?[]const u8,
    callee_ret_bare: []const u8,
    callee_ret_val: []const u8,
    thunk_has_sret: bool,
    thunk_ret_bare: []const u8,
) !void {
    if (thunk_has_sret) {
        if (!callee_has_sret and !std.mem.eql(u8, callee_ret_bare, "void")) {
            const lay = try emitter.resolver.resolveType(callee_ret_ty);
            const unpacked = try emitCoerceAbiToValue(
                emitter,
                state,
                callee_ret_ty,
                callee_ret_bare,
                callee_ret_val,
            );
            defer emitter.allocator.free(unpacked);
            try emitStoreValueToPtr(
                emitter,
                state,
                callee_ret_ty,
                unpacked,
                "%_sret",
                @max(lay.alignBytes(), 1),
                0,
                0,
                0,
            );
        }
        try state.writeAll("  ret void\n");
        return;
    }

    if (std.mem.eql(u8, thunk_ret_bare, "void")) {
        try state.writeAll("  ret void\n");
        return;
    }

    if (callee_has_sret) {
        const sret_slot = callee_sret_slot orelse "%_sret";
        const lay = try emitter.resolver.resolveType(callee_ret_ty);
        const loaded = try emitLoadValueFromPtr(
            emitter,
            state,
            callee_ret_ty,
            sret_slot,
            @max(lay.alignBytes(), 8),
            null,
            0,
            0,
            0,
        );
        defer emitter.allocator.free(loaded);
        const coerced = try emitCoerceValueToAbi(
            emitter,
            state,
            callee_ret_ty,
            loaded,
            thunk_ret_bare,
        );
        defer emitter.allocator.free(coerced);
        try state.print("  ret {s} {s}\n", .{ thunk_ret_bare, coerced });
        return;
    }

    if (std.mem.eql(u8, callee_ret_bare, thunk_ret_bare)) {
        try state.print("  ret {s} {s}\n", .{ thunk_ret_bare, callee_ret_val });
        return;
    }

    const unpacked = try emitCoerceAbiToValue(
        emitter,
        state,
        callee_ret_ty,
        callee_ret_bare,
        callee_ret_val,
    );
    defer emitter.allocator.free(unpacked);
    const coerced = try emitCoerceValueToAbi(
        emitter,
        state,
        callee_ret_ty,
        unpacked,
        thunk_ret_bare,
    );
    defer emitter.allocator.free(coerced);
    try state.print("  ret {s} {s}\n", .{ thunk_ret_bare, coerced });
}

/// Emits a synthesized closure forwarding thunk `@_cx_cthunk_<idx>(ptr %_env, …)`.
fn emitSingleClosureThunk(
    emitter: *LlvmModuleEmitter,
    thunk: ClosureThunkSpec,
    thunk_idx: u32,
) !void {
    const sig_view = emitter.input.pool.getFnSignatureView(thunk.closure_ty) orelse return;
    var clos_recipe = try classifyFnTypeAbi(emitter, thunk.closure_ty, false, true);
    defer clos_recipe.deinit(emitter.allocator);

    const callee_rec = &emitter.body_recipes.items[thunk.callee_body_idx];
    const callee_body = &emitter.input.bodies[thunk.callee_body_idx];
    const ptr_int = ptrIntType(emitter);

    const ret_decl = try formatAbiReturnDecl(emitter, sig_view.ret_ty, &clos_recipe);
    defer emitter.allocator.free(ret_decl.full_decl);
    defer emitter.allocator.free(ret_decl.bare_ty);

    try emitter.print(
        "define internal {s}{s} @_cx_cthunk_{d}(",
        .{ resolveCallingConvPrefix(&clos_recipe), ret_decl.full_decl, thunk_idx },
    );
    var hdr_count: usize = 0;
    if (clos_recipe.has_sret) {
        const sret_s = try formatAbiParamDeclPiece(
            emitter,
            sig_view.ret_ty,
            clos_recipe.sret_recipe,
            "%_sret",
        );
        defer emitter.allocator.free(sret_s);
        try emitter.writeAll(sret_s);
        hdr_count += 1;
    }
    if (hdr_count > 0) try emitter.writeAll(", ");
    try emitter.writeAll(if (thunk.is_three_word) "ptr noundef %_env" else "ptr nonnull noundef %_env");
    hdr_count += 1;

    for (clos_recipe.param_recipes, 0..) |p_rec, idx| {
        if (p_rec.pass_mode == .ignore_zst) continue;
        const p_name = try std.fmt.allocPrint(emitter.allocator, "%_cp_{d}", .{idx});
        defer emitter.allocator.free(p_name);
        const piece_s = try formatAbiParamDeclPiece(emitter, sig_view.getParamType(idx), p_rec, p_name);
        defer emitter.allocator.free(piece_s);
        try emitter.writeAll(", ");
        try emitter.writeAll(piece_s);
    }
    if (clos_recipe.swifterror_kind != .none) {
        try emitter.writeAll(", ptr swifterror %_cx_err_slot");
    }
    try emitter.print(") {s} {{\nentry:\n", .{fnUnwindAttrs(emitter)});

    var state = BodyEmitState{
        .allocator = emitter.allocator,
        .cur_label = try emitter.allocator.dupe(u8, "entry"),
        .local_ptrs = try emitter.allocator.alloc([]u8, 0),
        .local_aligns = try emitter.allocator.alloc(u32, 0),
        .edge_pred_labels = try emitter.allocator.alloc([]u8, 0),
        .edge_call_ret_vals = try emitter.allocator.alloc([]u8, 0),
        .edge_trampoline = try emitter.allocator.alloc(?u32, 0),
        .block_access_group = try emitter.allocator.alloc(u32, 0),
    };
    defer state.deinit();

    var call_args: std.ArrayListUnmanaged(u8) = .empty;
    defer call_args.deinit(emitter.allocator);
    var emitted_args: usize = 0;

    var callee_sret_tmp: ?[]u8 = null;
    defer if (callee_sret_tmp) |slot_s| emitter.allocator.free(slot_s);
    if (callee_rec.has_sret) {
        const sret_target: []const u8 = if (clos_recipe.has_sret) "%_sret" else blk_sret: {
            const c_lay = try emitter.resolver.resolveType(callee_body.ret_ty);
            const tmp_slot = try state.allocEntryBytes(
                @max(c_lay.size_bytes, 1),
                @max(@max(c_lay.alignBytes(), callee_rec.sret_recipe.pointee_align_bytes), 8),
            );
            callee_sret_tmp = tmp_slot;
            break :blk_sret tmp_slot;
        };
        const sret_s = try formatAbiParamDeclPiece(
            emitter,
            callee_body.ret_ty,
            callee_rec.sret_recipe,
            sret_target,
        );
        defer emitter.allocator.free(sret_s);
        try call_args.appendSlice(emitter.allocator, sret_s);
        emitted_args += 1;
    }
    if (callee_rec.has_implicit_context) {
        const ctx_s = try formatAbiParamDeclPiece(
            emitter,
            .usize_ty,
            callee_rec.context_recipe,
            "@_cx_default_ctx",
        );
        defer emitter.allocator.free(ctx_s);
        if (emitted_args > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, ctx_s);
        emitted_args += 1;
    }

    // Load captured values from `%_env` at aligned byte offsets:
    var cur_env_off: u64 = 0;
    const cap_count = thunk.capture_types.len;
    for (thunk.capture_types, 0..) |cap_ty, cap_i| {
        const cap_lay = try emitter.resolver.resolveType(cap_ty);
        if (cap_lay.size_bytes == 0) continue;
        cur_env_off = std.mem.alignForward(u64, cur_env_off, @max(@as(u64, cap_lay.alignBytes()), 1));
        if (cap_i < callee_rec.param_recipes.len) {
            const dst_rec = callee_rec.param_recipes[cap_i];
            if (dst_rec.pass_mode != .ignore_zst) {
                const t_id = state.nextTmp();
                try state.print(
                    "  %_cap_ptr_{d} = getelementptr inbounds i8, ptr %_env, {s} {d}\n",
                    .{ t_id, ptr_int, cur_env_off },
                );
                const cap_ptr_s = try std.fmt.allocPrint(emitter.allocator, "%_cap_ptr_{d}", .{t_id});
                defer emitter.allocator.free(cap_ptr_s);
                const arg_val_s = if (dst_rec.pass_mode == .indirect_by_ref or
                    dst_rec.pass_mode == .indirect_byval)
                    try emitter.allocator.dupe(u8, cap_ptr_s)
                else blk: {
                    const loaded_c = try emitLoadValueFromPtr(
                        emitter,
                        &state,
                        cap_ty,
                        cap_ptr_s,
                        cap_lay.alignBytes(),
                        null,
                        0,
                        0,
                        0,
                    );
                    defer emitter.allocator.free(loaded_c);
                    const abi_ty = try formatAbiParamOrRetType(emitter, cap_ty, dst_rec);
                    defer emitter.allocator.free(abi_ty);
                    break :blk try emitCoerceValueToAbi(emitter, &state, cap_ty, loaded_c, abi_ty);
                };
                defer emitter.allocator.free(arg_val_s);
                const piece_s = try formatAbiParamDeclPiece(emitter, cap_ty, dst_rec, arg_val_s);
                defer emitter.allocator.free(piece_s);
                if (emitted_args > 0) try call_args.appendSlice(emitter.allocator, ", ");
                try call_args.appendSlice(emitter.allocator, piece_s);
                emitted_args += 1;
            }
        }
        cur_env_off += cap_lay.size_bytes;
    }

    // Append forwarded explicit closure call parameters:
    for (clos_recipe.param_recipes, 0..) |src_rec, idx| {
        if (src_rec.pass_mode == .ignore_zst) continue;
        const callee_p_idx = cap_count + idx;
        if (callee_p_idx >= callee_rec.param_recipes.len) continue;
        const dst_rec = callee_rec.param_recipes[callee_p_idx];
        const p_name = try std.fmt.allocPrint(emitter.allocator, "%_cp_{d}", .{idx});
        defer emitter.allocator.free(p_name);
        const piece_s = try emitForwardAdaptedParamLlvm(
            emitter,
            &state,
            sig_view.getParamType(idx),
            src_rec,
            dst_rec,
            p_name,
        );
        defer emitter.allocator.free(piece_s);
        if (emitted_args > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, piece_s);
        emitted_args += 1;
    }

    if (callee_rec.swifterror_kind != .none) {
        try state.ensureSwifterrorCallSlot();
        try state.writeAll("  store ptr null, ptr %_cx_call_err, align 8\n");
        if (emitted_args > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, "ptr swifterror %_cx_call_err");
    }

    const callee_ret = try formatAbiReturnDecl(emitter, callee_body.ret_ty, callee_rec);
    defer emitter.allocator.free(callee_ret.full_decl);
    defer emitter.allocator.free(callee_ret.bare_ty);

    const callee_ident = try formatLlvmGlobalIdent(
        emitter.allocator,
        emitter.body_llvm_names.items[thunk.callee_body_idx],
    );
    defer emitter.allocator.free(callee_ident);

    if (std.mem.eql(u8, callee_ret.bare_ty, "void")) {
        try state.print(
            "  call {s}void {s}({s})\n",
            .{ resolveCallingConvPrefix(callee_rec), callee_ident, call_args.items },
        );
    } else {
        try state.print(
            "  %_thk_res = call {s}{s} {s}({s})\n",
            .{
                resolveCallingConvPrefix(callee_rec),
                callee_ret.full_decl,
                callee_ident,
                call_args.items,
            },
        );
    }

    if (callee_rec.swifterror_kind != .none and clos_recipe.swifterror_kind != .none) {
        try state.writeAll(
            "  %_thk_err = load ptr, ptr %_cx_call_err, align 8\n" ++
                "  %_thk_he = icmp ne ptr %_thk_err, null\n" ++
                "  br i1 %_thk_he, label %thk_store_err, label %thk_ret_ok\n" ++
                "thk_store_err:\n" ++
                "  store ptr %_thk_err, ptr %_cx_err_slot, align 8\n" ++
                "  br label %thk_ret_ok\n" ++
                "thk_ret_ok:\n",
        );
    }

    try emitThunkAdaptedReturnLlvm(
        emitter,
        &state,
        callee_body.ret_ty,
        callee_rec.has_sret,
        callee_sret_tmp,
        callee_ret.bare_ty,
        "%_thk_res",
        clos_recipe.has_sret,
        ret_decl.bare_ty,
    );

    if (state.entry_allocas.items.len > 0) {
        try emitter.writeAll(state.entry_allocas.items);
    }
    try emitter.writeAll(state.cur_buf.items);
    try emitter.writeAll("}\n\n");
}

/// Emits a stateful `fn(…)` `%_cx_ctx` adapter thunk `@_cx_fn_ctxwrap_<target_b>` forwarding to a contextless `MirBody`.
fn emitSingleFnCtxWrapper(
    emitter: *LlvmModuleEmitter,
    target_b: u32,
    fn_ty: TypeId,
) !void {
    const sig_view = emitter.input.pool.getFnSignatureView(fn_ty) orelse return;
    var wrap_recipe = try classifyFnTypeAbi(emitter, fn_ty, false, false);
    defer wrap_recipe.deinit(emitter.allocator);

    const callee_rec = &emitter.body_recipes.items[target_b];
    const callee_body = &emitter.input.bodies[target_b];
    const ptr_int = ptrIntType(emitter);

    const ret_decl = try formatAbiReturnDecl(emitter, sig_view.ret_ty, &wrap_recipe);
    defer emitter.allocator.free(ret_decl.full_decl);
    defer emitter.allocator.free(ret_decl.bare_ty);

    try emitter.print(
        "define internal {s}{s} @_cx_fn_ctxwrap_{d}(",
        .{ resolveCallingConvPrefix(&wrap_recipe), ret_decl.full_decl, target_b },
    );
    var hdr_count: usize = 0;
    if (wrap_recipe.has_sret) {
        const sret_s = try formatAbiParamDeclPiece(
            emitter,
            sig_view.ret_ty,
            wrap_recipe.sret_recipe,
            "%_sret",
        );
        defer emitter.allocator.free(sret_s);
        try emitter.writeAll(sret_s);
        hdr_count += 1;
    }
    if (wrap_recipe.has_implicit_context) {
        const ctx_s = try formatAbiParamDeclPiece(
            emitter,
            .usize_ty,
            wrap_recipe.context_recipe,
            "%_cx_ctx",
        );
        defer emitter.allocator.free(ctx_s);
        if (hdr_count > 0) try emitter.writeAll(", ");
        try emitter.writeAll(ctx_s);
        hdr_count += 1;
    }
    for (wrap_recipe.param_recipes, 0..) |param_rec, idx| {
        if (param_rec.pass_mode == .ignore_zst) continue;
        const param_name = try std.fmt.allocPrint(emitter.allocator, "%_wp_{d}", .{idx});
        defer emitter.allocator.free(param_name);
        const piece_s = try formatAbiParamDeclPiece(
            emitter,
            sig_view.getParamType(idx),
            param_rec,
            param_name,
        );
        defer emitter.allocator.free(piece_s);
        if (hdr_count > 0) try emitter.writeAll(", ");
        try emitter.writeAll(piece_s);
        hdr_count += 1;
    }
    if (wrap_recipe.swifterror_kind != .none) {
        if (hdr_count > 0) try emitter.writeAll(", ");
        try emitter.writeAll("ptr swifterror %_cx_err_slot");
    }
    try emitter.print(") {s} {{\nentry:\n", .{fnUnwindAttrs(emitter)});

    var state = BodyEmitState{
        .allocator = emitter.allocator,
        .cur_label = try emitter.allocator.dupe(u8, "entry"),
        .local_ptrs = try emitter.allocator.alloc([]u8, 0),
        .local_aligns = try emitter.allocator.alloc(u32, 0),
        .edge_pred_labels = try emitter.allocator.alloc([]u8, 0),
        .edge_call_ret_vals = try emitter.allocator.alloc([]u8, 0),
        .edge_trampoline = try emitter.allocator.alloc(?u32, 0),
        .block_access_group = try emitter.allocator.alloc(u32, 0),
    };
    defer state.deinit();

    var call_args: std.ArrayListUnmanaged(u8) = .empty;
    defer call_args.deinit(emitter.allocator);
    var emitted_args: usize = 0;

    var wrap_sret_tmp: ?[]u8 = null;
    defer if (wrap_sret_tmp) |slot_s| emitter.allocator.free(slot_s);
    if (callee_rec.has_sret) {
        const sret_target: []const u8 = if (wrap_recipe.has_sret) "%_sret" else blk_sret: {
            const c_lay = try emitter.resolver.resolveType(callee_body.ret_ty);
            const tmp_slot = try state.allocEntryBytes(
                @max(c_lay.size_bytes, 1),
                @max(@max(c_lay.alignBytes(), callee_rec.sret_recipe.pointee_align_bytes), 8),
            );
            wrap_sret_tmp = tmp_slot;
            break :blk_sret tmp_slot;
        };
        const sret_s = try formatAbiParamDeclPiece(
            emitter,
            callee_body.ret_ty,
            callee_rec.sret_recipe,
            sret_target,
        );
        defer emitter.allocator.free(sret_s);
        try call_args.appendSlice(emitter.allocator, sret_s);
        emitted_args += 1;
    }
    if (callee_rec.has_implicit_context) {
        const ctx_op = if (wrap_recipe.has_implicit_context) "%_cx_ctx" else "@_cx_default_ctx";
        const ctx_s = try formatAbiParamDeclPiece(
            emitter,
            .usize_ty,
            callee_rec.context_recipe,
            ctx_op,
        );
        defer emitter.allocator.free(ctx_s);
        if (emitted_args > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, ctx_s);
        emitted_args += 1;
    }

    for (wrap_recipe.param_recipes, 0..) |src_rec, idx| {
        if (src_rec.pass_mode == .ignore_zst) continue;
        if (idx >= callee_rec.param_recipes.len) continue;
        const dst_rec = callee_rec.param_recipes[idx];
        const param_name = try std.fmt.allocPrint(emitter.allocator, "%_wp_{d}", .{idx});
        defer emitter.allocator.free(param_name);
        const piece_s = try emitForwardAdaptedParamLlvm(
            emitter,
            &state,
            sig_view.getParamType(idx),
            src_rec,
            dst_rec,
            param_name,
        );
        defer emitter.allocator.free(piece_s);
        if (emitted_args > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, piece_s);
        emitted_args += 1;
    }

    if (callee_rec.swifterror_kind != .none) {
        try state.ensureSwifterrorCallSlot();
        try state.writeAll("  store ptr null, ptr %_cx_call_err, align 8\n");
        if (emitted_args > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, "ptr swifterror %_cx_call_err");
    }

    const callee_op = if (emitter.input.is_dev_got_enabled) blk: {
        const got_t = state.nextTmp();
        try state.print(
            "  %_wgot_p_{d} = getelementptr inbounds [{d} x ptr], " ++
                "ptr @_cx_dev_got, {s} 0, {s} {d}\n" ++
                "  %_wgot_f_{d} = load ptr, ptr %_wgot_p_{d}, align {d}\n",
            .{
                got_t,
                @max(emitter.input.bodies.len, 1),
                ptr_int,
                ptr_int,
                target_b,
                got_t,
                got_t,
                emitter.cfg.target.ptrBytes(),
            },
        );
        break :blk try std.fmt.allocPrint(emitter.allocator, "%_wgot_f_{d}", .{got_t});
    } else try formatLlvmGlobalIdent(emitter.allocator, emitter.body_llvm_names.items[target_b]);
    defer emitter.allocator.free(callee_op);

    const callee_ret = try formatAbiReturnDecl(emitter, callee_body.ret_ty, callee_rec);
    defer emitter.allocator.free(callee_ret.full_decl);
    defer emitter.allocator.free(callee_ret.bare_ty);

    if (std.mem.eql(u8, callee_ret.bare_ty, "void")) {
        try state.print(
            "  call {s}void {s}({s})\n",
            .{ resolveCallingConvPrefix(callee_rec), callee_op, call_args.items },
        );
    } else {
        try state.print(
            "  %_wres = call {s}{s} {s}({s})\n",
            .{ resolveCallingConvPrefix(callee_rec), callee_ret.full_decl, callee_op, call_args.items },
        );
    }

    if (callee_rec.swifterror_kind != .none and wrap_recipe.swifterror_kind != .none) {
        try state.writeAll(
            "  %_werr = load ptr, ptr %_cx_call_err, align 8\n" ++
                "  %_whe = icmp ne ptr %_werr, null\n" ++
                "  br i1 %_whe, label %wrap_store_err, label %wrap_ret_ok\n" ++
                "wrap_store_err:\n" ++
                "  store ptr %_werr, ptr %_cx_err_slot, align 8\n" ++
                "  br label %wrap_ret_ok\n" ++
                "wrap_ret_ok:\n",
        );
    }

    try emitThunkAdaptedReturnLlvm(
        emitter,
        &state,
        callee_body.ret_ty,
        callee_rec.has_sret,
        wrap_sret_tmp,
        callee_ret.bare_ty,
        "%_wres",
        wrap_recipe.has_sret,
        ret_decl.bare_ty,
    );

    if (state.entry_allocas.items.len > 0) {
        try emitter.writeAll(state.entry_allocas.items);
    }
    try emitter.writeAll(state.cur_buf.items);
    try emitter.writeAll("}\n\n");
}

// ----------- Pentagon Metadata, Places & Load/Store -----------

/// Looks up a Pentagon `ProvenValueRange` for `val_raw` inside `body_idx` (`null` if absent).
fn lookupProvenRange(
    emitter: *const LlvmModuleEmitter,
    body_idx: u32,
    val_raw: u32,
) ?ProvenValueRange {
    const all_ranges = emitter.input.proven_ranges orelse return null;
    if (body_idx >= all_ranges.len) return null;
    for (all_ranges[body_idx]) |entry| {
        if (entry.mir_value_raw == val_raw) return entry;
    }
    return null;
}

/// Interns or returns a valid LLVM `!range !{iW lo, iW hi_excl}` metadata ID (`null` when full domain).
fn getOrInternValidRangeMd(
    emitter: *LlvmModuleEmitter,
    range: ProvenValueRange,
) !?u32 {
    const width = range.bit_width;
    if (width == 0 or width > 64) return null;
    const mask: u64 = if (width == 64) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(width)) - 1;

    var lo_w: u64 = 0;
    var hi_incl_w: u64 = 0;
    if (range.flags().is_signed) {
        const s_min = range.signedMin();
        const s_max = range.signedMax();
        if (s_min > s_max) return null;
        const domain_min: i64 = if (width == 64) std.math.minInt(i64) else -(@as(i64, 1) << @intCast(width - 1));
        const domain_max: i64 = if (width == 64) std.math.maxInt(i64) else (@as(i64, 1) << @intCast(width - 1)) - 1;
        if (s_min <= domain_min and s_max >= domain_max) return null;
        const clamped_min = @max(s_min, domain_min);
        const clamped_max = @min(s_max, domain_max);
        lo_w = (@as(u64, @bitCast(clamped_min))) & mask;
        hi_incl_w = (@as(u64, @bitCast(clamped_max))) & mask;
    } else {
        if (range.min_bits > range.max_bits) return null;
        if (range.min_bits == 0 and range.max_bits >= mask) return null;
        const clamped_min: u64 = @intCast(@min(range.min_bits, @as(u128, mask)));
        const clamped_max: u64 = @intCast(@min(range.max_bits, @as(u128, mask)));
        lo_w = clamped_min & mask;
        hi_incl_w = clamped_max & mask;
    }
    const hi_excl_w: u64 = (hi_incl_w +% 1) & mask;
    // LLVM Verifier rule: `lo_w == hi_excl_w` is full `2^W` domain and MUST NOT emit `!range`:
    if (lo_w == hi_excl_w) return null;

    var hasher = std.hash.Wyhash.init(0x524E_4745);
    hasher.update(std.mem.asBytes(&width));
    hasher.update(std.mem.asBytes(&lo_w));
    hasher.update(std.mem.asBytes(&hi_excl_w));
    const cache_key = hasher.final();
    if (emitter.range_md_cache.get(cache_key)) |existing_md| return existing_md;

    const rhs = try std.fmt.allocPrint(
        emitter.allocator,
        "!{{i{d} {d}, i{d} {d}}}",
        .{ width, lo_w, width, hi_excl_w },
    );
    defer emitter.allocator.free(rhs);
    const md_id = try emitter.addMetadataNode(rhs);
    try emitter.range_md_cache.put(emitter.allocator, cache_key, md_id);
    return md_id;
}

/// Emits `@llvm.assume(i1 true) [ "nonnull"…, "align"… ]` when `range` proves pointer facts.
fn maybeEmitPointerAssume(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    ptr_ssa: []const u8,
    range: ProvenValueRange,
) !void {
    const is_nn = range.flags().is_nonnull_ptr or range.flags().is_non_zero;
    const align_log2 = range.proven_align_log2;
    if (!is_nn and align_log2 == 0) return;

    try emitter.requireIntrinsicDecl("declare void @llvm.assume(i1 noundef)");
    if (is_nn and align_log2 > 0) {
        const align_bytes: u64 = @as(u64, 1) << @intCast(@min(align_log2, 30));
        try state.print(
            "  call void @llvm.assume(i1 true) [ \"nonnull\"(ptr {s}), \"align\"(ptr {s}, i64 {d}) ]\n",
            .{ ptr_ssa, ptr_ssa, align_bytes },
        );
    } else if (is_nn) {
        try state.print(
            "  call void @llvm.assume(i1 true) [ \"nonnull\"(ptr {s}) ]\n",
            .{ptr_ssa},
        );
    } else {
        const align_bytes: u64 = @as(u64, 1) << @intCast(@min(align_log2, 30));
        try state.print(
            "  call void @llvm.assume(i1 true) [ \"align\"(ptr {s}, i64 {d}) ]\n",
            .{ ptr_ssa, align_bytes },
        );
    }
}

/// Checks whether Pentagon `ProvenValueRange` bounds prove `nsw` and/or `nuw` on `add`/`sub`/`mul`.
fn checkProvenNoWrapFlags(
    emitter: *const LlvmModuleEmitter,
    body_idx: u32,
    op_kind: mir.BinOpKind,
    lhs_raw: u32,
    rhs_raw: u32,
    bits: u16,
) struct { has_nsw: bool, has_nuw: bool } {
    if (bits == 0 or bits > 64) return .{ .has_nsw = false, .has_nuw = false };
    const lhs_r = lookupProvenRange(emitter, body_idx, lhs_raw) orelse
        return .{ .has_nsw = false, .has_nuw = false };
    const rhs_r = lookupProvenRange(emitter, body_idx, rhs_raw) orelse
        return .{ .has_nsw = false, .has_nuw = false };

    var has_nsw = false;
    var has_nuw = false;

    if (lhs_r.flags().is_signed and rhs_r.flags().is_signed) {
        const l_lo: i128 = lhs_r.signedMin();
        const l_hi: i128 = lhs_r.signedMax();
        const r_lo: i128 = rhs_r.signedMin();
        const r_hi: i128 = rhs_r.signedMax();
        const s_min: i128 = -(@as(i128, 1) << @intCast(bits - 1));
        const s_max: i128 = (@as(i128, 1) << @intCast(bits - 1)) - 1;
        switch (op_kind) {
            .add_wrap => {
                has_nsw = (l_lo + r_lo >= s_min) and (l_hi + r_hi <= s_max);
            },
            .sub_wrap => {
                has_nsw = (l_lo - r_hi >= s_min) and (l_hi - r_lo <= s_max);
            },
            .mul_wrap => {
                const c0 = l_lo * r_lo;
                const c1 = l_lo * r_hi;
                const c2 = l_hi * r_lo;
                const c3 = l_hi * r_hi;
                has_nsw = (@min(@min(c0, c1), @min(c2, c3)) >= s_min) and
                    (@max(@max(c0, c1), @max(c2, c3)) <= s_max);
            },
            else => {},
        }
    } else if (!lhs_r.flags().is_signed and !rhs_r.flags().is_signed) {
        const l_lo: u128 = lhs_r.min_bits;
        const l_hi: u128 = lhs_r.max_bits;
        const r_hi: u128 = rhs_r.max_bits;
        const u_max: u128 = if (bits == 64)
            std.math.maxInt(u64)
        else
            (@as(u128, 1) << @intCast(bits)) - 1;
        switch (op_kind) {
            .add_wrap => has_nuw = (l_hi + r_hi <= u_max),
            .sub_wrap => has_nuw = (l_lo >= r_hi),
            .mul_wrap => has_nuw = (l_hi * r_hi <= u_max),
            else => {},
        }
    }
    return .{ .has_nsw = has_nsw, .has_nuw = has_nuw };
}

/// Resolves MVS `!alias.scope` and `!noalias` metadata IDs for `root_param_local`.
fn lookupMvsScopeForLocal(
    state: *const BodyEmitState,
    root_param_local: u32,
) struct { scope_md: u32, noalias_md: u32 } {
    if (root_param_local == 0) return .{ .scope_md = 0, .noalias_md = 0 };
    for (state.mvs_scopes.items) |entry| {
        if (entry.local_idx == root_param_local) {
            return .{ .scope_md = entry.scope_list_md, .noalias_md = entry.noalias_list_md };
        }
    }
    return .{ .scope_md = 0, .noalias_md = 0 };
}

/// Appends optional `!alias.scope`, `!noalias`, `!llvm.access.group`, and `!dbg` suffixes to `cur_buf`.
fn appendMemMetadataSuffix(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    scope_md: u32,
    noalias_md: u32,
    access_group_md: u32,
    range_md: ?u32,
) !void {
    if (range_md) |r_md| {
        if (emitter.di_empty_tuple_md == 0) {
            emitter.di_empty_tuple_md = try emitter.addMetadataNode("!{}");
        }
        try state.print(", !range !{d}, !noundef !{d}", .{ r_md, emitter.di_empty_tuple_md });
    }
    if (scope_md != 0) try state.print(", !alias.scope !{d}", .{scope_md});
    if (noalias_md != 0) try state.print(", !noalias !{d}", .{noalias_md});
    if (access_group_md != 0) try state.print(", !llvm.access.group !{d}", .{access_group_md});
    if (state.active_dbg_loc_md != 0) try state.print(", !dbg !{d}", .{state.active_dbg_loc_md});
    try state.writeAll("\n");
}

/// Loads a CoreX SSA value of `raw_ty` from `ptr_str` (`bool` loaded as `i8` + `& 1` + `trunc to i1`).
fn emitLoadValueFromPtr(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    raw_ty: TypeId,
    ptr_str: []const u8,
    align_bytes: u32,
    maybe_range: ?ProvenValueRange,
    scope_md: u32,
    noalias_md: u32,
    access_group_md: u32,
) ![]u8 {
    const ty = try unwrapTransparentType(emitter, raw_ty);
    const eff_align = @max(align_bytes, 1);
    if (ty == .bool_ty) {
        const tmp_id = state.nextTmp();
        try state.print("  %_bld_{d} = load i8, ptr {s}, align {d}", .{ tmp_id, ptr_str, eff_align });
        try appendMemMetadataSuffix(emitter, state, scope_md, noalias_md, access_group_md, null);
        try state.print(
            "  %_band_{d} = and i8 %_bld_{d}, 1\n" ++
                "  %_bval_{d} = trunc i8 %_band_{d} to i1\n",
            .{ tmp_id, tmp_id, tmp_id, tmp_id },
        );
        return std.fmt.allocPrint(emitter.allocator, "%_bval_{d}", .{tmp_id});
    }

    const val_ty = try formatLlvmValueType(emitter, ty);
    defer emitter.allocator.free(val_ty);
    var range_md: ?u32 = null;
    if (maybe_range) |prov_r| {
        if (resolveIntegerInfo(emitter, ty)) |int_info| {
            if (int_info.bits <= 64 and prov_r.bit_width == int_info.bits) {
                range_md = try getOrInternValidRangeMd(emitter, prov_r);
            }
        }
    }
    const tmp_id = state.nextTmp();
    try state.print("  %_ld_{d} = load {s}, ptr {s}, align {d}", .{ tmp_id, val_ty, ptr_str, eff_align });
    try appendMemMetadataSuffix(emitter, state, scope_md, noalias_md, access_group_md, range_md);
    return std.fmt.allocPrint(emitter.allocator, "%_ld_{d}", .{tmp_id});
}

/// Stores a CoreX SSA value `val_str` of `raw_ty` into `ptr_str` (`bool` zero-extended to `i8`).
fn emitStoreValueToPtr(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    raw_ty: TypeId,
    val_str: []const u8,
    ptr_str: []const u8,
    align_bytes: u32,
    scope_md: u32,
    noalias_md: u32,
    access_group_md: u32,
) !void {
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (try isZeroSizedType(emitter, ty)) return;
    const eff_align = @max(align_bytes, 1);
    if (ty == .bool_ty) {
        const tmp_id = state.nextTmp();
        try state.print("  %_bst_{d} = zext i1 {s} to i8\n", .{ tmp_id, val_str });
        try state.print("  store i8 %_bst_{d}, ptr {s}, align {d}", .{ tmp_id, ptr_str, eff_align });
        try appendMemMetadataSuffix(emitter, state, scope_md, noalias_md, access_group_md, null);
        return;
    }
    const val_ty = try formatLlvmValueType(emitter, ty);
    defer emitter.allocator.free(val_ty);
    try state.print("  store {s} {s}, ptr {s}, align {d}", .{ val_ty, val_str, ptr_str, eff_align });
    try appendMemMetadataSuffix(emitter, state, scope_md, noalias_md, access_group_md, null);
}

/// Resolves the final projected `TypeId` of `place_id` in `body` without emitting IR.
fn resolvePlaceResultType(
    emitter: *LlvmModuleEmitter,
    body: *const MirBody,
    place_id: PlaceId,
) TypeId {
    if (place_id.isNone() or place_id.asInt() >= body.places.items.len) return .unit_ty;
    const place = body.places.items[place_id.asInt()];
    if (place.base >= body.locals.items.len) return .unit_ty;
    var cur_ty = emitter.input.pool.unwrapUnderlyingType(body.locals.items[place.base].type_id);
    var active_downcast: ?u32 = null;
    var soa_col_field_ty: ?TypeId = null;

    for (body.getPlaceProjections(place_id)) |proj| {
        if (soa_col_field_ty) |col_ty| {
            soa_col_field_ty = null;
            if (proj.kind == .index) {
                cur_ty = col_ty;
                continue;
            } else if (proj.kind == .slice_len) {
                return .usize_ty;
            }
        }
        const node = emitter.input.pool.getNode(cur_ty);
        switch (proj.kind) {
            .deref => {
                active_downcast = null;
                cur_ty = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
            },
            .downcast => {
                active_downcast = proj.payload;
            },
            .field => {
                if (active_downcast) |tag_ord| {
                    active_downcast = null;
                    cur_ty = resolveEnumVariantPayloadType(emitter, cur_ty, tag_ord);
                    if (proj.payload > 0) {
                        if (emitter.resolver.getFieldByDeclOrdinal(cur_ty, proj.payload) catch null) |sub_fld| {
                            cur_ty = emitter.input.pool.unwrapUnderlyingType(sub_fld.field_ty);
                        }
                    }
                } else if (cur_ty == .source_loc_ty) {
                    cur_ty = resolveSourceLocFieldLayout(emitter.cfg.target.ptrBytes(), proj.payload).field_ty;
                } else if (cur_ty == .fmt_spec_ty) {
                    cur_ty = if (proj.payload == 0) .u32_ty else .u16_ty;
                } else if (node.tag == .union_ty) {
                    cur_ty = resolveUnionFieldType(emitter, cur_ty, proj.payload);
                } else if (emitter.resolver.getFieldByDeclOrdinal(cur_ty, proj.payload) catch null) |fld| {
                    cur_ty = emitter.input.pool.unwrapUnderlyingType(fld.field_ty);
                }
            },
            .index => {
                active_downcast = null;
                cur_ty = if (cur_ty == .str_ty)
                    .u8_ty
                else
                    emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
            },
            .soa_elem => {
                active_downcast = null;
                const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
                if (emitter.resolver.getFieldByDeclOrdinal(elem_struct, proj.payload) catch null) |fld| {
                    soa_col_field_ty = emitter.input.pool.unwrapUnderlyingType(fld.field_ty);
                }
            },
            .slice_len => return .usize_ty,
        }
    }
    return cur_ty;
}

/// Emits dynamic `#soa [S]` column byte-offset computation for `elem_struct_ty` column `field_ord`.
fn emitDynamicSoaColByteOffset(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    elem_struct_ty: TypeId,
    field_ord: u32,
    len_ssa: []const u8,
) !struct { off_ssa: []u8, col_align_bytes: u32 } {
    const ptr_int = ptrIntType(emitter);
    const lay = try emitter.resolver.resolveType(elem_struct_ty);
    const simd_log2 = emitter.target_layout.simd_align_log2;

    var cur_ssa = try emitter.allocator.dupe(u8, "0");
    errdefer emitter.allocator.free(cur_ssa);
    var final_align: u32 = @as(u32, 1) << @intCast(simd_log2);

    var ord_i: u32 = 0;
    while (ord_i <= field_ord and ord_i < lay.aux_len) : (ord_i += 1) {
        const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + ord_i];
        const col_align: u64 = @as(u64, 1) << @intCast(@max(fld.align_log2, simd_log2));
        const aligned_ssa = if (ord_i == 0)
            try emitter.allocator.dupe(u8, "0")
        else blk: {
            const t_id = state.nextTmp();
            try state.print(
                "  %_soa_add_{d} = add {s} {s}, {d}\n" ++
                    "  %_soa_al_{d} = and {s} %_soa_add_{d}, {d}\n",
                .{
                    t_id,
                    ptr_int,
                    cur_ssa,
                    col_align - 1,
                    t_id,
                    ptr_int,
                    t_id,
                    @as(i64, -@as(i64, @intCast(col_align))),
                },
            );
            break :blk try std.fmt.allocPrint(emitter.allocator, "%_soa_al_{d}", .{t_id});
        };
        if (ord_i == field_ord) {
            emitter.allocator.free(cur_ssa);
            final_align = @intCast(col_align);
            return .{ .off_ssa = aligned_ssa, .col_align_bytes = final_align };
        }
        defer emitter.allocator.free(aligned_ssa);
        const t_id = state.nextTmp();
        try state.print(
            "  %_soa_mul_{d} = mul {s} {s}, {d}\n" ++
                "  %_soa_nx_{d} = add {s} {s}, %_soa_mul_{d}\n",
            .{ t_id, ptr_int, len_ssa, fld.size_bytes, t_id, ptr_int, aligned_ssa, t_id },
        );
        emitter.allocator.free(cur_ssa);
        cur_ssa = try std.fmt.allocPrint(emitter.allocator, "%_soa_nx_{d}", .{t_id});
    }
    return .{ .off_ssa = cur_ssa, .col_align_bytes = final_align };
}

/// Lowers `place_id` to an addressable `ptr` operand or compile-time array length.
fn lowerPlaceLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    place_id: PlaceId,
) !PlaceLoweringResult {
    const ptr_int = ptrIntType(emitter);
    const base_local = body.places.items[place_id.asInt()].base;
    const base_decl = body.locals.items[base_local];
    var cur_ty = try unwrapTransparentType(emitter, base_decl.type_id);
    var cur_align: u32 = if (base_local < state.local_aligns.len) state.local_aligns[base_local] else 1;

    const is_param_local = base_local >= 1 and base_local <= body.param_count;
    const is_direct_mvs_param = is_param_local and
        (base_decl.mode() == .inout_mode or base_decl.mode() == .set_mode);
    var active_mvs_param: u32 = if (is_direct_mvs_param) base_local else 0;
    var can_enter_param_ptr: bool = is_param_local and !is_direct_mvs_param;

    var cur_ptr = if (base_local < state.local_ptrs.len and state.local_ptrs[base_local].len > 0)
        try emitter.allocator.dupe(u8, state.local_ptrs[base_local])
    else
        try std.fmt.allocPrint(
            emitter.allocator,
            "inttoptr ({s} {d} to ptr)",
            .{ ptr_int, @max(cur_align, 1) },
        );
    errdefer emitter.allocator.free(cur_ptr);

    var active_downcast: ?u32 = null;
    var pending_soa: ?PendingSoaCol = null;
    defer if (pending_soa) |pend| {
        emitter.allocator.free(pend.col_ptr);
        emitter.allocator.free(pend.slice_base_ptr);
    };

    for (body.getPlaceProjections(place_id)) |proj| {
        if (pending_soa) |pend| {
            pending_soa = null;
            defer emitter.allocator.free(pend.col_ptr);
            defer emitter.allocator.free(pend.slice_base_ptr);
            if (proj.kind == .index) {
                const elem_lay = try emitter.resolver.resolveType(pend.field_ty);
                const idx_ssa = try coerceIndexToPtrInt(emitter, state, body, proj.payload);
                defer emitter.allocator.free(idx_ssa);
                const t_id = state.nextTmp();
                try state.print(
                    "  %_sidx_b_{d} = mul {s} {s}, {d}\n" ++
                        "  %_sidx_p_{d} = getelementptr inbounds i8, ptr {s}, {s} %_sidx_b_{d}\n",
                    .{ t_id, ptr_int, idx_ssa, elem_lay.stride_bytes, t_id, pend.col_ptr, ptr_int, t_id },
                );
                emitter.allocator.free(cur_ptr);
                cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_sidx_p_{d}", .{t_id});
                cur_ty = pend.field_ty;
                cur_align = @min(
                    @max(pend.col_align, 1),
                    effectiveOffsetAlign(elem_lay.stride_bytes, elem_lay.alignBytes()),
                );
                continue;
            } else if (proj.kind == .slice_len) {
                if (pend.is_fixed) {
                    emitter.allocator.free(cur_ptr);
                    return .{ .const_len = .{ .elem_count = pend.fixed_cap } };
                }
                const t_id = state.nextTmp();
                try state.print(
                    "  %_slen_p_{d} = getelementptr inbounds {{ ptr, {s} }}, ptr {s}, i32 0, i32 1\n",
                    .{ t_id, ptr_int, pend.slice_base_ptr },
                );
                emitter.allocator.free(cur_ptr);
                return .{
                    .addr_val = .{
                        .ptr_str = try std.fmt.allocPrint(emitter.allocator, "%_slen_p_{d}", .{t_id}),
                        .pointee_ty = .usize_ty,
                        .align_bytes = @min(@max(cur_align, 1), emitter.cfg.target.ptrBytes()),
                        .root_param_local = active_mvs_param,
                    },
                };
            }
        }

        const node = emitter.input.pool.getNode(cur_ty);
        switch (proj.kind) {
            .deref => {
                active_downcast = null;
                const pointee_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
                const p_lay = try emitter.resolver.resolveType(pointee_ty);
                if (emitter.input.pool.isSliceRefType(cur_ty)) {
                    cur_ty = pointee_ty;
                    cur_align = @min(@max(cur_align, 1), p_lay.alignBytes());
                } else {
                    const ptr_load_align = @min(@max(cur_align, 1), @max(emitter.cfg.target.ptrBytes(), 1));
                    const t_id = state.nextTmp();
                    try state.print(
                        "  %_deref_{d} = load ptr, ptr {s}, align {d}\n",
                        .{ t_id, cur_ptr, ptr_load_align },
                    );
                    emitter.allocator.free(cur_ptr);
                    cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_deref_{d}", .{t_id});
                    cur_ty = pointee_ty;
                    if (node.tag == .raw_ptr_ty) {
                        cur_align = 1;
                        active_mvs_param = 0;
                        can_enter_param_ptr = false;
                    } else {
                        cur_align = p_lay.alignBytes();
                        if (can_enter_param_ptr) {
                            active_mvs_param = base_local;
                            can_enter_param_ptr = false;
                        } else {
                            active_mvs_param = 0;
                        }
                    }
                }
            },
            .downcast => {
                active_downcast = proj.payload;
            },
            .field => {
                if (active_downcast) |tag_ord| {
                    active_downcast = null;
                    const sum_detail_opt = try emitter.resolver.getSumDetail(cur_ty);
                    const pay_off: u64 = if (sum_detail_opt) |sd| sd.payload_offset else 0;
                    const var_pay_ty = try unwrapTransparentType(
                        emitter,
                        resolveEnumVariantPayloadType(emitter, cur_ty, tag_ord),
                    );
                    var total_off: u64 = pay_off;
                    var final_ty = var_pay_ty;
                    if (proj.payload > 0) {
                        if (try emitter.resolver.getFieldByDeclOrdinal(var_pay_ty, proj.payload)) |sub_fld| {
                            total_off += sub_fld.byte_offset;
                            final_ty = try unwrapTransparentType(emitter, sub_fld.field_ty);
                        }
                    }
                    const f_lay = try emitter.resolver.resolveType(final_ty);
                    if (total_off > 0) {
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_vpay_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ t_id, cur_ptr, ptr_int, total_off },
                        );
                        emitter.allocator.free(cur_ptr);
                        cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_vpay_{d}", .{t_id});
                    }
                    cur_ty = final_ty;
                    cur_align = @min(@max(cur_align, 1), effectiveOffsetAlign(total_off, f_lay.alignBytes()));
                } else if (cur_ty == .source_loc_ty) {
                    const sloc_fld = resolveSourceLocFieldLayout(emitter.cfg.target.ptrBytes(), proj.payload);
                    const ptr_load_align = @min(@max(cur_align, 1), @max(emitter.cfg.target.ptrBytes(), 1));
                    const t_id = state.nextTmp();
                    try state.print(
                        "  %_sloc_p_{d} = load ptr, ptr {s}, align {d}\n",
                        .{ t_id, cur_ptr, ptr_load_align },
                    );
                    emitter.allocator.free(cur_ptr);
                    if (sloc_fld.byte_offset > 0) {
                        try state.print(
                            "  %_sloc_f_{d} = getelementptr inbounds i8, ptr %_sloc_p_{d}, {s} {d}\n",
                            .{ t_id, t_id, ptr_int, sloc_fld.byte_offset },
                        );
                        cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_sloc_f_{d}", .{t_id});
                    } else {
                        cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_sloc_p_{d}", .{t_id});
                    }
                    cur_ty = sloc_fld.field_ty;
                    cur_align = sloc_fld.align_bytes;
                    active_mvs_param = 0;
                    can_enter_param_ptr = false;
                } else if (cur_ty == .fmt_spec_ty) {
                    const spec_off: u64 = switch (proj.payload) {
                        0 => 0,
                        1 => 4,
                        else => 6,
                    };
                    const spec_ty: TypeId = if (proj.payload == 0) .u32_ty else .u16_ty;
                    const spec_align: u32 = if (proj.payload == 0) 4 else 2;
                    if (spec_off > 0) {
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_fsp_f_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ t_id, cur_ptr, ptr_int, spec_off },
                        );
                        emitter.allocator.free(cur_ptr);
                        cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_fsp_f_{d}", .{t_id});
                    }
                    cur_ty = spec_ty;
                    cur_align = @min(@max(cur_align, 1), spec_align);
                } else if (node.tag == .union_ty) {
                    const fld_ty = try unwrapTransparentType(
                        emitter,
                        resolveUnionFieldType(emitter, cur_ty, proj.payload),
                    );
                    const f_lay = try emitter.resolver.resolveType(fld_ty);
                    cur_ty = fld_ty;
                    cur_align = @min(@max(cur_align, 1), f_lay.alignBytes());
                } else if (try emitter.resolver.getFieldByDeclOrdinal(cur_ty, proj.payload)) |fld| {
                    const parent_lay = try emitter.resolver.resolveType(cur_ty);
                    const fld_ty = try unwrapTransparentType(emitter, fld.field_ty);
                    if (fld.byte_offset > 0) {
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_fld_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ t_id, cur_ptr, ptr_int, fld.byte_offset },
                        );
                        emitter.allocator.free(cur_ptr);
                        cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_fld_{d}", .{t_id});
                    }
                    cur_ty = fld_ty;
                    if (parent_lay.reprFlags().is_packed) {
                        cur_align = 1;
                    } else {
                        const fld_nat_align = @as(u32, 1) << @intCast(fld.align_log2);
                        cur_align = @min(
                            @min(@max(cur_align, 1), parent_lay.alignBytes()),
                            effectiveOffsetAlign(fld.byte_offset, fld_nat_align),
                        );
                    }
                }
            },
            .index => {
                active_downcast = null;
                const elem_ty = if (cur_ty == .str_ty)
                    TypeId.u8_ty
                else
                    try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
                const elem_lay = try emitter.resolver.resolveType(elem_ty);
                const idx_ssa = try coerceIndexToPtrInt(emitter, state, body, proj.payload);
                defer emitter.allocator.free(idx_ssa);
                const t_id = state.nextTmp();
                if (cur_ty == .str_ty or node.tag == .slice_ty or node.tag == .raw_ptr_ty) {
                    const hdr_align = @min(@max(cur_align, 1), emitter.cfg.target.ptrBytes());
                    try state.print(
                        "  %_sl_dp_{d} = load ptr, ptr {s}, align {d}\n" ++
                            "  %_sl_bo_{d} = mul {s} {s}, {d}\n" ++
                            "  %_sl_ep_{d} = getelementptr inbounds i8, ptr %_sl_dp_{d}, {s} %_sl_bo_{d}\n",
                        .{
                            t_id,
                            cur_ptr,
                            hdr_align,
                            t_id,
                            ptr_int,
                            idx_ssa,
                            elem_lay.stride_bytes,
                            t_id,
                            t_id,
                            ptr_int,
                            t_id,
                        },
                    );
                    emitter.allocator.free(cur_ptr);
                    cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_sl_ep_{d}", .{t_id});
                    cur_align = @min(
                        elem_lay.alignBytes(),
                        effectiveOffsetAlign(elem_lay.stride_bytes, elem_lay.alignBytes()),
                    );
                    if (can_enter_param_ptr) {
                        active_mvs_param = base_local;
                        can_enter_param_ptr = false;
                    }
                } else {
                    try state.print(
                        "  %_ar_bo_{d} = mul {s} {s}, {d}\n" ++
                            "  %_ar_ep_{d} = getelementptr inbounds i8, ptr {s}, {s} %_ar_bo_{d}\n",
                        .{ t_id, ptr_int, idx_ssa, elem_lay.stride_bytes, t_id, cur_ptr, ptr_int, t_id },
                    );
                    emitter.allocator.free(cur_ptr);
                    cur_ptr = try std.fmt.allocPrint(emitter.allocator, "%_ar_ep_{d}", .{t_id});
                    cur_align = @min(
                        @max(cur_align, 1),
                        effectiveOffsetAlign(elem_lay.stride_bytes, elem_lay.alignBytes()),
                    );
                }
                cur_ty = elem_ty;
            },
            .soa_elem => {
                active_downcast = null;
                const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
                const fld = (try emitter.resolver.getFieldByDeclOrdinal(elem_struct, proj.payload)).?;
                const fld_ty = try unwrapTransparentType(emitter, fld.field_ty);
                if (node.tag == .soa_array_ty) {
                    const cap: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                    const col_info = emitter.resolver.getSoaColumnOffset(elem_struct, proj.payload, cap).?;
                    const nat_col_align = @as(u32, 1) << @intCast(col_info.col_align_log2);
                    const t_id = state.nextTmp();
                    try state.print(
                        "  %_scol_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ t_id, cur_ptr, ptr_int, col_info.byte_offset },
                    );
                    pending_soa = .{
                        .col_ptr = try std.fmt.allocPrint(emitter.allocator, "%_scol_{d}", .{t_id}),
                        .field_ty = fld_ty,
                        .col_align = @min(
                            @max(cur_align, 1),
                            effectiveOffsetAlign(col_info.byte_offset, nat_col_align),
                        ),
                        .is_fixed = true,
                        .fixed_cap = cap,
                        .slice_base_ptr = try emitter.allocator.dupe(u8, cur_ptr),
                    };
                } else if (node.tag == .soa_vec_ty) {
                    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
                    const hdr_align = @min(@max(cur_align, 1), ptr_bytes);
                    const t_id = state.nextTmp();
                    try state.print(
                        "  %_ssl_dp_{d} = load ptr, ptr {s}, align {d}\n" ++
                            "  %_ssl_cp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  %_ssl_c32_{d} = load i32, ptr %_ssl_cp_{d}, align 4\n",
                        .{
                            t_id,          cur_ptr, hdr_align,
                            t_id,          cur_ptr, ptr_int,
                            ptr_bytes + 4, t_id,    t_id,
                        },
                    );
                    if (can_enter_param_ptr) {
                        active_mvs_param = base_local;
                        can_enter_param_ptr = false;
                    }
                    const cap_s = if (ptr_bytes == 4)
                        try std.fmt.allocPrint(emitter.allocator, "%_ssl_c32_{d}", .{t_id})
                    else blk_cz: {
                        try state.print("  %_ssl_cz_{d} = zext i32 %_ssl_c32_{d} to i64\n", .{ t_id, t_id });
                        break :blk_cz try std.fmt.allocPrint(emitter.allocator, "%_ssl_cz_{d}", .{t_id});
                    };
                    defer emitter.allocator.free(cap_s);
                    const dyn_col = try emitDynamicSoaColByteOffset(
                        emitter,
                        state,
                        elem_struct,
                        proj.payload,
                        cap_s,
                    );
                    defer emitter.allocator.free(dyn_col.off_ssa);
                    try state.print(
                        "  %_scol_{d} = getelementptr inbounds i8, ptr %_ssl_dp_{d}, {s} {s}\n",
                        .{ t_id, t_id, ptr_int, dyn_col.off_ssa },
                    );
                    pending_soa = .{
                        .col_ptr = try std.fmt.allocPrint(emitter.allocator, "%_scol_{d}", .{t_id}),
                        .field_ty = fld_ty,
                        .col_align = dyn_col.col_align_bytes,
                        .is_fixed = false,
                        .fixed_cap = 0,
                        .slice_base_ptr = try emitter.allocator.dupe(u8, cur_ptr),
                    };
                } else {
                    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
                    const hdr_align = @min(@max(cur_align, 1), ptr_bytes);
                    const t_id = state.nextTmp();
                    try state.print(
                        "  %_ssl_dp_{d} = load ptr, ptr {s}, align {d}\n" ++
                            "  %_ssl_sp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  %_ssl_st_{d} = load {s}, ptr %_ssl_sp_{d}, align {d}\n" ++
                            "  %_ssl_ep_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  %_ssl_eo_{d} = load {s}, ptr %_ssl_ep_{d}, align {d}\n",
                        .{
                            t_id,          cur_ptr,   hdr_align,
                            t_id,          cur_ptr,   ptr_int,
                            ptr_bytes * 2, t_id,      ptr_int,
                            t_id,          hdr_align, t_id,
                            cur_ptr,       ptr_int,   ptr_bytes * 3,
                            t_id,          ptr_int,   t_id,
                            hdr_align,
                        },
                    );
                    if (can_enter_param_ptr) {
                        active_mvs_param = base_local;
                        can_enter_param_ptr = false;
                    }
                    const stride_s = try std.fmt.allocPrint(emitter.allocator, "%_ssl_st_{d}", .{t_id});
                    defer emitter.allocator.free(stride_s);
                    const dyn_col = try emitDynamicSoaColByteOffset(
                        emitter,
                        state,
                        elem_struct,
                        proj.payload,
                        stride_s,
                    );
                    defer emitter.allocator.free(dyn_col.off_ssa);
                    try state.print(
                        "  %_ssl_em_{d} = mul {s} %_ssl_eo_{d}, {d}\n" ++
                            "  %_ssl_bo_{d} = add {s} {s}, %_ssl_em_{d}\n" ++
                            "  %_scol_{d} = getelementptr inbounds i8, ptr %_ssl_dp_{d}, {s} %_ssl_bo_{d}\n",
                        .{
                            t_id, ptr_int, t_id,            fld.size_bytes,
                            t_id, ptr_int, dyn_col.off_ssa, t_id,
                            t_id, t_id,    ptr_int,         t_id,
                        },
                    );
                    const col_align_b: u32 = if (fld.size_bytes == 0)
                        dyn_col.col_align_bytes
                    else
                        @min(dyn_col.col_align_bytes, @as(u32, 1) << @intCast(fld.align_log2));
                    pending_soa = .{
                        .col_ptr = try std.fmt.allocPrint(emitter.allocator, "%_scol_{d}", .{t_id}),
                        .field_ty = fld_ty,
                        .col_align = col_align_b,
                        .is_fixed = false,
                        .fixed_cap = 0,
                        .slice_base_ptr = try emitter.allocator.dupe(u8, cur_ptr),
                    };
                }
            },
            .slice_len => {
                if (cur_ty != .str_ty and
                    (node.tag == .array_ty or node.tag == .soa_array_ty))
                {
                    const arr_cap: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                    emitter.allocator.free(cur_ptr);
                    return .{ .const_len = .{ .elem_count = arr_cap } };
                }
                const t_id = state.nextTmp();
                try state.print(
                    "  %_len_p_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                    .{ t_id, cur_ptr, ptr_int, emitter.cfg.target.ptrBytes() },
                );
                emitter.allocator.free(cur_ptr);
                return .{
                    .addr_val = .{
                        .ptr_str = try std.fmt.allocPrint(emitter.allocator, "%_len_p_{d}", .{t_id}),
                        .pointee_ty = .usize_ty,
                        .align_bytes = @min(@max(cur_align, 1), emitter.cfg.target.ptrBytes()),
                        .root_param_local = active_mvs_param,
                    },
                };
            },
        }
    }

    return .{
        .addr_val = .{
            .ptr_str = cur_ptr,
            .pointee_ty = cur_ty,
            .align_bytes = @max(cur_align, 1),
            .root_param_local = active_mvs_param,
        },
    };
}

/// Converts an index `MirValueId` (`idx_raw`) to pointer-width integer (`i32` on `wasm32`, `i64` on 64-bit).
fn coerceIndexToPtrInt(
    emitter: *const LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    idx_raw: u32,
) ![]u8 {
    const ptr_bits: u16 = @as(u16, emitter.cfg.target.ptrBytes()) * 8;
    const idx_ty = body.getInst(MirValueId.fromInt(idx_raw)).type_id;
    const idx_info = resolveIntegerInfo(emitter, idx_ty) orelse IntScalarInfo{
        .bits = ptr_bits,
        .is_signed = false,
    };
    if (idx_info.bits == ptr_bits) {
        return std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{idx_raw});
    }
    const tmp_id = state.nextTmp();
    const cast_op = if (idx_info.bits < ptr_bits)
        (if (idx_info.is_signed) "sext" else "zext")
    else
        "trunc";
    try state.print(
        "  %_idx_c_{d} = {s} i{d} %_v_{d} to i{d}\n",
        .{ tmp_id, cast_op, idx_info.bits, idx_raw, ptr_bits },
    );
    return std.fmt.allocPrint(emitter.allocator, "%_idx_c_{d}", .{tmp_id});
}

// ------------------ MIR Instruction Lowering ------------------

/// Emits a conditional trap branch (`if (cond_i1) _cx_rt_trap(reason)`) and updates `state.cur_label`.
fn emitInlineTrapIfTrue(
    emitter: *const LlvmModuleEmitter,
    state: *BodyEmitState,
    cond_ssa: []const u8,
    reason_code: u32,
) !void {
    const tmp_id = state.nextTmp();
    try state.print(
        "  br i1 {s}, label %_trap_{d}, label %_ok_{d}\n" ++
            "_trap_{d}:\n" ++
            "  call void @_cx_rt_trap(i32 {d})\n" ++
            "  unreachable\n" ++
            "_ok_{d}:\n",
        .{ cond_ssa, tmp_id, tmp_id, tmp_id, reason_code, tmp_id },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_ok_{d}", .{tmp_id}));
}

/// Terminates a `noreturn` intrinsic call and opens a dead continuation block for any trailing MIR ops.
fn emitUnreachableAndDeadBlock(
    emitter: *const LlvmModuleEmitter,
    state: *BodyEmitState,
    dst_raw: u32,
) !void {
    const tmp_id = state.nextTmp();
    try state.print(
        "  unreachable\n_dead_{d}:\n  %_v_{d} = add i8 0, 0\n",
        .{ tmp_id, dst_raw },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_dead_{d}", .{tmp_id}));
}

/// Formats an IEEE-754 value as an exact 16-hex-digit LLVM IR floating-point constant (`0x…`).
fn formatLlvmHexFloatLiteral(allocator: std.mem.Allocator, is_f32: bool, raw_f64: f64) ![]u8 {
    if (is_f32) {
        const f32_val: f32 = @floatCast(raw_f64);
        if (std.math.isNan(f32_val)) {
            return allocator.dupe(u8, "0x7FF8000000000000");
        }
        const bits: u64 = @bitCast(@as(f64, @floatCast(f32_val)));
        return std.fmt.allocPrint(allocator, "0x{X:0>16}", .{bits});
    }
    if (std.math.isNan(raw_f64)) {
        return allocator.dupe(u8, "0x7FF8000000000000");
    }
    const bits: u64 = @bitCast(raw_f64);
    return std.fmt.allocPrint(allocator, "0x{X:0>16}", .{bits});
}

/// Extracts `(ptr_ssa, len_ssa)` (where `len_ssa` has type `ptrIntType`) from `str`, `[u8]`, `&[u8]`, or `[u8; N]`.
fn emitExtractByteSpanLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    arg_val: MirValueId,
) !struct { ptr_ssa: []u8, len_ssa: []u8 } {
    const ptr_int = ptrIntType(emitter);
    const arg_raw = arg_val.asInt();
    const arg_ty = try unwrapTransparentType(emitter, body.getInst(arg_val).type_id);
    if (arg_ty == .str_ty) {
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_bsp_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 0\n" ++
                "  %_bsl_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 1\n",
            .{ tmp_id, ptr_int, arg_raw, tmp_id, ptr_int, arg_raw },
        );
        return .{
            .ptr_ssa = try std.fmt.allocPrint(emitter.allocator, "%_bsp_{d}", .{tmp_id}),
            .len_ssa = try std.fmt.allocPrint(emitter.allocator, "%_bsl_{d}", .{tmp_id}),
        };
    }
    const node = emitter.input.pool.getNode(arg_ty);
    if (node.tag == .slice_ty or emitter.input.pool.isSliceRefType(arg_ty)) {
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_bsp_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 0\n" ++
                "  %_bsl_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 1\n",
            .{ tmp_id, ptr_int, arg_raw, tmp_id, ptr_int, arg_raw },
        );
        return .{
            .ptr_ssa = try std.fmt.allocPrint(emitter.allocator, "%_bsp_{d}", .{tmp_id}),
            .len_ssa = try std.fmt.allocPrint(emitter.allocator, "%_bsl_{d}", .{tmp_id}),
        };
    }
    if (node.tag == .array_ty) {
        const cap: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
        const lay = try emitter.resolver.resolveType(arg_ty);
        const scratch = try state.allocEntryBytes(lay.size_bytes, lay.alignBytes());
        const val_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{arg_raw});
        defer emitter.allocator.free(val_ssa);
        try emitStoreValueToPtr(emitter, state, arg_ty, val_ssa, scratch, lay.alignBytes(), 0, 0, 0);
        return .{
            .ptr_ssa = scratch,
            .len_ssa = try std.fmt.allocPrint(emitter.allocator, "{d}", .{cap}),
        };
    }
    if ((node.tag == .ref_ty or node.tag == .mut_ref_ty or node.tag == .raw_ptr_ty) and
        !emitter.input.pool.isSliceRefType(arg_ty))
    {
        const pointee = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
        if (pointee == .str_ty or
            emitter.input.pool.getNode(pointee).tag == .slice_ty or
            emitter.input.pool.isSliceRefType(pointee))
        {
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_bsfat_{d} = load {{ ptr, {s} }}, ptr %_v_{d}, align {d}\n" ++
                    "  %_bsp_{d} = extractvalue {{ ptr, {s} }} %_bsfat_{d}, 0\n" ++
                    "  %_bsl_{d} = extractvalue {{ ptr, {s} }} %_bsfat_{d}, 1\n",
                .{
                    tmp_id,
                    ptr_int,
                    arg_raw,
                    emitter.cfg.target.ptrBytes(),
                    tmp_id,
                    ptr_int,
                    tmp_id,
                    tmp_id,
                    ptr_int,
                    tmp_id,
                },
            );
            return .{
                .ptr_ssa = try std.fmt.allocPrint(emitter.allocator, "%_bsp_{d}", .{tmp_id}),
                .len_ssa = try std.fmt.allocPrint(emitter.allocator, "%_bsl_{d}", .{tmp_id}),
            };
        }
        const p_node = emitter.input.pool.getNode(pointee);
        if (p_node.tag == .array_ty) {
            const cap: u64 = p_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            return .{
                .ptr_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{arg_raw}),
                .len_ssa = try std.fmt.allocPrint(emitter.allocator, "{d}", .{cap}),
            };
        }
    }
    return .{
        .ptr_ssa = try std.fmt.allocPrint(emitter.allocator, "inttoptr ({s} 1 to ptr)", .{ptr_int}),
        .len_ssa = try emitter.allocator.dupe(u8, "0"),
    };
}

/// Widens or sign/zero-extends an integer SSA value `%_v_<val_raw>` (`val_ty`) to `i128`.
fn emitExtendIntToI128(
    emitter: *const LlvmModuleEmitter,
    state: *BodyEmitState,
    val_raw: u32,
    val_ty: TypeId,
    is_forced_unsigned: bool,
) ![]u8 {
    const unwrapped = emitter.input.pool.unwrapUnderlyingType(val_ty);
    if (unwrapped == .bool_ty) {
        const tmp_id = state.nextTmp();
        try state.print("  %_w128_{d} = zext i1 %_v_{d} to i128\n", .{ tmp_id, val_raw });
        return std.fmt.allocPrint(emitter.allocator, "%_w128_{d}", .{tmp_id});
    }
    const info = resolveIntegerInfo(emitter, unwrapped) orelse
        return emitter.allocator.dupe(u8, "0");
    if (info.bits == 128) {
        return std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{val_raw});
    }
    const tmp_id = state.nextTmp();
    const op_s = if (!is_forced_unsigned and info.is_signed) "sext" else "zext";
    try state.print(
        "  %_w128_{d} = {s} i{d} %_v_{d} to i128\n",
        .{ tmp_id, op_s, info.bits, val_raw },
    );
    return std.fmt.allocPrint(emitter.allocator, "%_w128_{d}", .{tmp_id});
}

/// Appends an LLVM byte-array literal `c"…"` (escaping non-printable bytes as `\XX`) to `buf`.
fn appendByteStringLiteralToBuf(
    allocator: std.mem.Allocator,
    buf: *std.ArrayListUnmanaged(u8),
    bytes: []const u8,
) !void {
    try buf.appendSlice(allocator, "c\"");
    for (bytes) |byte_val| {
        if (byte_val >= 0x20 and byte_val <= 0x7E and byte_val != '"' and byte_val != '\\') {
            try buf.append(allocator, byte_val);
        } else {
            var esc_buf: [3]u8 = undefined;
            const esc = std.fmt.bufPrint(&esc_buf, "\\{X:0>2}", .{byte_val}) catch unreachable;
            try buf.appendSlice(allocator, esc);
        }
    }
    try buf.append(allocator, '"');
}

/// Lazily emits `@_cx_rt_fmt_u128` into `emitter.synth_globals` for `128`-bit `str_concat` formatting.
fn ensureFmtU128Helper(emitter: *LlvmModuleEmitter) !void {
    if (emitter.has_fmt_u128_helper) return;
    emitter.has_fmt_u128_helper = true;
    const fn_ir = try std.fmt.allocPrint(
        emitter.allocator,
        "define internal i32 @_cx_rt_fmt_u128(ptr %buf, i128 %val) {s} {{\n" ++
            "entry:\n" ++
            "  %rev = alloca [48 x i8], align 1\n" ++
            "  %isz = icmp eq i128 %val, 0\n" ++
            "  br i1 %isz, label %zero, label %loop\n" ++
            "zero:\n" ++
            "  store i8 48, ptr %buf, align 1\n" ++
            "  ret i32 1\n" ++
            "loop:\n" ++
            "  %cur = phi i128 [ %val, %entry ], [ %nxt, %loop ]\n" ++
            "  %cnt = phi i32 [ 0, %entry ], [ %cnt_nx, %loop ]\n" ++
            "  %rem = urem i128 %cur, 10\n" ++
            "  %nxt = udiv i128 %cur, 10\n" ++
            "  %rem8 = trunc i128 %rem to i8\n" ++
            "  %dig = add i8 %rem8, 48\n" ++
            "  %rp = getelementptr inbounds [48 x i8], ptr %rev, i32 0, i32 %cnt\n" ++
            "  store i8 %dig, ptr %rp, align 1\n" ++
            "  %cnt_nx = add i32 %cnt, 1\n" ++
            "  %has_more = icmp ne i128 %nxt, 0\n" ++
            "  br i1 %has_more, label %loop, label %copy\n" ++
            "copy:\n" ++
            "  %idx = phi i32 [ 0, %loop ], [ %idx_nx, %copy ]\n" ++
            "  %ri_sub = sub i32 %cnt_nx, 1\n" ++
            "  %ri = sub i32 %ri_sub, %idx\n" ++
            "  %sp = getelementptr inbounds [48 x i8], ptr %rev, i32 0, i32 %ri\n" ++
            "  %ch = load i8, ptr %sp, align 1\n" ++
            "  %dp = getelementptr inbounds i8, ptr %buf, i32 %idx\n" ++
            "  store i8 %ch, ptr %dp, align 1\n" ++
            "  %idx_nx = add i32 %idx, 1\n" ++
            "  %more_cp = icmp slt i32 %idx_nx, %cnt_nx\n" ++
            "  br i1 %more_cp, label %copy, label %done\n" ++
            "done:\n" ++
            "  ret i32 %cnt_nx\n" ++
            "}}\n\n",
        .{fnUnwindAttrs(emitter)},
    );
    defer emitter.allocator.free(fn_ir);
    try emitter.synth_globals.appendSlice(emitter.allocator, fn_ir);
}

/// Lazily emits `@_cx_rt_fmt_i128` into `emitter.synth_globals` for signed `128`-bit `str_concat` formatting.
fn ensureFmtI128Helper(emitter: *LlvmModuleEmitter) !void {
    try ensureFmtU128Helper(emitter);
    if (emitter.has_fmt_i128_helper) return;
    emitter.has_fmt_i128_helper = true;
    const fn_ir = try std.fmt.allocPrint(
        emitter.allocator,
        "define internal i32 @_cx_rt_fmt_i128(ptr %buf, i128 %val) {s} {{\n" ++
            "entry:\n" ++
            "  %isneg = icmp slt i128 %val, 0\n" ++
            "  br i1 %isneg, label %neg, label %pos\n" ++
            "neg:\n" ++
            "  store i8 45, ptr %buf, align 1\n" ++
            "  %mag = sub i128 0, %val\n" ++
            "  %nbuf = getelementptr inbounds i8, ptr %buf, i32 1\n" ++
            "  %nlen = call i32 @_cx_rt_fmt_u128(ptr %nbuf, i128 %mag)\n" ++
            "  %tot = add i32 %nlen, 1\n" ++
            "  ret i32 %tot\n" ++
            "pos:\n" ++
            "  %plen = call i32 @_cx_rt_fmt_u128(ptr %buf, i128 %val)\n" ++
            "  ret i32 %plen\n" ++
            "}}\n\n",
        .{fnUnwindAttrs(emitter)},
    );
    defer emitter.allocator.free(fn_ir);
    try emitter.synth_globals.appendSlice(emitter.allocator, fn_ir);
}

/// Emits `&[T; N]` -> `[T]` / `&[T]` and `&[T]` <-> `[T]` pointer-slice coercions when applicable.
fn tryEmitSliceArrayPtrCoercionLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    dst_raw: u32,
    src_raw: u32,
    src_ty: TypeId,
    dst_ty: TypeId,
) !bool {
    if (src_ty.isPrimitiveOrSentinel() and src_ty != .str_ty) return false;
    if (dst_ty.isPrimitiveOrSentinel() and dst_ty != .str_ty) return false;

    const ptr_int = ptrIntType(emitter);
    const ptr_bytes = emitter.cfg.target.ptrBytes();
    const src_is_ptr_like = if (src_ty == .str_ty or emitter.input.pool.isSliceRefType(src_ty)) false else blk: {
        const sn = emitter.input.pool.getNode(src_ty);
        break :blk sn.tag == .ref_ty or sn.tag == .mut_ref_ty or sn.tag == .raw_ptr_ty;
    };
    const dst_is_ptr_like = if (dst_ty == .str_ty or emitter.input.pool.isSliceRefType(dst_ty)) false else blk: {
        const dn = emitter.input.pool.getNode(dst_ty);
        break :blk dn.tag == .ref_ty or dn.tag == .mut_ref_ty or dn.tag == .raw_ptr_ty;
    };
    const dst_is_fat_slice = if (dst_ty == .str_ty or emitter.input.pool.isSliceRefType(dst_ty)) true else blk: {
        const dn = emitter.input.pool.getNode(dst_ty);
        break :blk dn.tag == .slice_ty or dn.tag == .soa_slice_ty;
    };
    const src_is_fat_slice = if (src_ty == .str_ty or emitter.input.pool.isSliceRefType(src_ty)) true else blk: {
        const sn = emitter.input.pool.getNode(src_ty);
        break :blk sn.tag == .slice_ty or sn.tag == .soa_slice_ty;
    };

    if (src_is_fat_slice and dst_is_fat_slice) {
        const dst_sl_ty = try formatSliceLlvmStructType(emitter, dst_ty);
        defer emitter.allocator.free(dst_sl_ty);
        try state.print(
            "  %_v_{d} = select i1 true, {s} %_v_{d}, {s} %_v_{d}\n",
            .{ dst_raw, dst_sl_ty, src_raw, dst_sl_ty, src_raw },
        );
        return true;
    }

    if (src_is_ptr_like) {
        const src_pointee = try unwrapTransparentType(
            emitter,
            TypeId.fromInt(emitter.input.pool.getNode(src_ty).lhs),
        );
        if (src_pointee != .str_ty and !src_pointee.isPrimitiveOrSentinel()) {
            const sp_node = emitter.input.pool.getNode(src_pointee);
            if (sp_node.tag == .array_ty or sp_node.tag == .soa_array_ty) {
                const cap: u64 = sp_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(sp_node.lhs));
                const elem_lay = try emitter.resolver.resolveType(elem_ty);
                const data_ptr_s = if (cap == 0)
                    try std.fmt.allocPrint(
                        emitter.allocator,
                        "inttoptr ({s} {d} to ptr)",
                        .{ ptr_int, @max(elem_lay.alignBytes(), 1) },
                    )
                else
                    try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{src_raw});
                defer emitter.allocator.free(data_ptr_s);

                if (dst_is_fat_slice) {
                    const tmp_id = state.nextTmp();
                    const dst_sl_ty = try formatSliceLlvmStructType(emitter, dst_ty);
                    defer emitter.allocator.free(dst_sl_ty);
                    if (emitter.input.pool.isSoaSliceOrRefType(dst_ty)) {
                        try state.print(
                            "  %_sac0_{d} = insertvalue {s} zeroinitializer, ptr {s}, 0\n" ++
                                "  %_sac1_{d} = insertvalue {s} %_sac0_{d}, {s} {d}, 1\n" ++
                                "  %_sac2_{d} = insertvalue {s} %_sac1_{d}, {s} {d}, 2\n" ++
                                "  %_v_{d} = insertvalue {s} %_sac2_{d}, {s} 0, 3\n",
                            .{
                                tmp_id,    dst_sl_ty, data_ptr_s,
                                tmp_id,    dst_sl_ty, tmp_id,
                                ptr_int,   cap,       tmp_id,
                                dst_sl_ty, tmp_id,    ptr_int,
                                cap,       dst_raw,   dst_sl_ty,
                                tmp_id,    ptr_int,
                            },
                        );
                    } else {
                        try state.print(
                            "  %_sac0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr {s}, 0\n" ++
                                "  %_v_{d} = insertvalue {{ ptr, {s} }} %_sac0_{d}, {s} {d}, 1\n",
                            .{ tmp_id, ptr_int, data_ptr_s, dst_raw, ptr_int, tmp_id, ptr_int, cap },
                        );
                    }
                    return true;
                }
                if (dst_is_ptr_like) {
                    const dst_pointee = try unwrapTransparentType(
                        emitter,
                        TypeId.fromInt(emitter.input.pool.getNode(dst_ty).lhs),
                    );
                    const dp_is_slice = if (dst_pointee == .str_ty or emitter.input.pool.isSliceRefType(dst_pointee))
                        true
                    else if (dst_pointee.isPrimitiveOrSentinel())
                        false
                    else sub: {
                        const dpn = emitter.input.pool.getNode(dst_pointee);
                        break :sub dpn.tag == .slice_ty or dpn.tag == .soa_slice_ty;
                    };
                    if (dp_is_slice) {
                        const words = sliceDescriptorWordCount(emitter.input.pool, dst_pointee);
                        const fat_slot = try state.allocEntryBytes(words * ptr_bytes, ptr_bytes);
                        defer emitter.allocator.free(fat_slot);
                        try emitMemsetZero(emitter, state, fat_slot, words * ptr_bytes, ptr_bytes);
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  store ptr {s}, ptr {s}, align {d}\n" ++
                                "  %_sacp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                                "  store {s} {d}, ptr %_sacp_{d}, align {d}\n",
                            .{
                                data_ptr_s,
                                fat_slot,
                                ptr_bytes,
                                tmp_id,
                                fat_slot,
                                ptr_int,
                                ptr_bytes,
                                ptr_int,
                                cap,
                                tmp_id,
                                ptr_bytes,
                            },
                        );
                        if (words == 4) {
                            try state.print(
                                "  %_sacs_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                                    "  store {s} {d}, ptr %_sacs_{d}, align {d}\n",
                                .{ tmp_id, fat_slot, ptr_int, ptr_bytes * 2, ptr_int, cap, tmp_id, ptr_bytes },
                            );
                        }
                        try state.print(
                            "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                            .{ dst_raw, fat_slot, fat_slot },
                        );
                        return true;
                    }
                }
            }
        }
        const sp_is_slice = if (src_pointee == .str_ty or emitter.input.pool.isSliceRefType(src_pointee))
            true
        else if (src_pointee.isPrimitiveOrSentinel())
            false
        else sub: {
            const spn = emitter.input.pool.getNode(src_pointee);
            break :sub spn.tag == .slice_ty or spn.tag == .soa_slice_ty;
        };
        if (sp_is_slice and dst_is_fat_slice) {
            const dst_sl_ty = try formatSliceLlvmStructType(emitter, dst_ty);
            defer emitter.allocator.free(dst_sl_ty);
            try state.print(
                "  %_v_{d} = load {s}, ptr %_v_{d}, align {d}\n",
                .{ dst_raw, dst_sl_ty, src_raw, ptr_bytes },
            );
            return true;
        }
    }

    if (src_is_fat_slice and dst_is_ptr_like) {
        const dst_pointee = try unwrapTransparentType(
            emitter,
            TypeId.fromInt(emitter.input.pool.getNode(dst_ty).lhs),
        );
        const dp_is_slice = if (dst_pointee == .str_ty or emitter.input.pool.isSliceRefType(dst_pointee))
            true
        else if (dst_pointee.isPrimitiveOrSentinel())
            false
        else sub: {
            const dpn = emitter.input.pool.getNode(dst_pointee);
            break :sub dpn.tag == .slice_ty or dpn.tag == .soa_slice_ty;
        };
        if (dp_is_slice) {
            const src_inst = body.getInst(MirValueId.fromInt(src_raw));
            if (src_inst.op == .const_scalar) {
                const c_val = body.consts.items[src_inst.operands.lhs];
                switch (c_val) {
                    .str_val, .bytes_val => |sym_id| {
                        const raw_bytes = emitter.input.interner.get(sym_id);
                        const ptr_expr = if (raw_bytes.len == 0)
                            try emitter.allocator.dupe(u8, "@_cx_empty_cstr")
                        else
                            try std.fmt.allocPrint(emitter.allocator, "@_cx_str_bytes_{d}", .{sym_id.asInt()});
                        defer emitter.allocator.free(ptr_expr);
                        const sid = emitter.nextSynthGlobalId();
                        const hdr_line = try std.fmt.allocPrint(
                            emitter.allocator,
                            "@_cx_sref_{d} = private unnamed_addr constant {{ ptr, {s} }} " ++
                                "{{ ptr {s}, {s} {d} }}, align {d}\n",
                            .{ sid, ptr_int, ptr_expr, ptr_int, raw_bytes.len, ptr_bytes },
                        );
                        defer emitter.allocator.free(hdr_line);
                        try emitter.synth_globals.appendSlice(emitter.allocator, hdr_line);
                        try state.print(
                            "  %_v_{d} = select i1 true, ptr @_cx_sref_{d}, ptr @_cx_sref_{d}\n",
                            .{ dst_raw, sid, sid },
                        );
                        return true;
                    },
                    .raw_blob => |rb| {
                        try state.print(
                            "  %_v_{d} = select i1 true, ptr @_cx_blob_slice_{d}, ptr @_cx_blob_slice_{d}\n",
                            .{ dst_raw, rb.blob_id, rb.blob_id },
                        );
                        return true;
                    },
                    else => {},
                }
            }
            const fat_slot = try state.allocEntryBytes(2 * ptr_bytes, ptr_bytes);
            defer emitter.allocator.free(fat_slot);
            try state.print(
                "  store {{ ptr, {s} }} %_v_{d}, ptr {s}, align {d}\n" ++
                    "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                .{ ptr_int, src_raw, fat_slot, ptr_bytes, dst_raw, fat_slot, fat_slot },
            );
            return true;
        }
    }

    return false;
}

/// Emits a single non-terminator `MirInst` inside `body_idx` (`Pass 1`).
fn emitMirInstLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body_idx: u32,
    body: *const MirBody,
    bb_idx: u32,
    val_id: MirValueId,
) !void {
    const dst_raw = val_id.asInt();
    const inst = body.getInst(val_id);
    if (inst.op == .block_param or inst.op.isGhost()) return;

    const access_grp = if (bb_idx < state.block_access_group.len) state.block_access_group[bb_idx] else 0;
    const ptr_int = ptrIntType(emitter);

    switch (inst.op) {
        .block_param,
        .ghost_access_let,
        .ghost_access_inout,
        .ghost_access_set,
        .ghost_access_end,
        .ghost_storage_init,
        .ghost_storage_move,
        .ghost_storage_deinit,
        => {},

        .const_scalar => {
            if (try isZeroSizedType(emitter, inst.type_id)) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const c_val = body.consts.items[inst.operands.lhs];
            const dst_ty = try unwrapTransparentType(emitter, inst.type_id);
            switch (c_val) {
                .unit_val => try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw}),
                .bool_val => |bv| try state.print(
                    "  %_v_{d} = or i1 false, {s}\n",
                    .{ dst_raw, if (bv) "true" else "false" },
                ),
                .char_val => |cv| try state.print("  %_v_{d} = add i32 0, {d}\n", .{ dst_raw, @as(u32, cv) }),
                .int_val => |iv| {
                    if (dst_ty == .bool_ty) {
                        try state.print(
                            "  %_v_{d} = or i1 false, {s}\n",
                            .{ dst_raw, if ((iv & 1) != 0) "true" else "false" },
                        );
                    } else if (resolveIntegerInfo(emitter, dst_ty)) |info| {
                        if (info.bits == 128) {
                            try state.print("  %_v_{d} = add i128 0, {d}\n", .{ dst_raw, iv });
                        } else {
                            const mask: u128 = (@as(u128, 1) << @intCast(info.bits)) - 1;
                            const u_bits: u128 = (@as(u128, @bitCast(iv))) & mask;
                            try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, info.bits, u_bits });
                        }
                    } else {
                        const ty_s = try formatLlvmValueType(emitter, dst_ty);
                        defer emitter.allocator.free(ty_s);
                        if (std.mem.eql(u8, ty_s, "ptr")) {
                            const addr_u: u64 = @truncate(@as(u128, @bitCast(iv)));
                            if (addr_u == 0) {
                                try state.print("  %_v_{d} = select i1 true, ptr null, ptr null\n", .{dst_raw});
                            } else {
                                try state.print(
                                    "  %_v_{d} = select i1 true, ptr inttoptr ({s} {d} to ptr), ptr null\n",
                                    .{ dst_raw, ptr_int, addr_u },
                                );
                            }
                        } else {
                            const zero_s = resolveZeroLiteralForLlvmType(ty_s);
                            try state.print(
                                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                                .{ dst_raw, ty_s, zero_s, ty_s, zero_s },
                            );
                        }
                    }
                },
                .float_val => |fv| {
                    const is_f32 = dst_ty == .f32_ty;
                    const flt_ty = if (is_f32) "float" else "double";
                    const hex_s = try formatLlvmHexFloatLiteral(emitter.allocator, is_f32, fv);
                    defer emitter.allocator.free(hex_s);
                    try state.print(
                        "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                        .{ dst_raw, flt_ty, hex_s, flt_ty, hex_s },
                    );
                },
                .str_val, .bytes_val => |sym_id| {
                    const raw_bytes = emitter.input.interner.get(sym_id);
                    const dst_node = emitter.input.pool.getNode(dst_ty);
                    const ptr_expr = if (raw_bytes.len == 0)
                        try emitter.allocator.dupe(u8, "@_cx_empty_cstr")
                    else
                        try std.fmt.allocPrint(emitter.allocator, "@_cx_str_bytes_{d}", .{sym_id.asInt()});
                    defer emitter.allocator.free(ptr_expr);

                    if ((dst_node.tag == .ref_ty or dst_node.tag == .mut_ref_ty or dst_node.tag == .raw_ptr_ty) and
                        !emitter.input.pool.isSliceRefType(dst_ty))
                    {
                        const pointee = try unwrapTransparentType(emitter, TypeId.fromInt(dst_node.lhs));
                        if (emitter.input.pool.getNode(pointee).tag == .slice_ty or pointee == .str_ty) {
                            const sid = emitter.nextSynthGlobalId();
                            const hdr_line = try std.fmt.allocPrint(
                                emitter.allocator,
                                "@_cx_sref_{d} = private unnamed_addr constant {{ ptr, {s} }} " ++
                                    "{{ ptr {s}, {s} {d} }}, align {d}\n",
                                .{ sid, ptr_int, ptr_expr, ptr_int, raw_bytes.len, emitter.cfg.target.ptrBytes() },
                            );
                            defer emitter.allocator.free(hdr_line);
                            try emitter.synth_globals.appendSlice(emitter.allocator, hdr_line);
                            try state.print(
                                "  %_v_{d} = select i1 true, ptr @_cx_sref_{d}, ptr @_cx_sref_{d}\n",
                                .{ dst_raw, sid, sid },
                            );
                        } else {
                            try state.print(
                                "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                                .{ dst_raw, ptr_expr, ptr_expr },
                            );
                        }
                    } else if (dst_node.tag == .array_ty) {
                        const elem_count: u64 = dst_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                        if (elem_count == 0 or raw_bytes.len == 0) {
                            try state.print(
                                "  %_v_{d} = select i1 true, [{d} x i8] zeroinitializer, [{d} x i8] zeroinitializer\n",
                                .{ dst_raw, elem_count, elem_count },
                            );
                        } else {
                            try state.print(
                                "  %_v_{d} = load [{d} x i8], ptr {s}, align 1\n",
                                .{ dst_raw, elem_count, ptr_expr },
                            );
                        }
                    } else {
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  %_sf0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr {s}, 0\n" ++
                                "  %_v_{d} = insertvalue {{ ptr, {s} }} %_sf0_{d}, {s} {d}, 1\n",
                            .{ tmp_id, ptr_int, ptr_expr, dst_raw, ptr_int, tmp_id, ptr_int, raw_bytes.len },
                        );
                    }
                },
                .raw_blob => |rb| {
                    const dst_node = emitter.input.pool.getNode(dst_ty);
                    if ((dst_node.tag == .ref_ty or dst_node.tag == .mut_ref_ty or dst_node.tag == .raw_ptr_ty) and
                        !emitter.input.pool.isSliceRefType(dst_ty))
                    {
                        const pointee = try unwrapTransparentType(emitter, TypeId.fromInt(dst_node.lhs));
                        if (emitter.input.pool.getNode(pointee).tag == .slice_ty) {
                            try state.print(
                                "  %_v_{d} = select i1 true, ptr @_cx_blob_slice_{d}, ptr @_cx_blob_slice_{d}\n",
                                .{ dst_raw, rb.blob_id, rb.blob_id },
                            );
                        } else if (rb.byte_len == 0) {
                            const align_b: u32 = @as(u32, 1) << @intCast(rb.align_log2);
                            try state.print(
                                "  %_v_{d} = select i1 true, ptr inttoptr ({s} {d} to ptr), ptr null\n",
                                .{ dst_raw, ptr_int, @max(align_b, 1) },
                            );
                        } else {
                            try state.print(
                                "  %_v_{d} = select i1 true, ptr @_cx_blob_{d}, ptr @_cx_blob_{d}\n",
                                .{ dst_raw, rb.blob_id, rb.blob_id },
                            );
                        }
                    } else if (dst_node.tag == .array_ty) {
                        const elem_count: u64 = dst_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                        if (elem_count == 0 or rb.byte_len == 0) {
                            try state.print(
                                "  %_v_{d} = select i1 true, [{d} x i8] zeroinitializer, [{d} x i8] zeroinitializer\n",
                                .{ dst_raw, elem_count, elem_count },
                            );
                        } else {
                            try state.print(
                                "  %_v_{d} = load [{d} x i8], ptr @_cx_blob_{d}, align 1\n",
                                .{ dst_raw, elem_count, rb.blob_id },
                            );
                        }
                    } else {
                        try state.print(
                            "  %_v_{d} = load {{ ptr, {s} }}, ptr @_cx_blob_slice_{d}, align {d}\n",
                            .{ dst_raw, ptr_int, rb.blob_id, emitter.cfg.target.ptrBytes() },
                        );
                    }
                },
                .source_loc => |sloc| {
                    const loc_idx = emitter.source_loc_map.get(computeSourceLocKey(sloc)) orelse 0;
                    try state.print(
                        "  %_v_{d} = select i1 true, ptr @_cx_loc_{d}, ptr @_cx_loc_{d}\n",
                        .{ dst_raw, loc_idx, loc_idx },
                    );
                },
            }
        },

        .copy_val => {
            if (try isZeroSizedType(emitter, inst.type_id)) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const val_ty = try formatLlvmValueType(emitter, inst.type_id);
            defer emitter.allocator.free(val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} %_v_{d}, {s} %_v_{d}\n",
                .{ dst_raw, val_ty, inst.operands.lhs, val_ty, inst.operands.lhs },
            );
            if (std.mem.eql(u8, val_ty, "ptr")) {
                if (lookupProvenRange(emitter, body_idx, dst_raw)) |prov_r| {
                    const dst_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{dst_raw});
                    defer emitter.allocator.free(dst_ssa);
                    try maybeEmitPointerAssume(emitter, state, dst_ssa, prov_r);
                }
            }
        },

        .bin_op => {
            const kind: mir.BinOpKind = @fromBackingInt(@intCast(@as(u8, @truncate(inst.aux_u16))));
            try emitBinOpLlvm(
                emitter,
                state,
                body_idx,
                body,
                dst_raw,
                kind,
                MirValueId.fromInt(inst.operands.lhs),
                MirValueId.fromInt(inst.operands.rhs),
                inst.type_id,
            );
        },

        .unary_op => {
            const kind: mir.UnaryOpKind = @fromBackingInt(@intCast(@as(u8, @truncate(inst.aux_u16))));
            try emitUnaryOpLlvm(
                emitter,
                state,
                body,
                dst_raw,
                kind,
                MirValueId.fromInt(inst.operands.lhs),
                inst.operands.rhs,
                inst.type_id,
            );
        },

        .aggregate_make => {
            const kind: mir.AggregateKind = @fromBackingInt(@intCast(@as(u8, @truncate(inst.aux_u16))));
            try emitAggregateMakeLlvm(emitter, state, body_idx, body, dst_raw, kind, inst);
        },

        .aggregate_extract => {
            if (try isZeroSizedType(emitter, inst.type_id)) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const src_raw = inst.operands.lhs;
            const fld_ord = inst.operands.rhs;
            const src_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(src_raw)).type_id);
            if (src_ty == .source_loc_ty) {
                const sloc_fld = resolveSourceLocFieldLayout(emitter.cfg.target.ptrBytes(), fld_ord);
                const sloc_ptr = if (sloc_fld.byte_offset == 0)
                    try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{src_raw})
                else blk: {
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  %_sloc_ep_{d} = getelementptr inbounds i8, ptr %_v_{d}, {s} {d}\n",
                        .{ tmp_id, src_raw, ptr_int, sloc_fld.byte_offset },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_sloc_ep_{d}", .{tmp_id});
                };
                defer emitter.allocator.free(sloc_ptr);
                const loaded_sloc = try emitLoadValueFromPtr(
                    emitter,
                    state,
                    inst.type_id,
                    sloc_ptr,
                    sloc_fld.align_bytes,
                    lookupProvenRange(emitter, body_idx, dst_raw),
                    0,
                    0,
                    0,
                );
                defer emitter.allocator.free(loaded_sloc);
                const dst_sloc_ty = try formatLlvmValueType(emitter, inst.type_id);
                defer emitter.allocator.free(dst_sloc_ty);
                try state.print(
                    "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                    .{ dst_raw, dst_sloc_ty, loaded_sloc, dst_sloc_ty, loaded_sloc },
                );
                return;
            }
            const src_lay = try emitter.resolver.resolveType(src_ty);
            const scratch = try state.allocEntryBytes(src_lay.size_bytes, src_lay.alignBytes());
            defer emitter.allocator.free(scratch);
            const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{src_raw});
            defer emitter.allocator.free(src_ssa);
            try emitStoreValueToPtr(emitter, state, src_ty, src_ssa, scratch, src_lay.alignBytes(), 0, 0, 0);

            const src_node = emitter.input.pool.getNode(src_ty);
            var elem_off: u64 = 0;
            var elem_align: u32 = 1;
            if (src_ty == .fmt_spec_ty) {
                elem_off = switch (fld_ord) {
                    0 => 0,
                    1 => 4,
                    else => 6,
                };
                elem_align = if (fld_ord == 0) 4 else 2;
            } else if (src_node.tag == .array_ty) {
                const elem_lay = try emitter.resolver.resolveType(inst.type_id);
                elem_off = @as(u64, fld_ord) * elem_lay.stride_bytes;
                elem_align = @min(src_lay.alignBytes(), effectiveOffsetAlign(elem_off, elem_lay.alignBytes()));
            } else if (src_node.tag == .slice_ty or
                src_ty == .str_ty or
                src_node.tag == .soa_slice_ty or
                emitter.input.pool.isSliceRefType(src_ty))
            {
                elem_off = @as(u64, fld_ord) * emitter.cfg.target.ptrBytes();
                elem_align = emitter.cfg.target.ptrBytes();
            } else if (try emitter.resolver.getFieldByDeclOrdinal(src_ty, fld_ord)) |fld| {
                elem_off = fld.byte_offset;
                const nat_align = @as(u32, 1) << @intCast(fld.align_log2);
                elem_align = if (src_lay.reprFlags().is_packed)
                    1
                else
                    @min(src_lay.alignBytes(), effectiveOffsetAlign(fld.byte_offset, nat_align));
            }

            const fld_ptr = if (elem_off == 0)
                try emitter.allocator.dupe(u8, scratch)
            else blk: {
                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_aep_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                    .{ tmp_id, scratch, ptr_int, elem_off },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_aep_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(fld_ptr);

            const loaded = try emitLoadValueFromPtr(
                emitter,
                state,
                inst.type_id,
                fld_ptr,
                elem_align,
                lookupProvenRange(emitter, body_idx, dst_raw),
                0,
                0,
                0,
            );
            defer emitter.allocator.free(loaded);
            const dst_val_ty = try formatLlvmValueType(emitter, inst.type_id);
            defer emitter.allocator.free(dst_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, dst_val_ty, loaded, dst_val_ty, loaded },
            );
        },

        .aggregate_insert => {
            if (try isZeroSizedType(emitter, inst.type_id)) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const src_raw = inst.operands.lhs;
            const fld_ord = body.extra_args.items[inst.operands.rhs];
            const elem_raw = body.extra_args.items[inst.operands.rhs + 1];
            const agg_ty = try unwrapTransparentType(emitter, inst.type_id);
            const agg_lay = try emitter.resolver.resolveType(agg_ty);
            const scratch = try state.allocEntryBytes(agg_lay.size_bytes, agg_lay.alignBytes());
            defer emitter.allocator.free(scratch);
            const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{src_raw});
            defer emitter.allocator.free(src_ssa);
            try emitStoreValueToPtr(emitter, state, agg_ty, src_ssa, scratch, agg_lay.alignBytes(), 0, 0, 0);

            const elem_ty = body.getInst(MirValueId.fromInt(elem_raw)).type_id;
            if (!(try isZeroSizedType(emitter, elem_ty))) {
                const agg_node = emitter.input.pool.getNode(agg_ty);
                var elem_off: u64 = 0;
                var elem_align: u32 = 1;
                if (agg_node.tag == .array_ty) {
                    const elem_lay = try emitter.resolver.resolveType(elem_ty);
                    elem_off = @as(u64, fld_ord) * elem_lay.stride_bytes;
                    elem_align = @min(agg_lay.alignBytes(), effectiveOffsetAlign(elem_off, elem_lay.alignBytes()));
                } else if (agg_node.tag == .slice_ty or
                    agg_ty == .str_ty or
                    agg_node.tag == .soa_slice_ty or
                    emitter.input.pool.isSliceRefType(agg_ty))
                {
                    elem_off = @as(u64, fld_ord) * emitter.cfg.target.ptrBytes();
                    elem_align = emitter.cfg.target.ptrBytes();
                } else if (try emitter.resolver.getFieldByDeclOrdinal(agg_ty, fld_ord)) |fld| {
                    elem_off = fld.byte_offset;
                    const nat_align = @as(u32, 1) << @intCast(fld.align_log2);
                    elem_align = if (agg_lay.reprFlags().is_packed)
                        1
                    else
                        @min(agg_lay.alignBytes(), effectiveOffsetAlign(fld.byte_offset, nat_align));
                }
                const fld_ptr = if (elem_off == 0)
                    try emitter.allocator.dupe(u8, scratch)
                else blk: {
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  %_aip_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ tmp_id, scratch, ptr_int, elem_off },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_aip_{d}", .{tmp_id});
                };
                defer emitter.allocator.free(fld_ptr);
                const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                defer emitter.allocator.free(elem_ssa);
                try emitStoreValueToPtr(emitter, state, elem_ty, elem_ssa, fld_ptr, elem_align, 0, 0, 0);
            }
            const loaded = try emitLoadValueFromPtr(
                emitter,
                state,
                agg_ty,
                scratch,
                agg_lay.alignBytes(),
                null,
                0,
                0,
                0,
            );
            defer emitter.allocator.free(loaded);
            const agg_val_ty = try formatLlvmValueType(emitter, agg_ty);
            defer emitter.allocator.free(agg_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, agg_val_ty, loaded, agg_val_ty, loaded },
            );
        },

        .bitfield_extract => {
            const spec = hir.BitSpec.fromU32(inst.operands.rhs);
            const src_unwrapped = try unwrapTransparentType(
                emitter,
                body.getInst(MirValueId.fromInt(inst.operands.lhs)).type_id,
            );
            const dst_unwrapped = try unwrapTransparentType(emitter, inst.type_id);
            const tmp_id = state.nextTmp();

            if (!src_unwrapped.isPrimitiveOrSentinel() and emitter.input.pool.getNode(src_unwrapped).tag == .array_ty) {
                const arr_len: u32 = emitter.input.pool.getNode(src_unwrapped).rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                const bit_start: u32 = spec.fullBitOffset();
                const start_byte: u32 = bit_start / 8;
                const end_byte: u32 = @min((bit_start + @as(u32, spec.bit_width) + 7) / 8, arr_len);
                const span_len: usize = if (end_byte > start_byte) @intCast(end_byte - start_byte) else 0;
                const intra_bit: u8 = @intCast(bit_start % 8);
                try state.print("  %_bfea_0_{d} = add i128 0, 0\n", .{tmp_id});
                for (0..span_len) |byte_k| {
                    const byte_idx: u32 = start_byte + @as(u32, @intCast(byte_k));
                    try state.print(
                        "  %_bfeb_{d}_{d} = extractvalue [{d} x i8] %_v_{d}, {d}\n",
                        .{ tmp_id, byte_k, arr_len, inst.operands.lhs, byte_idx },
                    );
                    if (byte_k == 0) {
                        if (intra_bit == 0) {
                            try state.print(
                                "  %_bfez_{d}_{d} = zext i8 %_bfeb_{d}_{d} to i128\n" ++
                                    "  %_bfea_{d}_{d} = or i128 %_bfea_{d}_{d}, %_bfez_{d}_{d}\n",
                                .{ tmp_id, byte_k, tmp_id, byte_k, byte_k + 1, tmp_id, byte_k, tmp_id, tmp_id, byte_k },
                            );
                        } else {
                            try state.print(
                                "  %_bfes_{d}_{d} = lshr i8 %_bfeb_{d}_{d}, {d}\n" ++
                                    "  %_bfez_{d}_{d} = zext i8 %_bfes_{d}_{d} to i128\n" ++
                                    "  %_bfea_{d}_{d} = or i128 %_bfea_{d}_{d}, %_bfez_{d}_{d}\n",
                                .{
                                    tmp_id, byte_k, tmp_id, byte_k, intra_bit,
                                    tmp_id, byte_k, tmp_id, byte_k, byte_k + 1,
                                    tmp_id, byte_k, tmp_id, tmp_id, byte_k,
                                },
                            );
                        }
                    } else {
                        const shift_amt: usize = byte_k * 8 - intra_bit;
                        try state.print(
                            "  %_bfez_{d}_{d} = zext i8 %_bfeb_{d}_{d} to i128\n" ++
                                "  %_bfes_{d}_{d} = shl i128 %_bfez_{d}_{d}, {d}\n" ++
                                "  %_bfea_{d}_{d} = or i128 %_bfea_{d}_{d}, %_bfes_{d}_{d}\n",
                            .{
                                tmp_id, byte_k, tmp_id,    byte_k,     tmp_id, byte_k,
                                tmp_id, byte_k, shift_amt, byte_k + 1, tmp_id, byte_k,
                                tmp_id, tmp_id, byte_k,
                            },
                        );
                    }
                }
                const mask_128: u128 = if (spec.bit_width >= 128)
                    std.math.maxInt(u128)
                else
                    (@as(u128, 1) << @intCast(spec.bit_width)) - 1;
                if (spec.is_signed and spec.bit_width > 0 and spec.bit_width < 128) {
                    const sh_amt: u8 = 128 - spec.bit_width;
                    try state.print(
                        "  %_bfel_{d} = shl i128 %_bfea_{d}_{d}, {d}\n" ++
                            "  %_bfe_r_{d} = ashr i128 %_bfel_{d}, {d}\n",
                        .{ tmp_id, span_len, tmp_id, sh_amt, tmp_id, tmp_id, sh_amt },
                    );
                } else {
                    try state.print(
                        "  %_bfe_r_{d} = and i128 %_bfea_{d}_{d}, {d}\n",
                        .{ tmp_id, span_len, tmp_id, @as(i128, @bitCast(mask_128)) },
                    );
                }
                if (dst_unwrapped == .bool_ty) {
                    try state.print("  %_v_{d} = trunc i128 %_bfe_r_{d} to i1\n", .{ dst_raw, tmp_id });
                } else if (resolveIntegerInfo(emitter, dst_unwrapped)) |dst_info| {
                    if (dst_info.bits == 128) {
                        try state.print("  %_v_{d} = add i128 %_bfe_r_{d}, 0\n", .{ dst_raw, tmp_id });
                    } else {
                        try state.print(
                            "  %_v_{d} = trunc i128 %_bfe_r_{d} to i{d}\n",
                            .{ dst_raw, tmp_id, dst_info.bits },
                        );
                    }
                }
                return;
            }

            const back_bits: u16 = @max(@as(u16, spec.backing_bits), 8);
            if (spec.is_signed) {
                const sh_left: u16 = back_bits -| (@as(u16, spec.bit_offset) + @as(u16, spec.bit_width));
                const sh_right: u16 = back_bits -| @as(u16, spec.bit_width);
                try state.print(
                    "  %_bfe_l_{d} = shl i{d} %_v_{d}, {d}\n" ++
                        "  %_bfe_r_{d} = ashr i{d} %_bfe_l_{d}, {d}\n",
                    .{ tmp_id, back_bits, inst.operands.lhs, sh_left, tmp_id, back_bits, tmp_id, sh_right },
                );
            } else {
                try state.print(
                    "  %_bfe_s_{d} = lshr i{d} %_v_{d}, {d}\n",
                    .{ tmp_id, back_bits, inst.operands.lhs, spec.bit_offset },
                );
                if (spec.bit_width >= back_bits) {
                    try state.print(
                        "  %_bfe_r_{d} = add i{d} %_bfe_s_{d}, 0\n",
                        .{ tmp_id, back_bits, tmp_id },
                    );
                } else if (back_bits == 128) {
                    const mask_128: u128 = (@as(u128, 1) << @intCast(spec.bit_width)) - 1;
                    try state.print(
                        "  %_bfe_r_{d} = and i128 %_bfe_s_{d}, {d}\n",
                        .{ tmp_id, tmp_id, @as(i128, @bitCast(mask_128)) },
                    );
                } else {
                    const mask_u: u64 = (@as(u64, 1) << @intCast(spec.bit_width)) - 1;
                    try state.print(
                        "  %_bfe_r_{d} = and i{d} %_bfe_s_{d}, {d}\n",
                        .{ tmp_id, back_bits, tmp_id, mask_u },
                    );
                }
            }
            if (dst_unwrapped == .bool_ty) {
                try state.print("  %_v_{d} = trunc i{d} %_bfe_r_{d} to i1\n", .{ dst_raw, back_bits, tmp_id });
            } else if (resolveIntegerInfo(emitter, dst_unwrapped)) |dst_info| {
                if (dst_info.bits == back_bits) {
                    try state.print("  %_v_{d} = add i{d} %_bfe_r_{d}, 0\n", .{ dst_raw, back_bits, tmp_id });
                } else if (dst_info.bits < back_bits) {
                    try state.print(
                        "  %_v_{d} = trunc i{d} %_bfe_r_{d} to i{d}\n",
                        .{ dst_raw, back_bits, tmp_id, dst_info.bits },
                    );
                } else {
                    const ext_op = if (spec.is_signed) "sext" else "zext";
                    try state.print(
                        "  %_v_{d} = {s} i{d} %_bfe_r_{d} to i{d}\n",
                        .{ dst_raw, ext_op, back_bits, tmp_id, dst_info.bits },
                    );
                }
            }
        },

        .bitfield_insert => {
            const spec = hir.BitSpec.fromU32(inst.operands.rhs);
            const base_raw = body.extra_args.items[inst.operands.lhs];
            const ins_raw = body.extra_args.items[inst.operands.lhs + 1];
            const ins_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(ins_raw)).type_id);
            const dst_arr_ty = try unwrapTransparentType(emitter, inst.type_id);
            const tmp_id = state.nextTmp();

            if (!dst_arr_ty.isPrimitiveOrSentinel() and emitter.input.pool.getNode(dst_arr_ty).tag == .array_ty) {
                const arr_len: u32 = emitter.input.pool.getNode(dst_arr_ty).rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                if (ins_ty == .bool_ty) {
                    try state.print("  %_bfia_c_{d} = zext i1 %_v_{d} to i128\n", .{ tmp_id, ins_raw });
                } else if (resolveIntegerInfo(emitter, ins_ty)) |ins_info| {
                    if (ins_info.bits == 128) {
                        try state.print("  %_bfia_c_{d} = add i128 %_v_{d}, 0\n", .{ tmp_id, ins_raw });
                    } else {
                        try state.print(
                            "  %_bfia_c_{d} = zext i{d} %_v_{d} to i128\n",
                            .{ tmp_id, ins_info.bits, ins_raw },
                        );
                    }
                } else {
                    try state.print("  %_bfia_c_{d} = add i128 0, 0\n", .{tmp_id});
                }
                const arr_wmask: u128 = if (spec.bit_width >= 128)
                    std.math.maxInt(u128)
                else
                    (@as(u128, 1) << @intCast(spec.bit_width)) - 1;
                try state.print(
                    "  %_bfia_m_{d} = and i128 %_bfia_c_{d}, {d}\n",
                    .{ tmp_id, tmp_id, @as(i128, @bitCast(arr_wmask)) },
                );

                const bit_start: u32 = spec.fullBitOffset();
                const bit_end: u32 = bit_start + @as(u32, spec.bit_width);
                const start_byte: u32 = bit_start / 8;
                const end_byte: u32 = @min((bit_end + 7) / 8, arr_len);
                const span_len: usize = if (end_byte > start_byte) @intCast(end_byte - start_byte) else 0;
                if (span_len == 0) {
                    try state.print("  %_v_{d} = insertvalue [{d} x i8] %_v_{d}, i8 0, 0\n", .{ dst_raw, arr_len, base_raw });
                    return;
                }
                for (0..span_len) |byte_k| {
                    const byte_idx: u32 = start_byte + @as(u32, @intCast(byte_k));
                    const bit_lo: u8 = if (bit_start > byte_idx * 8) @intCast(bit_start - byte_idx * 8) else 0;
                    const bit_hi: u8 = if (bit_end < byte_idx * 8 + 8) @intCast(bit_end - byte_idx * 8) else 8;
                    const byte_mask: u8 = @intCast(((@as(u16, 1) << @intCast(bit_hi - bit_lo)) - 1) << @intCast(bit_lo));
                    const clr_byte_mask: u8 = ~byte_mask;
                    const ins_shift: u32 = (byte_idx * 8 + bit_lo) - bit_start;
                    const prev_agg = if (byte_k == 0)
                        try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{base_raw})
                    else
                        try std.fmt.allocPrint(emitter.allocator, "%_bfia_agg_{d}_{d}", .{ tmp_id, byte_k - 1 });
                    defer emitter.allocator.free(prev_agg);
                    const next_agg = if (byte_k + 1 == span_len)
                        try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{dst_raw})
                    else
                        try std.fmt.allocPrint(emitter.allocator, "%_bfia_agg_{d}_{d}", .{ tmp_id, byte_k });
                    defer emitter.allocator.free(next_agg);

                    try state.print(
                        "  %_bfia_ob_{d}_{d} = extractvalue [{d} x i8] {s}, {d}\n" ++
                            "  %_bfia_cb_{d}_{d} = and i8 %_bfia_ob_{d}_{d}, {d}\n" ++
                            "  %_bfia_sr_{d}_{d} = lshr i128 %_bfia_m_{d}, {d}\n" ++
                            "  %_bfia_tr_{d}_{d} = trunc i128 %_bfia_sr_{d}_{d} to i8\n",
                        .{
                            tmp_id, byte_k, arr_len, prev_agg,  byte_idx,
                            tmp_id, byte_k, tmp_id,  byte_k,    @as(i8, @bitCast(clr_byte_mask)),
                            tmp_id, byte_k, tmp_id,  ins_shift, tmp_id,
                            byte_k, tmp_id, byte_k,
                        },
                    );
                    try state.print(
                        "  %_bfia_sl_{d}_{d} = shl i8 %_bfia_tr_{d}_{d}, {d}\n" ++
                            "  %_bfia_pc_{d}_{d} = and i8 %_bfia_sl_{d}_{d}, {d}\n" ++
                            "  %_bfia_nb_{d}_{d} = or i8 %_bfia_cb_{d}_{d}, %_bfia_pc_{d}_{d}\n" ++
                            "  {s} = insertvalue [{d} x i8] {s}, i8 %_bfia_nb_{d}_{d}, {d}\n",
                        .{
                            tmp_id, byte_k,   tmp_id,  byte_k,   bit_lo,
                            tmp_id, byte_k,   tmp_id,  byte_k,   @as(i8, @bitCast(byte_mask)),
                            tmp_id, byte_k,   tmp_id,  byte_k,   tmp_id,
                            byte_k, next_agg, arr_len, prev_agg, tmp_id,
                            byte_k, byte_idx,
                        },
                    );
                }
                return;
            }

            const back_bits: u16 = @max(@as(u16, spec.backing_bits), 8);

            if (ins_ty == .bool_ty) {
                try state.print("  %_bfi_c_{d} = zext i1 %_v_{d} to i{d}\n", .{ tmp_id, ins_raw, back_bits });
            } else if (resolveIntegerInfo(emitter, ins_ty)) |ins_info| {
                if (ins_info.bits == back_bits) {
                    try state.print("  %_bfi_c_{d} = add i{d} %_v_{d}, 0\n", .{ tmp_id, back_bits, ins_raw });
                } else if (ins_info.bits < back_bits) {
                    try state.print(
                        "  %_bfi_c_{d} = zext i{d} %_v_{d} to i{d}\n",
                        .{ tmp_id, ins_info.bits, ins_raw, back_bits },
                    );
                } else {
                    try state.print(
                        "  %_bfi_c_{d} = trunc i{d} %_v_{d} to i{d}\n",
                        .{ tmp_id, ins_info.bits, ins_raw, back_bits },
                    );
                }
            } else {
                try state.print("  %_bfi_c_{d} = add i{d} 0, 0\n", .{ tmp_id, back_bits });
            }

            if (spec.bit_width >= back_bits) {
                try state.print("  %_v_{d} = add i{d} %_bfi_c_{d}, 0\n", .{ dst_raw, back_bits, tmp_id });
            } else {
                const raw_mask: u128 = (@as(u128, 1) << @intCast(spec.bit_width)) - 1;
                const pos_mask: u128 = raw_mask << @intCast(spec.bit_offset);
                const full_mask: u128 = if (back_bits == 128)
                    std.math.maxInt(u128)
                else
                    (@as(u128, 1) << @intCast(back_bits)) - 1;
                const clr_mask: u128 = full_mask ^ pos_mask;
                try state.print(
                    "  %_bfi_m_{d} = and i{d} %_bfi_c_{d}, {d}\n" ++
                        "  %_bfi_s_{d} = shl i{d} %_bfi_m_{d}, {d}\n" ++
                        "  %_bfi_b_{d} = and i{d} %_v_{d}, {d}\n" ++
                        "  %_v_{d} = or i{d} %_bfi_b_{d}, %_bfi_s_{d}\n",
                    .{
                        tmp_id,
                        back_bits,
                        tmp_id,
                        @as(i128, @bitCast(raw_mask)),
                        tmp_id,
                        back_bits,
                        tmp_id,
                        spec.bit_offset,
                        tmp_id,
                        back_bits,
                        base_raw,
                        @as(i128, @bitCast(clr_mask)),
                        dst_raw,
                        back_bits,
                        tmp_id,
                        tmp_id,
                    },
                );
            }
        },

        .fn_addr => {
            const def_id = DefId.fromInt(inst.operands.lhs);
            const sym_idx = SymbolIndex.fromInt(inst.operands.rhs);
            if (resolveBodyIndex(emitter, def_id, sym_idx)) |target_b| {
                const fn_name = emitter.body_llvm_names.items[target_b];
                if (emitter.ctx_wrap_map.contains(target_b) and
                    isFnAddrCtxWrapperNeeded(emitter, target_b, inst.type_id) and
                    isFnAddrUsedAsValue(body, dst_raw))
                {
                    try state.print(
                        "  %_v_{d} = select i1 true, ptr @_cx_fn_ctxwrap_{d}, ptr @_cx_fn_ctxwrap_{d}\n",
                        .{ dst_raw, target_b, target_b },
                    );
                } else if (emitter.input.is_dev_got_enabled) {
                    const got_len = @max(emitter.input.bodies.len, 1);
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  %_fngp_{d} = getelementptr inbounds [{d} x ptr], ptr @_cx_dev_got, {s} 0, {s} {d}\n" ++
                            "  %_v_{d} = load ptr, ptr %_fngp_{d}, align {d}\n",
                        .{
                            tmp_id,
                            got_len,
                            ptr_int,
                            ptr_int,
                            target_b,
                            dst_raw,
                            tmp_id,
                            emitter.cfg.target.ptrBytes(),
                        },
                    );
                } else {
                    const fn_ident = try formatLlvmGlobalIdent(emitter.allocator, fn_name);
                    defer emitter.allocator.free(fn_ident);
                    try state.print(
                        "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                        .{ dst_raw, fn_ident, fn_ident },
                    );
                }
            } else if (!sym_idx.isNone() and sym_idx.asInt() < emitter.input.sym_table.symbols.items.len) {
                const sym_rec = emitter.input.sym_table.getSymbol(sym_idx).*;
                if (sym_rec.kind == .const_sym) {
                    const resolved_def = if (!def_id.isNone()) def_id else sym_rec.def_id;
                    if (emitter.input.const_rodata_map) |crm| {
                        if (crm.get(resolved_def.asInt())) |r_idx| {
                            const sym_ty = try unwrapTransparentType(emitter, sym_rec.type_id);
                            const inst_ty = try unwrapTransparentType(emitter, inst.type_id);
                            const inst_node = emitter.input.pool.getNode(inst_ty);
                            const is_addr_of_sym = (inst_node.tag == .ref_ty or inst_node.tag == .mut_ref_ty) and
                                (try unwrapTransparentType(emitter, TypeId.fromInt(inst_node.lhs))) == sym_ty;
                            if (!is_addr_of_sym) {
                                if (try isZeroSizedType(emitter, inst.type_id)) {
                                    try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                                } else {
                                    const ro_ident = try std.fmt.allocPrint(emitter.allocator, "@_cx_rodata_{d}", .{r_idx});
                                    defer emitter.allocator.free(ro_ident);
                                    const glob_lay = try emitter.resolver.resolveType(sym_ty);
                                    const loaded_s = try emitLoadValueFromPtr(
                                        emitter,
                                        state,
                                        inst.type_id,
                                        ro_ident,
                                        glob_lay.alignBytes(),
                                        null,
                                        0,
                                        0,
                                        0,
                                    );
                                    defer emitter.allocator.free(loaded_s);
                                    const val_ty = try formatLlvmValueType(emitter, inst.type_id);
                                    defer emitter.allocator.free(val_ty);
                                    try state.print(
                                        "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                                        .{ dst_raw, val_ty, loaded_s, val_ty, loaded_s },
                                    );
                                }
                            } else {
                                try state.print(
                                    "  %_v_{d} = select i1 true, ptr @_cx_rodata_{d}, ptr @_cx_rodata_{d}\n",
                                    .{ dst_raw, r_idx, r_idx },
                                );
                            }
                            return;
                        }
                    }
                }
                const ffi_meta = extractSymFfiMetaLlvm(emitter, sym_idx);
                const ext_name = if (ffi_meta.link_name.len > 0) ffi_meta.link_name else sym_rec.name_text;
                const ext_ident = try formatLlvmGlobalIdent(emitter.allocator, ext_name);
                defer emitter.allocator.free(ext_ident);
                if (emitter.extern_global_sym_set.contains(sym_idx.asInt())) {
                    const sym_ty = try unwrapTransparentType(emitter, sym_rec.type_id);
                    const inst_ty = try unwrapTransparentType(emitter, inst.type_id);
                    const inst_node = emitter.input.pool.getNode(inst_ty);
                    const is_addr_of_sym = (inst_node.tag == .ref_ty or inst_node.tag == .mut_ref_ty) and
                        (try unwrapTransparentType(emitter, TypeId.fromInt(inst_node.lhs))) == sym_ty;
                    if (!is_addr_of_sym) {
                        if (try isZeroSizedType(emitter, inst.type_id)) {
                            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                        } else {
                            const glob_lay = try emitter.resolver.resolveType(sym_ty);
                            const loaded_s = try emitLoadValueFromPtr(
                                emitter,
                                state,
                                inst.type_id,
                                ext_ident,
                                glob_lay.alignBytes(),
                                null,
                                0,
                                0,
                                0,
                            );
                            defer emitter.allocator.free(loaded_s);
                            const val_ty = try formatLlvmValueType(emitter, inst.type_id);
                            defer emitter.allocator.free(val_ty);
                            try state.print(
                                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                                .{ dst_raw, val_ty, loaded_s, val_ty, loaded_s },
                            );
                        }
                    } else {
                        try state.print(
                            "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                            .{ dst_raw, ext_ident, ext_ident },
                        );
                    }
                } else {
                    try state.print(
                        "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                        .{ dst_raw, ext_ident, ext_ident },
                    );
                }
            } else {
                try state.print(
                    "  %_v_{d} = select i1 true, ptr inttoptr ({s} 1 to ptr), ptr null\n",
                    .{ dst_raw, ptr_int },
                );
            }
        },

        .place_load => {
            if (try isZeroSizedType(emitter, inst.type_id)) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const place_id = PlaceId.fromInt(inst.operands.lhs);
            const eff_access_grp = if (body.getPlaceProjections(place_id).len > 0) access_grp else 0;
            const lowered = try lowerPlaceLlvm(emitter, state, body, place_id);
            switch (lowered) {
                .const_len => |cl| {
                    const dst_info = resolveIntegerInfo(emitter, inst.type_id) orelse IntScalarInfo{
                        .bits = @as(u16, emitter.cfg.target.ptrBytes()) * 8,
                        .is_signed = false,
                    };
                    try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, cl.elem_count });
                },
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    const mvs = lookupMvsScopeForLocal(state, av.root_param_local);
                    const prov_r = lookupProvenRange(emitter, body_idx, dst_raw);
                    const loaded = try emitLoadValueFromPtr(
                        emitter,
                        state,
                        inst.type_id,
                        av.ptr_str,
                        av.align_bytes,
                        prov_r,
                        mvs.scope_md,
                        mvs.noalias_md,
                        eff_access_grp,
                    );
                    defer emitter.allocator.free(loaded);
                    const val_ty = try formatLlvmValueType(emitter, inst.type_id);
                    defer emitter.allocator.free(val_ty);
                    try state.print(
                        "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                        .{ dst_raw, val_ty, loaded, val_ty, loaded },
                    );
                    if (std.mem.eql(u8, val_ty, "ptr")) {
                        if (prov_r) |p_rng| {
                            const dst_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{dst_raw});
                            defer emitter.allocator.free(dst_ssa);
                            try maybeEmitPointerAssume(emitter, state, dst_ssa, p_rng);
                        }
                    }
                },
            }
        },

        .place_store => {
            const val_raw = inst.operands.rhs;
            const val_ty = body.getInst(MirValueId.fromInt(val_raw)).type_id;
            const place_id = PlaceId.fromInt(inst.operands.lhs);
            const eff_access_grp = if (body.getPlaceProjections(place_id).len > 0) access_grp else 0;
            const lowered = try lowerPlaceLlvm(emitter, state, body, place_id);
            switch (lowered) {
                .const_len => {},
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    const mvs = lookupMvsScopeForLocal(state, av.root_param_local);
                    const val_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{val_raw});
                    defer emitter.allocator.free(val_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        val_ty,
                        val_ssa,
                        av.ptr_str,
                        av.align_bytes,
                        mvs.scope_md,
                        mvs.noalias_md,
                        eff_access_grp,
                    );
                },
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .place_discriminant => {
            const lowered = try lowerPlaceLlvm(emitter, state, body, PlaceId.fromInt(inst.operands.lhs));
            switch (lowered) {
                .const_len => try state.print("  %_v_{d} = add i32 0, 0\n", .{dst_raw}),
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    const disc_32 = try emitReadSumDiscriminantFromPtr(
                        emitter,
                        state,
                        av.pointee_ty,
                        av.ptr_str,
                        av.align_bytes,
                    );
                    defer emitter.allocator.free(disc_32);
                    const dst_info = resolveIntegerInfo(emitter, inst.type_id) orelse
                        IntScalarInfo{ .bits = 32, .is_signed = false };
                    if (dst_info.bits == 32) {
                        try state.print("  %_v_{d} = add i32 {s}, 0\n", .{ dst_raw, disc_32 });
                    } else if (dst_info.bits < 32) {
                        try state.print(
                            "  %_v_{d} = trunc i32 {s} to i{d}\n",
                            .{ dst_raw, disc_32, dst_info.bits },
                        );
                    } else {
                        try state.print(
                            "  %_v_{d} = zext i32 {s} to i{d}\n",
                            .{ dst_raw, disc_32, dst_info.bits },
                        );
                    }
                },
            }
        },

        .place_set_discrim => {
            const lowered = try lowerPlaceLlvm(emitter, state, body, PlaceId.fromInt(inst.operands.lhs));
            switch (lowered) {
                .const_len => {},
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    try emitWriteSumDiscriminantToPtr(
                        emitter,
                        state,
                        av.pointee_ty,
                        av.ptr_str,
                        av.align_bytes,
                        inst.operands.rhs,
                    );
                },
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .place_addr => {
            const lowered = try lowerPlaceLlvm(emitter, state, body, PlaceId.fromInt(inst.operands.lhs));
            switch (lowered) {
                .const_len => |cl| {
                    try state.print(
                        "  %_v_{d} = select i1 true, ptr inttoptr ({s} {d} to ptr), ptr null\n",
                        .{ dst_raw, ptr_int, @max(cl.elem_count, 1) },
                    );
                },
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    const dst_unwrapped = try unwrapTransparentType(emitter, inst.type_id);
                    const dst_node = emitter.input.pool.getNode(dst_unwrapped);
                    const src_node = emitter.input.pool.getNode(av.pointee_ty);

                    const is_dst_slice_ref = (dst_node.tag == .ref_ty or
                        dst_node.tag == .mut_ref_ty or
                        dst_node.tag == .raw_ptr_ty) and
                        !emitter.input.pool.isSliceRefType(dst_unwrapped) and blk: {
                        const dp = try unwrapTransparentType(emitter, TypeId.fromInt(dst_node.lhs));
                        if (dp == .str_ty or emitter.input.pool.isSliceRefType(dp)) break :blk true;
                        if (dp.isPrimitiveOrSentinel()) break :blk false;
                        const dpn = emitter.input.pool.getNode(dp);
                        break :blk dpn.tag == .slice_ty or dpn.tag == .soa_slice_ty;
                    };
                    const is_dst_fat_slice = dst_node.tag == .slice_ty or
                        dst_node.tag == .soa_slice_ty or
                        emitter.input.pool.isSliceRefType(dst_unwrapped);

                    // Coercion `&[T; N]` / `&mut [T; N]` / `&*s` -> fat slice `[T]` or `&[T]`:
                    if (is_dst_fat_slice and
                        (src_node.tag == .array_ty or src_node.tag == .soa_array_ty))
                    {
                        const cap: u64 = src_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                        const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(src_node.lhs));
                        const elem_lay = try emitter.resolver.resolveType(elem_ty);
                        const data_ptr_s = if (cap == 0)
                            try std.fmt.allocPrint(
                                emitter.allocator,
                                "inttoptr ({s} {d} to ptr)",
                                .{ ptr_int, @max(elem_lay.alignBytes(), 1) },
                            )
                        else
                            try emitter.allocator.dupe(u8, av.ptr_str);
                        defer emitter.allocator.free(data_ptr_s);
                        const tmp_id = state.nextTmp();
                        const dst_sl_ty = try formatSliceLlvmStructType(emitter, dst_unwrapped);
                        defer emitter.allocator.free(dst_sl_ty);
                        if (emitter.input.pool.isSoaSliceOrRefType(dst_unwrapped)) {
                            try state.print(
                                "  %_paf0_{d} = insertvalue {s} zeroinitializer, ptr {s}, 0\n" ++
                                    "  %_paf1_{d} = insertvalue {s} %_paf0_{d}, {s} {d}, 1\n" ++
                                    "  %_paf2_{d} = insertvalue {s} %_paf1_{d}, {s} {d}, 2\n" ++
                                    "  %_v_{d} = insertvalue {s} %_paf2_{d}, {s} 0, 3\n",
                                .{
                                    tmp_id,    dst_sl_ty, data_ptr_s,
                                    tmp_id,    dst_sl_ty, tmp_id,
                                    ptr_int,   cap,       tmp_id,
                                    dst_sl_ty, tmp_id,    ptr_int,
                                    cap,       dst_raw,   dst_sl_ty,
                                    tmp_id,    ptr_int,
                                },
                            );
                        } else {
                            try state.print(
                                "  %_paf_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr {s}, 0\n" ++
                                    "  %_v_{d} = insertvalue {{ ptr, {s} }} %_paf_{d}, {s} {d}, 1\n",
                                .{ tmp_id, ptr_int, data_ptr_s, dst_raw, ptr_int, tmp_id, ptr_int, cap },
                            );
                        }
                    } else if (is_dst_fat_slice and
                        (src_node.tag == .slice_ty or src_node.tag == .soa_slice_ty))
                    {
                        const hdr_align = @min(@max(av.align_bytes, 1), emitter.cfg.target.ptrBytes());
                        const dst_sl_ty = try formatSliceLlvmStructType(emitter, dst_unwrapped);
                        defer emitter.allocator.free(dst_sl_ty);
                        try state.print(
                            "  %_v_{d} = load {s}, ptr {s}, align {d}\n",
                            .{ dst_raw, dst_sl_ty, av.ptr_str, hdr_align },
                        );
                    } else if (is_dst_slice_ref and
                        (src_node.tag == .array_ty or src_node.tag == .soa_array_ty))
                    {
                        const ptr_bytes = emitter.cfg.target.ptrBytes();
                        const cap: u64 = src_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                        const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(src_node.lhs));
                        const elem_lay = try emitter.resolver.resolveType(elem_ty);
                        const data_ptr_s = if (cap == 0)
                            try std.fmt.allocPrint(
                                emitter.allocator,
                                "inttoptr ({s} {d} to ptr)",
                                .{ ptr_int, @max(elem_lay.alignBytes(), 1) },
                            )
                        else
                            try emitter.allocator.dupe(u8, av.ptr_str);
                        defer emitter.allocator.free(data_ptr_s);
                        const dst_pt = try unwrapTransparentType(emitter, TypeId.fromInt(dst_node.lhs));
                        const words = sliceDescriptorWordCount(emitter.input.pool, dst_pt);
                        const fat_slot = try state.allocEntryBytes(words * ptr_bytes, ptr_bytes);
                        defer emitter.allocator.free(fat_slot);
                        try emitMemsetZero(emitter, state, fat_slot, words * ptr_bytes, ptr_bytes);
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  store ptr {s}, ptr {s}, align {d}\n" ++
                                "  %_pas_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                                "  store {s} {d}, ptr %_pas_{d}, align {d}\n",
                            .{
                                data_ptr_s,
                                fat_slot,
                                ptr_bytes,
                                tmp_id,
                                fat_slot,
                                ptr_int,
                                ptr_bytes,
                                ptr_int,
                                cap,
                                tmp_id,
                                ptr_bytes,
                            },
                        );
                        if (words == 4) {
                            try state.print(
                                "  %_pass_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                                    "  store {s} {d}, ptr %_pass_{d}, align {d}\n",
                                .{ tmp_id, fat_slot, ptr_int, ptr_bytes * 2, ptr_int, cap, tmp_id, ptr_bytes },
                            );
                        }
                        try state.print(
                            "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                            .{ dst_raw, fat_slot, fat_slot },
                        );
                    } else {
                        try state.print(
                            "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                            .{ dst_raw, av.ptr_str, av.ptr_str },
                        );
                        if (lookupProvenRange(emitter, body_idx, dst_raw)) |prov_r| {
                            var clamped_r = prov_r;
                            const place_log2: u8 = if (av.align_bytes > 1)
                                std.math.log2_int(u32, av.align_bytes)
                            else
                                0;
                            clamped_r.proven_align_log2 = @min(clamped_r.proven_align_log2, place_log2);
                            const dst_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{dst_raw});
                            defer emitter.allocator.free(dst_ssa);
                            try maybeEmitPointerAssume(emitter, state, dst_ssa, clamped_r);
                        }
                    }
                },
            }
        },

        .soa_column_slice => {
            const field_ord = inst.operands.rhs;
            const lowered = try lowerPlaceLlvm(emitter, state, body, PlaceId.fromInt(inst.operands.lhs));
            switch (lowered) {
                .const_len => {},
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    const unwrapped_src = if (emitter.input.pool.getSliceRefInner(av.pointee_ty)) |inner_sl|
                        try unwrapTransparentType(emitter, inner_sl)
                    else
                        try unwrapTransparentType(emitter, av.pointee_ty);
                    const src_node = emitter.input.pool.getNode(unwrapped_src);
                    const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(src_node.lhs));
                    const fld = (try emitter.resolver.getFieldByDeclOrdinal(elem_struct, field_ord)).?;
                    const fld_align: u32 = @as(u32, 1) << @intCast(fld.align_log2);
                    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
                    const hdr_align = @min(@max(av.align_bytes, 1), ptr_bytes);

                    if (src_node.tag == .soa_array_ty) {
                        const cap: u64 = src_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                        const col_info = emitter.resolver.getSoaColumnOffset(elem_struct, field_ord, cap).?;
                        const tmp_id = state.nextTmp();
                        if (cap == 0) {
                            try state.print(
                                "  %_scs0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr inttoptr ({s} {d} to ptr), 0\n" ++
                                    "  %_v_{d} = insertvalue {{ ptr, {s} }} %_scs0_{d}, {s} 0, 1\n",
                                .{ tmp_id, ptr_int, ptr_int, @max(fld_align, 1), dst_raw, ptr_int, tmp_id, ptr_int },
                            );
                        } else {
                            try state.print(
                                "  %_scsp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                                    "  %_scs0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %_scsp_{d}, 0\n" ++
                                    "  %_v_{d} = insertvalue {{ ptr, {s} }} %_scs0_{d}, {s} {d}, 1\n",
                                .{
                                    tmp_id,  av.ptr_str, ptr_int, col_info.byte_offset,
                                    tmp_id,  ptr_int,    tmp_id,  dst_raw,
                                    ptr_int, tmp_id,     ptr_int, cap,
                                },
                            );
                        }
                    } else if (src_node.tag == .soa_vec_ty) {
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  %_scsd_{d} = load ptr, ptr {s}, align {d}\n" ++
                                "  %_scslp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                                "  %_scsl32_{d} = load i32, ptr %_scslp_{d}, align {d}\n" ++
                                "  %_scscp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                                "  %_scsc32_{d} = load i32, ptr %_scscp_{d}, align {d}\n",
                            .{
                                tmp_id,             av.ptr_str,         hdr_align,
                                tmp_id,             av.ptr_str,         ptr_int,
                                ptr_bytes,          tmp_id,             tmp_id,
                                @min(hdr_align, 4), tmp_id,             av.ptr_str,
                                ptr_int,            ptr_bytes + 4,      tmp_id,
                                tmp_id,             @min(hdr_align, 4),
                            },
                        );
                        if (ptr_bytes == 4) {
                            try state.print(
                                "  %_scsl_{d} = add i32 %_scsl32_{d}, 0\n  %_scsc_{d} = add i32 %_scsc32_{d}, 0\n",
                                .{ tmp_id, tmp_id, tmp_id, tmp_id },
                            );
                        } else {
                            try state.print(
                                "  %_scsl_{d} = zext i32 %_scsl32_{d} to i64\n  %_scsc_{d} = zext i32 %_scsc32_{d} to i64\n",
                                .{ tmp_id, tmp_id, tmp_id, tmp_id },
                            );
                        }
                        const cap_s = try std.fmt.allocPrint(emitter.allocator, "%_scsc_{d}", .{tmp_id});
                        defer emitter.allocator.free(cap_s);
                        const dyn_col = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, field_ord, cap_s);
                        defer emitter.allocator.free(dyn_col.off_ssa);
                        try state.print(
                            "  %_scsp_{d} = getelementptr inbounds i8, ptr %_scsd_{d}, {s} {s}\n" ++
                                "  %_scsz_{d} = icmp eq {s} %_scsl_{d}, 0\n" ++
                                "  %_scsn_{d} = icmp eq ptr %_scsd_{d}, null\n" ++
                                "  %_scse_{d} = or i1 %_scsz_{d}, %_scsn_{d}\n" ++
                                "  %_scsnn_{d} = select i1 %_scse_{d}, ptr inttoptr ({s} {d} to ptr), ptr %_scsp_{d}\n" ++
                                "  %_scs0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %_scsnn_{d}, 0\n" ++
                                "  %_v_{d} = insertvalue {{ ptr, {s} }} %_scs0_{d}, {s} %_scsl_{d}, 1\n",
                            .{
                                tmp_id,  tmp_id,  ptr_int, dyn_col.off_ssa,
                                tmp_id,  ptr_int, tmp_id,  tmp_id,
                                tmp_id,  tmp_id,  tmp_id,  tmp_id,
                                tmp_id,  tmp_id,  ptr_int, @max(fld_align, 1),
                                tmp_id,  tmp_id,  ptr_int, tmp_id,
                                dst_raw, ptr_int, tmp_id,  ptr_int,
                                tmp_id,
                            },
                        );
                    } else {
                        const tmp_id = state.nextTmp();
                        const soa_sl_ty = try std.fmt.allocPrint(
                            emitter.allocator,
                            "{{ ptr, {s}, {s}, {s} }}",
                            .{ ptr_int, ptr_int, ptr_int },
                        );
                        defer emitter.allocator.free(soa_sl_ty);
                        try state.print(
                            "  %_scsf_{d} = load {s}, ptr {s}, align {d}\n" ++
                                "  %_scsd_{d} = extractvalue {s} %_scsf_{d}, 0\n" ++
                                "  %_scsl_{d} = extractvalue {s} %_scsf_{d}, 1\n" ++
                                "  %_scsst_{d} = extractvalue {s} %_scsf_{d}, 2\n" ++
                                "  %_scseo_{d} = extractvalue {s} %_scsf_{d}, 3\n",
                            .{
                                tmp_id,    soa_sl_ty, av.ptr_str, hdr_align,
                                tmp_id,    soa_sl_ty, tmp_id,     tmp_id,
                                soa_sl_ty, tmp_id,    tmp_id,     soa_sl_ty,
                                tmp_id,    tmp_id,    soa_sl_ty,  tmp_id,
                            },
                        );
                        const stride_s = try std.fmt.allocPrint(emitter.allocator, "%_scsst_{d}", .{tmp_id});
                        defer emitter.allocator.free(stride_s);
                        const dyn_col = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, field_ord, stride_s);
                        defer emitter.allocator.free(dyn_col.off_ssa);
                        try state.print(
                            "  %_scsem_{d} = mul {s} %_scseo_{d}, {d}\n" ++
                                "  %_scsbo_{d} = add {s} {s}, %_scsem_{d}\n" ++
                                "  %_scsp_{d} = getelementptr inbounds i8, ptr %_scsd_{d}, {s} %_scsbo_{d}\n" ++
                                "  %_scsz_{d} = icmp eq {s} %_scsl_{d}, 0\n" ++
                                "  %_scsn_{d} = icmp eq ptr %_scsd_{d}, null\n",
                            .{
                                tmp_id, ptr_int, tmp_id,          fld.size_bytes,
                                tmp_id, ptr_int, dyn_col.off_ssa, tmp_id,
                                tmp_id, tmp_id,  ptr_int,         tmp_id,
                                tmp_id, ptr_int, tmp_id,          tmp_id,
                                tmp_id,
                            },
                        );
                        try state.print(
                            "  %_scse_{d} = or i1 %_scsz_{d}, %_scsn_{d}\n" ++
                                "  %_scsnn_{d} = select i1 %_scse_{d}, ptr inttoptr ({s} {d} to ptr), ptr %_scsp_{d}\n" ++
                                "  %_scs0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %_scsnn_{d}, 0\n" ++
                                "  %_v_{d} = insertvalue {{ ptr, {s} }} %_scs0_{d}, {s} %_scsl_{d}, 1\n",
                            .{
                                tmp_id,             tmp_id, tmp_id,
                                tmp_id,             tmp_id, ptr_int,
                                @max(fld_align, 1), tmp_id, tmp_id,
                                ptr_int,            tmp_id, dst_raw,
                                ptr_int,            tmp_id, ptr_int,
                                tmp_id,
                            },
                        );
                    }
                },
            }
        },

        .intrinsic_op => {
            const ikind: mir.MirIntrinsicKind = @fromBackingInt(@intCast(inst.aux_u16));
            try emitIntrinsicOpLlvm(emitter, state, body, bb_idx, dst_raw, ikind, inst);
        },
    }
}

/// Emits an element-by-element structural equality loop (`i1`) over `count_ssa` items of `elem_ty`.
fn emitStructuralSpanLoopEqLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    elem_ty: TypeId,
    base_l_ptr: []const u8,
    base_r_ptr: []const u8,
    count_ssa: []const u8,
    depth: u32,
) anyerror![]u8 {
    if (try isZeroSizedType(emitter, elem_ty)) return emitter.allocator.dupe(u8, "true");
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes = emitter.cfg.target.ptrBytes();
    const elem_lay = try emitter.resolver.resolveType(elem_ty);

    const idx_slot = try state.allocEntryBytes(ptr_bytes, ptr_bytes);
    defer emitter.allocator.free(idx_slot);
    const res_slot = try state.allocEntryBytes(1, 1);
    defer emitter.allocator.free(res_slot);

    const tmp_id = state.nextTmp();
    try state.print(
        "  store {s} 0, ptr {s}, align {d}\n" ++
            "  store i8 1, ptr {s}, align 1\n" ++
            "  br label %_lpeq_hdr_{d}\n" ++
            "_lpeq_hdr_{d}:\n" ++
            "  %_lpeq_i_{d} = load {s}, ptr {s}, align {d}\n" ++
            "  %_lpeq_c_{d} = icmp ult {s} %_lpeq_i_{d}, {s}\n" ++
            "  br i1 %_lpeq_c_{d}, label %_lpeq_bd_{d}, label %_lpeq_dn_{d}\n" ++
            "_lpeq_bd_{d}:\n" ++
            "  %_lpeq_bo_{d} = mul {s} %_lpeq_i_{d}, {d}\n" ++
            "  %_lpeq_lp_{d} = getelementptr inbounds i8, ptr {s}, {s} %_lpeq_bo_{d}\n" ++
            "  %_lpeq_rp_{d} = getelementptr inbounds i8, ptr {s}, {s} %_lpeq_bo_{d}\n",
        .{
            ptr_int,               idx_slot,  ptr_bytes,
            res_slot,              tmp_id,    tmp_id,
            tmp_id,                ptr_int,   idx_slot,
            ptr_bytes,             tmp_id,    ptr_int,
            tmp_id,                count_ssa, tmp_id,
            tmp_id,                tmp_id,    tmp_id,
            tmp_id,                ptr_int,   tmp_id,
            elem_lay.stride_bytes, tmp_id,    base_l_ptr,
            ptr_int,               tmp_id,    tmp_id,
            base_r_ptr,            ptr_int,   tmp_id,
        },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_lpeq_bd_{d}", .{tmp_id}));

    const lp_s = try std.fmt.allocPrint(emitter.allocator, "%_lpeq_lp_{d}", .{tmp_id});
    defer emitter.allocator.free(lp_s);
    const rp_s = try std.fmt.allocPrint(emitter.allocator, "%_lpeq_rp_{d}", .{tmp_id});
    defer emitter.allocator.free(rp_s);
    const el_eq = try emitStructuralPtrEqLlvm(emitter, state, elem_ty, lp_s, rp_s, depth + 1);
    defer emitter.allocator.free(el_eq);

    try state.print(
        "  br i1 {s}, label %_lpeq_nx_{d}, label %_lpeq_fl_{d}\n" ++
            "_lpeq_fl_{d}:\n" ++
            "  store i8 0, ptr {s}, align 1\n" ++
            "  br label %_lpeq_dn_{d}\n" ++
            "_lpeq_nx_{d}:\n" ++
            "  %_lpeq_ni_{d} = add {s} %_lpeq_i_{d}, 1\n" ++
            "  store {s} %_lpeq_ni_{d}, ptr {s}, align {d}\n" ++
            "  br label %_lpeq_hdr_{d}\n" ++
            "_lpeq_dn_{d}:\n" ++
            "  %_lpeq_ld_{d} = load i8, ptr {s}, align 1\n" ++
            "  %_lpeq_rs_{d} = trunc i8 %_lpeq_ld_{d} to i1\n",
        .{
            el_eq,    tmp_id,    tmp_id,
            tmp_id,   res_slot,  tmp_id,
            tmp_id,   tmp_id,    ptr_int,
            tmp_id,   ptr_int,   tmp_id,
            idx_slot, ptr_bytes, tmp_id,
            tmp_id,   tmp_id,    res_slot,
            tmp_id,   tmp_id,
        },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_lpeq_dn_{d}", .{tmp_id}));
    return std.fmt.allocPrint(emitter.allocator, "%_lpeq_rs_{d}", .{tmp_id});
}

/// Emits UB-free, niche-aware structural equality (`i1`) comparing `raw_ty` at `(lhs_ptr, rhs_ptr)`.
fn emitStructuralPtrEqLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    raw_ty: TypeId,
    lhs_ptr: []const u8,
    rhs_ptr: []const u8,
    depth: u32,
) anyerror![]u8 {
    if (depth > 16) return emitter.allocator.dupe(u8, "false");
    const ty = try unwrapTransparentType(emitter, raw_ty);
    if (try isZeroSizedType(emitter, ty)) return emitter.allocator.dupe(u8, "true");
    const ptr_int = ptrIntType(emitter);

    if (ty == .bool_ty) {
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_peqb_l_{d} = load i8, ptr {s}, align 1\n" ++
                "  %_peqb_r_{d} = load i8, ptr {s}, align 1\n" ++
                "  %_peqb_lm_{d} = and i8 %_peqb_l_{d}, 1\n" ++
                "  %_peqb_rm_{d} = and i8 %_peqb_r_{d}, 1\n" ++
                "  %_peqb_eq_{d} = icmp eq i8 %_peqb_lm_{d}, %_peqb_rm_{d}\n",
            .{
                tmp_id, lhs_ptr,
                tmp_id, rhs_ptr,
                tmp_id, tmp_id,
                tmp_id, tmp_id,
                tmp_id, tmp_id,
                tmp_id,
            },
        );
        return std.fmt.allocPrint(emitter.allocator, "%_peqb_eq_{d}", .{tmp_id});
    }

    if (ty == .str_ty) {
        if (!emitter.declared_externs.contains("memcmp")) {
            try emitter.requireIntrinsicDecl(
                if (emitter.cfg.target.isWasm())
                    "declare i32 @memcmp(ptr, ptr, i32) nounwind"
                else
                    "declare i32 @memcmp(ptr, ptr, i64) nounwind",
            );
        }
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_peqs_l_{d} = load {{ ptr, {s} }}, ptr {s}, align 1\n" ++
                "  %_peqs_r_{d} = load {{ ptr, {s} }}, ptr {s}, align 1\n" ++
                "  %_peqs_lp_{d} = extractvalue {{ ptr, {s} }} %_peqs_l_{d}, 0\n" ++
                "  %_peqs_ll_{d} = extractvalue {{ ptr, {s} }} %_peqs_l_{d}, 1\n" ++
                "  %_peqs_rp_{d} = extractvalue {{ ptr, {s} }} %_peqs_r_{d}, 0\n" ++
                "  %_peqs_rl_{d} = extractvalue {{ ptr, {s} }} %_peqs_r_{d}, 1\n" ++
                "  %_peqs_ln_{d} = icmp eq {s} %_peqs_ll_{d}, %_peqs_rl_{d}\n" ++
                "  br i1 %_peqs_ln_{d}, label %_peqs_cz_{d}, label %_peqs_fl_{d}\n",
            .{
                tmp_id, ptr_int, lhs_ptr,
                tmp_id, ptr_int, rhs_ptr,
                tmp_id, ptr_int, tmp_id,
                tmp_id, ptr_int, tmp_id,
                tmp_id, ptr_int, tmp_id,
                tmp_id, ptr_int, tmp_id,
                tmp_id, ptr_int, tmp_id,
                tmp_id, tmp_id,  tmp_id,
                tmp_id,
            },
        );
        try state.print(
            "_peqs_cz_{d}:\n" ++
                "  %_peqs_iz_{d} = icmp eq {s} %_peqs_ll_{d}, 0\n" ++
                "  br i1 %_peqs_iz_{d}, label %_peqs_tr_{d}, label %_peqs_mc_{d}\n" ++
                "_peqs_mc_{d}:\n" ++
                "  %_peqs_mv_{d} = call i32 @memcmp(ptr %_peqs_lp_{d}, ptr %_peqs_rp_{d}, {s} %_peqs_ll_{d})\n" ++
                "  %_peqs_m0_{d} = icmp eq i32 %_peqs_mv_{d}, 0\n" ++
                "  br label %_peqs_jn_{d}\n" ++
                "_peqs_tr_{d}:\n  br label %_peqs_jn_{d}\n" ++
                "_peqs_fl_{d}:\n  br label %_peqs_jn_{d}\n" ++
                "_peqs_jn_{d}:\n" ++
                "  %_peqs_eq_{d} = phi i1 [ %_peqs_m0_{d}, %_peqs_mc_{d} ], " ++
                "[ true, %_peqs_tr_{d} ], [ false, %_peqs_fl_{d} ]\n",
            .{
                tmp_id,
                tmp_id,
                ptr_int,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                ptr_int,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
            },
        );
        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqs_jn_{d}", .{tmp_id}));
        return std.fmt.allocPrint(emitter.allocator, "%_peqs_eq_{d}", .{tmp_id});
    }

    if (ty == .f32_ty or ty == .f64_ty or ty == .untyped_float_ty) {
        const flt_ty = if (ty == .f32_ty) "float" else "double";
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_peqf_l_{d} = load {s}, ptr {s}, align 1\n" ++
                "  %_peqf_r_{d} = load {s}, ptr {s}, align 1\n" ++
                "  %_peqf_eq_{d} = fcmp oeq {s} %_peqf_l_{d}, %_peqf_r_{d}\n",
            .{ tmp_id, flt_ty, lhs_ptr, tmp_id, flt_ty, rhs_ptr, tmp_id, flt_ty, tmp_id, tmp_id },
        );
        return std.fmt.allocPrint(emitter.allocator, "%_peqf_eq_{d}", .{tmp_id});
    }

    if (resolveIntegerInfo(emitter, ty)) |int_info| {
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_peqi_l_{d} = load i{d}, ptr {s}, align 1\n" ++
                "  %_peqi_r_{d} = load i{d}, ptr {s}, align 1\n" ++
                "  %_peqi_eq_{d} = icmp eq i{d} %_peqi_l_{d}, %_peqi_r_{d}\n",
            .{
                tmp_id, int_info.bits, lhs_ptr,
                tmp_id, int_info.bits, rhs_ptr,
                tmp_id, int_info.bits, tmp_id,
                tmp_id,
            },
        );
        return std.fmt.allocPrint(emitter.allocator, "%_peqi_eq_{d}", .{tmp_id});
    }

    if (ty == .source_loc_ty or
        ty == .task_group_base_ty or
        ty == .task_handle_base_ty or
        emitter.input.pool.isTaskGroupType(ty) or
        emitter.input.pool.isTaskHandleType(ty))
    {
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_peqp_l_{d} = load ptr, ptr {s}, align 1\n" ++
                "  %_peqp_r_{d} = load ptr, ptr {s}, align 1\n" ++
                "  %_peqp_eq_{d} = icmp eq ptr %_peqp_l_{d}, %_peqp_r_{d}\n",
            .{ tmp_id, lhs_ptr, tmp_id, rhs_ptr, tmp_id, tmp_id, tmp_id },
        );
        return std.fmt.allocPrint(emitter.allocator, "%_peqp_eq_{d}", .{tmp_id});
    }
    if (ty == .fmt_spec_ty) {
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_peqfs_l_{d} = load i64, ptr {s}, align 1\n" ++
                "  %_peqfs_r_{d} = load i64, ptr {s}, align 1\n" ++
                "  %_peqfs_eq_{d} = icmp eq i64 %_peqfs_l_{d}, %_peqfs_r_{d}\n",
            .{ tmp_id, lhs_ptr, tmp_id, rhs_ptr, tmp_id, tmp_id, tmp_id },
        );
        return std.fmt.allocPrint(emitter.allocator, "%_peqfs_eq_{d}", .{tmp_id});
    }

    if (ty.isPrimitiveOrSentinel()) return emitter.allocator.dupe(u8, "false");
    const node = emitter.input.pool.getNode(ty);

    switch (node.tag) {
        .ref_ty, .mut_ref_ty => {
            if (emitter.input.pool.getSliceRefInner(ty)) |slice_inner| {
                return emitStructuralPtrEqLlvm(emitter, state, slice_inner, lhs_ptr, rhs_ptr, depth + 1);
            }
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_peqp_l_{d} = load ptr, ptr {s}, align 1\n" ++
                    "  %_peqp_r_{d} = load ptr, ptr {s}, align 1\n" ++
                    "  %_peqp_eq_{d} = icmp eq ptr %_peqp_l_{d}, %_peqp_r_{d}\n",
                .{ tmp_id, lhs_ptr, tmp_id, rhs_ptr, tmp_id, tmp_id, tmp_id },
            );
            return std.fmt.allocPrint(emitter.allocator, "%_peqp_eq_{d}", .{tmp_id});
        },
        .raw_ptr_ty, .fn_ty => {
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_peqp_l_{d} = load ptr, ptr {s}, align 1\n" ++
                    "  %_peqp_r_{d} = load ptr, ptr {s}, align 1\n" ++
                    "  %_peqp_eq_{d} = icmp eq ptr %_peqp_l_{d}, %_peqp_r_{d}\n",
                .{ tmp_id, lhs_ptr, tmp_id, rhs_ptr, tmp_id, tmp_id, tmp_id },
            );
            return std.fmt.allocPrint(emitter.allocator, "%_peqp_eq_{d}", .{tmp_id});
        },
        .optional_ty, .result_ty, .enum_ty => {
            const sum_detail = (try emitter.resolver.getSumDetail(ty)) orelse {
                const lay = try emitter.resolver.resolveType(ty);
                const bits: u16 = @intCast(@max(lay.size_bytes, 1) * 8);
                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_peqe_l_{d} = load i{d}, ptr {s}, align 1\n" ++
                        "  %_peqe_r_{d} = load i{d}, ptr {s}, align 1\n" ++
                        "  %_peqe_eq_{d} = icmp eq i{d} %_peqe_l_{d}, %_peqe_r_{d}\n",
                    .{ tmp_id, bits, lhs_ptr, tmp_id, bits, rhs_ptr, tmp_id, bits, tmp_id, tmp_id },
                );
                return std.fmt.allocPrint(emitter.allocator, "%_peqe_eq_{d}", .{tmp_id});
            };

            const disc_l = try emitReadSumDiscriminantFromPtr(emitter, state, ty, lhs_ptr, 1);
            defer emitter.allocator.free(disc_l);
            const disc_r = try emitReadSumDiscriminantFromPtr(emitter, state, ty, rhs_ptr, 1);
            defer emitter.allocator.free(disc_r);

            const var_count: u32 = switch (node.tag) {
                .optional_ty, .result_ty => 2,
                .enum_ty => blk: {
                    const sym_idx = SymbolIndex.fromInt(node.rhs);
                    if (sym_idx.isNone() or sym_idx.asInt() >= emitter.input.sym_table.symbols.items.len) break :blk 0;
                    const enum_sym = emitter.input.sym_table.getSymbol(sym_idx).*;
                    if (enum_sym.target_scope.isNone()) break :blk 0;
                    var cnt: u32 = 0;
                    for (emitter.input.sym_table.getScopeMembers(enum_sym.target_scope)) |m_idx| {
                        if (emitter.input.sym_table.getSymbol(m_idx).kind == .enum_variant_sym) cnt += 1;
                    }
                    break :blk cnt;
                },
                else => 0,
            };

            var has_non_zst_payload = false;
            var scan_ord: u32 = 0;
            while (scan_ord < var_count) : (scan_ord += 1) {
                const v_pay = resolveEnumVariantPayloadType(emitter, ty, scan_ord);
                if (!(try isZeroSizedType(emitter, v_pay))) {
                    has_non_zst_payload = true;
                    break;
                }
            }

            const tmp_id = state.nextTmp();
            try state.print(
                "  %_peqd_eq_{d} = icmp eq i32 {s}, {s}\n",
                .{ tmp_id, disc_l, disc_r },
            );
            if (!has_non_zst_payload) {
                return std.fmt.allocPrint(emitter.allocator, "%_peqd_eq_{d}", .{tmp_id});
            }

            const res_slot = try state.allocEntryBytes(1, 1);
            defer emitter.allocator.free(res_slot);
            try state.print(
                "  store i8 0, ptr {s}, align 1\n" ++
                    "  br i1 %_peqd_eq_{d}, label %_peqd_sm_{d}, label %_peqd_dn_{d}\n" ++
                    "_peqd_sm_{d}:\n",
                .{ res_slot, tmp_id, tmp_id, tmp_id, tmp_id },
            );

            const pay_l = if (sum_detail.payload_offset == 0)
                try emitter.allocator.dupe(u8, lhs_ptr)
            else blk: {
                try state.print(
                    "  %_peqd_pl_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                    .{ tmp_id, lhs_ptr, ptr_int, sum_detail.payload_offset },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_peqd_pl_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(pay_l);

            const pay_r = if (sum_detail.payload_offset == 0)
                try emitter.allocator.dupe(u8, rhs_ptr)
            else blk: {
                try state.print(
                    "  %_peqd_pr_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                    .{ tmp_id, rhs_ptr, ptr_int, sum_detail.payload_offset },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_peqd_pr_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(pay_r);

            var var_ord: u32 = 0;
            while (var_ord < var_count) : (var_ord += 1) {
                const sub_id = state.nextTmp();
                const v_pay = resolveEnumVariantPayloadType(emitter, ty, var_ord);
                try state.print(
                    "  %_peqd_vc_{d} = icmp eq i32 {s}, {d}\n" ++
                        "  br i1 %_peqd_vc_{d}, label %_peqd_vh_{d}, label %_peqd_vn_{d}\n" ++
                        "_peqd_vh_{d}:\n",
                    .{ sub_id, disc_l, var_ord, sub_id, sub_id, sub_id, sub_id },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqd_vh_{d}", .{sub_id}));
                const v_eq = try emitStructuralPtrEqLlvm(emitter, state, v_pay, pay_l, pay_r, depth + 1);
                defer emitter.allocator.free(v_eq);
                try state.print(
                    "  %_peqd_vz_{d} = zext i1 {s} to i8\n" ++
                        "  store i8 %_peqd_vz_{d}, ptr {s}, align 1\n" ++
                        "  br label %_peqd_dn_{d}\n" ++
                        "_peqd_vn_{d}:\n",
                    .{ sub_id, v_eq, sub_id, res_slot, tmp_id, sub_id },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqd_vn_{d}", .{sub_id}));
            }

            try state.print(
                "  br label %_peqd_dn_{d}\n" ++
                    "_peqd_dn_{d}:\n" ++
                    "  %_peqd_ld_{d} = load i8, ptr {s}, align 1\n" ++
                    "  %_peqd_res_{d} = trunc i8 %_peqd_ld_{d} to i1\n",
                .{ tmp_id, tmp_id, tmp_id, res_slot, tmp_id, tmp_id },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqd_dn_{d}", .{tmp_id}));
            return std.fmt.allocPrint(emitter.allocator, "%_peqd_res_{d}", .{tmp_id});
        },
        .struct_ty, .tuple_ty => {
            const lay = try emitter.resolver.resolveType(ty);
            var acc_ssa = try emitter.allocator.dupe(u8, "true");
            errdefer emitter.allocator.free(acc_ssa);
            var fld_i: u32 = 0;
            while (fld_i < lay.aux_len) : (fld_i += 1) {
                const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + fld_i];
                if (fld.size_bytes == 0) continue;
                const sub_id = state.nextTmp();
                const fp_l = if (fld.byte_offset == 0)
                    try emitter.allocator.dupe(u8, lhs_ptr)
                else blk: {
                    try state.print(
                        "  %_peqst_l_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ sub_id, lhs_ptr, ptr_int, fld.byte_offset },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_peqst_l_{d}", .{sub_id});
                };
                defer emitter.allocator.free(fp_l);
                const fp_r = if (fld.byte_offset == 0)
                    try emitter.allocator.dupe(u8, rhs_ptr)
                else blk: {
                    try state.print(
                        "  %_peqst_r_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ sub_id, rhs_ptr, ptr_int, fld.byte_offset },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_peqst_r_{d}", .{sub_id});
                };
                defer emitter.allocator.free(fp_r);
                const fld_eq = try emitStructuralPtrEqLlvm(emitter, state, fld.field_ty, fp_l, fp_r, depth + 1);
                defer emitter.allocator.free(fld_eq);
                try state.print(
                    "  %_peqst_a_{d} = and i1 {s}, {s}\n",
                    .{ sub_id, acc_ssa, fld_eq },
                );
                emitter.allocator.free(acc_ssa);
                acc_ssa = try std.fmt.allocPrint(emitter.allocator, "%_peqst_a_{d}", .{sub_id});
            }
            return acc_ssa;
        },
        .array_ty => {
            const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
            const cap: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            if (cap == 0) return emitter.allocator.dupe(u8, "true");
            const cap_s = try std.fmt.allocPrint(emitter.allocator, "{d}", .{cap});
            defer emitter.allocator.free(cap_s);
            return emitStructuralSpanLoopEqLlvm(emitter, state, elem_ty, lhs_ptr, rhs_ptr, cap_s, depth);
        },
        .soa_array_ty => {
            const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
            const st_lay = try emitter.resolver.resolveType(elem_struct);
            const cap: u64 = node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            if (cap == 0 or st_lay.size_bytes == 0) return emitter.allocator.dupe(u8, "true");
            const cap_s = try std.fmt.allocPrint(emitter.allocator, "{d}", .{cap});
            defer emitter.allocator.free(cap_s);
            var acc_ssa = try emitter.allocator.dupe(u8, "true");
            errdefer emitter.allocator.free(acc_ssa);
            var col_ord: u32 = 0;
            while (col_ord < st_lay.aux_len) : (col_ord += 1) {
                const fld = emitter.resolver.fields_by_decl.items[st_lay.aux_start + col_ord];
                if (fld.size_bytes == 0) continue;
                const col = emitter.resolver.getSoaColumnOffset(elem_struct, col_ord, cap).?;
                const sub_id = state.nextTmp();
                const col_l = if (col.byte_offset == 0)
                    try emitter.allocator.dupe(u8, lhs_ptr)
                else blk: {
                    try state.print(
                        "  %_peqsa_l_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ sub_id, lhs_ptr, ptr_int, col.byte_offset },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_peqsa_l_{d}", .{sub_id});
                };
                defer emitter.allocator.free(col_l);
                const col_r = if (col.byte_offset == 0)
                    try emitter.allocator.dupe(u8, rhs_ptr)
                else blk: {
                    try state.print(
                        "  %_peqsa_r_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ sub_id, rhs_ptr, ptr_int, col.byte_offset },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_peqsa_r_{d}", .{sub_id});
                };
                defer emitter.allocator.free(col_r);
                const col_eq = try emitStructuralSpanLoopEqLlvm(
                    emitter,
                    state,
                    fld.field_ty,
                    col_l,
                    col_r,
                    cap_s,
                    depth,
                );
                defer emitter.allocator.free(col_eq);
                try state.print("  %_peqsa_a_{d} = and i1 {s}, {s}\n", .{ sub_id, acc_ssa, col_eq });
                emitter.allocator.free(acc_ssa);
                acc_ssa = try std.fmt.allocPrint(emitter.allocator, "%_peqsa_a_{d}", .{sub_id});
            }
            return acc_ssa;
        },
        .soa_vec_ty => {
            const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
            const st_lay = try emitter.resolver.resolveType(elem_struct);
            const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
            const res_slot = try state.allocEntryBytes(1, 1);
            defer emitter.allocator.free(res_slot);
            const tmp_id = state.nextTmp();
            try state.print(
                "  store i8 0, ptr {s}, align 1\n" ++
                    "  %_peqsv_lp_{d} = load ptr, ptr {s}, align 1\n" ++
                    "  %_peqsv_llp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                    "  %_peqsv_ll32_{d} = load i32, ptr %_peqsv_llp_{d}, align 1\n" ++
                    "  %_peqsv_lcp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                    "  %_peqsv_lc32_{d} = load i32, ptr %_peqsv_lcp_{d}, align 1\n" ++
                    "  %_peqsv_rp_{d} = load ptr, ptr {s}, align 1\n" ++
                    "  %_peqsv_rlp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                    "  %_peqsv_rl32_{d} = load i32, ptr %_peqsv_rlp_{d}, align 1\n" ++
                    "  %_peqsv_rcp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                    "  %_peqsv_rc32_{d} = load i32, ptr %_peqsv_rcp_{d}, align 1\n",
                .{
                    res_slot,
                    tmp_id,
                    lhs_ptr,
                    tmp_id,
                    lhs_ptr,
                    ptr_int,
                    ptr_bytes,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    lhs_ptr,
                    ptr_int,
                    ptr_bytes + 4,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    rhs_ptr,
                    tmp_id,
                    rhs_ptr,
                    ptr_int,
                    ptr_bytes,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    rhs_ptr,
                    ptr_int,
                    ptr_bytes + 4,
                    tmp_id,
                    tmp_id,
                },
            );
            try state.print(
                "  %_peqsv_le_{d} = icmp eq i32 %_peqsv_ll32_{d}, %_peqsv_rl32_{d}\n" ++
                    "  br i1 %_peqsv_le_{d}, label %_peqsv_sm_{d}, label %_peqsv_dn_{d}\n" ++
                    "_peqsv_sm_{d}:\n" ++
                    "  %_peqsv_z_{d} = icmp eq i32 %_peqsv_ll32_{d}, 0\n" ++
                    "  br i1 %_peqsv_z_{d}, label %_peqsv_ok_{d}, label %_peqsv_cl_{d}\n" ++
                    "_peqsv_ok_{d}:\n" ++
                    "  store i8 1, ptr {s}, align 1\n" ++
                    "  br label %_peqsv_dn_{d}\n" ++
                    "_peqsv_cl_{d}:\n",
                .{
                    tmp_id, tmp_id,   tmp_id,
                    tmp_id, tmp_id,   tmp_id,
                    tmp_id, tmp_id,   tmp_id,
                    tmp_id, tmp_id,   tmp_id,
                    tmp_id, res_slot, tmp_id,
                    tmp_id,
                },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqsv_cl_{d}", .{tmp_id}));
            if (ptr_bytes == 4) {
                try state.print(
                    "  %_peqsv_ln_{d} = add i32 %_peqsv_ll32_{d}, 0\n" ++
                        "  %_peqsv_lc_{d} = add i32 %_peqsv_lc32_{d}, 0\n" ++
                        "  %_peqsv_rc_{d} = add i32 %_peqsv_rc32_{d}, 0\n",
                    .{ tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id },
                );
            } else {
                try state.print(
                    "  %_peqsv_ln_{d} = zext i32 %_peqsv_ll32_{d} to i64\n" ++
                        "  %_peqsv_lc_{d} = zext i32 %_peqsv_lc32_{d} to i64\n" ++
                        "  %_peqsv_rc_{d} = zext i32 %_peqsv_rc32_{d} to i64\n",
                    .{ tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id },
                );
            }
            const len_s = try std.fmt.allocPrint(emitter.allocator, "%_peqsv_ln_{d}", .{tmp_id});
            defer emitter.allocator.free(len_s);
            const lcap_s = try std.fmt.allocPrint(emitter.allocator, "%_peqsv_lc_{d}", .{tmp_id});
            defer emitter.allocator.free(lcap_s);
            const rcap_s = try std.fmt.allocPrint(emitter.allocator, "%_peqsv_rc_{d}", .{tmp_id});
            defer emitter.allocator.free(rcap_s);
            var acc_ssa = try emitter.allocator.dupe(u8, "true");
            errdefer emitter.allocator.free(acc_ssa);
            var col_ord: u32 = 0;
            while (col_ord < st_lay.aux_len) : (col_ord += 1) {
                const fld = emitter.resolver.fields_by_decl.items[st_lay.aux_start + col_ord];
                if (fld.size_bytes == 0) continue;
                const d_l = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, col_ord, lcap_s);
                defer emitter.allocator.free(d_l.off_ssa);
                const d_r = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, col_ord, rcap_s);
                defer emitter.allocator.free(d_r.off_ssa);
                const sub_id = state.nextTmp();
                try state.print(
                    "  %_peqsv_cl_{d} = getelementptr inbounds i8, ptr %_peqsv_lp_{d}, {s} {s}\n" ++
                        "  %_peqsv_cr_{d} = getelementptr inbounds i8, ptr %_peqsv_rp_{d}, {s} {s}\n",
                    .{ sub_id, tmp_id, ptr_int, d_l.off_ssa, sub_id, tmp_id, ptr_int, d_r.off_ssa },
                );
                const col_l = try std.fmt.allocPrint(emitter.allocator, "%_peqsv_cl_{d}", .{sub_id});
                defer emitter.allocator.free(col_l);
                const col_r = try std.fmt.allocPrint(emitter.allocator, "%_peqsv_cr_{d}", .{sub_id});
                defer emitter.allocator.free(col_r);
                const col_eq = try emitStructuralSpanLoopEqLlvm(emitter, state, fld.field_ty, col_l, col_r, len_s, depth);
                defer emitter.allocator.free(col_eq);
                try state.print("  %_peqsv_a_{d} = and i1 {s}, {s}\n", .{ sub_id, acc_ssa, col_eq });
                emitter.allocator.free(acc_ssa);
                acc_ssa = try std.fmt.allocPrint(emitter.allocator, "%_peqsv_a_{d}", .{sub_id});
            }
            try state.print(
                "  %_peqsv_b8_{d} = zext i1 {s} to i8\n" ++
                    "  store i8 %_peqsv_b8_{d}, ptr {s}, align 1\n" ++
                    "  br label %_peqsv_dn_{d}\n" ++
                    "_peqsv_dn_{d}:\n" ++
                    "  %_peqsv_rv_{d} = load i8, ptr {s}, align 1\n" ++
                    "  %_peqsv_okb_{d} = icmp ne i8 %_peqsv_rv_{d}, 0\n",
                .{ tmp_id, acc_ssa, tmp_id, res_slot, tmp_id, tmp_id, tmp_id, res_slot, tmp_id, tmp_id },
            );
            emitter.allocator.free(acc_ssa);
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqsv_dn_{d}", .{tmp_id}));
            return std.fmt.allocPrint(emitter.allocator, "%_peqsv_okb_{d}", .{tmp_id});
        },
        .slice_ty => {
            const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(node.lhs));
            const res_slot = try state.allocEntryBytes(1, 1);
            defer emitter.allocator.free(res_slot);
            const tmp_id = state.nextTmp();
            try state.print(
                "  store i8 0, ptr {s}, align 1\n" ++
                    "  %_peqsl_l_{d} = load {{ ptr, {s} }}, ptr {s}, align 1\n" ++
                    "  %_peqsl_r_{d} = load {{ ptr, {s} }}, ptr {s}, align 1\n" ++
                    "  %_peqsl_lp_{d} = extractvalue {{ ptr, {s} }} %_peqsl_l_{d}, 0\n" ++
                    "  %_peqsl_ll_{d} = extractvalue {{ ptr, {s} }} %_peqsl_l_{d}, 1\n" ++
                    "  %_peqsl_rp_{d} = extractvalue {{ ptr, {s} }} %_peqsl_r_{d}, 0\n" ++
                    "  %_peqsl_rl_{d} = extractvalue {{ ptr, {s} }} %_peqsl_r_{d}, 1\n" ++
                    "  %_peqsl_le_{d} = icmp eq {s} %_peqsl_ll_{d}, %_peqsl_rl_{d}\n" ++
                    "  br i1 %_peqsl_le_{d}, label %_peqsl_sm_{d}, label %_peqsl_dn_{d}\n" ++
                    "_peqsl_sm_{d}:\n",
                .{
                    res_slot,
                    tmp_id,
                    ptr_int,
                    lhs_ptr,
                    tmp_id,
                    ptr_int,
                    rhs_ptr,
                    tmp_id,
                    ptr_int,
                    tmp_id,
                    tmp_id,
                    ptr_int,
                    tmp_id,
                    tmp_id,
                    ptr_int,
                    tmp_id,
                    tmp_id,
                    ptr_int,
                    tmp_id,
                    tmp_id,
                    ptr_int,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqsl_sm_{d}", .{tmp_id}));
            const lp_s = try std.fmt.allocPrint(emitter.allocator, "%_peqsl_lp_{d}", .{tmp_id});
            defer emitter.allocator.free(lp_s);
            const rp_s = try std.fmt.allocPrint(emitter.allocator, "%_peqsl_rp_{d}", .{tmp_id});
            defer emitter.allocator.free(rp_s);
            const ll_s = try std.fmt.allocPrint(emitter.allocator, "%_peqsl_ll_{d}", .{tmp_id});
            defer emitter.allocator.free(ll_s);
            const span_eq = try emitStructuralSpanLoopEqLlvm(emitter, state, elem_ty, lp_s, rp_s, ll_s, depth);
            defer emitter.allocator.free(span_eq);
            try state.print(
                "  %_peqsl_z_{d} = zext i1 {s} to i8\n" ++
                    "  store i8 %_peqsl_z_{d}, ptr {s}, align 1\n" ++
                    "  br label %_peqsl_dn_{d}\n" ++
                    "_peqsl_dn_{d}:\n" ++
                    "  %_peqsl_ld_{d} = load i8, ptr {s}, align 1\n" ++
                    "  %_peqsl_rs_{d} = trunc i8 %_peqsl_ld_{d} to i1\n",
                .{ tmp_id, span_eq, tmp_id, res_slot, tmp_id, tmp_id, tmp_id, res_slot, tmp_id, tmp_id },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqsl_dn_{d}", .{tmp_id}));
            return std.fmt.allocPrint(emitter.allocator, "%_peqsl_rs_{d}", .{tmp_id});
        },
        .soa_slice_ty => {
            const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
            const st_lay = try emitter.resolver.resolveType(elem_struct);
            const res_slot = try state.allocEntryBytes(1, 1);
            defer emitter.allocator.free(res_slot);
            const soa_sl_ty = try std.fmt.allocPrint(
                emitter.allocator,
                "{{ ptr, {s}, {s}, {s} }}",
                .{ ptr_int, ptr_int, ptr_int },
            );
            defer emitter.allocator.free(soa_sl_ty);
            const tmp_id = state.nextTmp();
            try state.print(
                "  store i8 0, ptr {s}, align 1\n" ++
                    "  %_peqss_l_{d} = load {s}, ptr {s}, align 1\n" ++
                    "  %_peqss_r_{d} = load {s}, ptr {s}, align 1\n" ++
                    "  %_peqss_lp_{d} = extractvalue {s} %_peqss_l_{d}, 0\n" ++
                    "  %_peqss_ll_{d} = extractvalue {s} %_peqss_l_{d}, 1\n" ++
                    "  %_peqss_ls_{d} = extractvalue {s} %_peqss_l_{d}, 2\n" ++
                    "  %_peqss_lo_{d} = extractvalue {s} %_peqss_l_{d}, 3\n",
                .{
                    res_slot,
                    tmp_id,
                    soa_sl_ty,
                    lhs_ptr,
                    tmp_id,
                    soa_sl_ty,
                    rhs_ptr,
                    tmp_id,
                    soa_sl_ty,
                    tmp_id,
                    tmp_id,
                    soa_sl_ty,
                    tmp_id,
                    tmp_id,
                    soa_sl_ty,
                    tmp_id,
                    tmp_id,
                    soa_sl_ty,
                    tmp_id,
                },
            );
            try state.print(
                "  %_peqss_rp_{d} = extractvalue {s} %_peqss_r_{d}, 0\n" ++
                    "  %_peqss_rl_{d} = extractvalue {s} %_peqss_r_{d}, 1\n" ++
                    "  %_peqss_rsd_{d} = extractvalue {s} %_peqss_r_{d}, 2\n" ++
                    "  %_peqss_ro_{d} = extractvalue {s} %_peqss_r_{d}, 3\n" ++
                    "  %_peqss_le_{d} = icmp eq {s} %_peqss_ll_{d}, %_peqss_rl_{d}\n" ++
                    "  br i1 %_peqss_le_{d}, label %_peqss_sm_{d}, label %_peqss_dn_{d}\n" ++
                    "_peqss_sm_{d}:\n",
                .{
                    tmp_id, soa_sl_ty, tmp_id,
                    tmp_id, soa_sl_ty, tmp_id,
                    tmp_id, soa_sl_ty, tmp_id,
                    tmp_id, soa_sl_ty, tmp_id,
                    tmp_id, ptr_int,   tmp_id,
                    tmp_id, tmp_id,    tmp_id,
                    tmp_id, tmp_id,
                },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqss_sm_{d}", .{tmp_id}));
            const ll_s = try std.fmt.allocPrint(emitter.allocator, "%_peqss_ll_{d}", .{tmp_id});
            defer emitter.allocator.free(ll_s);
            const ls_s = try std.fmt.allocPrint(emitter.allocator, "%_peqss_ls_{d}", .{tmp_id});
            defer emitter.allocator.free(ls_s);
            const rs_s = try std.fmt.allocPrint(emitter.allocator, "%_peqss_rsd_{d}", .{tmp_id});
            defer emitter.allocator.free(rs_s);
            var acc_ssa = try emitter.allocator.dupe(u8, "true");
            errdefer emitter.allocator.free(acc_ssa);
            var col_ord: u32 = 0;
            while (col_ord < st_lay.aux_len) : (col_ord += 1) {
                const fld = emitter.resolver.fields_by_decl.items[st_lay.aux_start + col_ord];
                if (fld.size_bytes == 0) continue;
                const dyn_col_l = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, col_ord, ls_s);
                defer emitter.allocator.free(dyn_col_l.off_ssa);
                const dyn_col_r = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, col_ord, rs_s);
                defer emitter.allocator.free(dyn_col_r.off_ssa);
                const sub_id = state.nextTmp();
                try state.print(
                    "  %_peqss_lm_{d} = mul {s} %_peqss_lo_{d}, {d}\n" ++
                        "  %_peqss_lb_{d} = add {s} {s}, %_peqss_lm_{d}\n" ++
                        "  %_peqss_rm_{d} = mul {s} %_peqss_ro_{d}, {d}\n" ++
                        "  %_peqss_rb_{d} = add {s} {s}, %_peqss_rm_{d}\n" ++
                        "  %_peqss_cl_{d} = getelementptr inbounds i8, ptr %_peqss_lp_{d}, {s} %_peqss_lb_{d}\n" ++
                        "  %_peqss_cr_{d} = getelementptr inbounds i8, ptr %_peqss_rp_{d}, {s} %_peqss_rb_{d}\n",
                    .{
                        sub_id, ptr_int, tmp_id,            fld.size_bytes,
                        sub_id, ptr_int, dyn_col_l.off_ssa, sub_id,
                        sub_id, ptr_int, tmp_id,            fld.size_bytes,
                        sub_id, ptr_int, dyn_col_r.off_ssa, sub_id,
                        sub_id, tmp_id,  ptr_int,           sub_id,
                        sub_id, tmp_id,  ptr_int,           sub_id,
                    },
                );
                const col_l = try std.fmt.allocPrint(emitter.allocator, "%_peqss_cl_{d}", .{sub_id});
                defer emitter.allocator.free(col_l);
                const col_r = try std.fmt.allocPrint(emitter.allocator, "%_peqss_cr_{d}", .{sub_id});
                defer emitter.allocator.free(col_r);
                const col_eq = try emitStructuralSpanLoopEqLlvm(
                    emitter,
                    state,
                    fld.field_ty,
                    col_l,
                    col_r,
                    ll_s,
                    depth,
                );
                defer emitter.allocator.free(col_eq);
                try state.print("  %_peqss_a_{d} = and i1 {s}, {s}\n", .{ sub_id, acc_ssa, col_eq });
                emitter.allocator.free(acc_ssa);
                acc_ssa = try std.fmt.allocPrint(emitter.allocator, "%_peqss_a_{d}", .{sub_id});
            }
            defer emitter.allocator.free(acc_ssa);
            try state.print(
                "  %_peqss_z_{d} = zext i1 {s} to i8\n" ++
                    "  store i8 %_peqss_z_{d}, ptr {s}, align 1\n" ++
                    "  br label %_peqss_dn_{d}\n" ++
                    "_peqss_dn_{d}:\n" ++
                    "  %_peqss_ld_{d} = load i8, ptr {s}, align 1\n" ++
                    "  %_peqss_rs_{d} = trunc i8 %_peqss_ld_{d} to i1\n",
                .{ tmp_id, acc_ssa, tmp_id, res_slot, tmp_id, tmp_id, tmp_id, res_slot, tmp_id, tmp_id },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_peqss_dn_{d}", .{tmp_id}));
            return std.fmt.allocPrint(emitter.allocator, "%_peqss_rs_{d}", .{tmp_id});
        },
        else => return emitter.allocator.dupe(u8, "false"),
    }
}

/// Emits UB-free LLVM binary arithmetic, shift, bitwise, and relational operations into `%_v_<dst_raw>`.
fn emitBinOpLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body_idx: u32,
    body: *const MirBody,
    dst_raw: u32,
    kind: mir.BinOpKind,
    lhs_val: MirValueId,
    rhs_val: MirValueId,
    res_ty: TypeId,
) !void {
    const l_raw = lhs_val.asInt();
    const r_raw = rhs_val.asInt();
    const op_ty = try unwrapTransparentType(emitter, body.getInst(lhs_val).type_id);
    const ptr_int = ptrIntType(emitter);

    // [0] Zero-sized equality (`unit == unit`, `unit != unit`):
    if ((kind == .eq or kind == .ne) and (try isZeroSizedType(emitter, op_ty))) {
        const res_lit = if (kind == .eq) "true" else "false";
        try state.print("  %_v_{d} = or i1 false, {s}\n", .{ dst_raw, res_lit });
        return;
    }

    // [1] Fat-string equality (`str == str`, `str != str`):
    if (op_ty == .str_ty and (kind == .eq or kind == .ne)) {
        if (!emitter.declared_externs.contains("memcmp")) {
            try emitter.requireIntrinsicDecl(
                if (emitter.cfg.target.isWasm())
                    "declare i32 @memcmp(ptr, ptr, i32) nounwind"
                else
                    "declare i32 @memcmp(ptr, ptr, i64) nounwind",
            );
        }
        const tmp_id = state.nextTmp();
        try state.print(
            "  %_slp_l_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 0\n" ++
                "  %_sll_l_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 1\n" ++
                "  %_slp_r_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 0\n" ++
                "  %_sll_r_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 1\n" ++
                "  %_seq_ln_{d} = icmp eq {s} %_sll_l_{d}, %_sll_r_{d}\n" ++
                "  br i1 %_seq_ln_{d}, label %_seq_chkz_{d}, label %_seq_false_{d}\n" ++
                "_seq_chkz_{d}:\n" ++
                "  %_seq_isz_{d} = icmp eq {s} %_sll_l_{d}, 0\n" ++
                "  br i1 %_seq_isz_{d}, label %_seq_true_{d}, label %_seq_mcmp_{d}\n",
            .{
                tmp_id,  ptr_int, l_raw,
                tmp_id,  ptr_int, l_raw,
                tmp_id,  ptr_int, r_raw,
                tmp_id,  ptr_int, r_raw,
                tmp_id,  ptr_int, tmp_id,
                tmp_id,  tmp_id,  tmp_id,
                tmp_id,  tmp_id,  tmp_id,
                ptr_int, tmp_id,  tmp_id,
                tmp_id,  tmp_id,
            },
        );
        try state.print(
            "_seq_mcmp_{d}:\n" ++
                "  %_seq_mc_{d} = call i32 @memcmp(ptr %_slp_l_{d}, ptr %_slp_r_{d}, {s} %_sll_l_{d})\n" ++
                "  %_seq_m0_{d} = icmp eq i32 %_seq_mc_{d}, 0\n" ++
                "  br label %_seq_join_{d}\n" ++
                "_seq_true_{d}:\n" ++
                "  br label %_seq_join_{d}\n" ++
                "_seq_false_{d}:\n" ++
                "  br label %_seq_join_{d}\n" ++
                "_seq_join_{d}:\n" ++
                "  %_seq_eq_{d} = phi i1 [ %_seq_m0_{d}, %_seq_mcmp_{d} ], [ true, %_seq_true_{d} ], [ false, %_seq_false_{d} ]\n",
            .{
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                ptr_int,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
                tmp_id,
            },
        );
        if (kind == .ne) {
            try state.print("  %_v_{d} = xor i1 %_seq_eq_{d}, true\n", .{ dst_raw, tmp_id });
        } else {
            try state.print("  %_v_{d} = or i1 %_seq_eq_{d}, false\n", .{ dst_raw, tmp_id });
        }
        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_seq_join_{d}", .{tmp_id}));
        return;
    }

    // [2] IEEE-754 floating-point arithmetic and relational comparisons:
    if (op_ty == .f32_ty or op_ty == .f64_ty or op_ty == .untyped_float_ty) {
        const flt_ty = if (op_ty == .f32_ty) "float" else "double";
        switch (kind) {
            .fadd => try state.print("  %_v_{d} = fadd {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .fsub => try state.print("  %_v_{d} = fsub {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .fmul => try state.print("  %_v_{d} = fmul {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .fdiv => try state.print("  %_v_{d} = fdiv {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .frem => try state.print("  %_v_{d} = frem {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .eq => try state.print("  %_v_{d} = fcmp oeq {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .ne => try state.print("  %_v_{d} = fcmp une {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .flt => try state.print("  %_v_{d} = fcmp olt {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .fle => try state.print("  %_v_{d} = fcmp ole {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .fgt => try state.print("  %_v_{d} = fcmp ogt {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            .fge => try state.print("  %_v_{d} = fcmp oge {s} %_v_{d}, %_v_{d}\n", .{ dst_raw, flt_ty, l_raw, r_raw }),
            else => try state.print("  %_v_{d} = or i1 false, false\n", .{dst_raw}),
        }
        return;
    }

    // [3] Pointer relational and equality comparisons + composite structural equality (`Option`, `Result`, etc.):
    if ((kind == .eq or kind == .ne) and
        (op_ty == .source_loc_ty or
            op_ty == .task_group_base_ty or
            op_ty == .task_handle_base_ty or
            emitter.input.pool.isTaskGroupType(op_ty) or
            emitter.input.pool.isTaskHandleType(op_ty)))
    {
        const pred = if (kind == .eq) "eq" else "ne";
        try state.print("  %_v_{d} = icmp {s} ptr %_v_{d}, %_v_{d}\n", .{ dst_raw, pred, l_raw, r_raw });
        return;
    }
    if ((kind == .eq or kind == .ne) and op_ty == .fmt_spec_ty) {
        const l_slot = try state.allocEntryBytes(8, 4);
        defer emitter.allocator.free(l_slot);
        const r_slot = try state.allocEntryBytes(8, 4);
        defer emitter.allocator.free(r_slot);
        const tmp_id = state.nextTmp();
        const pred = if (kind == .eq) "eq" else "ne";
        try state.print(
            "  store {{ i32, i16, i16 }} %_v_{d}, ptr {s}, align 4\n" ++
                "  store {{ i32, i16, i16 }} %_v_{d}, ptr {s}, align 4\n" ++
                "  %_fse_l_{d} = load i64, ptr {s}, align 4\n" ++
                "  %_fse_r_{d} = load i64, ptr {s}, align 4\n" ++
                "  %_v_{d} = icmp {s} i64 %_fse_l_{d}, %_fse_r_{d}\n",
            .{ l_raw, l_slot, r_raw, r_slot, tmp_id, l_slot, tmp_id, r_slot, dst_raw, pred, tmp_id, tmp_id },
        );
        return;
    }
    if (!op_ty.isPrimitiveOrSentinel()) {
        const op_tag = emitter.input.pool.getNode(op_ty).tag;
        if ((op_tag == .ref_ty or op_tag == .mut_ref_ty or op_tag == .raw_ptr_ty or op_tag == .fn_ty) and
            !emitter.input.pool.isSliceRefType(op_ty))
        {
            const pred = switch (kind) {
                .eq => "eq",
                .ne => "ne",
                .ult, .slt => "ult",
                .ule, .sle => "ule",
                .ugt, .sgt => "ugt",
                .uge, .sge => "uge",
                else => "eq",
            };
            try state.print("  %_v_{d} = icmp {s} ptr %_v_{d}, %_v_{d}\n", .{ dst_raw, pred, l_raw, r_raw });
            return;
        }
        if ((kind == .eq or kind == .ne) and resolveIntegerInfo(emitter, op_ty) == null) {
            const lay = try emitter.resolver.resolveType(op_ty);
            const l_slot = try state.allocEntryBytes(lay.size_bytes, lay.alignBytes());
            defer emitter.allocator.free(l_slot);
            const r_slot = try state.allocEntryBytes(lay.size_bytes, lay.alignBytes());
            defer emitter.allocator.free(r_slot);
            try emitMemsetZero(emitter, state, l_slot, lay.size_bytes, lay.alignBytes());
            try emitMemsetZero(emitter, state, r_slot, lay.size_bytes, lay.alignBytes());
            const l_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{l_raw});
            defer emitter.allocator.free(l_ssa);
            const r_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{r_raw});
            defer emitter.allocator.free(r_ssa);
            try emitStoreValueToPtr(emitter, state, op_ty, l_ssa, l_slot, lay.alignBytes(), 0, 0, 0);
            try emitStoreValueToPtr(emitter, state, op_ty, r_ssa, r_slot, lay.alignBytes(), 0, 0, 0);

            const eq_ssa = try emitStructuralPtrEqLlvm(emitter, state, op_ty, l_slot, r_slot, 0);
            defer emitter.allocator.free(eq_ssa);
            if (kind == .ne) {
                try state.print("  %_v_{d} = xor i1 {s}, true\n", .{ dst_raw, eq_ssa });
            } else {
                try state.print("  %_v_{d} = or i1 {s}, false\n", .{ dst_raw, eq_ssa });
            }
            return;
        }
    }

    // [4] Boolean operations (`i1`):
    if (op_ty == .bool_ty) {
        switch (kind) {
            .bit_and => try state.print("  %_v_{d} = and i1 %_v_{d}, %_v_{d}\n", .{ dst_raw, l_raw, r_raw }),
            .bit_or => try state.print("  %_v_{d} = or i1 %_v_{d}, %_v_{d}\n", .{ dst_raw, l_raw, r_raw }),
            .bit_xor, .ne => try state.print("  %_v_{d} = xor i1 %_v_{d}, %_v_{d}\n", .{ dst_raw, l_raw, r_raw }),
            .eq => {
                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_bneq_{d} = xor i1 %_v_{d}, %_v_{d}\n" ++
                        "  %_v_{d} = xor i1 %_bneq_{d}, true\n",
                    .{ tmp_id, l_raw, r_raw, dst_raw, tmp_id },
                );
            },
            .ult, .slt => try state.print("  %_v_{d} = icmp ult i1 %_v_{d}, %_v_{d}\n", .{ dst_raw, l_raw, r_raw }),
            .ule, .sle => try state.print("  %_v_{d} = icmp ule i1 %_v_{d}, %_v_{d}\n", .{ dst_raw, l_raw, r_raw }),
            .ugt, .sgt => try state.print("  %_v_{d} = icmp ugt i1 %_v_{d}, %_v_{d}\n", .{ dst_raw, l_raw, r_raw }),
            .uge, .sge => try state.print("  %_v_{d} = icmp uge i1 %_v_{d}, %_v_{d}\n", .{ dst_raw, l_raw, r_raw }),
            else => try state.print("  %_v_{d} = or i1 false, false\n", .{dst_raw}),
        }
        return;
    }

    // [5] Integer operations (`i8`, `i16`, `i32`, `i64`, `i128`):
    const info = resolveIntegerInfo(emitter, if (kind == .eq or kind == .ne or
        kind == .slt or kind == .ult or kind == .sle or kind == .ule or
        kind == .sgt or kind == .ugt or kind == .sge or kind == .uge)
        op_ty
    else
        res_ty) orelse {
        if (emitter.input.pool.unwrapUnderlyingType(res_ty) == .bool_ty) {
            try state.print("  %_v_{d} = or i1 false, false\n", .{dst_raw});
        } else {
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        }
        return;
    };
    const bits = info.bits;

    switch (kind) {
        .sadd_checked, .uadd_checked, .ssub_checked, .usub_checked, .smul_checked, .umul_checked => {
            const intr_stem = switch (kind) {
                .sadd_checked => "sadd",
                .uadd_checked => "uadd",
                .ssub_checked => "ssub",
                .usub_checked => "usub",
                .smul_checked => "smul",
                else => "umul",
            };
            const decl = try std.fmt.allocPrint(
                emitter.allocator,
                "declare {{ i{d}, i1 }} @llvm.{s}.with.overflow.i{d}(i{d}, i{d})",
                .{ bits, intr_stem, bits, bits, bits },
            );
            defer emitter.allocator.free(decl);
            try emitter.requireIntrinsicDecl(decl);

            const tmp_id = state.nextTmp();
            try state.print(
                "  %_ovp_{d} = call {{ i{d}, i1 }} @llvm.{s}.with.overflow.i{d}(i{d} %_v_{d}, i{d} %_v_{d})\n" ++
                    "  %_ovf_{d} = extractvalue {{ i{d}, i1 }} %_ovp_{d}, 1\n",
                .{ tmp_id, bits, intr_stem, bits, bits, l_raw, bits, r_raw, tmp_id, bits, tmp_id },
            );
            const ov_ssa = try std.fmt.allocPrint(emitter.allocator, "%_ovf_{d}", .{tmp_id});
            defer emitter.allocator.free(ov_ssa);
            try emitInlineTrapIfTrue(emitter, state, ov_ssa, 2);
            try state.print(
                "  %_v_{d} = extractvalue {{ i{d}, i1 }} %_ovp_{d}, 0\n",
                .{ dst_raw, bits, tmp_id },
            );
        },

        .udiv_checked, .urem_checked => {
            const tmp_id = state.nextTmp();
            try state.print("  %_dz_{d} = icmp eq i{d} %_v_{d}, 0\n", .{ tmp_id, bits, r_raw });
            const dz_ssa = try std.fmt.allocPrint(emitter.allocator, "%_dz_{d}", .{tmp_id});
            defer emitter.allocator.free(dz_ssa);
            try emitInlineTrapIfTrue(emitter, state, dz_ssa, 2);
            const div_op = if (kind == .udiv_checked) "udiv" else "urem";
            try state.print(
                "  %_v_{d} = {s} i{d} %_v_{d}, %_v_{d}\n",
                .{ dst_raw, div_op, bits, l_raw, r_raw },
            );
        },

        .sdiv_checked, .srem_checked => {
            const min_s: i128 = -(@as(i128, 1) << @intCast(bits - 1));
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_dz_{d} = icmp eq i{d} %_v_{d}, 0\n" ++
                    "  %_ismin_{d} = icmp eq i{d} %_v_{d}, {d}\n" ++
                    "  %_isn1_{d} = icmp eq i{d} %_v_{d}, -1\n" ++
                    "  %_dov_{d} = and i1 %_ismin_{d}, %_isn1_{d}\n" ++
                    "  %_dbad_{d} = or i1 %_dz_{d}, %_dov_{d}\n",
                .{
                    tmp_id, bits,   r_raw,
                    tmp_id, bits,   l_raw,
                    min_s,  tmp_id, bits,
                    r_raw,  tmp_id, tmp_id,
                    tmp_id, tmp_id, tmp_id,
                    tmp_id,
                },
            );
            const bad_ssa = try std.fmt.allocPrint(emitter.allocator, "%_dbad_{d}", .{tmp_id});
            defer emitter.allocator.free(bad_ssa);
            try emitInlineTrapIfTrue(emitter, state, bad_ssa, 2);
            const div_op = if (kind == .sdiv_checked) "sdiv" else "srem";
            try state.print(
                "  %_v_{d} = {s} i{d} %_v_{d}, %_v_{d}\n",
                .{ dst_raw, div_op, bits, l_raw, r_raw },
            );
        },

        .shl_checked, .ashr_checked, .lshr_checked => {
            const rhs_info = resolveIntegerInfo(emitter, body.getInst(rhs_val).type_id) orelse
                IntScalarInfo{ .bits = bits, .is_signed = false };
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_shoob_{d} = icmp uge i{d} %_v_{d}, {d}\n",
                .{ tmp_id, rhs_info.bits, r_raw, bits },
            );
            const oob_ssa = try std.fmt.allocPrint(emitter.allocator, "%_shoob_{d}", .{tmp_id});
            defer emitter.allocator.free(oob_ssa);
            try emitInlineTrapIfTrue(emitter, state, oob_ssa, 2);

            const amt_ssa = if (rhs_info.bits == bits)
                try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{r_raw})
            else blk: {
                const cast_op = if (rhs_info.bits < bits) "zext" else "trunc";
                try state.print(
                    "  %_shamt_{d} = {s} i{d} %_v_{d} to i{d}\n",
                    .{ tmp_id, cast_op, rhs_info.bits, r_raw, bits },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_shamt_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(amt_ssa);
            const sh_op = switch (kind) {
                .shl_checked => "shl",
                .ashr_checked => "ashr",
                else => "lshr",
            };
            try state.print(
                "  %_v_{d} = {s} i{d} %_v_{d}, {s}\n",
                .{ dst_raw, sh_op, bits, l_raw, amt_ssa },
            );
        },

        .add_wrap, .sub_wrap, .mul_wrap => {
            const nw = checkProvenNoWrapFlags(emitter, body_idx, kind, l_raw, r_raw, bits);
            const op_tok = switch (kind) {
                .add_wrap => "add",
                .sub_wrap => "sub",
                else => "mul",
            };
            const flag_s = if (nw.has_nsw and nw.has_nuw)
                " nsw nuw"
            else if (nw.has_nsw)
                " nsw"
            else if (nw.has_nuw)
                " nuw"
            else
                "";
            try state.print(
                "  %_v_{d} = {s}{s} i{d} %_v_{d}, %_v_{d}\n",
                .{ dst_raw, op_tok, flag_s, bits, l_raw, r_raw },
            );
        },

        .shl_wrap, .ashr_wrap, .lshr_wrap => {
            const rhs_info = resolveIntegerInfo(emitter, body.getInst(rhs_val).type_id) orelse
                IntScalarInfo{ .bits = bits, .is_signed = false };
            const tmp_id = state.nextTmp();
            const coerced_s = if (rhs_info.bits == bits)
                try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{r_raw})
            else blk: {
                const cast_op = if (rhs_info.bits < bits) "zext" else "trunc";
                try state.print(
                    "  %_shw_c_{d} = {s} i{d} %_v_{d} to i{d}\n",
                    .{ tmp_id, cast_op, rhs_info.bits, r_raw, bits },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_shw_c_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(coerced_s);
            const sh_op = switch (kind) {
                .shl_wrap => "shl",
                .ashr_wrap => "ashr",
                else => "lshr",
            };
            try state.print(
                "  %_shw_m_{d} = and i{d} {s}, {d}\n" ++
                    "  %_v_{d} = {s} i{d} %_v_{d}, %_shw_m_{d}\n",
                .{ tmp_id, bits, coerced_s, bits - 1, dst_raw, sh_op, bits, l_raw, tmp_id },
            );
        },

        .sadd_sat, .uadd_sat, .ssub_sat, .usub_sat => {
            const intr_stem = switch (kind) {
                .sadd_sat => "sadd",
                .uadd_sat => "uadd",
                .ssub_sat => "ssub",
                else => "usub",
            };
            const decl = try std.fmt.allocPrint(
                emitter.allocator,
                "declare i{d} @llvm.{s}.sat.i{d}(i{d}, i{d})",
                .{ bits, intr_stem, bits, bits, bits },
            );
            defer emitter.allocator.free(decl);
            try emitter.requireIntrinsicDecl(decl);
            try state.print(
                "  %_v_{d} = call i{d} @llvm.{s}.sat.i{d}(i{d} %_v_{d}, i{d} %_v_{d})\n",
                .{ dst_raw, bits, intr_stem, bits, bits, l_raw, bits, r_raw },
            );
        },

        .umul_sat => {
            const decl = try std.fmt.allocPrint(
                emitter.allocator,
                "declare {{ i{d}, i1 }} @llvm.umul.with.overflow.i{d}(i{d}, i{d})",
                .{ bits, bits, bits, bits },
            );
            defer emitter.allocator.free(decl);
            try emitter.requireIntrinsicDecl(decl);
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_ums_p_{d} = call {{ i{d}, i1 }} @llvm.umul.with.overflow.i{d}(i{d} %_v_{d}, i{d} %_v_{d})\n" ++
                    "  %_ums_v_{d} = extractvalue {{ i{d}, i1 }} %_ums_p_{d}, 0\n" ++
                    "  %_ums_o_{d} = extractvalue {{ i{d}, i1 }} %_ums_p_{d}, 1\n" ++
                    "  %_v_{d} = select i1 %_ums_o_{d}, i{d} -1, i{d} %_ums_v_{d}\n",
                .{
                    tmp_id, bits, bits,   bits,   l_raw, bits,   r_raw,
                    tmp_id, bits, tmp_id, tmp_id, bits,  tmp_id, dst_raw,
                    tmp_id, bits, bits,   tmp_id,
                },
            );
        },

        .smul_sat => {
            const decl = try std.fmt.allocPrint(
                emitter.allocator,
                "declare {{ i{d}, i1 }} @llvm.smul.with.overflow.i{d}(i{d}, i{d})",
                .{ bits, bits, bits, bits },
            );
            defer emitter.allocator.free(decl);
            try emitter.requireIntrinsicDecl(decl);
            const min_s: i128 = -(@as(i128, 1) << @intCast(bits - 1));
            const max_s: i128 = (@as(i128, 1) << @intCast(bits - 1)) - 1;
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_sms_p_{d} = call {{ i{d}, i1 }} @llvm.smul.with.overflow.i{d}(i{d} %_v_{d}, i{d} %_v_{d})\n" ++
                    "  %_sms_v_{d} = extractvalue {{ i{d}, i1 }} %_sms_p_{d}, 0\n" ++
                    "  %_sms_o_{d} = extractvalue {{ i{d}, i1 }} %_sms_p_{d}, 1\n",
                .{
                    tmp_id, bits, bits,   bits,   l_raw, bits,   r_raw,
                    tmp_id, bits, tmp_id, tmp_id, bits,  tmp_id,
                },
            );
            try state.print(
                "  %_sms_x_{d} = xor i{d} %_v_{d}, %_v_{d}\n" ++
                    "  %_sms_n_{d} = icmp slt i{d} %_sms_x_{d}, 0\n" ++
                    "  %_sms_l_{d} = select i1 %_sms_n_{d}, i{d} {d}, i{d} {d}\n" ++
                    "  %_v_{d} = select i1 %_sms_o_{d}, i{d} %_sms_l_{d}, i{d} %_sms_v_{d}\n",
                .{
                    tmp_id, bits,    l_raw,  r_raw,
                    tmp_id, bits,    tmp_id, tmp_id,
                    tmp_id, bits,    min_s,  bits,
                    max_s,  dst_raw, tmp_id, bits,
                    tmp_id, bits,    tmp_id,
                },
            );
        },

        .bit_and => try state.print("  %_v_{d} = and i{d} %_v_{d}, %_v_{d}\n", .{ dst_raw, bits, l_raw, r_raw }),
        .bit_or => try state.print("  %_v_{d} = or i{d} %_v_{d}, %_v_{d}\n", .{ dst_raw, bits, l_raw, r_raw }),
        .bit_xor => try state.print("  %_v_{d} = xor i{d} %_v_{d}, %_v_{d}\n", .{ dst_raw, bits, l_raw, r_raw }),

        .eq, .ne, .slt, .ult, .sle, .ule, .sgt, .ugt, .sge, .uge => {
            const pred = switch (kind) {
                .eq => "eq",
                .ne => "ne",
                .slt => "slt",
                .ult => "ult",
                .sle => "sle",
                .ule => "ule",
                .sgt => "sgt",
                .ugt => "ugt",
                .sge => "sge",
                else => "uge",
            };
            try state.print("  %_v_{d} = icmp {s} i{d} %_v_{d}, %_v_{d}\n", .{ dst_raw, pred, bits, l_raw, r_raw });
        },

        else => try state.print("  %_v_{d} = add i{d} 0, 0\n", .{ dst_raw, bits }),
    }
}

/// Emits UB-free LLVM unary operations and scalar/aggregate casts into `%_v_<dst_raw>`.
fn emitUnaryOpLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    dst_raw: u32,
    kind: mir.UnaryOpKind,
    src_val: MirValueId,
    rhs_ord: u32,
    dst_ty: TypeId,
) !void {
    const s_raw = src_val.asInt();
    const src_ty = try unwrapTransparentType(emitter, body.getInst(src_val).type_id);
    const unwrapped_dst = try unwrapTransparentType(emitter, dst_ty);
    const ptr_int = ptrIntType(emitter);

    switch (kind) {
        .sneg_checked => {
            const info = resolveIntegerInfo(emitter, unwrapped_dst) orelse return;
            const decl = try std.fmt.allocPrint(
                emitter.allocator,
                "declare {{ i{d}, i1 }} @llvm.ssub.with.overflow.i{d}(i{d}, i{d})",
                .{ info.bits, info.bits, info.bits, info.bits },
            );
            defer emitter.allocator.free(decl);
            try emitter.requireIntrinsicDecl(decl);
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_negp_{d} = call {{ i{d}, i1 }} @llvm.ssub.with.overflow.i{d}(i{d} 0, i{d} %_v_{d})\n" ++
                    "  %_nego_{d} = extractvalue {{ i{d}, i1 }} %_negp_{d}, 1\n",
                .{ tmp_id, info.bits, info.bits, info.bits, info.bits, s_raw, tmp_id, info.bits, tmp_id },
            );
            const ov_ssa = try std.fmt.allocPrint(emitter.allocator, "%_nego_{d}", .{tmp_id});
            defer emitter.allocator.free(ov_ssa);
            try emitInlineTrapIfTrue(emitter, state, ov_ssa, 2);
            try state.print(
                "  %_v_{d} = extractvalue {{ i{d}, i1 }} %_negp_{d}, 0\n",
                .{ dst_raw, info.bits, tmp_id },
            );
        },

        .neg_wrap => {
            const info = resolveIntegerInfo(emitter, unwrapped_dst) orelse return;
            try state.print("  %_v_{d} = sub i{d} 0, %_v_{d}\n", .{ dst_raw, info.bits, s_raw });
        },

        .fneg => {
            const flt_ty = if (unwrapped_dst == .f32_ty) "float" else "double";
            try state.print("  %_v_{d} = fneg {s} %_v_{d}\n", .{ dst_raw, flt_ty, s_raw });
        },

        .bool_not => {
            try state.print("  %_v_{d} = xor i1 %_v_{d}, true\n", .{ dst_raw, s_raw });
        },

        .bit_not => {
            if (unwrapped_dst == .bool_ty) {
                try state.print("  %_v_{d} = xor i1 %_v_{d}, true\n", .{ dst_raw, s_raw });
            } else if (resolveIntegerInfo(emitter, unwrapped_dst)) |info| {
                try state.print("  %_v_{d} = xor i{d} %_v_{d}, -1\n", .{ dst_raw, info.bits, s_raw });
            } else if (!unwrapped_dst.isPrimitiveOrSentinel() and
                emitter.input.pool.getNode(unwrapped_dst).tag == .array_ty)
            {
                const arr_node = emitter.input.pool.getNode(unwrapped_dst);
                const lane_ty = try unwrapTransparentType(emitter, TypeId.fromInt(arr_node.lhs));
                const lanes: u64 = arr_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                if (lanes == 0) {
                    const empty_ty = try formatLlvmValueType(emitter, unwrapped_dst);
                    defer emitter.allocator.free(empty_ty);
                    try state.print(
                        "  %_v_{d} = select i1 true, {s} zeroinitializer, {s} zeroinitializer\n",
                        .{ dst_raw, empty_ty, empty_ty },
                    );
                } else {
                    const arr_lay = try emitter.resolver.resolveType(unwrapped_dst);
                    const lane_mem = try formatLlvmMemoryType(emitter, lane_ty);
                    defer emitter.allocator.free(lane_mem);
                    const lane_bits: u16 = if (lane_ty == .bool_ty)
                        8
                    else if (resolveIntegerInfo(emitter, lane_ty)) |lane_info|
                        lane_info.bits
                    else
                        8;
                    const mask_lit = if (lane_ty == .bool_ty) "1" else "-1";
                    var mask_buf: std.ArrayListUnmanaged(u8) = .empty;
                    defer mask_buf.deinit(emitter.allocator);
                    try mask_buf.append(emitter.allocator, '<');
                    var lane_i: u64 = 0;
                    while (lane_i < lanes) : (lane_i += 1) {
                        if (lane_i > 0) try mask_buf.appendSlice(emitter.allocator, ", ");
                        const piece = try std.fmt.allocPrint(emitter.allocator, "i{d} {s}", .{ lane_bits, mask_lit });
                        defer emitter.allocator.free(piece);
                        try mask_buf.appendSlice(emitter.allocator, piece);
                    }
                    try mask_buf.append(emitter.allocator, '>');

                    const vec_align = @max(arr_lay.alignBytes(), 16);
                    const vec_store_bytes = std.math.ceilPowerOfTwo(u64, @max(arr_lay.size_bytes, 1)) catch arr_lay.size_bytes;
                    const slot = try state.allocEntryBytes(vec_store_bytes, vec_align);
                    defer emitter.allocator.free(slot);
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  store [{d} x {s}] %_v_{d}, ptr {s}, align {d}\n" ++
                            "  %_bnv_{d} = load <{d} x i{d}>, ptr {s}, align {d}\n" ++
                            "  %_bno_{d} = xor <{d} x i{d}> %_bnv_{d}, {s}\n" ++
                            "  store <{d} x i{d}> %_bno_{d}, ptr {s}, align {d}\n" ++
                            "  %_v_{d} = load [{d} x {s}], ptr {s}, align {d}\n",
                        .{
                            lanes,     lane_mem,  s_raw,          slot,
                            vec_align, tmp_id,    lanes,          lane_bits,
                            slot,      vec_align, tmp_id,         lanes,
                            lane_bits, tmp_id,    mask_buf.items, lanes,
                            lane_bits, tmp_id,    slot,           vec_align,
                            dst_raw,   lanes,     lane_mem,       slot,
                            vec_align,
                        },
                    );
                }
            }
        },

        .int_sext, .int_zext, .int_trunc => {
            const src_bits: u16 = if (src_ty == .bool_ty)
                1
            else if (resolveIntegerInfo(emitter, src_ty)) |si|
                si.bits
            else
                32;
            if (unwrapped_dst == .bool_ty) {
                if (src_bits == 1) {
                    try state.print("  %_v_{d} = or i1 %_v_{d}, false\n", .{ dst_raw, s_raw });
                } else {
                    try state.print("  %_v_{d} = trunc i{d} %_v_{d} to i1\n", .{ dst_raw, src_bits, s_raw });
                }
                return;
            }
            const dst_info = resolveIntegerInfo(emitter, unwrapped_dst) orelse return;
            if (src_bits == dst_info.bits) {
                try state.print("  %_v_{d} = add i{d} %_v_{d}, 0\n", .{ dst_raw, dst_info.bits, s_raw });
            } else if (src_bits < dst_info.bits) {
                const ext_op = if (kind == .int_sext and src_ty != .bool_ty) "sext" else "zext";
                try state.print(
                    "  %_v_{d} = {s} i{d} %_v_{d} to i{d}\n",
                    .{ dst_raw, ext_op, src_bits, s_raw, dst_info.bits },
                );
            } else {
                try state.print(
                    "  %_v_{d} = trunc i{d} %_v_{d} to i{d}\n",
                    .{ dst_raw, src_bits, s_raw, dst_info.bits },
                );
            }
        },

        .int_to_float_signed, .int_to_float_unsigned => {
            const src_bits: u16 = if (src_ty == .bool_ty)
                1
            else if (resolveIntegerInfo(emitter, src_ty)) |si|
                si.bits
            else
                32;
            const flt_ty = if (unwrapped_dst == .f32_ty) "float" else "double";
            const conv_op = if (kind == .int_to_float_signed and src_ty != .bool_ty) "sitofp" else "uitofp";
            try state.print(
                "  %_v_{d} = {s} i{d} %_v_{d} to {s}\n",
                .{ dst_raw, conv_op, src_bits, s_raw, flt_ty },
            );
        },

        .float_to_int_signed, .float_to_int_unsigned => {
            const dst_info = resolveIntegerInfo(emitter, unwrapped_dst) orelse return;
            const is_signed = kind == .float_to_int_signed;
            try emitter.requireIntrinsicDecl("declare double @llvm.fabs.f64(double)");
            try emitter.requireIntrinsicDecl("declare double @llvm.trunc.f64(double)");

            const tmp_id = state.nextTmp();
            const f64_ssa = if (src_ty == .f32_ty) blk: {
                try state.print("  %_ftiw_{d} = fpext float %_v_{d} to double\n", .{ tmp_id, s_raw });
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_ftiw_{d}", .{tmp_id});
            } else try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{s_raw});
            defer emitter.allocator.free(f64_ssa);

            const min_f64: f64 = if (is_signed)
                std.math.ldexp(@as(f64, -1.0), @as(i32, @intCast(dst_info.bits - 1)))
            else
                0.0;
            const max_excl_f64: f64 = std.math.ldexp(
                @as(f64, 1.0),
                @as(i32, @intCast(if (is_signed) dst_info.bits - 1 else dst_info.bits)),
            );
            const min_hex = try formatLlvmHexFloatLiteral(emitter.allocator, false, min_f64);
            defer emitter.allocator.free(min_hex);
            const max_hex = try formatLlvmHexFloatLiteral(emitter.allocator, false, max_excl_f64);
            defer emitter.allocator.free(max_hex);

            try state.print(
                "  %_ftia_{d} = call double @llvm.fabs.f64(double {s})\n" ++
                    "  %_ftibad_{d} = fcmp uge double %_ftia_{d}, 0x7FF0000000000000\n" ++
                    "  %_ftitr_{d} = call double @llvm.trunc.f64(double {s})\n" ++
                    "  %_ftilt_{d} = fcmp olt double %_ftitr_{d}, {s}\n" ++
                    "  %_ftige_{d} = fcmp oge double %_ftitr_{d}, {s}\n" ++
                    "  %_ftio1_{d} = or i1 %_ftibad_{d}, %_ftilt_{d}\n" ++
                    "  %_ftioob_{d} = or i1 %_ftio1_{d}, %_ftige_{d}\n",
                .{
                    tmp_id,  f64_ssa,
                    tmp_id,  tmp_id,
                    tmp_id,  f64_ssa,
                    tmp_id,  tmp_id,
                    min_hex, tmp_id,
                    tmp_id,  max_hex,
                    tmp_id,  tmp_id,
                    tmp_id,  tmp_id,
                    tmp_id,  tmp_id,
                },
            );
            const oob_ssa = try std.fmt.allocPrint(emitter.allocator, "%_ftioob_{d}", .{tmp_id});
            defer emitter.allocator.free(oob_ssa);
            try emitInlineTrapIfTrue(emitter, state, oob_ssa, 2);

            const conv_op = if (is_signed) "fptosi" else "fptoui";
            try state.print(
                "  %_v_{d} = {s} double %_ftitr_{d} to i{d}\n",
                .{ dst_raw, conv_op, tmp_id, dst_info.bits },
            );
        },

        .float_promote => {
            try state.print("  %_v_{d} = fpext float %_v_{d} to double\n", .{ dst_raw, s_raw });
        },

        .float_demote => {
            try state.print("  %_v_{d} = fptrunc double %_v_{d} to float\n", .{ dst_raw, s_raw });
        },

        .bitcast_op => {
            if (try isZeroSizedType(emitter, unwrapped_dst)) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            if (try tryEmitSliceArrayPtrCoercionLlvm(
                emitter,
                state,
                body,
                dst_raw,
                s_raw,
                src_ty,
                unwrapped_dst,
            )) return;
            const dst_lay = try emitter.resolver.resolveType(unwrapped_dst);
            const src_lay = try emitter.resolver.resolveType(src_ty);
            const scratch = try state.allocEntryBytes(
                @max(dst_lay.size_bytes, src_lay.size_bytes),
                @max(dst_lay.alignBytes(), src_lay.alignBytes()),
            );
            defer emitter.allocator.free(scratch);
            try emitMemsetZero(
                emitter,
                state,
                scratch,
                @max(dst_lay.size_bytes, src_lay.size_bytes),
                @max(dst_lay.alignBytes(), src_lay.alignBytes()),
            );
            const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{s_raw});
            defer emitter.allocator.free(src_ssa);
            try emitStoreValueToPtr(emitter, state, src_ty, src_ssa, scratch, src_lay.alignBytes(), 0, 0, 0);
            const loaded = try emitLoadValueFromPtr(
                emitter,
                state,
                unwrapped_dst,
                scratch,
                dst_lay.alignBytes(),
                null,
                0,
                0,
                0,
            );
            defer emitter.allocator.free(loaded);
            const dst_val_ty = try formatLlvmValueType(emitter, unwrapped_dst);
            defer emitter.allocator.free(dst_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, dst_val_ty, loaded, dst_val_ty, loaded },
            );
        },

        .ptr_cast => {
            if (try tryEmitSliceArrayPtrCoercionLlvm(
                emitter,
                state,
                body,
                dst_raw,
                s_raw,
                src_ty,
                unwrapped_dst,
            )) return;
            const src_val_ty = try formatLlvmValueType(emitter, src_ty);
            defer emitter.allocator.free(src_val_ty);
            const dst_val_ty = try formatLlvmValueType(emitter, unwrapped_dst);
            defer emitter.allocator.free(dst_val_ty);

            const src_is_ptr = std.mem.eql(u8, src_val_ty, "ptr");
            const dst_is_ptr = std.mem.eql(u8, dst_val_ty, "ptr");
            if (src_is_ptr and dst_is_ptr) {
                try state.print("  %_v_{d} = select i1 true, ptr %_v_{d}, ptr %_v_{d}\n", .{ dst_raw, s_raw, s_raw });
            } else if (src_is_ptr and !dst_is_ptr) {
                const dst_info = resolveIntegerInfo(emitter, unwrapped_dst) orelse
                    IntScalarInfo{ .bits = @as(u16, emitter.cfg.target.ptrBytes()) * 8, .is_signed = false };
                try state.print("  %_v_{d} = ptrtoint ptr %_v_{d} to i{d}\n", .{ dst_raw, s_raw, dst_info.bits });
            } else if (!src_is_ptr and dst_is_ptr) {
                const src_info = resolveIntegerInfo(emitter, src_ty) orelse
                    IntScalarInfo{ .bits = @as(u16, emitter.cfg.target.ptrBytes()) * 8, .is_signed = false };
                try state.print("  %_v_{d} = inttoptr i{d} %_v_{d} to ptr\n", .{ dst_raw, src_info.bits, s_raw });
            } else {
                try state.print(
                    "  %_v_{d} = select i1 true, {s} %_v_{d}, {s} %_v_{d}\n",
                    .{ dst_raw, dst_val_ty, s_raw, dst_val_ty, s_raw },
                );
            }
        },

        .ssa_discriminant => {
            if (try isZeroSizedType(emitter, src_ty)) {
                const detail_opt = try emitter.resolver.getSumDetail(src_ty);
                const d_val: u32 = if (detail_opt) |sd| sd.payload_discriminant else 0;
                const dst_info = resolveIntegerInfo(emitter, unwrapped_dst) orelse
                    IntScalarInfo{ .bits = 32, .is_signed = false };
                try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, d_val });
                return;
            }
            const src_lay = try emitter.resolver.resolveType(src_ty);
            const scratch = try state.allocEntryBytes(src_lay.size_bytes, src_lay.alignBytes());
            defer emitter.allocator.free(scratch);
            const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{s_raw});
            defer emitter.allocator.free(src_ssa);
            try emitStoreValueToPtr(emitter, state, src_ty, src_ssa, scratch, src_lay.alignBytes(), 0, 0, 0);

            if ((try emitter.resolver.getSumDetail(src_ty)) != null or
                (!src_ty.isPrimitiveOrSentinel() and emitter.input.pool.getNode(src_ty).tag == .enum_ty))
            {
                const disc_32 = try emitReadSumDiscriminantFromPtr(
                    emitter,
                    state,
                    src_ty,
                    scratch,
                    src_lay.alignBytes(),
                );
                defer emitter.allocator.free(disc_32);
                const dst_info = resolveIntegerInfo(emitter, unwrapped_dst) orelse
                    IntScalarInfo{ .bits = 32, .is_signed = false };
                if (dst_info.bits == 32) {
                    try state.print("  %_v_{d} = add i32 {s}, 0\n", .{ dst_raw, disc_32 });
                } else if (dst_info.bits < 32) {
                    try state.print("  %_v_{d} = trunc i32 {s} to i{d}\n", .{ dst_raw, disc_32, dst_info.bits });
                } else {
                    try state.print("  %_v_{d} = zext i32 {s} to i{d}\n", .{ dst_raw, disc_32, dst_info.bits });
                }
            } else {
                const loaded = try emitLoadValueFromPtr(
                    emitter,
                    state,
                    unwrapped_dst,
                    scratch,
                    src_lay.alignBytes(),
                    null,
                    0,
                    0,
                    0,
                );
                defer emitter.allocator.free(loaded);
                const dst_val_ty = try formatLlvmValueType(emitter, unwrapped_dst);
                defer emitter.allocator.free(dst_val_ty);
                try state.print(
                    "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                    .{ dst_raw, dst_val_ty, loaded, dst_val_ty, loaded },
                );
            }
        },

        .ssa_variant_payload => {
            if (try isZeroSizedType(emitter, unwrapped_dst)) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const src_lay = try emitter.resolver.resolveType(src_ty);
            const scratch = try state.allocEntryBytes(src_lay.size_bytes, src_lay.alignBytes());
            defer emitter.allocator.free(scratch);
            const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{s_raw});
            defer emitter.allocator.free(src_ssa);
            try emitStoreValueToPtr(emitter, state, src_ty, src_ssa, scratch, src_lay.alignBytes(), 0, 0, 0);

            const detail_opt = try emitter.resolver.getSumDetail(src_ty);
            const pay_off: u64 = if (detail_opt) |sd| sd.payload_offset else 0;
            _ = rhs_ord;
            const pay_ptr = if (pay_off == 0)
                try emitter.allocator.dupe(u8, scratch)
            else blk: {
                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_svpp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                    .{ tmp_id, scratch, ptr_int, pay_off },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_svpp_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(pay_ptr);

            const dst_lay = try emitter.resolver.resolveType(unwrapped_dst);
            const loaded = try emitLoadValueFromPtr(
                emitter,
                state,
                unwrapped_dst,
                pay_ptr,
                @min(src_lay.alignBytes(), effectiveOffsetAlign(pay_off, dst_lay.alignBytes())),
                null,
                0,
                0,
                0,
            );
            defer emitter.allocator.free(loaded);
            const dst_val_ty = try formatLlvmValueType(emitter, unwrapped_dst);
            defer emitter.allocator.free(dst_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, dst_val_ty, loaded, dst_val_ty, loaded },
            );
        },
    }
}

/// Emits `MirOp.aggregate_make` into `%_v_<dst_raw>` with zeroed `@zero_pad` memory semantics (`D-01`).
fn emitAggregateMakeLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body_idx: u32,
    body: *const MirBody,
    dst_raw: u32,
    kind: mir.AggregateKind,
    inst: mir.MirInst,
) !void {
    if (try isZeroSizedType(emitter, inst.type_id)) {
        try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        return;
    }
    const ptr_int = ptrIntType(emitter);
    const agg_ty = try unwrapTransparentType(emitter, inst.type_id);

    switch (kind) {
        .closure_make => {
            const is_three_w = codegen_abi.isThreeWordClosureType(emitter.input.pool, agg_ty);
            const clos_val_ty = if (is_three_w) "{ ptr, ptr, ptr }" else "{ ptr, ptr }";
            const key: u64 = (@as(u64, body_idx) << 32) | @as(u64, dst_raw);
            const thunk_idx = emitter.closure_thunk_map.get(key) orelse {
                try state.print(
                    "  %_v_{d} = select i1 true, {s} zeroinitializer, {s} zeroinitializer\n",
                    .{ dst_raw, clos_val_ty, clos_val_ty },
                );
                return;
            };
            const thunk = emitter.closure_thunks.items[thunk_idx];
            var env_size: u64 = 0;
            var env_align: u32 = emitter.cfg.target.ptrBytes();
            for (thunk.capture_types) |cap_ty| {
                const cap_lay = try emitter.resolver.resolveType(cap_ty);
                if (cap_lay.size_bytes == 0) continue;
                env_align = @max(env_align, cap_lay.alignBytes());
                env_size = std.mem.alignForward(u64, env_size, @max(@as(u64, cap_lay.alignBytes()), 1));
                env_size += cap_lay.size_bytes;
            }
            const env_ptr_s = if (env_size == 0)
                try std.fmt.allocPrint(
                    emitter.allocator,
                    "inttoptr ({s} {d} to ptr)",
                    .{ ptr_int, emitter.cfg.target.ptrBytes() },
                )
            else blk: {
                const env_slot = if (thunk.is_three_word) heap: {
                    if (!emitter.declared_externs.contains("calloc")) {
                        try emitter.requireIntrinsicDecl(
                            if (emitter.cfg.target.isWasm())
                                "declare ptr @calloc(i32, i32) nounwind"
                            else
                                "declare ptr @calloc(i64, i64) nounwind",
                        );
                    }
                    const hp_id = state.nextTmp();
                    try state.print(
                        "  %_cenv_hp_{d} = call ptr @calloc({s} 1, {s} {d})\n" ++
                            "  %_cenv_oom_{d} = icmp eq ptr %_cenv_hp_{d}, null\n",
                        .{ hp_id, ptr_int, ptr_int, env_size, hp_id, hp_id },
                    );
                    const oom_s = try std.fmt.allocPrint(emitter.allocator, "%_cenv_oom_{d}", .{hp_id});
                    defer emitter.allocator.free(oom_s);
                    try emitInlineTrapIfTrue(emitter, state, oom_s, 0);
                    break :heap try std.fmt.allocPrint(emitter.allocator, "%_cenv_hp_{d}", .{hp_id});
                } else stack: {
                    const s_slot = try state.allocEntryBytes(env_size, env_align);
                    try emitMemsetZero(emitter, state, s_slot, env_size, env_align);
                    break :stack s_slot;
                };
                var cur_off: u64 = 0;
                for (thunk.capture_types, 0..) |cap_ty, cap_i| {
                    const cap_lay = try emitter.resolver.resolveType(cap_ty);
                    if (cap_lay.size_bytes == 0) continue;
                    cur_off = std.mem.alignForward(u64, cur_off, @max(@as(u64, cap_lay.alignBytes()), 1));
                    const cap_val_raw = body.extra_args.items[inst.operands.rhs + 1 + cap_i];
                    const dst_p = if (cur_off == 0)
                        try emitter.allocator.dupe(u8, env_slot)
                    else sub: {
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_cenv_p_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ t_id, env_slot, ptr_int, cur_off },
                        );
                        break :sub try std.fmt.allocPrint(emitter.allocator, "%_cenv_p_{d}", .{t_id});
                    };
                    defer emitter.allocator.free(dst_p);
                    const cap_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{cap_val_raw});
                    defer emitter.allocator.free(cap_ssa);
                    const eff_cap_align = if (thunk.is_three_word)
                        @min(@max(emitter.cfg.target.ptrBytes(), 8), effectiveOffsetAlign(cur_off, cap_lay.alignBytes()))
                    else
                        cap_lay.alignBytes();
                    try emitStoreValueToPtr(emitter, state, cap_ty, cap_ssa, dst_p, eff_cap_align, 0, 0, 0);
                    cur_off += cap_lay.size_bytes;
                }
                break :blk env_slot;
            };
            defer emitter.allocator.free(env_ptr_s);

            const tmp_id = state.nextTmp();
            if (thunk.is_three_word) {
                const drop_fn_s = if (env_size == 0)
                    try emitter.allocator.dupe(u8, "null")
                else
                    try std.fmt.allocPrint(emitter.allocator, "@_cx_cdrop_{d}", .{thunk_idx});
                defer emitter.allocator.free(drop_fn_s);
                try state.print(
                    "  %_cm0_{d} = insertvalue {{ ptr, ptr, ptr }} zeroinitializer, ptr {s}, 0\n" ++
                        "  %_cm1_{d} = insertvalue {{ ptr, ptr, ptr }} %_cm0_{d}, ptr @_cx_cthunk_{d}, 1\n" ++
                        "  %_v_{d} = insertvalue {{ ptr, ptr, ptr }} %_cm1_{d}, ptr {s}, 2\n",
                    .{ tmp_id, env_ptr_s, tmp_id, tmp_id, thunk_idx, dst_raw, tmp_id, drop_fn_s },
                );
            } else {
                try state.print(
                    "  %_cm0_{d} = insertvalue {{ ptr, ptr }} zeroinitializer, ptr {s}, 0\n" ++
                        "  %_v_{d} = insertvalue {{ ptr, ptr }} %_cm0_{d}, ptr @_cx_cthunk_{d}, 1\n",
                    .{ tmp_id, env_ptr_s, dst_raw, tmp_id, thunk_idx },
                );
            }
            return;
        },

        .fmt_args_make => {
            const words = body.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
            var piece_count: usize = 0;
            if (words.len >= 1) {
                const p_inst = body.getInst(MirValueId.fromInt(words[0]));
                if (p_inst.op == .const_scalar and p_inst.operands.lhs < body.consts.items.len) {
                    switch (body.consts.items[p_inst.operands.lhs]) {
                        .int_val => |iv| piece_count = @intCast(@as(u128, @bitCast(iv))),
                        else => {},
                    }
                }
            }
            const hole_count: usize = if (1 + piece_count <= words.len) (words.len - 1 - piece_count) / 3 else 0;
            const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();

            // Static `.rodata` fast-path for 0-hole constant `FmtArgs` literals:
            if (hole_count == 0 and piece_count >= 1 and 1 + piece_count <= words.len) {
                var is_all_const_str = true;
                for (words[1 .. 1 + piece_count]) |piece_raw| {
                    const p_inst = body.getInst(MirValueId.fromInt(piece_raw));
                    if (p_inst.op != .const_scalar or p_inst.operands.lhs >= body.consts.items.len) {
                        is_all_const_str = false;
                        break;
                    }
                    switch (body.consts.items[p_inst.operands.lhs]) {
                        .str_val => {},
                        else => {
                            is_all_const_str = false;
                            break;
                        },
                    }
                }
                if (is_all_const_str) {
                    const sid = emitter.nextSynthGlobalId();
                    const hdr_s = try std.fmt.allocPrint(
                        emitter.allocator,
                        "@_cx_fsp_{d} = private unnamed_addr constant [{d} x {{ ptr, {s} }}] [",
                        .{ sid, piece_count, ptr_int },
                    );
                    defer emitter.allocator.free(hdr_s);
                    try emitter.synth_globals.appendSlice(emitter.allocator, hdr_s);
                    for (words[1 .. 1 + piece_count], 0..) |piece_raw, p_idx| {
                        if (p_idx > 0) try emitter.synth_globals.appendSlice(emitter.allocator, ", ");
                        const p_inst = body.getInst(MirValueId.fromInt(piece_raw));
                        const sym_id = body.consts.items[p_inst.operands.lhs].str_val;
                        const raw_s = emitter.input.interner.get(sym_id);
                        const p_expr = if (raw_s.len == 0)
                            try emitter.allocator.dupe(u8, "@_cx_empty_cstr")
                        else
                            try std.fmt.allocPrint(emitter.allocator, "@_cx_str_bytes_{d}", .{sym_id.asInt()});
                        defer emitter.allocator.free(p_expr);
                        const elem_s = try std.fmt.allocPrint(
                            emitter.allocator,
                            "{{ ptr, {s} }} {{ ptr {s}, {s} {d} }}",
                            .{ ptr_int, p_expr, ptr_int, raw_s.len },
                        );
                        defer emitter.allocator.free(elem_s);
                        try emitter.synth_globals.appendSlice(emitter.allocator, elem_s);
                    }
                    const tail_s = try std.fmt.allocPrint(emitter.allocator, "], align {d}\n", .{ptr_bytes});
                    defer emitter.allocator.free(tail_s);
                    try emitter.synth_globals.appendSlice(emitter.allocator, tail_s);

                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  %_fa0_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} zeroinitializer, ptr @_cx_fsp_{d}, 0\n" ++
                            "  %_fa1_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} %_fa0_{d}, {s} {d}, 1\n" ++
                            "  %_fa2_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} %_fa1_{d}, ptr null, 2\n" ++
                            "  %_v_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} %_fa2_{d}, {s} 0, 3\n",
                        .{
                            tmp_id,  ptr_int,     ptr_int, sid,
                            tmp_id,  ptr_int,     ptr_int, tmp_id,
                            ptr_int, piece_count, tmp_id,  ptr_int,
                            ptr_int, tmp_id,      dst_raw, ptr_int,
                            ptr_int, tmp_id,      ptr_int,
                        },
                    );
                    return;
                }
            }

            const piece_stride: u64 = 2 * @as(u64, ptr_bytes);
            const pieces_slot = try state.allocEntryBytes(@max(@as(u64, piece_count) * piece_stride, 1), ptr_bytes);
            defer emitter.allocator.free(pieces_slot);
            if (1 + piece_count <= words.len) {
                for (words[1 .. 1 + piece_count], 0..) |piece_raw, p_idx| {
                    const p_off: u64 = @as(u64, p_idx) * piece_stride;
                    const p_dst = if (p_off == 0)
                        try emitter.allocator.dupe(u8, pieces_slot)
                    else blk: {
                        const sub_id = state.nextTmp();
                        try state.print(
                            "  %_fap_p_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ sub_id, pieces_slot, ptr_int, p_off },
                        );
                        break :blk try std.fmt.allocPrint(emitter.allocator, "%_fap_p_{d}", .{sub_id});
                    };
                    defer emitter.allocator.free(p_dst);
                    try state.print(
                        "  store {{ ptr, {s} }} %_v_{d}, ptr {s}, align {d}\n",
                        .{ ptr_int, piece_raw, p_dst, ptr_bytes },
                    );
                }
            }

            const arg_stride: u64 = std.mem.alignForward(u64, 2 * @as(u64, ptr_bytes) + 8, @as(u64, ptr_bytes));
            const args_ptr_s = if (hole_count == 0)
                try emitter.allocator.dupe(u8, "null")
            else blk: {
                const args_slot = try state.allocEntryBytes(@as(u64, hole_count) * arg_stride, ptr_bytes);
                var hole_j: usize = 0;
                while (hole_j < hole_count) : (hole_j += 1) {
                    const href_raw = words[1 + piece_count + hole_j * 3];
                    const spec_lo_raw = words[1 + piece_count + hole_j * 3 + 1];
                    const spec_hi_raw = words[1 + piece_count + hole_j * 3 + 2];

                    const href_ty = try unwrapTransparentType(
                        emitter,
                        body.getInst(MirValueId.fromInt(href_raw)).type_id,
                    );
                    const href_node = emitter.input.pool.getNode(href_ty);
                    const is_ptr_arg = (href_node.tag == .ref_ty or
                        href_node.tag == .mut_ref_ty or
                        href_node.tag == .raw_ptr_ty) and
                        !emitter.input.pool.isSliceRefType(href_ty);
                    const hval_ty = try unwrapTransparentType(
                        emitter,
                        if (is_ptr_arg) TypeId.fromInt(href_node.lhs) else href_ty,
                    );
                    const data_ptr_s = if (is_ptr_arg)
                        try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{href_raw})
                    else spill: {
                        const h_lay = try emitter.resolver.resolveType(hval_ty);
                        const h_slot = try state.allocEntryBytes(@max(h_lay.size_bytes, 1), h_lay.alignBytes());
                        if (!(try isZeroSizedType(emitter, hval_ty))) {
                            const h_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{href_raw});
                            defer emitter.allocator.free(h_ssa);
                            try emitStoreValueToPtr(emitter, state, hval_ty, h_ssa, h_slot, h_lay.alignBytes(), 0, 0, 0);
                        }
                        break :spill h_slot;
                    };
                    defer emitter.allocator.free(data_ptr_s);

                    const base_off: u64 = @as(u64, hole_j) * arg_stride;
                    const sub_id = state.nextTmp();
                    const d_ptr = if (base_off == 0)
                        try emitter.allocator.dupe(u8, args_slot)
                    else dp: {
                        try state.print(
                            "  %_faa_d_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ sub_id, args_slot, ptr_int, base_off },
                        );
                        break :dp try std.fmt.allocPrint(emitter.allocator, "%_faa_d_{d}", .{sub_id});
                    };
                    defer emitter.allocator.free(d_ptr);

                    try state.print(
                        "  store ptr {s}, ptr {s}, align {d}\n" ++
                            "  %_faa_f_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  store ptr @_cx_fmt_ty_{d}, ptr %_faa_f_{d}, align {d}\n" ++
                            "  %_faa_l_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  store i32 %_v_{d}, ptr %_faa_l_{d}, align 4\n",
                        .{
                            data_ptr_s,           d_ptr,                              ptr_bytes,
                            sub_id,               args_slot,                          ptr_int,
                            base_off + ptr_bytes, hval_ty.toU32(),                    sub_id,
                            ptr_bytes,            sub_id,                             args_slot,
                            ptr_int,              base_off + 2 * @as(u64, ptr_bytes), spec_lo_raw,
                            sub_id,
                        },
                    );
                    try state.print(
                        "  %_faa_w_{d} = trunc i32 %_v_{d} to i16\n" ++
                            "  %_faa_hs_{d} = lshr i32 %_v_{d}, 16\n" ++
                            "  %_faa_pr_{d} = trunc i32 %_faa_hs_{d} to i16\n" ++
                            "  %_faa_wp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  store i16 %_faa_w_{d}, ptr %_faa_wp_{d}, align 2\n" ++
                            "  %_faa_pp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  store i16 %_faa_pr_{d}, ptr %_faa_pp_{d}, align 2\n",
                        .{
                            sub_id,  spec_hi_raw,                            sub_id,  spec_hi_raw,
                            sub_id,  sub_id,                                 sub_id,  args_slot,
                            ptr_int, base_off + 2 * @as(u64, ptr_bytes) + 4, sub_id,  sub_id,
                            sub_id,  args_slot,                              ptr_int, base_off + 2 * @as(u64, ptr_bytes) + 6,
                            sub_id,  sub_id,
                        },
                    );
                }
                break :blk args_slot;
            };
            defer emitter.allocator.free(args_ptr_s);

            const tmp_id = state.nextTmp();
            try state.print(
                "  %_fa0_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} zeroinitializer, ptr {s}, 0\n" ++
                    "  %_fa1_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} %_fa0_{d}, {s} {d}, 1\n" ++
                    "  %_fa2_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} %_fa1_{d}, ptr {s}, 2\n" ++
                    "  %_v_{d} = insertvalue {{ ptr, {s}, ptr, {s} }} %_fa2_{d}, {s} {d}, 3\n",
                .{
                    tmp_id,     ptr_int,     ptr_int,    pieces_slot,
                    tmp_id,     ptr_int,     ptr_int,    tmp_id,
                    ptr_int,    piece_count, tmp_id,     ptr_int,
                    ptr_int,    tmp_id,      args_ptr_s, dst_raw,
                    ptr_int,    ptr_int,     tmp_id,     ptr_int,
                    hole_count,
                },
            );
            return;
        },

        .str_concat => {
            if (!emitter.declared_externs.contains("malloc")) {
                try emitter.requireIntrinsicDecl(
                    if (emitter.cfg.target.isWasm())
                        "declare ptr @malloc(i32) nounwind"
                    else
                        "declare ptr @malloc(i64) nounwind",
                );
            }
            const uadd_decl = try std.fmt.allocPrint(
                emitter.allocator,
                "declare {{ {s}, i1 }} @llvm.uadd.with.overflow.{s}({s}, {s})",
                .{ ptr_int, ptr_int, ptr_int, ptr_int },
            );
            defer emitter.allocator.free(uadd_decl);
            try emitter.requireIntrinsicDecl(uadd_decl);

            const parts = body.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
            const tmp_id = state.nextTmp();
            const part_ptrs = try emitter.allocator.alloc([]u8, parts.len);
            defer {
                for (part_ptrs) |ps| emitter.allocator.free(ps);
                emitter.allocator.free(part_ptrs);
            }
            const part_lens = try emitter.allocator.alloc([]u8, parts.len);
            defer {
                for (part_lens) |ls| emitter.allocator.free(ls);
                emitter.allocator.free(part_lens);
            }

            var tot_ssa = try emitter.allocator.dupe(u8, "0");
            defer emitter.allocator.free(tot_ssa);

            for (parts, 0..) |part_raw, pk| {
                const part_ty = try unwrapTransparentType(
                    emitter,
                    body.getInst(MirValueId.fromInt(part_raw)).type_id,
                );
                const sub_id = state.nextTmp();
                if (part_ty == .str_ty) {
                    try state.print(
                        "  %_scp_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 0\n" ++
                            "  %_scl_{d} = extractvalue {{ ptr, {s} }} %_v_{d}, 1\n",
                        .{ sub_id, ptr_int, part_raw, sub_id, ptr_int, part_raw },
                    );
                    part_ptrs[pk] = try std.fmt.allocPrint(emitter.allocator, "%_scp_{d}", .{sub_id});
                    part_lens[pk] = try std.fmt.allocPrint(emitter.allocator, "%_scl_{d}", .{sub_id});
                } else if (part_ty == .bool_ty) {
                    try state.print(
                        "  %_scp_{d} = select i1 %_v_{d}, ptr @.cx_str_true, ptr @.cx_str_false\n" ++
                            "  %_scl_{d} = select i1 %_v_{d}, {s} 4, {s} 5\n",
                        .{ sub_id, part_raw, sub_id, part_raw, ptr_int, ptr_int },
                    );
                    part_ptrs[pk] = try std.fmt.allocPrint(emitter.allocator, "%_scp_{d}", .{sub_id});
                    part_lens[pk] = try std.fmt.allocPrint(emitter.allocator, "%_scl_{d}", .{sub_id});
                } else if (resolveIntegerInfo(emitter, part_ty)) |p_int| {
                    const fmt_buf = try state.allocEntryBytes(64, 8);
                    if (p_int.bits == 128) {
                        if (p_int.is_signed) {
                            try ensureFmtI128Helper(emitter);
                            try state.print(
                                "  %_sccl_{d} = call i32 @_cx_rt_fmt_i128(ptr {s}, i128 %_v_{d})\n",
                                .{ sub_id, fmt_buf, part_raw },
                            );
                        } else {
                            try ensureFmtU128Helper(emitter);
                            try state.print(
                                "  %_sccl_{d} = call i32 @_cx_rt_fmt_u128(ptr {s}, i128 %_v_{d})\n",
                                .{ sub_id, fmt_buf, part_raw },
                            );
                        }
                    } else {
                        const ext_op = if (p_int.bits < 64)
                            (if (p_int.is_signed) "sext" else "zext")
                        else
                            "trunc";
                        if (p_int.bits == 64) {
                            try state.print("  %_sci64_{d} = add i64 %_v_{d}, 0\n", .{ sub_id, part_raw });
                        } else {
                            try state.print(
                                "  %_sci64_{d} = {s} i{d} %_v_{d} to i64\n",
                                .{ sub_id, ext_op, p_int.bits, part_raw },
                            );
                        }
                        const fmt_sym = if (p_int.is_signed) "@.cx_fmt_i64" else "@.cx_fmt_u64";
                        try state.print(
                            "  %_scn32_{d} = call i32 (ptr, {s}, ptr, ...) @snprintf(" ++
                                "ptr {s}, {s} 64, ptr {s}, i64 %_sci64_{d})\n" ++
                                "  %_scpos_{d} = icmp sgt i32 %_scn32_{d}, 0\n" ++
                                "  %_sccl_{d} = select i1 %_scpos_{d}, i32 %_scn32_{d}, i32 0\n",
                            .{
                                sub_id, ptr_int, fmt_buf, ptr_int, fmt_sym, sub_id,
                                sub_id, sub_id,  sub_id,  sub_id,  sub_id,
                            },
                        );
                    }
                    if (emitter.cfg.target.isWasm()) {
                        try state.print("  %_scl_{d} = add i32 %_sccl_{d}, 0\n", .{ sub_id, sub_id });
                    } else {
                        try state.print("  %_scl_{d} = zext i32 %_sccl_{d} to i64\n", .{ sub_id, sub_id });
                    }
                    part_ptrs[pk] = fmt_buf;
                    part_lens[pk] = try std.fmt.allocPrint(emitter.allocator, "%_scl_{d}", .{sub_id});
                } else {
                    part_ptrs[pk] = try emitter.allocator.dupe(u8, "@_cx_empty_cstr");
                    part_lens[pk] = try emitter.allocator.dupe(u8, "0");
                }
                const add_id = state.nextTmp();
                try state.print(
                    "  %_scovp_{d} = call {{ {s}, i1 }} @llvm.uadd.with.overflow.{s}({s} {s}, {s} {s})\n" ++
                        "  %_scovf_{d} = extractvalue {{ {s}, i1 }} %_scovp_{d}, 1\n",
                    .{
                        add_id, ptr_int, ptr_int, ptr_int, tot_ssa, ptr_int, part_lens[pk],
                        add_id, ptr_int, add_id,
                    },
                );
                const ov_ssa = try std.fmt.allocPrint(emitter.allocator, "%_scovf_{d}", .{add_id});
                defer emitter.allocator.free(ov_ssa);
                try emitInlineTrapIfTrue(emitter, state, ov_ssa, 1);
                try state.print(
                    "  %_sctot_{d} = extractvalue {{ {s}, i1 }} %_scovp_{d}, 0\n",
                    .{ add_id, ptr_int, add_id },
                );
                emitter.allocator.free(tot_ssa);
                tot_ssa = try std.fmt.allocPrint(emitter.allocator, "%_sctot_{d}", .{add_id});
            }

            try state.print(
                "  %_sc_isz_{d} = icmp eq {s} {s}, 0\n" ++
                    "  br i1 %_sc_isz_{d}, label %_sc_empty_{d}, label %_sc_alloc_{d}\n" ++
                    "_sc_alloc_{d}:\n" ++
                    "  %_sc_ov1_{d} = call {{ {s}, i1 }} @llvm.uadd.with.overflow.{s}({s} {s}, {s} 1)\n" ++
                    "  %_sc_ovf_{d} = extractvalue {{ {s}, i1 }} %_sc_ov1_{d}, 1\n",
                .{
                    tmp_id,  ptr_int, tot_ssa, tmp_id,  tmp_id, tmp_id,  tmp_id, tmp_id, ptr_int,
                    ptr_int, ptr_int, tot_ssa, ptr_int, tmp_id, ptr_int, tmp_id,
                },
            );
            const nul_ov_ssa = try std.fmt.allocPrint(emitter.allocator, "%_sc_ovf_{d}", .{tmp_id});
            defer emitter.allocator.free(nul_ov_ssa);
            try emitInlineTrapIfTrue(emitter, state, nul_ov_ssa, 1);
            try state.print(
                "  %_sc_alsz_{d} = extractvalue {{ {s}, i1 }} %_sc_ov1_{d}, 0\n" ++
                    "  %_sc_buf_{d} = call ptr @malloc({s} %_sc_alsz_{d})\n" ++
                    "  %_sc_oom_{d} = icmp eq ptr %_sc_buf_{d}, null\n",
                .{ tmp_id, ptr_int, tmp_id, tmp_id, ptr_int, tmp_id, tmp_id, tmp_id },
            );
            const oom_ssa = try std.fmt.allocPrint(emitter.allocator, "%_sc_oom_{d}", .{tmp_id});
            defer emitter.allocator.free(oom_ssa);
            try emitInlineTrapIfTrue(emitter, state, oom_ssa, 0);

            var cur_off_s = try emitter.allocator.dupe(u8, "0");
            defer emitter.allocator.free(cur_off_s);
            try emitter.requireIntrinsicDecl(
                "declare void @llvm.memcpy.p0.p0.i64(ptr noalias nocapture writeonly, ptr noalias nocapture readonly, i64, i1 immarg)",
            );
            for (0..parts.len) |pk| {
                const cp_id = state.nextTmp();
                const len64_s = if (emitter.cfg.target.isWasm()) blk: {
                    try state.print("  %_scl64_{d} = zext i32 {s} to i64\n", .{ cp_id, part_lens[pk] });
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_scl64_{d}", .{cp_id});
                } else try emitter.allocator.dupe(u8, part_lens[pk]);
                defer emitter.allocator.free(len64_s);

                try state.print(
                    "  %_scdst_{d} = getelementptr inbounds i8, ptr %_sc_buf_{d}, {s} {s}\n" ++
                        "  call void @llvm.memcpy.p0.p0.i64(ptr align 1 %_scdst_{d}, ptr align 1 {s}, i64 {s}, i1 false)\n" ++
                        "  %_scnx_{d} = add {s} {s}, {s}\n",
                    .{
                        cp_id,   tmp_id,        ptr_int,       cur_off_s,
                        cp_id,   part_ptrs[pk], len64_s,       cp_id,
                        ptr_int, cur_off_s,     part_lens[pk],
                    },
                );
                emitter.allocator.free(cur_off_s);
                cur_off_s = try std.fmt.allocPrint(emitter.allocator, "%_scnx_{d}", .{cp_id});
            }
            const alloc_end_lbl = try emitter.allocator.dupe(u8, state.cur_label);
            defer emitter.allocator.free(alloc_end_lbl);

            try state.print(
                "  %_sc_nulp_{d} = getelementptr inbounds i8, ptr %_sc_buf_{d}, {s} {s}\n" ++
                    "  store i8 0, ptr %_sc_nulp_{d}, align 1\n" ++
                    "  br label %_sc_done_{d}\n" ++
                    "_sc_empty_{d}:\n" ++
                    "  br label %_sc_done_{d}\n" ++
                    "_sc_done_{d}:\n" ++
                    "  %_sc_fp_{d} = phi ptr [ %_sc_buf_{d}, %{s} ], [ @_cx_empty_cstr, %_sc_empty_{d} ]\n" ++
                    "  %_sc_f0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %_sc_fp_{d}, 0\n" ++
                    "  %_v_{d} = insertvalue {{ ptr, {s} }} %_sc_f0_{d}, {s} {s}, 1\n",
                .{
                    tmp_id,
                    tmp_id,
                    ptr_int,
                    tot_ssa,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    tmp_id,
                    alloc_end_lbl,
                    tmp_id,
                    tmp_id,
                    ptr_int,
                    tmp_id,
                    dst_raw,
                    ptr_int,
                    tmp_id,
                    ptr_int,
                    tot_ssa,
                },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_sc_done_{d}", .{tmp_id}));
            return;
        },

        else => {},
    }

    const agg_lay = try emitter.resolver.resolveType(agg_ty);
    const scratch = try state.allocEntryBytes(agg_lay.size_bytes, agg_lay.alignBytes());
    defer emitter.allocator.free(scratch);
    try emitMemsetZero(emitter, state, scratch, agg_lay.size_bytes, agg_lay.alignBytes());

    switch (kind) {
        .tuple_agg, .struct_agg => {
            const elems = body.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
            if (emitter.input.pool.getNode(agg_ty).tag == .union_ty) {
                for (elems) |elem_raw| {
                    const elem_ty = body.getInst(MirValueId.fromInt(elem_raw)).type_id;
                    if (try isZeroSizedType(emitter, elem_ty)) continue;
                    const elem_lay = try emitter.resolver.resolveType(elem_ty);
                    const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                    defer emitter.allocator.free(elem_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        elem_ty,
                        elem_ssa,
                        scratch,
                        @min(agg_lay.alignBytes(), elem_lay.alignBytes()),
                        0,
                        0,
                        0,
                    );
                }
            } else if (agg_ty == .fmt_spec_ty) {
                for (elems, 0..) |elem_raw, fld_i| {
                    const elem_ty = body.getInst(MirValueId.fromInt(elem_raw)).type_id;
                    const byte_off: u64 = switch (fld_i) {
                        0 => 0,
                        1 => 4,
                        else => 6,
                    };
                    const fld_align: u32 = if (fld_i == 0) 4 else 2;
                    const fld_ptr = if (byte_off == 0)
                        try emitter.allocator.dupe(u8, scratch)
                    else blk: {
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  %_agp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ tmp_id, scratch, ptr_int, byte_off },
                        );
                        break :blk try std.fmt.allocPrint(emitter.allocator, "%_agp_{d}", .{tmp_id});
                    };
                    defer emitter.allocator.free(fld_ptr);
                    const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                    defer emitter.allocator.free(elem_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        elem_ty,
                        elem_ssa,
                        fld_ptr,
                        fld_align,
                        0,
                        0,
                        0,
                    );
                }
            } else {
                for (elems, 0..) |elem_raw, fld_i| {
                    const elem_ty = body.getInst(MirValueId.fromInt(elem_raw)).type_id;
                    if (try isZeroSizedType(emitter, elem_ty)) continue;
                    const fld = (try emitter.resolver.getFieldByDeclOrdinal(agg_ty, @intCast(fld_i))) orelse continue;
                    const fld_ptr = if (fld.byte_offset == 0)
                        try emitter.allocator.dupe(u8, scratch)
                    else blk: {
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  %_agp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ tmp_id, scratch, ptr_int, fld.byte_offset },
                        );
                        break :blk try std.fmt.allocPrint(emitter.allocator, "%_agp_{d}", .{tmp_id});
                    };
                    defer emitter.allocator.free(fld_ptr);
                    const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                    defer emitter.allocator.free(elem_ssa);
                    const nat_align = @as(u32, 1) << @intCast(fld.align_log2);
                    const fld_align = if (agg_lay.reprFlags().is_packed)
                        1
                    else
                        @min(agg_lay.alignBytes(), effectiveOffsetAlign(fld.byte_offset, nat_align));
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        elem_ty,
                        elem_ssa,
                        fld_ptr,
                        fld_align,
                        0,
                        0,
                        0,
                    );
                }
            }
        },

        .array_elems => {
            const elems = body.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs];
            const arr_node = emitter.input.pool.getNode(agg_ty);
            if (arr_node.tag == .soa_array_ty) {
                const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(arr_node.lhs));
                const st_lay = try emitter.resolver.resolveType(elem_struct);
                const cap: u64 = arr_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                const elem_scratch = try state.allocEntryBytes(st_lay.size_bytes, st_lay.alignBytes());
                defer emitter.allocator.free(elem_scratch);

                for (elems, 0..) |elem_raw, elem_i| {
                    const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                    defer emitter.allocator.free(elem_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        elem_struct,
                        elem_ssa,
                        elem_scratch,
                        st_lay.alignBytes(),
                        0,
                        0,
                        0,
                    );
                    var fld_ord: u32 = 0;
                    while (fld_ord < st_lay.aux_len) : (fld_ord += 1) {
                        const fld = emitter.resolver.fields_by_decl.items[st_lay.aux_start + fld_ord];
                        if (fld.size_bytes == 0) continue;
                        const col = emitter.resolver.getSoaColumnOffset(elem_struct, fld_ord, cap).?;
                        const f_lay = try emitter.resolver.resolveType(fld.field_ty);
                        const src_fp = if (fld.byte_offset == 0)
                            try emitter.allocator.dupe(u8, elem_scratch)
                        else blk: {
                            const t_id = state.nextTmp();
                            try state.print(
                                "  %_aes_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                                .{ t_id, elem_scratch, ptr_int, fld.byte_offset },
                            );
                            break :blk try std.fmt.allocPrint(emitter.allocator, "%_aes_{d}", .{t_id});
                        };
                        defer emitter.allocator.free(src_fp);
                        const src_align = if (st_lay.reprFlags().is_packed)
                            1
                        else
                            @min(st_lay.alignBytes(), effectiveOffsetAlign(fld.byte_offset, f_lay.alignBytes()));
                        const f_val = try emitLoadValueFromPtr(
                            emitter,
                            state,
                            fld.field_ty,
                            src_fp,
                            src_align,
                            null,
                            0,
                            0,
                            0,
                        );
                        defer emitter.allocator.free(f_val);

                        const dst_off = col.byte_offset + @as(u64, elem_i) * f_lay.stride_bytes;
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_aed_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ t_id, scratch, ptr_int, dst_off },
                        );
                        const dst_fp = try std.fmt.allocPrint(emitter.allocator, "%_aed_{d}", .{t_id});
                        defer emitter.allocator.free(dst_fp);
                        const dst_align = @min(
                            agg_lay.alignBytes(),
                            effectiveOffsetAlign(dst_off, f_lay.alignBytes()),
                        );
                        try emitStoreValueToPtr(emitter, state, fld.field_ty, f_val, dst_fp, dst_align, 0, 0, 0);
                    }
                }
            } else {
                for (elems, 0..) |elem_raw, elem_i| {
                    const elem_ty = body.getInst(MirValueId.fromInt(elem_raw)).type_id;
                    if (try isZeroSizedType(emitter, elem_ty)) continue;
                    const elem_lay = try emitter.resolver.resolveType(elem_ty);
                    const off = @as(u64, elem_i) * elem_lay.stride_bytes;
                    const dst_p = if (off == 0)
                        try emitter.allocator.dupe(u8, scratch)
                    else blk: {
                        const t_id = state.nextTmp();
                        try state.print(
                            "  %_aep2_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ t_id, scratch, ptr_int, off },
                        );
                        break :blk try std.fmt.allocPrint(emitter.allocator, "%_aep2_{d}", .{t_id});
                    };
                    defer emitter.allocator.free(dst_p);
                    const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                    defer emitter.allocator.free(elem_ssa);
                    const dst_align = @min(
                        agg_lay.alignBytes(),
                        effectiveOffsetAlign(off, elem_lay.alignBytes()),
                    );
                    try emitStoreValueToPtr(emitter, state, elem_ty, elem_ssa, dst_p, dst_align, 0, 0, 0);
                }
            }
        },

        .array_repeat => {
            const elem_raw = inst.operands.lhs;
            const rep_count: u64 = inst.operands.rhs;
            const elem_ty = body.getInst(MirValueId.fromInt(elem_raw)).type_id;
            if (rep_count > 0 and !(try isZeroSizedType(emitter, elem_ty))) {
                const arr_node = emitter.input.pool.getNode(agg_ty);
                const loop_id = state.nextTmp();
                const pre_lbl = try emitter.allocator.dupe(u8, state.cur_label);
                defer emitter.allocator.free(pre_lbl);

                if (arr_node.tag == .soa_array_ty) {
                    const elem_struct = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(arr_node.lhs));
                    const st_lay = try emitter.resolver.resolveType(elem_struct);
                    const elem_scratch = try state.allocEntryBytes(st_lay.size_bytes, st_lay.alignBytes());
                    defer emitter.allocator.free(elem_scratch);
                    const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                    defer emitter.allocator.free(elem_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        elem_struct,
                        elem_ssa,
                        elem_scratch,
                        st_lay.alignBytes(),
                        0,
                        0,
                        0,
                    );

                    try state.print(
                        "  br label %_rep_hdr_{d}\n" ++
                            "_rep_hdr_{d}:\n" ++
                            "  %_rep_i_{d} = phi {s} [ 0, %{s} ], [ %_rep_nx_{d}, %_rep_body_{d} ]\n" ++
                            "  %_rep_c_{d} = icmp ult {s} %_rep_i_{d}, {d}\n" ++
                            "  br i1 %_rep_c_{d}, label %_rep_body_{d}, label %_rep_end_{d}\n" ++
                            "_rep_body_{d}:\n",
                        .{
                            loop_id,   loop_id,
                            loop_id,   ptr_int,
                            pre_lbl,   loop_id,
                            loop_id,   loop_id,
                            ptr_int,   loop_id,
                            rep_count, loop_id,
                            loop_id,   loop_id,
                            loop_id,
                        },
                    );
                    var fld_ord: u32 = 0;
                    while (fld_ord < st_lay.aux_len) : (fld_ord += 1) {
                        const fld = emitter.resolver.fields_by_decl.items[st_lay.aux_start + fld_ord];
                        if (fld.size_bytes == 0) continue;
                        const col = emitter.resolver.getSoaColumnOffset(elem_struct, fld_ord, rep_count).?;
                        const f_lay = try emitter.resolver.resolveType(fld.field_ty);
                        const sub_id = state.nextTmp();
                        try state.print(
                            "  %_rfs_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ sub_id, elem_scratch, ptr_int, fld.byte_offset },
                        );
                        const s_fp = try std.fmt.allocPrint(emitter.allocator, "%_rfs_{d}", .{sub_id});
                        defer emitter.allocator.free(s_fp);
                        const src_align = if (st_lay.reprFlags().is_packed)
                            1
                        else
                            @min(st_lay.alignBytes(), effectiveOffsetAlign(fld.byte_offset, f_lay.alignBytes()));
                        const f_val = try emitLoadValueFromPtr(
                            emitter,
                            state,
                            fld.field_ty,
                            s_fp,
                            src_align,
                            null,
                            0,
                            0,
                            0,
                        );
                        defer emitter.allocator.free(f_val);
                        try state.print(
                            "  %_rfo_{d} = mul {s} %_rep_i_{d}, {d}\n" ++
                                "  %_rfa_{d} = add {s} %_rfo_{d}, {d}\n" ++
                                "  %_rfd_{d} = getelementptr inbounds i8, ptr {s}, {s} %_rfa_{d}\n",
                            .{
                                sub_id, ptr_int, loop_id, f_lay.stride_bytes,
                                sub_id, ptr_int, sub_id,  col.byte_offset,
                                sub_id, scratch, ptr_int, sub_id,
                            },
                        );
                        const d_fp = try std.fmt.allocPrint(emitter.allocator, "%_rfd_{d}", .{sub_id});
                        defer emitter.allocator.free(d_fp);
                        const dst_align = @min(
                            agg_lay.alignBytes(),
                            effectiveOffsetAlign(col.byte_offset, f_lay.alignBytes()),
                        );
                        try emitStoreValueToPtr(emitter, state, fld.field_ty, f_val, d_fp, dst_align, 0, 0, 0);
                    }
                    try state.print(
                        "  %_rep_nx_{d} = add {s} %_rep_i_{d}, 1\n" ++
                            "  br label %_rep_hdr_{d}\n" ++
                            "_rep_end_{d}:\n",
                        .{ loop_id, ptr_int, loop_id, loop_id, loop_id },
                    );
                } else {
                    const elem_lay = try emitter.resolver.resolveType(elem_ty);
                    try state.print(
                        "  br label %_rep_hdr_{d}\n" ++
                            "_rep_hdr_{d}:\n" ++
                            "  %_rep_i_{d} = phi {s} [ 0, %{s} ], [ %_rep_nx_{d}, %_rep_body_{d} ]\n" ++
                            "  %_rep_c_{d} = icmp ult {s} %_rep_i_{d}, {d}\n" ++
                            "  br i1 %_rep_c_{d}, label %_rep_body_{d}, label %_rep_end_{d}\n" ++
                            "_rep_body_{d}:\n" ++
                            "  %_rep_bo_{d} = mul {s} %_rep_i_{d}, {d}\n" ++
                            "  %_rep_dp_{d} = getelementptr inbounds i8, ptr {s}, {s} %_rep_bo_{d}\n",
                        .{
                            loop_id,               loop_id,
                            loop_id,               ptr_int,
                            pre_lbl,               loop_id,
                            loop_id,               loop_id,
                            ptr_int,               loop_id,
                            rep_count,             loop_id,
                            loop_id,               loop_id,
                            loop_id,               loop_id,
                            ptr_int,               loop_id,
                            elem_lay.stride_bytes, loop_id,
                            scratch,               ptr_int,
                            loop_id,
                        },
                    );
                    const dp_s = try std.fmt.allocPrint(emitter.allocator, "%_rep_dp_{d}", .{loop_id});
                    defer emitter.allocator.free(dp_s);
                    const elem_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{elem_raw});
                    defer emitter.allocator.free(elem_ssa);
                    const dst_align = @min(
                        agg_lay.alignBytes(),
                        effectiveOffsetAlign(elem_lay.stride_bytes, elem_lay.alignBytes()),
                    );
                    try emitStoreValueToPtr(emitter, state, elem_ty, elem_ssa, dp_s, dst_align, 0, 0, 0);
                    try state.print(
                        "  %_rep_nx_{d} = add {s} %_rep_i_{d}, 1\n" ++
                            "  br label %_rep_hdr_{d}\n" ++
                            "_rep_end_{d}:\n",
                        .{ loop_id, ptr_int, loop_id, loop_id, loop_id },
                    );
                }
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_rep_end_{d}", .{loop_id}));
            }
        },

        .tagged_variant => {
            const tag_ord: u32 = inst.operands.rhs >> 16;
            const arg_len: u32 = inst.operands.rhs & 0xFFFF;
            const args = body.extra_args.items[inst.operands.lhs .. inst.operands.lhs + arg_len];
            if (try emitter.resolver.getSumDetail(agg_ty)) |sum_detail| {
                const var_pay_ty = try unwrapTransparentType(
                    emitter,
                    resolveEnumVariantPayloadType(emitter, agg_ty, tag_ord),
                );
                if (arg_len > 0 and !(try isZeroSizedType(emitter, var_pay_ty))) {
                    const pay_ptr = if (sum_detail.payload_offset == 0)
                        try emitter.allocator.dupe(u8, scratch)
                    else blk: {
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  %_tvp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ tmp_id, scratch, ptr_int, sum_detail.payload_offset },
                        );
                        break :blk try std.fmt.allocPrint(emitter.allocator, "%_tvp_{d}", .{tmp_id});
                    };
                    defer emitter.allocator.free(pay_ptr);

                    if (arg_len == 1 and
                        (try unwrapTransparentType(
                            emitter,
                            body.getInst(MirValueId.fromInt(args[0])).type_id,
                        )) == var_pay_ty)
                    {
                        const pay_lay = try emitter.resolver.resolveType(var_pay_ty);
                        const arg_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
                        defer emitter.allocator.free(arg_ssa);
                        try emitStoreValueToPtr(
                            emitter,
                            state,
                            var_pay_ty,
                            arg_ssa,
                            pay_ptr,
                            @min(
                                agg_lay.alignBytes(),
                                effectiveOffsetAlign(sum_detail.payload_offset, pay_lay.alignBytes()),
                            ),
                            0,
                            0,
                            0,
                        );
                    } else {
                        for (args, 0..) |sub_raw, sub_i| {
                            const sub_ty = body.getInst(MirValueId.fromInt(sub_raw)).type_id;
                            if (try isZeroSizedType(emitter, sub_ty)) continue;
                            const fld = (try emitter.resolver.getFieldByDeclOrdinal(var_pay_ty, @intCast(sub_i))) orelse
                                continue;
                            const sub_ptr = if (fld.byte_offset == 0)
                                try emitter.allocator.dupe(u8, pay_ptr)
                            else blk: {
                                const tmp_id = state.nextTmp();
                                try state.print(
                                    "  %_tvsp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                                    .{ tmp_id, pay_ptr, ptr_int, fld.byte_offset },
                                );
                                break :blk try std.fmt.allocPrint(emitter.allocator, "%_tvsp_{d}", .{tmp_id});
                            };
                            defer emitter.allocator.free(sub_ptr);
                            const sub_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{sub_raw});
                            defer emitter.allocator.free(sub_ssa);
                            const total_off = sum_detail.payload_offset + fld.byte_offset;
                            const nat_align = @as(u32, 1) << @intCast(fld.align_log2);
                            try emitStoreValueToPtr(
                                emitter,
                                state,
                                sub_ty,
                                sub_ssa,
                                sub_ptr,
                                @min(agg_lay.alignBytes(), effectiveOffsetAlign(total_off, nat_align)),
                                0,
                                0,
                                0,
                            );
                        }
                    }
                }
                try emitWriteSumDiscriminantToPtr(
                    emitter,
                    state,
                    agg_ty,
                    scratch,
                    agg_lay.alignBytes(),
                    tag_ord,
                );
            } else if (resolveIntegerInfo(emitter, agg_ty)) |enum_int| {
                const disc_lit = try formatScalarIntLiteralAlloc(
                    emitter.allocator,
                    enum_int.bits,
                    resolveScalarEnumDiscrimI128(emitter, agg_ty, tag_ord),
                );
                defer emitter.allocator.free(disc_lit);
                try state.print("  %_v_{d} = add i{d} 0, {s}\n", .{ dst_raw, enum_int.bits, disc_lit });
                return;
            }
        },

        .closure_make, .str_concat, .fmt_args_make => unreachable,
    }

    const loaded = try emitLoadValueFromPtr(emitter, state, agg_ty, scratch, agg_lay.alignBytes(), null, 0, 0, 0);
    defer emitter.allocator.free(loaded);
    const val_ty = try formatLlvmValueType(emitter, agg_ty);
    defer emitter.allocator.free(val_ty);
    try state.print(
        "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
        .{ dst_raw, val_ty, loaded, val_ty, loaded },
    );
}

/// Extracts a compile-time constant `u64` `MemoryOrder` from `maybe_val_raw` (`5` when omitted).
fn extractConstU64FromMirBody(body: *const MirBody, maybe_val_raw: ?u32) ?u64 {
    const val_raw = maybe_val_raw orelse return 5;
    const ord_inst = body.getInst(MirValueId.fromInt(val_raw));
    if (ord_inst.op != .const_scalar or ord_inst.operands.lhs >= body.consts.items.len) return null;
    return switch (body.consts.items[ord_inst.operands.lhs]) {
        .int_val => |iv| if (iv < 0) 6 else @intCast(@min(@as(u128, @intCast(iv)), 6)),
        else => null,
    };
}

/// Extracts a compile-time constant `bool` `is_weak` flag from `maybe_val_raw` (`false` when omitted).
fn extractConstWeakFromMirBody(body: *const MirBody, maybe_val_raw: ?u32) ?bool {
    const val_raw = maybe_val_raw orelse return false;
    const wk_inst = body.getInst(MirValueId.fromInt(val_raw));
    if (wk_inst.op != .const_scalar or wk_inst.operands.lhs >= body.consts.items.len) return null;
    return switch (body.consts.items[wk_inst.operands.lhs]) {
        .bool_val => |bv| bv,
        .int_val => |iv| iv != 0,
        else => null,
    };
}

/// Coerces a runtime `is_weak` operand (`bool` or integer) to an `i1` SSA token.
fn emitCoerceWeakToI1Llvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    val_raw: u32,
) ![]u8 {
    const wk_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(val_raw)).type_id);
    if (wk_ty == .bool_ty) {
        return std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{val_raw});
    }
    const wk_info = resolveIntegerInfo(emitter, wk_ty) orelse
        IntScalarInfo{ .bits = 8, .is_signed = false };
    const tmp_id = state.nextTmp();
    try state.print(
        "  %_awk_{d} = icmp ne i{d} %_v_{d}, 0\n",
        .{ tmp_id, wk_info.bits, val_raw },
    );
    return std.fmt.allocPrint(emitter.allocator, "%_awk_{d}", .{tmp_id});
}

/// Maps `MemoryOrder` (`0..5`) to the legal LLVM IR ordering keyword (`""` for relaxed `fence`).
fn resolveLlvmAtomicOrderKeyword(ord_val: u64, op_class: AtomicOpClass) ?[]const u8 {
    if (ord_val > 5) return null;
    return switch (op_class) {
        .fence_op => switch (ord_val) {
            0 => "",
            1, 2 => "acquire",
            3 => "release",
            4 => "acq_rel",
            else => "seq_cst",
        },
        .load_op => switch (ord_val) {
            0, 3 => "monotonic",
            1, 2, 4 => "acquire",
            else => "seq_cst",
        },
        .store_op => switch (ord_val) {
            0, 1, 2 => "monotonic",
            3, 4 => "release",
            else => "seq_cst",
        },
        .rmw_op => switch (ord_val) {
            0 => "monotonic",
            1, 2 => "acquire",
            3 => "release",
            4 => "acq_rel",
            else => "seq_cst",
        },
    };
}

/// Maps `(succ_ord, fail_ord)` (`0..5`) to the canonical 0..8 LLVM `cmpxchg` ordering pair index.
fn resolveLlvmCmpxchgPairIndex(succ_ord: u64, fail_ord: u64) ?u8 {
    if (succ_ord > 5 or fail_ord > 5) return null;
    if (fail_ord == 5) return 8;
    if (fail_ord == 1 or fail_ord == 2 or fail_ord == 4) {
        if (succ_ord == 5) return 7;
        if (succ_ord >= 3) return 6;
        return 5;
    }
    return @intCast(switch (succ_ord) {
        0 => @as(u8, 0),
        1, 2 => @as(u8, 1),
        3 => @as(u8, 2),
        4 => @as(u8, 3),
        else => @as(u8, 4),
    });
}

/// Canonical `(succ_kw, fail_kw)` table indexed by `resolveLlvmCmpxchgPairIndex` (`0..8`).
const CMPXCHG_ORDER_PAIRS: [9]struct { succ_kw: []const u8, fail_kw: []const u8 } = .{
    .{ .succ_kw = "monotonic", .fail_kw = "monotonic" },
    .{ .succ_kw = "acquire", .fail_kw = "monotonic" },
    .{ .succ_kw = "release", .fail_kw = "monotonic" },
    .{ .succ_kw = "acq_rel", .fail_kw = "monotonic" },
    .{ .succ_kw = "seq_cst", .fail_kw = "monotonic" },
    .{ .succ_kw = "acquire", .fail_kw = "acquire" },
    .{ .succ_kw = "acq_rel", .fail_kw = "acquire" },
    .{ .succ_kw = "seq_cst", .fail_kw = "acquire" },
    .{ .succ_kw = "seq_cst", .fail_kw = "seq_cst" },
};

/// Coerces a runtime `MemoryOrder` operand (`u8` / integer) to an `i32` SSA token.
fn emitCoerceOrderToI32Llvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    maybe_val_raw: ?u32,
) ![]u8 {
    const val_raw = maybe_val_raw orelse return emitter.allocator.dupe(u8, "5");
    const ord_ty = body.getInst(MirValueId.fromInt(val_raw)).type_id;
    const ord_info = resolveIntegerInfo(emitter, ord_ty) orelse
        IntScalarInfo{ .bits = 8, .is_signed = false };
    if (ord_info.bits == 32) {
        return std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{val_raw});
    }
    const tmp_id = state.nextTmp();
    const cast_op = if (ord_info.bits < 32) "zext" else "trunc";
    try state.print(
        "  %_ao32_{d} = {s} i{d} %_v_{d} to i32\n",
        .{ tmp_id, cast_op, ord_info.bits, val_raw },
    );
    return std.fmt.allocPrint(emitter.allocator, "%_ao32_{d}", .{tmp_id});
}

/// Emits `MirOp.intrinsic_op` across all surface and internal intrinsics (`DR-19`, `DR-22`).
fn emitIntrinsicOpLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    bb_idx: u32,
    dst_raw: u32,
    ikind: mir.MirIntrinsicKind,
    inst: mir.MirInst,
) !void {
    const ptr_int = ptrIntType(emitter);
    const access_grp = if (bb_idx < state.block_access_group.len) state.block_access_group[bb_idx] else 0;
    const args: []const u32 = if (ikind.hasExtraArgs() and inst.operands.rhs > 0)
        body.extra_args.items[inst.operands.lhs .. inst.operands.lhs + inst.operands.rhs]
    else
        &.{};

    switch (ikind) {
        .compile_assert => {
            if (args.len >= 1) {
                const tmp_id = state.nextTmp();
                try state.print("  %_ca_bad_{d} = xor i1 %_v_{d}, true\n", .{ tmp_id, args[0] });
                const bad_ssa = try std.fmt.allocPrint(emitter.allocator, "%_ca_bad_{d}", .{tmp_id});
                defer emitter.allocator.free(bad_ssa);
                try emitInlineTrapIfTrue(emitter, state, bad_ssa, 3);
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
            } else {
                try state.writeAll("  call void @_cx_rt_trap(i32 3)\n");
                try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
            }
        },

        .compile_error, .abort_vacated_panic, .embed_bytes => {
            const reason: u32 = if (ikind == .embed_bytes) 0 else 3;
            try state.print("  call void @_cx_rt_trap(i32 {d})\n", .{reason});
            try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
        },

        .derive_debug_fmt => {
            if (args.len >= 1) {
                const arg_ty = try unwrapTransparentType(
                    emitter,
                    body.getInst(MirValueId.fromInt(args[0])).type_id,
                );
                const val_ptr: []u8 = if (try isZeroSizedType(emitter, arg_ty))
                    try std.fmt.allocPrint(emitter.allocator, "inttoptr ({s} 1 to ptr)", .{ptr_int})
                else blk: {
                    const arg_lay = try emitter.resolver.resolveType(arg_ty);
                    const slot = try state.allocEntryBytes(arg_lay.size_bytes, arg_lay.alignBytes());
                    const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
                    defer emitter.allocator.free(src_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        arg_ty,
                        src_ssa,
                        slot,
                        arg_lay.alignBytes(),
                        0,
                        0,
                        0,
                    );
                    break :blk slot;
                };
                defer emitter.allocator.free(val_ptr);
                const buf_slot = try state.allocEntryBytes(24, 8);
                defer emitter.allocator.free(buf_slot);
                try state.print(
                    "  store {{ ptr, i64, i64 }} zeroinitializer, ptr {s}, align 8\n" ++
                        "  call void @_cx_fmt_ty_{d}(ptr {s}, ptr {s}, i32 134217728, i32 -1)\n" ++
                        "  %_v_{d} = call {{ ptr, {s} }} @_cx_rt_buf_finish(ptr {s})\n",
                    .{ buf_slot, arg_ty.toU32(), buf_slot, val_ptr, dst_raw, ptr_int, buf_slot },
                );
            } else {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
            }
        },

        .size_of => {
            const refl_lay = try emitter.resolver.resolveType(TypeId.fromInt(inst.operands.lhs));
            const dst_info = resolveIntegerInfo(emitter, inst.type_id) orelse
                IntScalarInfo{ .bits = @as(u16, emitter.cfg.target.ptrBytes()) * 8, .is_signed = false };
            try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, refl_lay.size_bytes });
        },

        .align_of => {
            const refl_lay = try emitter.resolver.resolveType(TypeId.fromInt(inst.operands.lhs));
            const dst_info = resolveIntegerInfo(emitter, inst.type_id) orelse
                IntScalarInfo{ .bits = @as(u16, emitter.cfg.target.ptrBytes()) * 8, .is_signed = false };
            try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, refl_lay.alignBytes() });
        },

        .type_name => {
            const refl_ty = TypeId.fromInt(inst.operands.lhs);
            var name_buf: [512]u8 = undefined;
            const rendered = emitter.input.pool.formatType(refl_ty, emitter.input.sym_table, &name_buf);
            const tmp_id = state.nextTmp();
            if (rendered.len == 0) {
                try state.print(
                    "  %_tn0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr @_cx_empty_cstr, 0\n" ++
                        "  %_v_{d} = insertvalue {{ ptr, {s} }} %_tn0_{d}, {s} 0, 1\n",
                    .{ tmp_id, ptr_int, dst_raw, ptr_int, tmp_id, ptr_int },
                );
            } else {
                try state.print(
                    "  %_tn0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr @_cx_tyname_{d}, 0\n" ++
                        "  %_v_{d} = insertvalue {{ ptr, {s} }} %_tn0_{d}, {s} {d}, 1\n",
                    .{ tmp_id, ptr_int, refl_ty.toU32(), dst_raw, ptr_int, tmp_id, ptr_int, rendered.len },
                );
            }
        },

        .as_bytes => {
            if (args.len < 1) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const ref_val = MirValueId.fromInt(args[0]);
            const ref_ty = try unwrapTransparentType(emitter, body.getInst(ref_val).type_id);
            const ref_node = emitter.input.pool.getNode(ref_ty);
            const is_ptr_src = (ref_node.tag == .ref_ty or
                ref_node.tag == .mut_ref_ty or
                ref_node.tag == .raw_ptr_ty) and !emitter.input.pool.isSliceRefType(ref_ty);
            const val_ty = if (is_ptr_src)
                try unwrapTransparentType(emitter, TypeId.fromInt(ref_node.lhs))
            else
                ref_ty;
            const val_lay = try emitter.resolver.resolveType(val_ty);

            const data_ptr_s = if (val_lay.size_bytes == 0)
                try std.fmt.allocPrint(emitter.allocator, "inttoptr ({s} 1 to ptr)", .{ptr_int})
            else if (is_ptr_src)
                try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]})
            else blk: {
                const scratch = try state.allocEntryBytes(val_lay.size_bytes, val_lay.alignBytes());
                const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
                defer emitter.allocator.free(src_ssa);
                try emitStoreValueToPtr(emitter, state, val_ty, src_ssa, scratch, val_lay.alignBytes(), 0, 0, 0);
                break :blk scratch;
            };
            defer emitter.allocator.free(data_ptr_s);

            const dst_unwrapped = try unwrapTransparentType(emitter, inst.type_id);
            const dst_node = emitter.input.pool.getNode(dst_unwrapped);
            const tmp_id = state.nextTmp();
            if ((dst_node.tag == .ref_ty or dst_node.tag == .mut_ref_ty or dst_node.tag == .raw_ptr_ty) and
                !emitter.input.pool.isSliceRefType(dst_unwrapped))
            {
                const fat_slot = try state.allocEntryBytes(
                    2 * emitter.cfg.target.ptrBytes(),
                    emitter.cfg.target.ptrBytes(),
                );
                defer emitter.allocator.free(fat_slot);
                try state.print(
                    "  store ptr {s}, ptr {s}, align {d}\n" ++
                        "  %_ab_lp_{d} = getelementptr inbounds {{ ptr, {s} }}, ptr {s}, i32 0, i32 1\n" ++
                        "  store {s} {d}, ptr %_ab_lp_{d}, align {d}\n" ++
                        "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                    .{
                        data_ptr_s,
                        fat_slot,
                        emitter.cfg.target.ptrBytes(),
                        tmp_id,
                        ptr_int,
                        fat_slot,
                        ptr_int,
                        val_lay.size_bytes,
                        tmp_id,
                        emitter.cfg.target.ptrBytes(),
                        dst_raw,
                        fat_slot,
                        fat_slot,
                    },
                );
            } else {
                try state.print(
                    "  %_ab0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr {s}, 0\n" ++
                        "  %_v_{d} = insertvalue {{ ptr, {s} }} %_ab0_{d}, {s} {d}, 1\n",
                    .{ tmp_id, ptr_int, data_ptr_s, dst_raw, ptr_int, tmp_id, ptr_int, val_lay.size_bytes },
                );
            }
        },

        .bit_cast => {
            if (args.len < 1 or (try isZeroSizedType(emitter, inst.type_id))) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const src_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(args[0])).type_id);
            const dst_ty = try unwrapTransparentType(emitter, inst.type_id);
            const src_lay = try emitter.resolver.resolveType(src_ty);
            const dst_lay = try emitter.resolver.resolveType(dst_ty);
            const max_sz = @max(src_lay.size_bytes, dst_lay.size_bytes);
            const max_al = @max(src_lay.alignBytes(), dst_lay.alignBytes());
            const scratch = try state.allocEntryBytes(max_sz, max_al);
            defer emitter.allocator.free(scratch);
            try emitMemsetZero(emitter, state, scratch, max_sz, max_al);
            const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
            defer emitter.allocator.free(src_ssa);
            try emitStoreValueToPtr(emitter, state, src_ty, src_ssa, scratch, src_lay.alignBytes(), 0, 0, 0);
            const loaded = try emitLoadValueFromPtr(emitter, state, dst_ty, scratch, dst_lay.alignBytes(), null, 0, 0, 0);
            defer emitter.allocator.free(loaded);
            const dst_val_ty = try formatLlvmValueType(emitter, dst_ty);
            defer emitter.allocator.free(dst_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, dst_val_ty, loaded, dst_val_ty, loaded },
            );
        },

        .from_bytes, .view_bytes => {
            if (args.len < 1 or (try isZeroSizedType(emitter, inst.type_id))) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const is_view = ikind == .view_bytes;
            const span_s = try emitExtractByteSpanLlvm(emitter, state, body, MirValueId.fromInt(args[0]));
            defer emitter.allocator.free(span_s.ptr_ssa);
            defer emitter.allocator.free(span_s.len_ssa);

            const opt_ty = try unwrapTransparentType(emitter, inst.type_id);
            const opt_lay = try emitter.resolver.resolveType(opt_ty);
            const opt_node = emitter.input.pool.getNode(opt_ty);
            const some_pay_ty = try unwrapTransparentType(emitter, TypeId.fromInt(opt_node.lhs));
            const some_node = emitter.input.pool.getNode(some_pay_ty);
            const target_ty = if (is_view and
                (some_node.tag == .ref_ty or some_node.tag == .mut_ref_ty or some_node.tag == .raw_ptr_ty))
                try unwrapTransparentType(emitter, TypeId.fromInt(some_node.lhs))
            else
                some_pay_ty;
            const target_lay = try emitter.resolver.resolveType(target_ty);
            const sum_detail = (try emitter.resolver.getSumDetail(opt_ty)) orelse {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            };

            const out_slot = try state.allocEntryBytes(opt_lay.size_bytes, opt_lay.alignBytes());
            defer emitter.allocator.free(out_slot);
            try emitMemsetZero(emitter, state, out_slot, opt_lay.size_bytes, opt_lay.alignBytes());

            const tmp_id = state.nextTmp();
            if (is_view) {
                try state.print(
                    "  %_vw_sz_{d} = icmp eq {s} {s}, {d}\n" ++
                        "  %_vw_nn_{d} = icmp ne ptr {s}, null\n" ++
                        "  %_vw_pi_{d} = ptrtoint ptr {s} to {s}\n" ++
                        "  %_vw_am_{d} = and {s} %_vw_pi_{d}, {d}\n" ++
                        "  %_vw_al_{d} = icmp eq {s} %_vw_am_{d}, 0\n" ++
                        "  %_vw_c1_{d} = and i1 %_vw_sz_{d}, %_vw_nn_{d}\n" ++
                        "  %_vw_ok_{d} = and i1 %_vw_c1_{d}, %_vw_al_{d}\n",
                    .{
                        tmp_id,                      ptr_int,        span_s.len_ssa, target_lay.size_bytes,
                        tmp_id,                      span_s.ptr_ssa, tmp_id,         span_s.ptr_ssa,
                        ptr_int,                     tmp_id,         ptr_int,        tmp_id,
                        target_lay.alignBytes() - 1, tmp_id,         ptr_int,        tmp_id,
                        tmp_id,                      tmp_id,         tmp_id,         tmp_id,
                        tmp_id,                      tmp_id,
                    },
                );
            } else {
                try state.print(
                    "  %_vw_ok_{d} = icmp eq {s} {s}, {d}\n",
                    .{ tmp_id, ptr_int, span_s.len_ssa, target_lay.size_bytes },
                );
            }

            try state.print(
                "  br i1 %_vw_ok_{d}, label %_fb_some_{d}, label %_fb_none_{d}\n" ++
                    "_fb_some_{d}:\n",
                .{ tmp_id, tmp_id, tmp_id, tmp_id },
            );
            const pay_ptr = if (sum_detail.payload_offset == 0)
                try emitter.allocator.dupe(u8, out_slot)
            else blk: {
                try state.print(
                    "  %_fb_pp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                    .{ tmp_id, out_slot, ptr_int, sum_detail.payload_offset },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_fb_pp_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(pay_ptr);

            if (is_view) {
                if (!(try isZeroSizedType(emitter, some_pay_ty))) {
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        some_pay_ty,
                        span_s.ptr_ssa,
                        pay_ptr,
                        @min(opt_lay.alignBytes(), emitter.cfg.target.ptrBytes()),
                        0,
                        0,
                        0,
                    );
                }
            } else if (target_lay.size_bytes > 0) {
                try emitMemcpyBytes(emitter, state, pay_ptr, 1, span_s.ptr_ssa, 1, target_lay.size_bytes);
            }
            try emitWriteSumDiscriminantToPtr(emitter, state, opt_ty, out_slot, opt_lay.alignBytes(), 1);
            try state.print("  br label %_fb_join_{d}\n_fb_none_{d}:\n", .{ tmp_id, tmp_id });
            try emitWriteSumDiscriminantToPtr(emitter, state, opt_ty, out_slot, opt_lay.alignBytes(), 0);
            try state.print("  br label %_fb_join_{d}\n_fb_join_{d}:\n", .{ tmp_id, tmp_id });
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fb_join_{d}", .{tmp_id}));

            const loaded = try emitLoadValueFromPtr(emitter, state, opt_ty, out_slot, opt_lay.alignBytes(), null, 0, 0, 0);
            defer emitter.allocator.free(loaded);
            const opt_val_ty = try formatLlvmValueType(emitter, opt_ty);
            defer emitter.allocator.free(opt_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, opt_val_ty, loaded, opt_val_ty, loaded },
            );
        },

        .drop_trace => {
            if (args.len >= 1) {
                const id_ty = body.getInst(MirValueId.fromInt(args[0])).type_id;
                const id_info = resolveIntegerInfo(emitter, id_ty) orelse
                    IntScalarInfo{ .bits = 64, .is_signed = true };
                const tmp_id = state.nextTmp();
                if (id_info.bits == 64) {
                    try state.print("  %_dt_i64_{d} = add i64 %_v_{d}, 0\n", .{ tmp_id, args[0] });
                } else if (id_info.bits < 64) {
                    const ext_s = if (id_info.is_signed) "sext" else "zext";
                    try state.print(
                        "  %_dt_i64_{d} = {s} i{d} %_v_{d} to i64\n",
                        .{ tmp_id, ext_s, id_info.bits, args[0] },
                    );
                } else {
                    try state.print("  %_dt_i64_{d} = trunc i128 %_v_{d} to i64\n", .{ tmp_id, args[0] });
                }
                const buf_s = try state.allocEntryBytes(64, 8);
                defer emitter.allocator.free(buf_s);
                try state.print(
                    "  %_dt_n32_{d} = call i32 (ptr, {s}, ptr, ...) @snprintf(" ++
                        "ptr {s}, {s} 64, ptr @.cx_fmt_drop, i64 %_dt_i64_{d})\n" ++
                        "  %_dt_ok_{d} = icmp sgt i32 %_dt_n32_{d}, 0\n" ++
                        "  %_dt_cl_{d} = select i1 %_dt_ok_{d}, i32 %_dt_n32_{d}, i32 0\n",
                    .{
                        tmp_id, ptr_int, buf_s,  ptr_int, tmp_id,
                        tmp_id, tmp_id,  tmp_id, tmp_id,  tmp_id,
                    },
                );
                if (emitter.cfg.target.isWasm()) {
                    try state.print(
                        "  call void @_cx_rt_trace_append(ptr {s}, i32 %_dt_cl_{d})\n",
                        .{ buf_s, tmp_id },
                    );
                } else {
                    try state.print(
                        "  %_dt_ln_{d} = zext i32 %_dt_cl_{d} to i64\n" ++
                            "  call void @_cx_rt_trace_append(ptr {s}, i64 %_dt_ln_{d})\n",
                        .{ tmp_id, tmp_id, buf_s, tmp_id },
                    );
                }
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .bounds_check => {
            if (args.len >= 2) {
                const idx_ty = body.getInst(MirValueId.fromInt(args[0])).type_id;
                const idx_info = resolveIntegerInfo(emitter, idx_ty) orelse
                    IntScalarInfo{ .bits = 64, .is_signed = false };
                if (idx_info.is_signed) {
                    const neg_id = state.nextTmp();
                    try state.print("  %_bc_neg_{d} = icmp slt i{d} %_v_{d}, 0\n", .{ neg_id, idx_info.bits, args[0] });
                    const neg_s = try std.fmt.allocPrint(emitter.allocator, "%_bc_neg_{d}", .{neg_id});
                    defer emitter.allocator.free(neg_s);
                    try emitInlineTrapIfTrue(emitter, state, neg_s, 2);
                }
                const idx_u = try emitExtendIntToI128(emitter, state, args[0], idx_ty, true);
                defer emitter.allocator.free(idx_u);
                const len_ty = body.getInst(MirValueId.fromInt(args[1])).type_id;
                const len_u = try emitExtendIntToI128(emitter, state, args[1], len_ty, true);
                defer emitter.allocator.free(len_u);
                const cmp_id = state.nextTmp();
                try state.print("  %_bc_ge_{d} = icmp uge i128 {s}, {s}\n", .{ cmp_id, idx_u, len_u });
                const ge_s = try std.fmt.allocPrint(emitter.allocator, "%_bc_ge_{d}", .{cmp_id});
                defer emitter.allocator.free(ge_s);
                try emitInlineTrapIfTrue(emitter, state, ge_s, 2);
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .slice_range_check => {
            if (args.len >= 3) {
                const lo_ty = body.getInst(MirValueId.fromInt(args[0])).type_id;
                const hi_ty = body.getInst(MirValueId.fromInt(args[1])).type_id;
                const len_ty = body.getInst(MirValueId.fromInt(args[2])).type_id;
                if (resolveIntegerInfo(emitter, lo_ty)) |lo_i| {
                    if (lo_i.is_signed) {
                        const nid = state.nextTmp();
                        try state.print("  %_sr_ln_{d} = icmp slt i{d} %_v_{d}, 0\n", .{ nid, lo_i.bits, args[0] });
                        const ns = try std.fmt.allocPrint(emitter.allocator, "%_sr_ln_{d}", .{nid});
                        defer emitter.allocator.free(ns);
                        try emitInlineTrapIfTrue(emitter, state, ns, 2);
                    }
                }
                if (resolveIntegerInfo(emitter, hi_ty)) |hi_i| {
                    if (hi_i.is_signed) {
                        const nid = state.nextTmp();
                        try state.print("  %_sr_hn_{d} = icmp slt i{d} %_v_{d}, 0\n", .{ nid, hi_i.bits, args[1] });
                        const ns = try std.fmt.allocPrint(emitter.allocator, "%_sr_hn_{d}", .{nid});
                        defer emitter.allocator.free(ns);
                        try emitInlineTrapIfTrue(emitter, state, ns, 2);
                    }
                }
                const lo_u = try emitExtendIntToI128(emitter, state, args[0], lo_ty, true);
                defer emitter.allocator.free(lo_u);
                const hi_u = try emitExtendIntToI128(emitter, state, args[1], hi_ty, true);
                defer emitter.allocator.free(hi_u);
                const len_u = try emitExtendIntToI128(emitter, state, args[2], len_ty, true);
                defer emitter.allocator.free(len_u);
                const cid = state.nextTmp();
                try state.print(
                    "  %_sr_c1_{d} = icmp ugt i128 {s}, {s}\n" ++
                        "  %_sr_c2_{d} = icmp ugt i128 {s}, {s}\n" ++
                        "  %_sr_bad_{d} = or i1 %_sr_c1_{d}, %_sr_c2_{d}\n",
                    .{ cid, lo_u, hi_u, cid, hi_u, len_u, cid, cid, cid },
                );
                const bad_s = try std.fmt.allocPrint(emitter.allocator, "%_sr_bad_{d}", .{cid});
                defer emitter.allocator.free(bad_s);
                try emitInlineTrapIfTrue(emitter, state, bad_s, 2);
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .narrow_check, .try_narrow => {
            if (args.len < 3) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const is_try = ikind == .try_narrow;
            const opt_ty = try unwrapTransparentType(emitter, inst.type_id);
            const dst_ty = if (is_try) TypeId.fromInt(emitter.input.pool.getNode(opt_ty).lhs) else inst.type_id;
            const dst_unwrapped = emitter.input.pool.unwrapUnderlyingType(dst_ty);
            const src_ty = body.getInst(MirValueId.fromInt(args[0])).type_id;
            const min_ty = body.getInst(MirValueId.fromInt(args[1])).type_id;
            const max_ty = body.getInst(MirValueId.fromInt(args[2])).type_id;
            const src_info = resolveIntegerInfo(emitter, src_ty) orelse return;
            const dst_info = resolveIntegerInfo(emitter, dst_ty) orelse return;

            const min_128 = try emitExtendIntToI128(emitter, state, args[1], min_ty, false);
            defer emitter.allocator.free(min_128);
            const max_128 = try emitExtendIntToI128(emitter, state, args[2], max_ty, false);
            defer emitter.allocator.free(max_128);
            const src_128 = try emitExtendIntToI128(emitter, state, args[0], src_ty, !src_info.is_signed);
            defer emitter.allocator.free(src_128);

            const is_unrefined_u128 = dst_unwrapped == .u128_ty and
                emitter.input.pool.getRefinementBounds(dst_ty) == null;
            const tmp_id = state.nextTmp();

            if (src_info.is_signed) {
                if (is_unrefined_u128) {
                    try state.print("  %_nr_ok_{d} = icmp sge i128 {s}, 0\n", .{ tmp_id, src_128 });
                } else {
                    try state.print(
                        "  %_nr_ge_{d} = icmp sge i128 {s}, {s}\n" ++
                            "  %_nr_le_{d} = icmp sle i128 {s}, {s}\n" ++
                            "  %_nr_ok_{d} = and i1 %_nr_ge_{d}, %_nr_le_{d}\n",
                        .{ tmp_id, src_128, min_128, tmp_id, src_128, max_128, tmp_id, tmp_id, tmp_id },
                    );
                }
            } else if (is_unrefined_u128) {
                try state.print("  %_nr_ok_{d} = or i1 true, true\n", .{tmp_id});
            } else {
                try state.print(
                    "  %_nr_mxnn_{d} = icmp sge i128 {s}, 0\n" ++
                        "  %_nr_mnng_{d} = icmp slt i128 {s}, 0\n" ++
                        "  %_nr_umin_{d} = select i1 %_nr_mnng_{d}, i128 0, i128 {s}\n" ++
                        "  %_nr_uge_{d} = icmp uge i128 {s}, %_nr_umin_{d}\n" ++
                        "  %_nr_ule_{d} = icmp ule i128 {s}, {s}\n" ++
                        "  %_nr_ub_{d} = and i1 %_nr_uge_{d}, %_nr_ule_{d}\n" ++
                        "  %_nr_ok_{d} = and i1 %_nr_mxnn_{d}, %_nr_ub_{d}\n",
                    .{
                        tmp_id,  max_128,
                        tmp_id,  min_128,
                        tmp_id,  tmp_id,
                        min_128, tmp_id,
                        src_128, tmp_id,
                        tmp_id,  src_128,
                        max_128, tmp_id,
                        tmp_id,  tmp_id,
                        tmp_id,  tmp_id,
                        tmp_id,
                    },
                );
            }

            const conv_ssa = if (dst_info.bits == 128)
                try emitter.allocator.dupe(u8, src_128)
            else blk: {
                try state.print(
                    "  %_nr_cv_{d} = trunc i128 {s} to i{d}\n",
                    .{ tmp_id, src_128, dst_info.bits },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_nr_cv_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(conv_ssa);

            if (!is_try) {
                try state.print("  %_nr_bad_{d} = xor i1 %_nr_ok_{d}, true\n", .{ tmp_id, tmp_id });
                const bad_s = try std.fmt.allocPrint(emitter.allocator, "%_nr_bad_{d}", .{tmp_id});
                defer emitter.allocator.free(bad_s);
                try emitInlineTrapIfTrue(emitter, state, bad_s, 2);
                try state.print("  %_v_{d} = add i{d} {s}, 0\n", .{ dst_raw, dst_info.bits, conv_ssa });
            } else {
                const opt_lay = try emitter.resolver.resolveType(opt_ty);
                const sum_detail = (try emitter.resolver.getSumDetail(opt_ty)) orelse return;
                const out_slot = try state.allocEntryBytes(opt_lay.size_bytes, opt_lay.alignBytes());
                defer emitter.allocator.free(out_slot);
                try emitMemsetZero(emitter, state, out_slot, opt_lay.size_bytes, opt_lay.alignBytes());

                try state.print(
                    "  br i1 %_nr_ok_{d}, label %_nr_some_{d}, label %_nr_none_{d}\n" ++
                        "_nr_some_{d}:\n",
                    .{ tmp_id, tmp_id, tmp_id, tmp_id },
                );
                const pay_ptr = if (sum_detail.payload_offset == 0)
                    try emitter.allocator.dupe(u8, out_slot)
                else blk: {
                    try state.print(
                        "  %_nr_pp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ tmp_id, out_slot, ptr_int, sum_detail.payload_offset },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_nr_pp_{d}", .{tmp_id});
                };
                defer emitter.allocator.free(pay_ptr);

                if (!(try isZeroSizedType(emitter, dst_ty))) {
                    const dst_lay = try emitter.resolver.resolveType(dst_ty);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        dst_ty,
                        conv_ssa,
                        pay_ptr,
                        @min(opt_lay.alignBytes(), dst_lay.alignBytes()),
                        0,
                        0,
                        0,
                    );
                }
                try emitWriteSumDiscriminantToPtr(emitter, state, opt_ty, out_slot, opt_lay.alignBytes(), 1);
                try state.print("  br label %_nr_join_{d}\n_nr_none_{d}:\n", .{ tmp_id, tmp_id });
                try emitWriteSumDiscriminantToPtr(emitter, state, opt_ty, out_slot, opt_lay.alignBytes(), 0);
                try state.print("  br label %_nr_join_{d}\n_nr_join_{d}:\n", .{ tmp_id, tmp_id });
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_nr_join_{d}", .{tmp_id}));

                const loaded = try emitLoadValueFromPtr(emitter, state, opt_ty, out_slot, opt_lay.alignBytes(), null, 0, 0, 0);
                defer emitter.allocator.free(loaded);
                const opt_val_ty = try formatLlvmValueType(emitter, opt_ty);
                defer emitter.allocator.free(opt_val_ty);
                try state.print(
                    "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                    .{ dst_raw, opt_val_ty, loaded, opt_val_ty, loaded },
                );
            }
        },

        .zero_pad => {
            const lowered = try lowerPlaceLlvm(emitter, state, body, PlaceId.fromInt(inst.operands.lhs));
            switch (lowered) {
                .const_len => {},
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    if (!(try isZeroSizedType(emitter, av.pointee_ty))) {
                        const lay = try emitter.resolver.resolveType(av.pointee_ty);
                        try emitMemsetZero(emitter, state, av.ptr_str, lay.size_bytes, av.align_bytes);
                    }
                },
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .drop_in_place, .drop_if_live => {
            const lowered = try lowerPlaceLlvm(emitter, state, body, PlaceId.fromInt(inst.operands.lhs));
            switch (lowered) {
                .const_len => {},
                .addr_val => |av| {
                    defer emitter.allocator.free(av.ptr_str);
                    const dropped_ty = emitter.input.pool.unwrapUnderlyingType(
                        if (inst.type_id != .unit_ty and !inst.type_id.isError())
                            inst.type_id
                        else
                            av.pointee_ty,
                    );
                    if (emitter.drop_type_set.contains(dropped_ty.toU32()) and
                        !(try isZeroSizedType(emitter, dropped_ty)))
                    {
                        if (ikind == .drop_if_live) {
                            if (inst.operands.rhs != mir.NONE_U32) {
                                const tmp_id = state.nextTmp();
                                try state.print(
                                    "  br i1 %_v_{d}, label %_dil_do_{d}, label %_dil_nx_{d}\n" ++
                                        "_dil_do_{d}:\n" ++
                                        "  call void @_cx_drop_ty_{d}(ptr {s})\n" ++
                                        "  br label %_dil_nx_{d}\n" ++
                                        "_dil_nx_{d}:\n",
                                    .{
                                        inst.operands.rhs, tmp_id,             tmp_id,
                                        tmp_id,            dropped_ty.toU32(), av.ptr_str,
                                        tmp_id,            tmp_id,
                                    },
                                );
                                state.setLabelOwned(
                                    try std.fmt.allocPrint(emitter.allocator, "_dil_nx_{d}", .{tmp_id}),
                                );
                            }
                        } else {
                            try state.print(
                                "  call void @_cx_drop_ty_{d}(ptr {s})\n",
                                .{ dropped_ty.toU32(), av.ptr_str },
                            );
                        }
                    }
                },
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .ghost_storage_free => {
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .atomic_fence => {
            const maybe_ord = if (args.len >= 1) args[0] else null;
            if (extractConstU64FromMirBody(body, maybe_ord)) |const_ord| {
                const ord_kw = resolveLlvmAtomicOrderKeyword(const_ord, .fence_op) orelse {
                    try state.writeAll("  call void @_cx_rt_trap(i32 3)\n");
                    try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
                    return;
                };
                if (ord_kw.len > 0) {
                    try state.print("  fence {s}\n", .{ord_kw});
                }
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
            } else {
                const ord32 = try emitCoerceOrderToI32Llvm(emitter, state, body, maybe_ord);
                defer emitter.allocator.free(ord32);
                const tmp_id = state.nextTmp();
                try state.print(
                    "  switch i32 {s}, label %_af_bad_{d} [\n" ++
                        "    i32 0, label %_af_jn_{d}\n" ++
                        "    i32 1, label %_af_ac_{d}\n" ++
                        "    i32 2, label %_af_ac_{d}\n" ++
                        "    i32 3, label %_af_rl_{d}\n" ++
                        "    i32 4, label %_af_ar_{d}\n" ++
                        "    i32 5, label %_af_sc_{d}\n" ++
                        "  ]\n" ++
                        "_af_ac_{d}:\n  fence acquire\n  br label %_af_jn_{d}\n" ++
                        "_af_rl_{d}:\n  fence release\n  br label %_af_jn_{d}\n" ++
                        "_af_ar_{d}:\n  fence acq_rel\n  br label %_af_jn_{d}\n" ++
                        "_af_sc_{d}:\n  fence seq_cst\n  br label %_af_jn_{d}\n" ++
                        "_af_bad_{d}:\n  call void @_cx_rt_trap(i32 3)\n  unreachable\n" ++
                        "_af_jn_{d}:\n  %_v_{d} = add i8 0, 0\n",
                    .{
                        ord32,  tmp_id, tmp_id,  tmp_id, tmp_id, tmp_id, tmp_id, tmp_id,
                        tmp_id, tmp_id, tmp_id,  tmp_id, tmp_id, tmp_id, tmp_id, tmp_id,
                        tmp_id, tmp_id, dst_raw,
                    },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_af_jn_{d}", .{tmp_id}));
            }
        },

        .atomic_load => {
            if (args.len < 1 or (try isZeroSizedType(emitter, inst.type_id))) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const dst_ty = try unwrapTransparentType(emitter, inst.type_id);
            const lay = try emitter.resolver.resolveType(dst_ty);
            const val_align = @max(lay.alignBytes(), 1);
            const maybe_ord = if (args.len >= 2) args[1] else null;

            if (extractConstU64FromMirBody(body, maybe_ord)) |const_ord| {
                const ord_kw = resolveLlvmAtomicOrderKeyword(const_ord, .load_op) orelse {
                    try state.writeAll("  call void @_cx_rt_trap(i32 3)\n");
                    try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
                    return;
                };
                if (dst_ty == .bool_ty) {
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  %_ald8_{d} = load atomic i8, ptr %_v_{d} {s}, align 1\n" ++
                            "  %_alda_{d} = and i8 %_ald8_{d}, 1\n" ++
                            "  %_v_{d} = trunc i8 %_alda_{d} to i1\n",
                        .{ tmp_id, args[0], ord_kw, tmp_id, tmp_id, dst_raw, tmp_id },
                    );
                } else {
                    const val_ty = try formatLlvmValueType(emitter, dst_ty);
                    defer emitter.allocator.free(val_ty);
                    try state.print(
                        "  %_v_{d} = load atomic {s}, ptr %_v_{d} {s}, align {d}\n",
                        .{ dst_raw, val_ty, args[0], ord_kw, val_align },
                    );
                }
            } else {
                const ord32 = try emitCoerceOrderToI32Llvm(emitter, state, body, maybe_ord);
                defer emitter.allocator.free(ord32);
                const res_slot = try state.allocEntryBytes(@max(lay.size_bytes, 1), val_align);
                defer emitter.allocator.free(res_slot);
                const tmp_id = state.nextTmp();
                try state.print(
                    "  switch i32 {s}, label %_ald_bad_{d} [\n" ++
                        "    i32 0, label %_ald_c0_{d}\n" ++
                        "    i32 3, label %_ald_c0_{d}\n" ++
                        "    i32 1, label %_ald_c1_{d}\n" ++
                        "    i32 2, label %_ald_c1_{d}\n" ++
                        "    i32 4, label %_ald_c1_{d}\n" ++
                        "    i32 5, label %_ald_c2_{d}\n" ++
                        "  ]\n",
                    .{ ord32, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id },
                );
                const load_kws = [_][]const u8{ "monotonic", "acquire", "seq_cst" };
                const val_ty = if (dst_ty == .bool_ty)
                    try emitter.allocator.dupe(u8, "i8")
                else
                    try formatLlvmValueType(emitter, dst_ty);
                defer emitter.allocator.free(val_ty);
                const eff_align: u32 = if (dst_ty == .bool_ty) 1 else val_align;
                for (load_kws, 0..) |ord_kw, case_i| {
                    try state.print(
                        "_ald_c{d}_{d}:\n" ++
                            "  %_aldr_{d}_{d} = load atomic {s}, ptr %_v_{d} {s}, align {d}\n" ++
                            "  store {s} %_aldr_{d}_{d}, ptr {s}, align {d}\n" ++
                            "  br label %_ald_jn_{d}\n",
                        .{
                            case_i,    tmp_id, case_i, tmp_id, val_ty,   args[0],   ord_kw,
                            eff_align, val_ty, case_i, tmp_id, res_slot, eff_align, tmp_id,
                        },
                    );
                }
                try state.print(
                    "_ald_bad_{d}:\n  call void @_cx_rt_trap(i32 3)\n  unreachable\n_ald_jn_{d}:\n",
                    .{ tmp_id, tmp_id },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_ald_jn_{d}", .{tmp_id}));
                if (dst_ty == .bool_ty) {
                    try state.print(
                        "  %_ald8_{d} = load i8, ptr {s}, align 1\n" ++
                            "  %_alda_{d} = and i8 %_ald8_{d}, 1\n" ++
                            "  %_v_{d} = trunc i8 %_alda_{d} to i1\n",
                        .{ tmp_id, res_slot, tmp_id, tmp_id, dst_raw, tmp_id },
                    );
                } else {
                    try state.print(
                        "  %_v_{d} = load {s}, ptr {s}, align {d}\n",
                        .{ dst_raw, val_ty, res_slot, eff_align },
                    );
                }
            }
        },

        .atomic_store => {
            if (args.len >= 2) {
                const val_ty = try unwrapTransparentType(
                    emitter,
                    body.getInst(MirValueId.fromInt(args[1])).type_id,
                );
                const maybe_ord = if (args.len >= 3) args[2] else null;
                if (extractConstU64FromMirBody(body, maybe_ord)) |const_ord| {
                    const ord_kw = resolveLlvmAtomicOrderKeyword(const_ord, .store_op) orelse {
                        try state.writeAll("  call void @_cx_rt_trap(i32 3)\n");
                        try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
                        return;
                    };
                    if (!(try isZeroSizedType(emitter, val_ty))) {
                        const lay = try emitter.resolver.resolveType(val_ty);
                        if (val_ty == .bool_ty) {
                            const tmp_id = state.nextTmp();
                            try state.print(
                                "  %_ast8_{d} = zext i1 %_v_{d} to i8\n" ++
                                    "  store atomic i8 %_ast8_{d}, ptr %_v_{d} {s}, align 1\n",
                                .{ tmp_id, args[1], tmp_id, args[0], ord_kw },
                            );
                        } else {
                            const val_llvm = try formatLlvmValueType(emitter, val_ty);
                            defer emitter.allocator.free(val_llvm);
                            try state.print(
                                "  store atomic {s} %_v_{d}, ptr %_v_{d} {s}, align {d}\n",
                                .{ val_llvm, args[1], args[0], ord_kw, @max(lay.alignBytes(), 1) },
                            );
                        }
                    }
                } else {
                    const ord32 = try emitCoerceOrderToI32Llvm(emitter, state, body, maybe_ord);
                    defer emitter.allocator.free(ord32);
                    const tmp_id = state.nextTmp();
                    if (try isZeroSizedType(emitter, val_ty)) {
                        try state.print("  %_ast_ob_{d} = icmp ugt i32 {s}, 5\n", .{ tmp_id, ord32 });
                        const bad_ssa = try std.fmt.allocPrint(emitter.allocator, "%_ast_ob_{d}", .{tmp_id});
                        defer emitter.allocator.free(bad_ssa);
                        try emitInlineTrapIfTrue(emitter, state, bad_ssa, 3);
                    } else {
                        const lay = try emitter.resolver.resolveType(val_ty);
                        const eff_align: u32 = if (val_ty == .bool_ty) 1 else @max(lay.alignBytes(), 1);
                        const val_llvm = if (val_ty == .bool_ty)
                            try emitter.allocator.dupe(u8, "i8")
                        else
                            try formatLlvmValueType(emitter, val_ty);
                        defer emitter.allocator.free(val_llvm);
                        const val_op = if (val_ty == .bool_ty) blk: {
                            try state.print("  %_ast8_{d} = zext i1 %_v_{d} to i8\n", .{ tmp_id, args[1] });
                            break :blk try std.fmt.allocPrint(emitter.allocator, "%_ast8_{d}", .{tmp_id});
                        } else try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[1]});
                        defer emitter.allocator.free(val_op);

                        try state.print(
                            "  switch i32 {s}, label %_ast_bad_{d} [\n" ++
                                "    i32 0, label %_ast_c0_{d}\n" ++
                                "    i32 1, label %_ast_c0_{d}\n" ++
                                "    i32 2, label %_ast_c0_{d}\n" ++
                                "    i32 3, label %_ast_c1_{d}\n" ++
                                "    i32 4, label %_ast_c1_{d}\n" ++
                                "    i32 5, label %_ast_c2_{d}\n" ++
                                "  ]\n",
                            .{ ord32, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id },
                        );
                        const store_kws = [_][]const u8{ "monotonic", "release", "seq_cst" };
                        for (store_kws, 0..) |ord_kw, case_i| {
                            try state.print(
                                "_ast_c{d}_{d}:\n" ++
                                    "  store atomic {s} {s}, ptr %_v_{d} {s}, align {d}\n" ++
                                    "  br label %_ast_jn_{d}\n",
                                .{ case_i, tmp_id, val_llvm, val_op, args[0], ord_kw, eff_align, tmp_id },
                            );
                        }
                        try state.print(
                            "_ast_bad_{d}:\n  call void @_cx_rt_trap(i32 3)\n  unreachable\n_ast_jn_{d}:\n",
                            .{ tmp_id, tmp_id },
                        );
                        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_ast_jn_{d}", .{tmp_id}));
                    }
                }
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .atomic_rmw_add, .atomic_rmw_sub, .atomic_rmw_xchg => {
            if (args.len < 2 or (try isZeroSizedType(emitter, inst.type_id))) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const dst_ty = try unwrapTransparentType(emitter, inst.type_id);
            const lay = try emitter.resolver.resolveType(dst_ty);
            const val_align = @max(lay.alignBytes(), 1);
            const rmw_op = switch (ikind) {
                .atomic_rmw_add => "add",
                .atomic_rmw_sub => "sub",
                else => "xchg",
            };
            const maybe_ord = if (args.len >= 3) args[2] else null;

            if (extractConstU64FromMirBody(body, maybe_ord)) |const_ord| {
                const ord_kw = resolveLlvmAtomicOrderKeyword(const_ord, .rmw_op) orelse {
                    try state.writeAll("  call void @_cx_rt_trap(i32 3)\n");
                    try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
                    return;
                };
                if (dst_ty == .bool_ty) {
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  %_armwb_{d} = zext i1 %_v_{d} to i8\n" ++
                            "  %_armwr_{d} = atomicrmw {s} ptr %_v_{d}, i8 %_armwb_{d} {s}, align 1\n" ++
                            "  %_armwa_{d} = and i8 %_armwr_{d}, 1\n" ++
                            "  %_v_{d} = trunc i8 %_armwa_{d} to i1\n",
                        .{ tmp_id, args[1], tmp_id, rmw_op, args[0], tmp_id, ord_kw, tmp_id, tmp_id, dst_raw, tmp_id },
                    );
                } else {
                    const val_llvm = try formatLlvmValueType(emitter, dst_ty);
                    defer emitter.allocator.free(val_llvm);
                    try state.print(
                        "  %_v_{d} = atomicrmw {s} ptr %_v_{d}, {s} %_v_{d} {s}, align {d}\n",
                        .{ dst_raw, rmw_op, args[0], val_llvm, args[1], ord_kw, val_align },
                    );
                }
            } else {
                const ord32 = try emitCoerceOrderToI32Llvm(emitter, state, body, maybe_ord);
                defer emitter.allocator.free(ord32);
                const eff_align: u32 = if (dst_ty == .bool_ty) 1 else val_align;
                const res_slot = try state.allocEntryBytes(@max(lay.size_bytes, 1), eff_align);
                defer emitter.allocator.free(res_slot);
                const tmp_id = state.nextTmp();
                const val_llvm = if (dst_ty == .bool_ty)
                    try emitter.allocator.dupe(u8, "i8")
                else
                    try formatLlvmValueType(emitter, dst_ty);
                defer emitter.allocator.free(val_llvm);
                const val_op = if (dst_ty == .bool_ty) blk: {
                    try state.print("  %_armwb_{d} = zext i1 %_v_{d} to i8\n", .{ tmp_id, args[1] });
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_armwb_{d}", .{tmp_id});
                } else try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[1]});
                defer emitter.allocator.free(val_op);

                try state.print(
                    "  switch i32 {s}, label %_arm_bad_{d} [\n" ++
                        "    i32 0, label %_arm_c0_{d}\n" ++
                        "    i32 1, label %_arm_c1_{d}\n" ++
                        "    i32 2, label %_arm_c1_{d}\n" ++
                        "    i32 3, label %_arm_c2_{d}\n" ++
                        "    i32 4, label %_arm_c3_{d}\n" ++
                        "    i32 5, label %_arm_c4_{d}\n" ++
                        "  ]\n",
                    .{ ord32, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id },
                );
                const rmw_kws = [_][]const u8{ "monotonic", "acquire", "release", "acq_rel", "seq_cst" };
                for (rmw_kws, 0..) |ord_kw, case_i| {
                    try state.print(
                        "_arm_c{d}_{d}:\n" ++
                            "  %_armr_{d}_{d} = atomicrmw {s} ptr %_v_{d}, {s} {s} {s}, align {d}\n" ++
                            "  store {s} %_armr_{d}_{d}, ptr {s}, align {d}\n" ++
                            "  br label %_arm_jn_{d}\n",
                        .{
                            case_i, tmp_id,    case_i,   tmp_id, rmw_op, args[0],  val_llvm,  val_op,
                            ord_kw, eff_align, val_llvm, case_i, tmp_id, res_slot, eff_align, tmp_id,
                        },
                    );
                }
                try state.print(
                    "_arm_bad_{d}:\n  call void @_cx_rt_trap(i32 3)\n  unreachable\n_arm_jn_{d}:\n",
                    .{ tmp_id, tmp_id },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_arm_jn_{d}", .{tmp_id}));
                if (dst_ty == .bool_ty) {
                    try state.print(
                        "  %_armwr_{d} = load i8, ptr {s}, align 1\n" ++
                            "  %_armwa_{d} = and i8 %_armwr_{d}, 1\n" ++
                            "  %_v_{d} = trunc i8 %_armwa_{d} to i1\n",
                        .{ tmp_id, res_slot, tmp_id, tmp_id, dst_raw, tmp_id },
                    );
                } else {
                    try state.print(
                        "  %_v_{d} = load {s}, ptr {s}, align {d}\n",
                        .{ dst_raw, val_llvm, res_slot, eff_align },
                    );
                }
            }
        },

        .atomic_cmpxchg => {
            if (args.len < 3) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const val_ty = try unwrapTransparentType(
                emitter,
                body.getInst(MirValueId.fromInt(args[1])).type_id,
            );
            const val_lay = try emitter.resolver.resolveType(val_ty);
            const eff_align: u32 = if (val_ty == .bool_ty) 1 else @max(val_lay.alignBytes(), 1);
            const tup_ty = try unwrapTransparentType(emitter, inst.type_id);
            const tup_lay = try emitter.resolver.resolveType(tup_ty);
            const tmp_id = state.nextTmp();

            const const_succ = extractConstU64FromMirBody(body, if (args.len >= 4) args[3] else null);
            const const_fail = if (args.len >= 5) extractConstU64FromMirBody(body, args[4]) else const_succ;
            const const_weak = extractConstWeakFromMirBody(body, if (args.len >= 6) args[5] else null);

            if (const_succ != null and const_fail != null and const_weak != null) {
                const pair_idx = resolveLlvmCmpxchgPairIndex(const_succ.?, const_fail.?) orelse {
                    try state.writeAll("  call void @_cx_rt_trap(i32 3)\n");
                    try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
                    return;
                };
                const pair = CMPXCHG_ORDER_PAIRS[pair_idx];
                const cx_kw = if (const_weak.?) "cmpxchg weak" else "cmpxchg";
                if (val_ty == .bool_ty) {
                    try state.print(
                        "  %_cx_e8_{d} = zext i1 %_v_{d} to i8\n" ++
                            "  %_cx_d8_{d} = zext i1 %_v_{d} to i8\n" ++
                            "  %_cx_pr_{d} = {s} ptr %_v_{d}, i8 %_cx_e8_{d}, i8 %_cx_d8_{d} {s} {s}, align 1\n" ++
                            "  %_cx_o8_{d} = extractvalue {{ i8, i1 }} %_cx_pr_{d}, 0\n" ++
                            "  %_cx_oa_{d} = and i8 %_cx_o8_{d}, 1\n" ++
                            "  %_cx_old_{d} = trunc i8 %_cx_oa_{d} to i1\n" ++
                            "  %_cx_ok_{d} = extractvalue {{ i8, i1 }} %_cx_pr_{d}, 1\n",
                        .{
                            tmp_id,       args[1],
                            tmp_id,       args[2],
                            tmp_id,       cx_kw,
                            args[0],      tmp_id,
                            tmp_id,       pair.succ_kw,
                            pair.fail_kw, tmp_id,
                            tmp_id,       tmp_id,
                            tmp_id,       tmp_id,
                            tmp_id,       tmp_id,
                            tmp_id,
                        },
                    );
                } else {
                    const val_llvm = try formatLlvmValueType(emitter, val_ty);
                    defer emitter.allocator.free(val_llvm);
                    try state.print(
                        "  %_cx_pr_{d} = {s} ptr %_v_{d}, {s} %_v_{d}, {s} %_v_{d} {s} {s}, align {d}\n" ++
                            "  %_cx_old_{d} = extractvalue {{ {s}, i1 }} %_cx_pr_{d}, 0\n" ++
                            "  %_cx_ok_{d} = extractvalue {{ {s}, i1 }} %_cx_pr_{d}, 1\n",
                        .{
                            tmp_id,  cx_kw,        args[0],      val_llvm,  args[1], val_llvm,
                            args[2], pair.succ_kw, pair.fail_kw, eff_align, tmp_id,  val_llvm,
                            tmp_id,  tmp_id,       val_llvm,     tmp_id,
                        },
                    );
                }
            } else {
                if (const_succ != null and const_fail != null) {
                    if (resolveLlvmCmpxchgPairIndex(const_succ.?, const_fail.?) == null) {
                        try state.writeAll("  call void @_cx_rt_trap(i32 3)\n");
                        try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
                        return;
                    }
                }
                const old_slot = try state.allocEntryBytes(@max(val_lay.size_bytes, 1), eff_align);
                defer emitter.allocator.free(old_slot);
                const ok_slot = try state.allocEntryBytes(1, 1);
                defer emitter.allocator.free(ok_slot);

                const val_llvm = if (val_ty == .bool_ty)
                    try emitter.allocator.dupe(u8, "i8")
                else
                    try formatLlvmValueType(emitter, val_ty);
                defer emitter.allocator.free(val_llvm);

                const exp_op = if (val_ty == .bool_ty) blk: {
                    try state.print("  %_cx_e8_{d} = zext i1 %_v_{d} to i8\n", .{ tmp_id, args[1] });
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_cx_e8_{d}", .{tmp_id});
                } else try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[1]});
                defer emitter.allocator.free(exp_op);

                const des_op = if (val_ty == .bool_ty) blk: {
                    try state.print("  %_cx_d8_{d} = zext i1 %_v_{d} to i8\n", .{ tmp_id, args[2] });
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_cx_d8_{d}", .{tmp_id});
                } else try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[2]});
                defer emitter.allocator.free(des_op);

                if (const_succ != null and const_fail != null) {
                    const pair = CMPXCHG_ORDER_PAIRS[resolveLlvmCmpxchgPairIndex(const_succ.?, const_fail.?).?];
                    const weak_i1 = try emitCoerceWeakToI1Llvm(emitter, state, body, args[5]);
                    defer emitter.allocator.free(weak_i1);
                    try state.print(
                        "  br i1 {s}, label %_acx_wk_{d}, label %_acx_st_{d}\n" ++
                            "_acx_wk_{d}:\n" ++
                            "  %_acxpw_{d} = cmpxchg weak ptr %_v_{d}, {s} {s}, {s} {s} {s} {s}, align {d}\n" ++
                            "  %_acxow_{d} = extractvalue {{ {s}, i1 }} %_acxpw_{d}, 0\n" ++
                            "  %_acxkw_{d} = extractvalue {{ {s}, i1 }} %_acxpw_{d}, 1\n" ++
                            "  %_acxzw_{d} = zext i1 %_acxkw_{d} to i8\n" ++
                            "  store {s} %_acxow_{d}, ptr {s}, align {d}\n" ++
                            "  store i8 %_acxzw_{d}, ptr {s}, align 1\n" ++
                            "  br label %_acx_jn_{d}\n",
                        .{
                            weak_i1,   tmp_id, tmp_id,   tmp_id,   tmp_id,       args[0],
                            val_llvm,  exp_op, val_llvm, des_op,   pair.succ_kw, pair.fail_kw,
                            eff_align, tmp_id, val_llvm, tmp_id,   tmp_id,       val_llvm,
                            tmp_id,    tmp_id, tmp_id,   val_llvm, tmp_id,       old_slot,
                            eff_align, tmp_id, ok_slot,  tmp_id,
                        },
                    );
                    try state.print(
                        "_acx_st_{d}:\n" ++
                            "  %_acxps_{d} = cmpxchg ptr %_v_{d}, {s} {s}, {s} {s} {s} {s}, align {d}\n" ++
                            "  %_acxos_{d} = extractvalue {{ {s}, i1 }} %_acxps_{d}, 0\n" ++
                            "  %_acxks_{d} = extractvalue {{ {s}, i1 }} %_acxps_{d}, 1\n" ++
                            "  %_acxzs_{d} = zext i1 %_acxks_{d} to i8\n" ++
                            "  store {s} %_acxos_{d}, ptr {s}, align {d}\n" ++
                            "  store i8 %_acxzs_{d}, ptr {s}, align 1\n" ++
                            "  br label %_acx_jn_{d}\n" ++
                            "_acx_jn_{d}:\n",
                        .{
                            tmp_id,   tmp_id,       args[0],      val_llvm,  exp_op, val_llvm,
                            des_op,   pair.succ_kw, pair.fail_kw, eff_align, tmp_id, val_llvm,
                            tmp_id,   tmp_id,       val_llvm,     tmp_id,    tmp_id, tmp_id,
                            val_llvm, tmp_id,       old_slot,     eff_align, tmp_id, ok_slot,
                            tmp_id,   tmp_id,
                        },
                    );
                } else {
                    const succ32 = try emitCoerceOrderToI32Llvm(
                        emitter,
                        state,
                        body,
                        if (args.len >= 4) args[3] else null,
                    );
                    defer emitter.allocator.free(succ32);
                    const fail32 = if (args.len >= 5)
                        try emitCoerceOrderToI32Llvm(emitter, state, body, args[4])
                    else
                        try emitter.allocator.dupe(u8, succ32);
                    defer emitter.allocator.free(fail32);

                    try state.print(
                        "  %_cx_bs_{d} = icmp ugt i32 {s}, 5\n" ++
                            "  %_cx_bf_{d} = icmp ugt i32 {s}, 5\n" ++
                            "  %_cx_bo_{d} = or i1 %_cx_bs_{d}, %_cx_bf_{d}\n",
                        .{ tmp_id, succ32, tmp_id, fail32, tmp_id, tmp_id, tmp_id },
                    );
                    const bad_ord_ssa = try std.fmt.allocPrint(emitter.allocator, "%_cx_bo_{d}", .{tmp_id});
                    defer emitter.allocator.free(bad_ord_ssa);
                    try emitInlineTrapIfTrue(emitter, state, bad_ord_ssa, 3);

                    if (const_weak == null) {
                        const weak_i1 = try emitCoerceWeakToI1Llvm(emitter, state, body, args[5]);
                        defer emitter.allocator.free(weak_i1);
                        try state.print(
                            "  %_cx_fm6_{d} = mul i32 {s}, 6\n" ++
                                "  %_cx_cmb0_{d} = add i32 %_cx_fm6_{d}, {s}\n" ++
                                "  %_cx_wo_{d} = select i1 {s}, i32 36, i32 0\n" ++
                                "  %_cx_cmb_{d} = add i32 %_cx_cmb0_{d}, %_cx_wo_{d}\n" ++
                                "  switch i32 %_cx_cmb_{d}, label %_acx_bad_{d} [\n",
                            .{
                                tmp_id,  fail32, tmp_id, tmp_id, succ32, tmp_id,
                                weak_i1, tmp_id, tmp_id, tmp_id, tmp_id, tmp_id,
                            },
                        );
                    } else {
                        try state.print(
                            "  %_cx_fm6_{d} = mul i32 {s}, 6\n" ++
                                "  %_cx_cmb_{d} = add i32 %_cx_fm6_{d}, {s}\n" ++
                                "  switch i32 %_cx_cmb_{d}, label %_acx_bad_{d} [\n",
                            .{ tmp_id, fail32, tmp_id, tmp_id, succ32, tmp_id, tmp_id },
                        );
                    }
                    var fail_k: u64 = 0;
                    while (fail_k <= 5) : (fail_k += 1) {
                        var succ_k: u64 = 0;
                        while (succ_k <= 5) : (succ_k += 1) {
                            const pair_idx = resolveLlvmCmpxchgPairIndex(succ_k, fail_k).?;
                            try state.print(
                                "    i32 {d}, label %_acx_c{d}_{d}\n",
                                .{ fail_k * 6 + succ_k, pair_idx, tmp_id },
                            );
                            if (const_weak == null) {
                                try state.print(
                                    "    i32 {d}, label %_acx_cw{d}_{d}\n",
                                    .{ 36 + fail_k * 6 + succ_k, pair_idx, tmp_id },
                                );
                            }
                        }
                    }
                    try state.writeAll("  ]\n");
                    const base_cx_kw = if (const_weak != null and const_weak.?) "cmpxchg weak" else "cmpxchg";
                    for (CMPXCHG_ORDER_PAIRS, 0..) |pair, case_i| {
                        try state.print(
                            "_acx_c{d}_{d}:\n" ++
                                "  %_acxp_{d}_{d} = {s} ptr %_v_{d}, {s} {s}, {s} {s} {s} {s}, align {d}\n" ++
                                "  %_acxo_{d}_{d} = extractvalue {{ {s}, i1 }} %_acxp_{d}_{d}, 0\n" ++
                                "  %_acxk_{d}_{d} = extractvalue {{ {s}, i1 }} %_acxp_{d}_{d}, 1\n",
                            .{
                                case_i,    tmp_id, case_i,   tmp_id,   base_cx_kw,   args[0],
                                val_llvm,  exp_op, val_llvm, des_op,   pair.succ_kw, pair.fail_kw,
                                eff_align, case_i, tmp_id,   val_llvm, case_i,       tmp_id,
                                case_i,    tmp_id, val_llvm, case_i,   tmp_id,
                            },
                        );
                        try state.print(
                            "  %_acxz_{d}_{d} = zext i1 %_acxk_{d}_{d} to i8\n" ++
                                "  store {s} %_acxo_{d}_{d}, ptr {s}, align {d}\n" ++
                                "  store i8 %_acxz_{d}_{d}, ptr {s}, align 1\n" ++
                                "  br label %_acx_jn_{d}\n",
                            .{
                                case_i,   tmp_id,    case_i, tmp_id, val_llvm, case_i, tmp_id,
                                old_slot, eff_align, case_i, tmp_id, ok_slot,  tmp_id,
                            },
                        );
                        if (const_weak == null) {
                            try state.print(
                                "_acx_cw{d}_{d}:\n" ++
                                    "  %_acxwp_{d}_{d} = cmpxchg weak ptr %_v_{d}, {s} {s}, {s} {s} {s} {s}, align {d}\n" ++
                                    "  %_acxwo_{d}_{d} = extractvalue {{ {s}, i1 }} %_acxwp_{d}_{d}, 0\n" ++
                                    "  %_acxwk_{d}_{d} = extractvalue {{ {s}, i1 }} %_acxwp_{d}_{d}, 1\n",
                                .{
                                    case_i, tmp_id,   case_i,   tmp_id,       args[0],      val_llvm,
                                    exp_op, val_llvm, des_op,   pair.succ_kw, pair.fail_kw, eff_align,
                                    case_i, tmp_id,   val_llvm, case_i,       tmp_id,       case_i,
                                    tmp_id, val_llvm, case_i,   tmp_id,
                                },
                            );
                            try state.print(
                                "  %_acxwz_{d}_{d} = zext i1 %_acxwk_{d}_{d} to i8\n" ++
                                    "  store {s} %_acxwo_{d}_{d}, ptr {s}, align {d}\n" ++
                                    "  store i8 %_acxwz_{d}_{d}, ptr {s}, align 1\n" ++
                                    "  br label %_acx_jn_{d}\n",
                                .{
                                    case_i,   tmp_id,    case_i, tmp_id, val_llvm, case_i, tmp_id,
                                    old_slot, eff_align, case_i, tmp_id, ok_slot,  tmp_id,
                                },
                            );
                        }
                    }
                    try state.print(
                        "_acx_bad_{d}:\n  call void @_cx_rt_trap(i32 3)\n  unreachable\n_acx_jn_{d}:\n",
                        .{ tmp_id, tmp_id },
                    );
                }
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_acx_jn_{d}", .{tmp_id}));
                if (val_ty == .bool_ty) {
                    try state.print(
                        "  %_cx_o8_{d} = load i8, ptr {s}, align 1\n" ++
                            "  %_cx_oa_{d} = and i8 %_cx_o8_{d}, 1\n" ++
                            "  %_cx_old_{d} = trunc i8 %_cx_oa_{d} to i1\n",
                        .{ tmp_id, old_slot, tmp_id, tmp_id, tmp_id, tmp_id },
                    );
                } else {
                    try state.print(
                        "  %_cx_old_{d} = load {s}, ptr {s}, align {d}\n",
                        .{ tmp_id, val_llvm, old_slot, eff_align },
                    );
                }
                try state.print(
                    "  %_cx_kb8_{d} = load i8, ptr {s}, align 1\n" ++
                        "  %_cx_kba_{d} = and i8 %_cx_kb8_{d}, 1\n" ++
                        "  %_cx_ok_{d} = trunc i8 %_cx_kba_{d} to i1\n",
                    .{ tmp_id, ok_slot, tmp_id, tmp_id, tmp_id, tmp_id },
                );
            }

            const old_ssa = try std.fmt.allocPrint(emitter.allocator, "%_cx_old_{d}", .{tmp_id});
            defer emitter.allocator.free(old_ssa);
            const ok_ssa = try std.fmt.allocPrint(emitter.allocator, "%_cx_ok_{d}", .{tmp_id});
            defer emitter.allocator.free(ok_ssa);

            const tup_slot = try state.allocEntryBytes(tup_lay.size_bytes, tup_lay.alignBytes());
            defer emitter.allocator.free(tup_slot);
            try emitMemsetZero(emitter, state, tup_slot, tup_lay.size_bytes, tup_lay.alignBytes());

            if (try emitter.resolver.getFieldByDeclOrdinal(tup_ty, 0)) |fld0| {
                const p0 = if (fld0.byte_offset == 0)
                    try emitter.allocator.dupe(u8, tup_slot)
                else sub: {
                    try state.print(
                        "  %_cx_f0_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ tmp_id, tup_slot, ptr_int, fld0.byte_offset },
                    );
                    break :sub try std.fmt.allocPrint(emitter.allocator, "%_cx_f0_{d}", .{tmp_id});
                };
                defer emitter.allocator.free(p0);
                try emitStoreValueToPtr(
                    emitter,
                    state,
                    val_ty,
                    old_ssa,
                    p0,
                    @min(
                        tup_lay.alignBytes(),
                        effectiveOffsetAlign(fld0.byte_offset, @as(u32, 1) << @intCast(fld0.align_log2)),
                    ),
                    0,
                    0,
                    0,
                );
            }
            if (try emitter.resolver.getFieldByDeclOrdinal(tup_ty, 1)) |fld1| {
                const p1 = if (fld1.byte_offset == 0)
                    try emitter.allocator.dupe(u8, tup_slot)
                else sub: {
                    try state.print(
                        "  %_cx_f1_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                        .{ tmp_id, tup_slot, ptr_int, fld1.byte_offset },
                    );
                    break :sub try std.fmt.allocPrint(emitter.allocator, "%_cx_f1_{d}", .{tmp_id});
                };
                defer emitter.allocator.free(p1);
                try emitStoreValueToPtr(emitter, state, .bool_ty, ok_ssa, p1, 1, 0, 0, 0);
            }

            const loaded = try emitLoadValueFromPtr(emitter, state, tup_ty, tup_slot, tup_lay.alignBytes(), null, 0, 0, 0);
            defer emitter.allocator.free(loaded);
            const tup_val_ty = try formatLlvmValueType(emitter, tup_ty);
            defer emitter.allocator.free(tup_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, tup_val_ty, loaded, tup_val_ty, loaded },
            );
        },

        .simd_splat => {
            if (args.len < 1) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const vec_ty = try unwrapTransparentType(emitter, inst.type_id);
            const vec_lay = try emitter.resolver.resolveType(vec_ty);
            const vec_node = emitter.input.pool.getNode(vec_ty);
            const lane_ty = try unwrapTransparentType(emitter, TypeId.fromInt(vec_node.lhs));
            const lanes: u64 = vec_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            const lane_llvm = try formatLlvmValueType(emitter, lane_ty);
            defer emitter.allocator.free(lane_llvm);

            const vec_align = @max(vec_lay.alignBytes(), 16);
            const scratch = try state.allocEntryBytes(vec_lay.size_bytes, vec_align);
            defer emitter.allocator.free(scratch);
            const tmp_id = state.nextTmp();
            try state.print(
                "  %_vsp_i_{d} = insertelement <{d} x {s}> poison, {s} %_v_{d}, i32 0\n" ++
                    "  %_vsp_v_{d} = shufflevector <{d} x {s}> %_vsp_i_{d}, <{d} x {s}> poison, <{d} x i32> zeroinitializer\n" ++
                    "  store <{d} x {s}> %_vsp_v_{d}, ptr {s}, align {d}\n" ++
                    "  %_v_{d} = load [{d} x {s}], ptr {s}, align {d}\n",
                .{
                    tmp_id,    lanes,     lane_llvm, lane_llvm, args[0],
                    tmp_id,    lanes,     lane_llvm, tmp_id,    lanes,
                    lane_llvm, lanes,     lanes,     lane_llvm, tmp_id,
                    scratch,   vec_align, dst_raw,   lanes,     lane_llvm,
                    scratch,   vec_align,
                },
            );
        },

        .simd_add, .simd_sub, .simd_mul => {
            if (args.len < 2) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const vec_ty = try unwrapTransparentType(emitter, inst.type_id);
            const vec_lay = try emitter.resolver.resolveType(vec_ty);
            const vec_node = emitter.input.pool.getNode(vec_ty);
            const lane_ty = try unwrapTransparentType(emitter, TypeId.fromInt(vec_node.lhs));
            const lanes: u64 = vec_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            const lane_llvm = try formatLlvmValueType(emitter, lane_ty);
            defer emitter.allocator.free(lane_llvm);
            const is_flt = lane_ty == .f32_ty or lane_ty == .f64_ty;
            const vop = switch (ikind) {
                .simd_add => if (is_flt) "fadd" else "add",
                .simd_sub => if (is_flt) "fsub" else "sub",
                else => if (is_flt) "fmul" else "mul",
            };

            const vec_align = @max(vec_lay.alignBytes(), 16);
            const vec_store_bytes = std.math.ceilPowerOfTwo(u64, @max(vec_lay.size_bytes, 1)) catch vec_lay.size_bytes;
            const slot_l = try state.allocEntryBytes(vec_store_bytes, vec_align);
            defer emitter.allocator.free(slot_l);
            const slot_r = try state.allocEntryBytes(vec_store_bytes, vec_align);
            defer emitter.allocator.free(slot_r);
            const tmp_id = state.nextTmp();
            try state.print(
                "  store [{d} x {s}] %_v_{d}, ptr {s}, align {d}\n" ++
                    "  store [{d} x {s}] %_v_{d}, ptr {s}, align {d}\n" ++
                    "  %_vbl_{d} = load <{d} x {s}>, ptr {s}, align {d}\n" ++
                    "  %_vbr_{d} = load <{d} x {s}>, ptr {s}, align {d}\n",
                .{
                    lanes,  lane_llvm, args[0],   slot_l, vec_align,
                    lanes,  lane_llvm, args[1],   slot_r, vec_align,
                    tmp_id, lanes,     lane_llvm, slot_l, vec_align,
                    tmp_id, lanes,     lane_llvm, slot_r, vec_align,
                },
            );
            try state.print(
                "  %_vbo_{d} = {s} <{d} x {s}> %_vbl_{d}, %_vbr_{d}\n" ++
                    "  store <{d} x {s}> %_vbo_{d}, ptr {s}, align {d}\n" ++
                    "  %_v_{d} = load [{d} x {s}], ptr {s}, align {d}\n",
                .{
                    tmp_id, vop,       lanes,  lane_llvm, tmp_id,    tmp_id,
                    lanes,  lane_llvm, tmp_id, slot_l,    vec_align, dst_raw,
                    lanes,  lane_llvm, slot_l, vec_align,
                },
            );
        },

        .simd_reduce_add => {
            if (args.len < 1) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const vec_ty = try unwrapTransparentType(
                emitter,
                body.getInst(MirValueId.fromInt(args[0])).type_id,
            );
            const vec_lay = try emitter.resolver.resolveType(vec_ty);
            const vec_node = emitter.input.pool.getNode(vec_ty);
            const lane_ty = try unwrapTransparentType(emitter, TypeId.fromInt(vec_node.lhs));
            const lanes: u64 = vec_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
            const lane_llvm = try formatLlvmValueType(emitter, lane_ty);
            defer emitter.allocator.free(lane_llvm);

            const vec_align = @max(vec_lay.alignBytes(), 16);
            const vec_store_bytes = std.math.ceilPowerOfTwo(u64, @max(vec_lay.size_bytes, 1)) catch vec_lay.size_bytes;
            const slot_v = try state.allocEntryBytes(vec_store_bytes, vec_align);
            defer emitter.allocator.free(slot_v);
            const tmp_id = state.nextTmp();
            try state.print(
                "  store [{d} x {s}] %_v_{d}, ptr {s}, align {d}\n" ++
                    "  %_vrd_v_{d} = load <{d} x {s}>, ptr {s}, align {d}\n",
                .{
                    lanes,  lane_llvm, args[0],   slot_v, vec_align,
                    tmp_id, lanes,     lane_llvm, slot_v, vec_align,
                },
            );

            if (lane_ty == .f32_ty or lane_ty == .f64_ty) {
                const mangled_f = if (lane_ty == .f32_ty) "f32" else "f64";
                const decl = try std.fmt.allocPrint(
                    emitter.allocator,
                    "declare {s} @llvm.vector.reduce.fadd.v{d}{s}({s}, <{d} x {s}>)",
                    .{ lane_llvm, lanes, mangled_f, lane_llvm, lanes, lane_llvm },
                );
                defer emitter.allocator.free(decl);
                try emitter.requireIntrinsicDecl(decl);
                try state.print(
                    "  %_v_{d} = call {s} @llvm.vector.reduce.fadd.v{d}{s}({s} -0.0, <{d} x {s}> %_vrd_v_{d})\n",
                    .{ dst_raw, lane_llvm, lanes, mangled_f, lane_llvm, lanes, lane_llvm, tmp_id },
                );
            } else if (resolveIntegerInfo(emitter, lane_ty)) |l_info| {
                const decl = try std.fmt.allocPrint(
                    emitter.allocator,
                    "declare i{d} @llvm.vector.reduce.add.v{d}i{d}(<{d} x i{d}>)",
                    .{ l_info.bits, lanes, l_info.bits, lanes, l_info.bits },
                );
                defer emitter.allocator.free(decl);
                try emitter.requireIntrinsicDecl(decl);
                try state.print(
                    "  %_v_{d} = call i{d} @llvm.vector.reduce.add.v{d}i{d}(<{d} x i{d}> %_vrd_v_{d})\n",
                    .{ dst_raw, l_info.bits, lanes, l_info.bits, lanes, l_info.bits, tmp_id },
                );
            }
            _ = access_grp;
        },

        .poll_reload => {
            if (emitter.input.is_dev_got_enabled) {
                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_pr_pend_{d} = load atomic i64, ptr @_cx_reload_ctrl seq_cst, align 8\n" ++
                        "  %_pr_app_p_{d} = getelementptr inbounds {{ i64, i64, i64, i32, i32, i32, i32, i64, i32, i32, i64 }}, " ++
                        "ptr @_cx_reload_ctrl, i32 0, i32 1\n" ++
                        "  %_pr_app_{d} = load atomic i64, ptr %_pr_app_p_{d} seq_cst, align 8\n" ++
                        "  %_pr_has_{d} = icmp ugt i64 %_pr_pend_{d}, %_pr_app_{d}\n" ++
                        "  br i1 %_pr_has_{d}, label %_pr_upd_{d}, label %_pr_join_{d}\n" ++
                        "_pr_upd_{d}:\n" ++
                        "  store atomic i64 %_pr_pend_{d}, ptr %_pr_app_p_{d} seq_cst, align 8\n" ++
                        "  br label %_pr_join_{d}\n" ++
                        "_pr_join_{d}:\n" ++
                        "  %_v_{d} = or i1 %_pr_has_{d}, false\n",
                    .{
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        tmp_id,
                        dst_raw,
                        tmp_id,
                    },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_pr_join_{d}", .{tmp_id}));
            } else {
                try state.print("  %_v_{d} = or i1 false, false\n", .{dst_raw});
            }
        },

        .panic => {
            if (emitter.cfg.target.isFreestanding() or
                (emitter.is_in_c_abi_body and !emitter.input.is_oracle_trace_enabled))
            {
                try state.writeAll("  call void @llvm.trap()\n");
                try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
                return;
            }
            if (args.len >= 1) {
                const msg_ty = try unwrapTransparentType(
                    emitter,
                    body.getInst(MirValueId.fromInt(args[0])).type_id,
                );
                if (msg_ty == .fmt_args_ty) {
                    const fa_lay = try emitter.resolver.resolveType(.fmt_args_ty);
                    const fa_slot = try state.allocEntryBytes(fa_lay.size_bytes, fa_lay.alignBytes());
                    defer emitter.allocator.free(fa_slot);
                    const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
                    defer emitter.allocator.free(src_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        .fmt_args_ty,
                        src_ssa,
                        fa_slot,
                        fa_lay.alignBytes(),
                        0,
                        0,
                        0,
                    );
                    try state.print("  call void @_cx_rt_panic_fmt_args(ptr {s})\n", .{fa_slot});
                } else {
                    const span_s = try emitExtractByteSpanLlvm(emitter, state, body, MirValueId.fromInt(args[0]));
                    defer emitter.allocator.free(span_s.ptr_ssa);
                    defer emitter.allocator.free(span_s.len_ssa);
                    try state.print(
                        "  call void @_cx_rt_panic(ptr {s}, {s} {s})\n",
                        .{ span_s.ptr_ssa, ptr_int, span_s.len_ssa },
                    );
                }
            } else {
                try state.print("  call void @_cx_rt_panic(ptr null, {s} 0)\n", .{ptr_int});
            }
            try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
        },

        .trap => {
            if (emitter.cfg.target.isFreestanding() or
                (emitter.is_in_c_abi_body and !emitter.input.is_oracle_trace_enabled))
            {
                try state.writeAll("  call void @llvm.trap()\n");
            } else {
                try state.writeAll("  call void @_cx_rt_trap(i32 0)\n");
            }
            try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
        },

        .sys_write => {
            if (args.len < 2) {
                try state.print("  %_v_{d} = add {s} 0, 0\n", .{ dst_raw, ptr_int });
                return;
            }
            const fd_ty = body.getInst(MirValueId.fromInt(args[0])).type_id;
            const fd_info = resolveIntegerInfo(emitter, fd_ty) orelse
                IntScalarInfo{ .bits = 32, .is_signed = true };
            const tmp_id = state.nextTmp();
            const fd32_s = if (fd_info.bits == 32)
                try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]})
            else blk: {
                const op_s = if (fd_info.bits < 32)
                    (if (fd_info.is_signed) "sext" else "zext")
                else
                    "trunc";
                try state.print(
                    "  %_sw_fd_{d} = {s} i{d} %_v_{d} to i32\n",
                    .{ tmp_id, op_s, fd_info.bits, args[0] },
                );
                break :blk try std.fmt.allocPrint(emitter.allocator, "%_sw_fd_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(fd32_s);

            const span_s = try emitExtractByteSpanLlvm(emitter, state, body, MirValueId.fromInt(args[1]));
            defer emitter.allocator.free(span_s.ptr_ssa);
            defer emitter.allocator.free(span_s.len_ssa);
            try state.print(
                "  %_sw_res_{d} = call {s} @_cx_rt_sys_write(i32 {s}, ptr {s}, {s} {s})\n",
                .{ tmp_id, ptr_int, fd32_s, span_s.ptr_ssa, ptr_int, span_s.len_ssa },
            );
            const dst_info = resolveIntegerInfo(emitter, inst.type_id) orelse
                IntScalarInfo{ .bits = @as(u16, emitter.cfg.target.ptrBytes()) * 8, .is_signed = true };
            const ptr_bits: u16 = @as(u16, emitter.cfg.target.ptrBytes()) * 8;
            if (dst_info.bits == ptr_bits) {
                try state.print("  %_v_{d} = add {s} %_sw_res_{d}, 0\n", .{ dst_raw, ptr_int, tmp_id });
            } else if (dst_info.bits > ptr_bits) {
                try state.print(
                    "  %_v_{d} = sext {s} %_sw_res_{d} to i{d}\n",
                    .{ dst_raw, ptr_int, tmp_id, dst_info.bits },
                );
            } else {
                try state.print(
                    "  %_v_{d} = trunc {s} %_sw_res_{d} to i{d}\n",
                    .{ dst_raw, ptr_int, tmp_id, dst_info.bits },
                );
            }
        },

        .sys_exit => {
            if (args.len >= 1) {
                const code_ty = body.getInst(MirValueId.fromInt(args[0])).type_id;
                const code_info = resolveIntegerInfo(emitter, code_ty) orelse
                    IntScalarInfo{ .bits = 32, .is_signed = true };
                const tmp_id = state.nextTmp();
                const code32_s = if (code_info.bits == 32)
                    try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]})
                else blk: {
                    const op_s = if (code_info.bits < 32)
                        (if (code_info.is_signed) "sext" else "zext")
                    else
                        "trunc";
                    try state.print(
                        "  %_sx_c_{d} = {s} i{d} %_v_{d} to i32\n",
                        .{ tmp_id, op_s, code_info.bits, args[0] },
                    );
                    break :blk try std.fmt.allocPrint(emitter.allocator, "%_sx_c_{d}", .{tmp_id});
                };
                defer emitter.allocator.free(code32_s);
                try state.print("  call void @_cx_rt_sys_exit(i32 {s})\n", .{code32_s});
            } else {
                try state.writeAll("  call void @_cx_rt_sys_exit(i32 0)\n");
            }
            try emitUnreachableAndDeadBlock(emitter, state, dst_raw);
        },

        .subslice_make => {
            if (args.len < 3) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const base_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(args[0])).type_id);
            const base_node = emitter.input.pool.getNode(base_ty);
            const base_data_ptr: []u8 = if (base_ty == .str_ty or
                base_node.tag == .slice_ty or
                base_node.tag == .soa_slice_ty or
                emitter.input.pool.isSliceRefType(base_ty))
            blk_fat: {
                const bp_id = state.nextTmp();
                const base_sl_ty = try formatSliceLlvmStructType(emitter, base_ty);
                defer emitter.allocator.free(base_sl_ty);
                try state.print(
                    "  %_sm_bp_{d} = extractvalue {s} %_v_{d}, 0\n",
                    .{ bp_id, base_sl_ty, args[0] },
                );
                break :blk_fat try std.fmt.allocPrint(emitter.allocator, "%_sm_bp_{d}", .{bp_id});
            } else if (base_node.tag == .ref_ty or
                base_node.tag == .mut_ref_ty or
                base_node.tag == .raw_ptr_ty)
            blk_ref: {
                const pt_ty = try unwrapTransparentType(emitter, TypeId.fromInt(base_node.lhs));
                const pt_tag = emitter.input.pool.getNode(pt_ty).tag;
                if (pt_ty == .str_ty or
                    pt_tag == .slice_ty or
                    pt_tag == .soa_slice_ty or
                    emitter.input.pool.isSliceRefType(pt_ty))
                {
                    const bp_id = state.nextTmp();
                    try state.print(
                        "  %_sm_bp_{d} = load ptr, ptr %_v_{d}, align {d}\n",
                        .{ bp_id, args[0], emitter.cfg.target.ptrBytes() },
                    );
                    break :blk_ref try std.fmt.allocPrint(emitter.allocator, "%_sm_bp_{d}", .{bp_id});
                }
                break :blk_ref try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
            } else if (try isZeroSizedType(emitter, base_ty))
                try std.fmt.allocPrint(emitter.allocator, "inttoptr ({s} 1 to ptr)", .{ptr_int})
            else blk_arr: {
                const base_lay = try emitter.resolver.resolveType(base_ty);
                const scratch = try state.allocEntryBytes(base_lay.size_bytes, base_lay.alignBytes());
                const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
                defer emitter.allocator.free(src_ssa);
                try emitStoreValueToPtr(
                    emitter,
                    state,
                    base_ty,
                    src_ssa,
                    scratch,
                    base_lay.alignBytes(),
                    0,
                    0,
                    0,
                );
                break :blk_arr scratch;
            };
            defer emitter.allocator.free(base_data_ptr);

            const lo_ssa = try coerceIndexToPtrInt(emitter, state, body, args[1]);
            defer emitter.allocator.free(lo_ssa);
            const hi_ssa = try coerceIndexToPtrInt(emitter, state, body, args[2]);
            defer emitter.allocator.free(hi_ssa);

            const dst_unwrapped = try unwrapTransparentType(emitter, inst.type_id);
            const dst_node = emitter.input.pool.getNode(dst_unwrapped);
            const is_thin_ref_dst = (dst_node.tag == .ref_ty or
                dst_node.tag == .mut_ref_ty or
                dst_node.tag == .raw_ptr_ty) and !emitter.input.pool.isSliceRefType(dst_unwrapped);
            const sl_ty = if (emitter.input.pool.getSliceRefInner(dst_unwrapped)) |slice_inner|
                try unwrapTransparentType(emitter, slice_inner)
            else if (is_thin_ref_dst)
                try unwrapTransparentType(emitter, TypeId.fromInt(dst_node.lhs))
            else
                dst_unwrapped;

            const tmp_id = state.nextTmp();
            if (emitter.input.pool.isSoaSliceOrRefType(sl_ty)) {
                const ptr_bytes = emitter.cfg.target.ptrBytes();
                const soa_sl_ty = try formatSliceLlvmStructType(emitter, sl_ty);
                defer emitter.allocator.free(soa_sl_ty);
                var base_stride_ssa: []u8 = undefined;
                var base_eoff_ssa: []u8 = undefined;
                if (emitter.input.pool.isSoaSliceOrRefType(base_ty)) {
                    try state.print(
                        "  %_sm_bst_{d} = extractvalue {s} %_v_{d}, 2\n" ++
                            "  %_sm_beo_{d} = extractvalue {s} %_v_{d}, 3\n",
                        .{ tmp_id, soa_sl_ty, args[0], tmp_id, soa_sl_ty, args[0] },
                    );
                    base_stride_ssa = try std.fmt.allocPrint(emitter.allocator, "%_sm_bst_{d}", .{tmp_id});
                    base_eoff_ssa = try std.fmt.allocPrint(emitter.allocator, "%_sm_beo_{d}", .{tmp_id});
                } else if (base_node.tag == .ref_ty or base_node.tag == .mut_ref_ty or base_node.tag == .raw_ptr_ty) {
                    const pt_ty = try unwrapTransparentType(emitter, TypeId.fromInt(base_node.lhs));
                    if (emitter.input.pool.isSoaSliceOrRefType(pt_ty)) {
                        try state.print(
                            "  %_sm_sp_{d} = getelementptr inbounds i8, ptr %_v_{d}, {s} {d}\n" ++
                                "  %_sm_bst_{d} = load {s}, ptr %_sm_sp_{d}, align {d}\n" ++
                                "  %_sm_ep_{d} = getelementptr inbounds i8, ptr %_v_{d}, {s} {d}\n" ++
                                "  %_sm_beo_{d} = load {s}, ptr %_sm_ep_{d}, align {d}\n",
                            .{
                                tmp_id, args[0], ptr_int, ptr_bytes * 2,
                                tmp_id, ptr_int, tmp_id,  ptr_bytes,
                                tmp_id, args[0], ptr_int, ptr_bytes * 3,
                                tmp_id, ptr_int, tmp_id,  ptr_bytes,
                            },
                        );
                        base_stride_ssa = try std.fmt.allocPrint(emitter.allocator, "%_sm_bst_{d}", .{tmp_id});
                        base_eoff_ssa = try std.fmt.allocPrint(emitter.allocator, "%_sm_beo_{d}", .{tmp_id});
                    } else {
                        const arr_cap: u64 = emitter.input.pool.getNode(pt_ty).rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                        base_stride_ssa = try std.fmt.allocPrint(emitter.allocator, "{d}", .{arr_cap});
                        base_eoff_ssa = try emitter.allocator.dupe(u8, "0");
                    }
                } else {
                    const arr_cap: u64 = base_node.rhs & ~type_system.SYMBOLIC_ARRAY_LEN_FLAG;
                    base_stride_ssa = try std.fmt.allocPrint(emitter.allocator, "{d}", .{arr_cap});
                    base_eoff_ssa = try emitter.allocator.dupe(u8, "0");
                }
                defer emitter.allocator.free(base_stride_ssa);
                defer emitter.allocator.free(base_eoff_ssa);
                try state.print(
                    "  %_sm_len_{d} = sub {s} {s}, {s}\n" ++
                        "  %_sm_neo_{d} = add {s} {s}, {s}\n",
                    .{ tmp_id, ptr_int, hi_ssa, lo_ssa, tmp_id, ptr_int, base_eoff_ssa, lo_ssa },
                );
                if (is_thin_ref_dst) {
                    const fat_slot = try state.allocEntryBytes(4 * ptr_bytes, ptr_bytes);
                    defer emitter.allocator.free(fat_slot);
                    try state.print(
                        "  store ptr {s}, ptr {s}, align {d}\n" ++
                            "  %_sm_lp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  store {s} %_sm_len_{d}, ptr %_sm_lp_{d}, align {d}\n" ++
                            "  %_sm_stp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  store {s} {s}, ptr %_sm_stp_{d}, align {d}\n" ++
                            "  %_sm_eop_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                            "  store {s} %_sm_neo_{d}, ptr %_sm_eop_{d}, align {d}\n" ++
                            "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                        .{
                            base_data_ptr, fat_slot,        ptr_bytes,
                            tmp_id,        fat_slot,        ptr_int,
                            ptr_bytes,     ptr_int,         tmp_id,
                            tmp_id,        ptr_bytes,       tmp_id,
                            fat_slot,      ptr_int,         ptr_bytes * 2,
                            ptr_int,       base_stride_ssa, tmp_id,
                            ptr_bytes,     tmp_id,          fat_slot,
                            ptr_int,       ptr_bytes * 3,   ptr_int,
                            tmp_id,        tmp_id,          ptr_bytes,
                            dst_raw,       fat_slot,        fat_slot,
                        },
                    );
                } else {
                    try state.print(
                        "  %_sm_a0_{d} = insertvalue {s} zeroinitializer, ptr {s}, 0\n" ++
                            "  %_sm_a1_{d} = insertvalue {s} %_sm_a0_{d}, {s} %_sm_len_{d}, 1\n" ++
                            "  %_sm_a2_{d} = insertvalue {s} %_sm_a1_{d}, {s} {s}, 2\n" ++
                            "  %_v_{d} = insertvalue {s} %_sm_a2_{d}, {s} %_sm_neo_{d}, 3\n",
                        .{
                            tmp_id,          soa_sl_ty, base_data_ptr,
                            tmp_id,          soa_sl_ty, tmp_id,
                            ptr_int,         tmp_id,    tmp_id,
                            soa_sl_ty,       tmp_id,    ptr_int,
                            base_stride_ssa, dst_raw,   soa_sl_ty,
                            tmp_id,          ptr_int,   tmp_id,
                        },
                    );
                }
            } else {
                const elem_stride: u64 = if (sl_ty == .str_ty)
                    1
                else blk_st: {
                    const elem_ty = try unwrapTransparentType(
                        emitter,
                        TypeId.fromInt(emitter.input.pool.getNode(sl_ty).lhs),
                    );
                    break :blk_st (try emitter.resolver.resolveType(elem_ty)).stride_bytes;
                };
                try state.print(
                    "  %_sm_off_{d} = mul {s} {s}, {d}\n" ++
                        "  %_sm_ptr_{d} = getelementptr i8, ptr {s}, {s} %_sm_off_{d}\n" ++
                        "  %_sm_len_{d} = sub {s} {s}, {s}\n",
                    .{
                        tmp_id, ptr_int,       lo_ssa,  elem_stride,
                        tmp_id, base_data_ptr, ptr_int, tmp_id,
                        tmp_id, ptr_int,       hi_ssa,  lo_ssa,
                    },
                );
                if (is_thin_ref_dst) {
                    const fat_slot = try state.allocEntryBytes(
                        2 * emitter.cfg.target.ptrBytes(),
                        emitter.cfg.target.ptrBytes(),
                    );
                    defer emitter.allocator.free(fat_slot);
                    try state.print(
                        "  store ptr %_sm_ptr_{d}, ptr {s}, align {d}\n" ++
                            "  %_sm_lp_{d} = getelementptr inbounds {{ ptr, {s} }}, ptr {s}, i32 0, i32 1\n" ++
                            "  store {s} %_sm_len_{d}, ptr %_sm_lp_{d}, align {d}\n" ++
                            "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                        .{
                            tmp_id,                        fat_slot, emitter.cfg.target.ptrBytes(),
                            tmp_id,                        ptr_int,  fat_slot,
                            ptr_int,                       tmp_id,   tmp_id,
                            emitter.cfg.target.ptrBytes(), dst_raw,  fat_slot,
                            fat_slot,
                        },
                    );
                } else {
                    try state.print(
                        "  %_sm_agg_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %_sm_ptr_{d}, 0\n" ++
                            "  %_v_{d} = insertvalue {{ ptr, {s} }} %_sm_agg_{d}, {s} %_sm_len_{d}, 1\n",
                        .{ tmp_id, ptr_int, tmp_id, dst_raw, ptr_int, tmp_id, ptr_int, tmp_id },
                    );
                }
            }
        },

        .ctx_get => {
            if (args.len < 1 or (try isZeroSizedType(emitter, inst.type_id))) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const dst_ty = try unwrapTransparentType(emitter, inst.type_id);
            if (type_system.ContextFieldLayout.resolveRefPointee(
                emitter.input.pool,
                emitter.input.sym_table,
                dst_ty,
            )) |ctx_pointee| {
                const ctx_lay = try emitter.resolver.resolveType(ctx_pointee);
                const snap_ptr = try state.allocEntryBytes(@max(ctx_lay.size_bytes, 1), ctx_lay.alignBytes());
                defer emitter.allocator.free(snap_ptr);
                try emitMemsetZero(emitter, state, snap_ptr, ctx_lay.size_bytes, ctx_lay.alignBytes());
                const ctx_stride: u64 = emitter.cfg.target.ptrBytes();
                var decl_ord: u32 = 0;
                while (decl_ord < ctx_lay.aux_len and decl_ord < 10) : (decl_ord += 1) {
                    const fld = emitter.resolver.fields_by_decl.items[ctx_lay.aux_start + decl_ord];
                    if (fld.size_bytes == 0) continue;
                    const dst_fld_ptr = if (fld.byte_offset == 0)
                        try emitter.allocator.dupe(u8, snap_ptr)
                    else blk_fld_gep: {
                        const gep_tmp = state.nextTmp();
                        try state.print(
                            "  %_cgs_dst_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                            .{ gep_tmp, snap_ptr, ptr_int, fld.byte_offset },
                        );
                        break :blk_fld_gep try std.fmt.allocPrint(emitter.allocator, "%_cgs_dst_{d}", .{gep_tmp});
                    };
                    defer emitter.allocator.free(dst_fld_ptr);
                    const dst_fld_align = effectiveOffsetAlign(fld.byte_offset, ctx_lay.alignBytes());
                    if (fld.size_bytes <= ctx_stride) {
                        const src_slot_ptr = if (decl_ord == 0)
                            try emitter.allocator.dupe(u8, "@_cx_default_ctx")
                        else blk_src_gep: {
                            const src_tmp = state.nextTmp();
                            try state.print(
                                "  %_cgs_src_{d} = getelementptr inbounds i8, ptr @_cx_default_ctx, {s} {d}\n",
                                .{ src_tmp, ptr_int, @as(u64, decl_ord) * ctx_stride },
                            );
                            break :blk_src_gep try std.fmt.allocPrint(emitter.allocator, "%_cgs_src_{d}", .{src_tmp});
                        };
                        defer emitter.allocator.free(src_slot_ptr);
                        try emitMemcpyBytes(
                            emitter,
                            state,
                            dst_fld_ptr,
                            dst_fld_align,
                            src_slot_ptr,
                            emitter.cfg.target.ptrBytes(),
                            fld.size_bytes,
                        );
                    } else if (emitter.ctx_wide_slot_sizes[decl_ord] >= fld.size_bytes) {
                        const wide_src_ptr = try std.fmt.allocPrint(emitter.allocator, "@_cx_ctx_wide_{d}", .{decl_ord});
                        defer emitter.allocator.free(wide_src_ptr);
                        try emitMemcpyBytes(
                            emitter,
                            state,
                            dst_fld_ptr,
                            dst_fld_align,
                            wide_src_ptr,
                            emitter.ctx_wide_slot_aligns[decl_ord],
                            fld.size_bytes,
                        );
                    }
                }
                try state.print(
                    "  %_v_{d} = select i1 true, ptr {s}, ptr {s}\n",
                    .{ dst_raw, snap_ptr, snap_ptr },
                );
                return;
            }
            const dst_lay = try emitter.resolver.resolveType(dst_ty);
            const ctx_stride: u64 = emitter.cfg.target.ptrBytes();
            var slot_align: u32 = emitter.cfg.target.ptrBytes();
            const slot_ptr_ssa: []u8 = if (dst_lay.size_bytes > ctx_stride) blk_wide: {
                var ord_u: usize = 0;
                const ord_inst = body.getInst(MirValueId.fromInt(args[0]));
                if (ord_inst.op == .const_scalar and ord_inst.operands.lhs < body.consts.items.len) {
                    switch (body.consts.items[ord_inst.operands.lhs]) {
                        .int_val => |iv| ord_u = @intCast(@as(u128, @bitCast(iv)) % 10),
                        else => {},
                    }
                }
                slot_align = emitter.ctx_wide_slot_aligns[ord_u];
                break :blk_wide try std.fmt.allocPrint(emitter.allocator, "@_cx_ctx_wide_{d}", .{ord_u});
            } else blk_inline: {
                const ord_ssa = try coerceIndexToPtrInt(emitter, state, body, args[0]);
                defer emitter.allocator.free(ord_ssa);
                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_cg_msk_{d} = urem {s} {s}, 10\n" ++
                        "  %_cg_off_{d} = mul {s} %_cg_msk_{d}, {d}\n" ++
                        "  %_cg_ptr_{d} = getelementptr inbounds i8, ptr @_cx_default_ctx, {s} %_cg_off_{d}\n",
                    .{ tmp_id, ptr_int, ord_ssa, tmp_id, ptr_int, tmp_id, ctx_stride, tmp_id, ptr_int, tmp_id },
                );
                break :blk_inline try std.fmt.allocPrint(emitter.allocator, "%_cg_ptr_{d}", .{tmp_id});
            };
            defer emitter.allocator.free(slot_ptr_ssa);

            const loaded = try emitLoadValueFromPtr(
                emitter,
                state,
                dst_ty,
                slot_ptr_ssa,
                @min(slot_align, dst_lay.alignBytes()),
                null,
                0,
                0,
                0,
            );
            defer emitter.allocator.free(loaded);
            const dst_val_ty = try formatLlvmValueType(emitter, dst_ty);
            defer emitter.allocator.free(dst_val_ty);
            try state.print(
                "  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n",
                .{ dst_raw, dst_val_ty, loaded, dst_val_ty, loaded },
            );
        },

        .ctx_set => {
            if (args.len >= 2) {
                const val_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(args[1])).type_id);
                if (!(try isZeroSizedType(emitter, val_ty))) {
                    const val_lay = try emitter.resolver.resolveType(val_ty);
                    const ctx_stride: u64 = emitter.cfg.target.ptrBytes();
                    var slot_align: u32 = emitter.cfg.target.ptrBytes();
                    const slot_ptr_ssa: []u8 = if (val_lay.size_bytes > ctx_stride) blk_wide: {
                        var ord_u: usize = 0;
                        const ord_inst = body.getInst(MirValueId.fromInt(args[0]));
                        if (ord_inst.op == .const_scalar and ord_inst.operands.lhs < body.consts.items.len) {
                            switch (body.consts.items[ord_inst.operands.lhs]) {
                                .int_val => |iv| ord_u = @intCast(@as(u128, @bitCast(iv)) % 10),
                                else => {},
                            }
                        }
                        slot_align = emitter.ctx_wide_slot_aligns[ord_u];
                        break :blk_wide try std.fmt.allocPrint(emitter.allocator, "@_cx_ctx_wide_{d}", .{ord_u});
                    } else blk_inline: {
                        const ord_ssa = try coerceIndexToPtrInt(emitter, state, body, args[0]);
                        defer emitter.allocator.free(ord_ssa);
                        const tmp_id = state.nextTmp();
                        try state.print(
                            "  %_cs_msk_{d} = urem {s} {s}, 10\n" ++
                                "  %_cs_off_{d} = mul {s} %_cs_msk_{d}, {d}\n" ++
                                "  %_cs_ptr_{d} = getelementptr inbounds i8, ptr @_cx_default_ctx, {s} %_cs_off_{d}\n",
                            .{ tmp_id, ptr_int, ord_ssa, tmp_id, ptr_int, tmp_id, ctx_stride, tmp_id, ptr_int, tmp_id },
                        );
                        break :blk_inline try std.fmt.allocPrint(emitter.allocator, "%_cs_ptr_{d}", .{tmp_id});
                    };
                    defer emitter.allocator.free(slot_ptr_ssa);

                    const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[1]});
                    defer emitter.allocator.free(src_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        val_ty,
                        src_ssa,
                        slot_ptr_ssa,
                        @min(slot_align, val_lay.alignBytes()),
                        0,
                        0,
                        0,
                    );
                }
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .ghost_ctx_region_push, .ghost_ctx_region_pop => {
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .fmt_value => {
            if (args.len >= 3) {
                const val_ty = try unwrapTransparentType(
                    emitter,
                    body.getInst(MirValueId.fromInt(args[0])).type_id,
                );
                const val_ptr: []u8 = if (try isZeroSizedType(emitter, val_ty))
                    try std.fmt.allocPrint(emitter.allocator, "inttoptr ({s} 1 to ptr)", .{ptr_int})
                else blk: {
                    const val_lay = try emitter.resolver.resolveType(val_ty);
                    const slot = try state.allocEntryBytes(val_lay.size_bytes, val_lay.alignBytes());
                    const src_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
                    defer emitter.allocator.free(src_ssa);
                    try emitStoreValueToPtr(
                        emitter,
                        state,
                        val_ty,
                        src_ssa,
                        slot,
                        val_lay.alignBytes(),
                        0,
                        0,
                        0,
                    );
                    break :blk slot;
                };
                defer emitter.allocator.free(val_ptr);
                const buf_slot = try state.allocEntryBytes(24, 8);
                defer emitter.allocator.free(buf_slot);
                try state.print(
                    "  store {{ ptr, i64, i64 }} zeroinitializer, ptr {s}, align 8\n" ++
                        "  call void @_cx_fmt_ty_{d}(ptr {s}, ptr {s}, i32 %_v_{d}, i32 %_v_{d})\n" ++
                        "  %_v_{d} = call {{ ptr, {s} }} @_cx_rt_buf_finish(ptr {s})\n",
                    .{ buf_slot, val_ty.toU32(), buf_slot, val_ptr, args[1], args[2], dst_raw, ptr_int, buf_slot },
                );
            } else {
                try state.print(
                    "  %_v_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr @_cx_empty_cstr, 0\n",
                    .{ dst_raw, ptr_int },
                );
            }
        },

        .async_future_make => {
            if (!emitter.has_async_ops or args.len < 3) {
                const val_ty = try formatLlvmValueType(emitter, inst.type_id);
                defer emitter.allocator.free(val_ty);
                const zero_s = resolveZeroLiteralForLlvmType(val_ty);
                try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, zero_s, val_ty, zero_s });
            } else {
                try emitAsyncFutureMakeLlvm(emitter, state, body, dst_raw, inst.type_id, args);
            }
        },

        .async_task_group_enter => {
            if (!emitter.has_async_ops) {
                try state.print("  %_v_{d} = select i1 true, ptr null, ptr null\n", .{dst_raw});
            } else {
                try state.print("  %_v_{d} = call ptr @_cx_async_group_enter()\n", .{dst_raw});
            }
        },

        .async_spawn => {
            if (!emitter.has_async_ops or args.len < 3) {
                try state.print("  %_v_{d} = select i1 true, ptr null, ptr null\n", .{dst_raw});
            } else {
                const fut_ty = try unwrapTransparentType(
                    emitter,
                    body.getInst(MirValueId.fromInt(args[2])).type_id,
                );
                const fut_lay = try emitter.resolver.resolveType(fut_ty);
                const fut_slot = try state.allocEntryBytes(fut_lay.size_bytes, fut_lay.alignBytes());
                defer emitter.allocator.free(fut_slot);
                try emitMemsetZero(emitter, state, fut_slot, fut_lay.size_bytes, fut_lay.alignBytes());
                const fut_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[2]});
                defer emitter.allocator.free(fut_ssa);
                try emitStoreValueToPtr(emitter, state, fut_ty, fut_ssa, fut_slot, fut_lay.alignBytes(), 0, 0, 0);

                const out_ty = emitter.input.pool.unwrapUnderlyingType(
                    emitter.input.pool.getFutureOutputType(fut_ty) orelse .unit_ty,
                );
                const out_lay = try emitter.resolver.resolveType(out_ty);
                const err_fn_s = if (emitter.res_err_check_set.contains(out_ty.toU32()))
                    try std.fmt.allocPrint(emitter.allocator, "@_cx_res_is_err_{d}", .{out_ty.toU32()})
                else
                    try emitter.allocator.dupe(u8, "null");
                defer emitter.allocator.free(err_fn_s);

                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_sp_gp_{d} = load ptr, ptr %_v_{d}, align 1\n" ++
                        "  %_v_{d} = call ptr @_cx_async_spawn(ptr %_sp_gp_{d}, ptr {s}, {s} {d}, ptr {s})\n",
                    .{ tmp_id, args[1], dst_raw, tmp_id, fut_slot, ptr_int, out_lay.size_bytes, err_fn_s },
                );
            }
        },

        .async_join => {
            const fut_ty = try unwrapTransparentType(emitter, inst.type_id);
            const fut_lay = try emitter.resolver.resolveType(fut_ty);
            const fut_slot = try state.allocEntryBytes(fut_lay.size_bytes, fut_lay.alignBytes());
            defer emitter.allocator.free(fut_slot);
            try emitMemsetZero(emitter, state, fut_slot, fut_lay.size_bytes, fut_lay.alignBytes());
            if (emitter.has_async_ops and args.len >= 1) {
                const out_ty = emitter.input.pool.getFutureOutputType(fut_ty) orelse .unit_ty;
                const out_lay = try emitter.resolver.resolveType(out_ty);
                const tmp_id = state.nextTmp();
                try state.print(
                    "  store ptr %_v_{d}, ptr {s}, align 1\n" ++
                        "  %_aj_kp_{d} = getelementptr inbounds %_cx_fut_raw_t, ptr {s}, i32 0, i32 1\n" ++
                        "  %_aj_sp_{d} = getelementptr inbounds %_cx_fut_raw_t, ptr {s}, i32 0, i32 3\n" ++
                        "  store {s} 3, ptr %_aj_kp_{d}, align 1\n" ++
                        "  store {s} {d}, ptr %_aj_sp_{d}, align 1\n",
                    .{ args[0], fut_slot, tmp_id, fut_slot, tmp_id, fut_slot, ptr_int, tmp_id, ptr_int, out_lay.size_bytes, tmp_id },
                );
            }
            const loaded = try emitLoadValueFromPtr(emitter, state, fut_ty, fut_slot, fut_lay.alignBytes(), null, 0, 0, 0);
            defer emitter.allocator.free(loaded);
            const val_ty = try formatLlvmValueType(emitter, fut_ty);
            defer emitter.allocator.free(val_ty);
            try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, loaded, val_ty, loaded });
        },

        .async_cancel => {
            const dst_ty = try unwrapTransparentType(emitter, inst.type_id);
            if (args.len >= 2 or dst_ty == .bool_ty) {
                if (!emitter.has_async_ops or args.len < 1) {
                    try state.print("  %_v_{d} = select i1 true, i1 false, i1 false\n", .{dst_raw});
                } else {
                    const tmp_id = state.nextTmp();
                    const prev_lbl = try emitter.allocator.dupe(u8, state.cur_label);
                    defer emitter.allocator.free(prev_lbl);
                    try state.print(
                        "  %_ac_gp_{d} = load ptr, ptr %_v_{d}, align 1\n" ++
                            "  %_ac_hn_{d} = icmp ne ptr %_ac_gp_{d}, null\n" ++
                            "  br i1 %_ac_hn_{d}, label %_ac_ld_{d}, label %_ac_jn_{d}\n" ++
                            "_ac_ld_{d}:\n" ++
                            "  %_ac_cp_{d} = getelementptr inbounds %_cx_task_group_t, ptr %_ac_gp_{d}, i32 0, i32 3\n" ++
                            "  %_ac_cv_{d} = load i8, ptr %_ac_cp_{d}, align 1\n" ++
                            "  %_ac_b_{d} = icmp ne i8 %_ac_cv_{d}, 0\n" ++
                            "  br label %_ac_jn_{d}\n" ++
                            "_ac_jn_{d}:\n" ++
                            "  %_v_{d} = phi i1 [ %_ac_b_{d}, %_ac_ld_{d} ], [ false, %{s} ]\n",
                        .{
                            tmp_id,  args[0], tmp_id, tmp_id,   tmp_id, tmp_id, tmp_id, tmp_id,
                            tmp_id,  tmp_id,  tmp_id, tmp_id,   tmp_id, tmp_id, tmp_id, tmp_id,
                            dst_raw, tmp_id,  tmp_id, prev_lbl,
                        },
                    );
                    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_ac_jn_{d}", .{tmp_id}));
                }
            } else if (emitter.input.pool.isFutureType(dst_ty)) {
                const fut_lay = try emitter.resolver.resolveType(dst_ty);
                const fut_slot = try state.allocEntryBytes(fut_lay.size_bytes, fut_lay.alignBytes());
                defer emitter.allocator.free(fut_slot);
                try emitMemsetZero(emitter, state, fut_slot, fut_lay.size_bytes, fut_lay.alignBytes());
                if (emitter.has_async_ops and args.len >= 1) {
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  store ptr %_v_{d}, ptr {s}, align 1\n" ++
                            "  %_ac_kp_{d} = getelementptr inbounds %_cx_fut_raw_t, ptr {s}, i32 0, i32 1\n" ++
                            "  store {s} 4, ptr %_ac_kp_{d}, align 1\n",
                        .{ args[0], fut_slot, tmp_id, fut_slot, ptr_int, tmp_id },
                    );
                }
                const loaded = try emitLoadValueFromPtr(emitter, state, dst_ty, fut_slot, fut_lay.alignBytes(), null, 0, 0, 0);
                defer emitter.allocator.free(loaded);
                const val_ty = try formatLlvmValueType(emitter, dst_ty);
                defer emitter.allocator.free(val_ty);
                try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, loaded, val_ty, loaded });
            } else {
                if (emitter.has_async_ops and args.len >= 1) {
                    const tmp_id = state.nextTmp();
                    try state.print(
                        "  %_ac_ca_{d} = load ptr, ptr %_v_{d}, align 1\n" ++
                            "  call void @_cx_async_group_cancel_all(ptr %_ac_ca_{d})\n",
                        .{ tmp_id, args[0], tmp_id },
                    );
                }
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
            }
        },

        .async_task_group_exit => {
            if (emitter.has_async_ops and args.len >= 1) {
                try emitAsyncTaskGroupExitLlvm(emitter, state, body, bb_idx, args[0]);
            }
            try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
        },

        .async_yield => {
            const fut_ty = try unwrapTransparentType(emitter, inst.type_id);
            const fut_lay = try emitter.resolver.resolveType(fut_ty);
            const fut_slot = try state.allocEntryBytes(fut_lay.size_bytes, fut_lay.alignBytes());
            defer emitter.allocator.free(fut_slot);
            try emitMemsetZero(emitter, state, fut_slot, fut_lay.size_bytes, fut_lay.alignBytes());
            if (emitter.has_async_ops) {
                const tmp_id = state.nextTmp();
                try state.print(
                    "  %_ay_kp_{d} = getelementptr inbounds %_cx_fut_raw_t, ptr {s}, i32 0, i32 1\n" ++
                        "  store {s} 2, ptr %_ay_kp_{d}, align 1\n",
                    .{ tmp_id, fut_slot, ptr_int, tmp_id },
                );
            }
            const loaded = try emitLoadValueFromPtr(emitter, state, fut_ty, fut_slot, fut_lay.alignBytes(), null, 0, 0, 0);
            defer emitter.allocator.free(loaded);
            const val_ty = try formatLlvmValueType(emitter, fut_ty);
            defer emitter.allocator.free(val_ty);
            try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, loaded, val_ty, loaded });
        },

        .async_block_on => {
            if (!emitter.has_async_ops or args.len < 1) {
                if (try isZeroSizedType(emitter, inst.type_id)) {
                    try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                } else {
                    const val_ty = try formatLlvmValueType(emitter, inst.type_id);
                    defer emitter.allocator.free(val_ty);
                    const zero_s = resolveZeroLiteralForLlvmType(val_ty);
                    try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, zero_s, val_ty, zero_s });
                }
            } else {
                const fut_ty = try unwrapTransparentType(
                    emitter,
                    body.getInst(MirValueId.fromInt(args[0])).type_id,
                );
                const fut_lay = try emitter.resolver.resolveType(fut_ty);
                const fut_slot = try state.allocEntryBytes(fut_lay.size_bytes, fut_lay.alignBytes());
                defer emitter.allocator.free(fut_slot);
                try emitMemsetZero(emitter, state, fut_slot, fut_lay.size_bytes, fut_lay.alignBytes());
                const fut_ssa = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
                defer emitter.allocator.free(fut_ssa);
                try emitStoreValueToPtr(emitter, state, fut_ty, fut_ssa, fut_slot, fut_lay.alignBytes(), 0, 0, 0);

                if (try isZeroSizedType(emitter, inst.type_id)) {
                    try state.print("  call void @_cx_async_block_on(ptr {s}, ptr null)\n  %_v_{d} = add i8 0, 0\n", .{ fut_slot, dst_raw });
                } else {
                    const dst_ty = try unwrapTransparentType(emitter, inst.type_id);
                    const dst_lay = try emitter.resolver.resolveType(dst_ty);
                    const out_slot = try state.allocEntryBytes(dst_lay.size_bytes, dst_lay.alignBytes());
                    defer emitter.allocator.free(out_slot);
                    try emitMemsetZero(emitter, state, out_slot, dst_lay.size_bytes, dst_lay.alignBytes());
                    try state.print("  call void @_cx_async_block_on(ptr {s}, ptr {s})\n", .{ fut_slot, out_slot });
                    const loaded = try emitLoadValueFromPtr(emitter, state, dst_ty, out_slot, dst_lay.alignBytes(), null, 0, 0, 0);
                    defer emitter.allocator.free(loaded);
                    const val_ty = try formatLlvmValueType(emitter, dst_ty);
                    defer emitter.allocator.free(val_ty);
                    try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, loaded, val_ty, loaded });
                }
            }
        },

        .implements,
        .int_min,
        .int_max,
        .int_bits,
        .scalar_clz,
        .scalar_ctz,
        .scalar_popcnt,
        .scalar_bswap,
        .scalar_rotl,
        .scalar_rotr,
        .ptr_is_null,
        .ptr_offset,
        .slice_split_at,
        .slice_reverse,
        .soa_vec_new,
        .soa_vec_with_cap,
        .soa_vec_len,
        .soa_vec_cap,
        .soa_vec_push,
        .soa_vec_pop,
        .soa_vec_clear,
        .soa_vec_reserve,
        .soa_vec_as_slice,
        .soa_vec_col_slice,
        .ctx_next_rng_seed,
        .tls_scratch_ptr,
        .tls_alloc_state,
        .fmt_write,
        .memcpy,
        .memmove,
        .memset,
        .ptr_copy,
        .ptr_copy_nonoverlapping,
        .ptr_read,
        .ptr_write,
        .ptr_drop_in_place,
        .forget,
        .slice_from_raw_parts,
        .str_from_utf8_unchecked,
        .from_le_bytes,
        .from_be_bytes,
        .to_le_bytes,
        .to_be_bytes,
        .sqrt,
        .sys_mmap,
        .sys_munmap,
        .wasm_memory_grow,
        .simd_load_unaligned,
        .simd_and,
        .simd_or,
        .simd_xor,
        .simd_eq,
        .simd_gt_s8,
        .simd_lt_s8,
        .simd_swizzle,
        .simd_shl_u8,
        .simd_shr_u8,
        .simd_bitmask,
        => try emitStd01IntrinsicOpLlvm(emitter, state, body, dst_raw, ikind, inst, args),
    }
    _ = access_grp;
}

/// Evaluates compile-time `@implements[T, Bound]()` statically for unoptimized MIR fallback in LLVM.
fn evalImplementsStaticLlvm(emitter: *const LlvmModuleEmitter, raw_ty: TypeId, raw_bound: TypeId) bool {
    return type_system.evalStaticImplements(
        emitter.input.pool,
        emitter.input.sym_table,
        emitter.target_layout,
        raw_ty,
        raw_bound,
    );
}

/// Extracts `<ptr_int>` allocator handle bits from SSA `arg_raw` (`0` for ZST `System`).
fn emitExtractAllocRawLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    arg_raw: u32,
) ![]u8 {
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const arg_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(arg_raw)).type_id);
    if (try isZeroSizedType(emitter, arg_ty)) {
        return emitter.allocator.dupe(u8, "0");
    }
    if (!arg_ty.isPrimitiveOrSentinel()) {
        const node = emitter.input.pool.getNode(arg_ty);
        if (node.tag == .ref_ty or node.tag == .mut_ref_ty or node.tag == .raw_ptr_ty) {
            const pointee_ty = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(node.lhs));
            const t_id = state.nextTmp();
            if (pointee_ty == .u8_ty) {
                try state.print("  %_arp_{d} = ptrtoint ptr %_v_{d} to {s}\n", .{ t_id, arg_raw, ptr_int });
                return std.fmt.allocPrint(emitter.allocator, "%_arp_{d}", .{t_id});
            }
            try state.print(
                "  %_arp_{d} = ptrtoint ptr %_v_{d} to {s}\n" ++
                    "  %_aro_{d} = or {s} %_arp_{d}, 1\n",
                .{ t_id, arg_raw, ptr_int, t_id, ptr_int, t_id },
            );
            return std.fmt.allocPrint(emitter.allocator, "%_aro_{d}", .{t_id});
        }
    }
    const lay = try emitter.resolver.resolveType(arg_ty);
    const slot_sz = @max(lay.size_bytes, ptr_bytes);
    const slot_al = @max(lay.alignBytes(), ptr_bytes);
    const slot = try state.allocEntryBytes(slot_sz, slot_al);
    defer emitter.allocator.free(slot);
    try emitMemsetZero(emitter, state, slot, slot_sz, slot_al);
    const val_s = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{arg_raw});
    defer emitter.allocator.free(val_s);
    try emitStoreValueToPtr(emitter, state, arg_ty, val_s, slot, slot_al, 0, 0, 0);
    const t_id = state.nextTmp();
    try state.print("  %_arl_{d} = load {s}, ptr {s}, align {d}\n", .{ t_id, ptr_int, slot, ptr_bytes });
    return std.fmt.allocPrint(emitter.allocator, "%_arl_{d}", .{t_id});
}

/// Emits LLVM IR ensuring `#soa Vec[S]` at `vec_ptr_ssa` has capacity `>= min_cap_u64_ssa`, returning `i1` success SSA.
fn emitSoaVecEnsureCapLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    vec_ptr_ssa: []const u8,
    elem_struct: TypeId,
    min_cap_u64_ssa: []const u8,
    is_try: bool,
) ![]u8 {
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const lay = try emitter.resolver.resolveType(elem_struct);
    const slab_align: u32 = @max(
        @as(u32, 1) << @intCast(@max(lay.align_log2, emitter.target_layout.simd_align_log2)),
        16,
    );
    const ok_slot = try state.allocEntryBytes(1, 1);
    defer emitter.allocator.free(ok_slot);
    const tmp_id = state.nextTmp();
    try state.print(
        "  store i8 1, ptr {s}, align 1\n" ++
            "  %_seg_cp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
            "  %_seg_c32_{d} = load i32, ptr %_seg_cp_{d}, align 1\n" ++
            "  %_seg_c64_{d} = zext i32 %_seg_c32_{d} to i64\n" ++
            "  %_seg_nd_{d} = icmp ugt i64 {s}, %_seg_c64_{d}\n" ++
            "  br i1 %_seg_nd_{d}, label %_seg_chk_{d}, label %_seg_dn_{d}\n" ++
            "_seg_chk_{d}:\n" ++
            "  %_seg_ov_{d} = icmp ugt i64 {s}, 4294967295\n" ++
            "  br i1 %_seg_ov_{d}, label %_seg_bad_{d}, label %_seg_gr_{d}\n" ++
            "_seg_bad_{d}:\n",
        .{
            ok_slot,         tmp_id, vec_ptr_ssa,     ptr_int, ptr_bytes + 4,
            tmp_id,          tmp_id, tmp_id,          tmp_id,  tmp_id,
            min_cap_u64_ssa, tmp_id, tmp_id,          tmp_id,  tmp_id,
            tmp_id,          tmp_id, min_cap_u64_ssa, tmp_id,  tmp_id,
            tmp_id,          tmp_id,
        },
    );
    if (is_try) {
        try state.print("  store i8 0, ptr {s}, align 1\n  br label %_seg_dn_{d}\n", .{ ok_slot, tmp_id });
    } else {
        try state.writeAll("  call void @_cx_rt_trap(i32 0)\n  unreachable\n");
    }
    try state.print(
        "_seg_gr_{d}:\n" ++
            "  %_seg_d1_{d} = mul i64 %_seg_c64_{d}, 2\n" ++
            "  %_seg_lt8_{d} = icmp ult i64 %_seg_d1_{d}, 8\n" ++
            "  %_seg_d2_{d} = select i1 %_seg_lt8_{d}, i64 8, i64 %_seg_d1_{d}\n" ++
            "  %_seg_ltm_{d} = icmp ult i64 %_seg_d2_{d}, {s}\n" ++
            "  %_seg_d3_{d} = select i1 %_seg_ltm_{d}, i64 {s}, i64 %_seg_d2_{d}\n" ++
            "  %_seg_gtu_{d} = icmp ugt i64 %_seg_d3_{d}, 4294967295\n" ++
            "  %_seg_nc64_{d} = select i1 %_seg_gtu_{d}, i64 {s}, i64 %_seg_d3_{d}\n" ++
            "  %_seg_nc32_{d} = trunc i64 %_seg_nc64_{d} to i32\n",
        .{
            tmp_id,          tmp_id, tmp_id, tmp_id,          tmp_id,
            tmp_id,          tmp_id, tmp_id, tmp_id,          tmp_id,
            min_cap_u64_ssa, tmp_id, tmp_id, min_cap_u64_ssa, tmp_id,
            tmp_id,          tmp_id, tmp_id, tmp_id,          min_cap_u64_ssa,
            tmp_id,          tmp_id, tmp_id,
        },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_seg_gr_{d}", .{tmp_id}));
    const nc_pt = if (ptr_bytes == 4)
        try std.fmt.allocPrint(emitter.allocator, "%_seg_nc32_{d}", .{tmp_id})
    else
        try std.fmt.allocPrint(emitter.allocator, "%_seg_nc64_{d}", .{tmp_id});
    defer emitter.allocator.free(nc_pt);

    var tot_ssa: []u8 = try emitter.allocator.dupe(u8, "0");
    defer emitter.allocator.free(tot_ssa);
    if (lay.aux_len > 0) {
        const last_ord = lay.aux_len - 1;
        const last_col = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, last_ord, nc_pt);
        defer emitter.allocator.free(last_col.off_ssa);
        const last_fld = emitter.resolver.fields_by_decl.items[lay.aux_start + last_ord];
        try state.print(
            "  %_seg_lm_{d} = mul {s} {s}, {d}\n" ++
                "  %_seg_tot_{d} = add {s} {s}, %_seg_lm_{d}\n",
            .{ tmp_id, ptr_int, nc_pt, last_fld.size_bytes, tmp_id, ptr_int, last_col.off_ssa, tmp_id },
        );
        emitter.allocator.free(tot_ssa);
        tot_ssa = try std.fmt.allocPrint(emitter.allocator, "%_seg_tot_{d}", .{tmp_id});
    }

    try state.print(
        "  %_seg_ap0_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
            "  %_seg_av0_{d} = load {s}, ptr %_seg_ap0_{d}, align 1\n" ++
            "  %_seg_np_{d} = call ptr @_cx_soa_zalloc({s} %_seg_av0_{d}, {s} {s}, {s} {d}, i1 {s})\n" ++
            "  %_seg_nn_{d} = icmp eq ptr %_seg_np_{d}, null\n" ++
            "  br i1 %_seg_nn_{d}, label %_seg_oom_{d}, label %_seg_cpb_{d}\n" ++
            "_seg_oom_{d}:\n" ++
            "  store i8 0, ptr {s}, align 1\n" ++
            "  br label %_seg_dn_{d}\n" ++
            "_seg_cpb_{d}:\n",
        .{
            tmp_id,  vec_ptr_ssa, ptr_int,                         ptr_bytes + 8,
            tmp_id,  ptr_int,     tmp_id,                          tmp_id,
            ptr_int, tmp_id,      ptr_int,                         tot_ssa,
            ptr_int, slab_align,  if (is_try) "true" else "false", tmp_id,
            tmp_id,  tmp_id,      tmp_id,                          tmp_id,
            tmp_id,  ok_slot,     tmp_id,                          tmp_id,
        },
    );
    try state.print(
        "  %_seg_op_{d} = load ptr, ptr {s}, align 1\n" ++
            "  %_seg_lp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
            "  %_seg_l32_{d} = load i32, ptr %_seg_lp_{d}, align 1\n" ++
            "  %_seg_ho_{d} = icmp ne ptr %_seg_op_{d}, null\n" ++
            "  %_seg_hl_{d} = icmp ugt i32 %_seg_l32_{d}, 0\n" ++
            "  %_seg_dc_{d} = and i1 %_seg_ho_{d}, %_seg_hl_{d}\n" ++
            "  br i1 %_seg_dc_{d}, label %_seg_mc_{d}, label %_seg_up_{d}\n" ++
            "_seg_mc_{d}:\n",
        .{
            tmp_id,  vec_ptr_ssa,
            tmp_id,  vec_ptr_ssa,
            ptr_int, ptr_bytes,
            tmp_id,  tmp_id,
            tmp_id,  tmp_id,
            tmp_id,  tmp_id,
            tmp_id,  tmp_id,
            tmp_id,  tmp_id,
            tmp_id,  tmp_id,
            tmp_id,
        },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_seg_mc_{d}", .{tmp_id}));
    const oc_pt = if (ptr_bytes == 4)
        try std.fmt.allocPrint(emitter.allocator, "%_seg_c32_{d}", .{tmp_id})
    else
        try std.fmt.allocPrint(emitter.allocator, "%_seg_c64_{d}", .{tmp_id});
    defer emitter.allocator.free(oc_pt);
    try state.print("  %_seg_l64_{d} = zext i32 %_seg_l32_{d} to i64\n", .{ tmp_id, tmp_id });
    try emitter.requireIntrinsicDecl(
        "declare void @llvm.memcpy.p0.p0.i64(ptr noalias nocapture writeonly, " ++
            "ptr noalias nocapture readonly, i64, i1 immarg)",
    );
    var col_i: u32 = 0;
    while (col_i < lay.aux_len) : (col_i += 1) {
        const fld = emitter.resolver.fields_by_decl.items[lay.aux_start + col_i];
        if (fld.size_bytes == 0) continue;
        const old_c = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, col_i, oc_pt);
        defer emitter.allocator.free(old_c.off_ssa);
        const new_c = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, col_i, nc_pt);
        defer emitter.allocator.free(new_c.off_ssa);
        const sub_t = state.nextTmp();
        try state.print(
            "  %_seg_sp_{d} = getelementptr inbounds i8, ptr %_seg_op_{d}, {s} {s}\n" ++
                "  %_seg_dp_{d} = getelementptr inbounds i8, ptr %_seg_np_{d}, {s} {s}\n" ++
                "  %_seg_cb_{d} = mul i64 %_seg_l64_{d}, {d}\n" ++
                "  call void @llvm.memcpy.p0.p0.i64(ptr align 1 %_seg_dp_{d}, ptr align 1 %_seg_sp_{d}, i64 %_seg_cb_{d}, i1 false)\n",
            .{
                sub_t, tmp_id, ptr_int,        old_c.off_ssa,
                sub_t, tmp_id, ptr_int,        new_c.off_ssa,
                sub_t, tmp_id, fld.size_bytes, sub_t,
                sub_t, sub_t,
            },
        );
    }
    try state.print(
        "  br label %_seg_up_{d}\n" ++
            "_seg_up_{d}:\n" ++
            "  %_seg_hc_{d} = icmp ugt i32 %_seg_c32_{d}, 0\n" ++
            "  %_seg_df_{d} = and i1 %_seg_ho_{d}, %_seg_hc_{d}\n" ++
            "  br i1 %_seg_df_{d}, label %_seg_fo_{d}, label %_seg_st_{d}\n" ++
            "_seg_fo_{d}:\n",
        .{
            tmp_id, tmp_id,
            tmp_id, tmp_id,
            tmp_id, tmp_id,
            tmp_id, tmp_id,
            tmp_id, tmp_id,
            tmp_id,
        },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_seg_fo_{d}", .{tmp_id}));
    var old_tot_ssa: []u8 = try emitter.allocator.dupe(u8, "0");
    defer emitter.allocator.free(old_tot_ssa);
    if (lay.aux_len > 0) {
        const last_ord = lay.aux_len - 1;
        const old_last = try emitDynamicSoaColByteOffset(emitter, state, elem_struct, last_ord, oc_pt);
        defer emitter.allocator.free(old_last.off_ssa);
        const last_fld = emitter.resolver.fields_by_decl.items[lay.aux_start + last_ord];
        try state.print(
            "  %_seg_olm_{d} = mul {s} {s}, {d}\n" ++
                "  %_seg_ot_{d} = add {s} {s}, %_seg_olm_{d}\n",
            .{ tmp_id, ptr_int, oc_pt, last_fld.size_bytes, tmp_id, ptr_int, old_last.off_ssa, tmp_id },
        );
        emitter.allocator.free(old_tot_ssa);
        old_tot_ssa = try std.fmt.allocPrint(emitter.allocator, "%_seg_ot_{d}", .{tmp_id});
    }
    try state.print(
        "  call void @_cx_soa_free({s} %_seg_av0_{d}, ptr %_seg_op_{d}, {s} {s}, {s} {d})\n" ++
            "  br label %_seg_st_{d}\n" ++
            "_seg_st_{d}:\n" ++
            "  store ptr %_seg_np_{d}, ptr {s}, align 1\n" ++
            "  store i32 %_seg_nc32_{d}, ptr %_seg_cp_{d}, align 1\n" ++
            "  br label %_seg_dn_{d}\n" ++
            "_seg_dn_{d}:\n" ++
            "  %_seg_ok8_{d} = load i8, ptr {s}, align 1\n" ++
            "  %_seg_ok1_{d} = icmp ne i8 %_seg_ok8_{d}, 0\n",
        .{
            ptr_int, tmp_id, tmp_id,  ptr_int,     old_tot_ssa, ptr_int, slab_align,
            tmp_id,  tmp_id, tmp_id,  vec_ptr_ssa, tmp_id,      tmp_id,  tmp_id,
            tmp_id,  tmp_id, ok_slot, tmp_id,      tmp_id,
        },
    );
    state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_seg_dn_{d}", .{tmp_id}));
    return std.fmt.allocPrint(emitter.allocator, "%_seg_ok1_{d}", .{tmp_id});
}

/// Finds a 3-parameter `Display.fmt` (`is_debug == false`) or `Debug.fmt_debug` (`is_debug == true`) body in LLVM.
fn lookupCustomFmtBodyIndexLlvm(emitter: *const LlvmModuleEmitter, ty: TypeId, is_debug: bool) ?u32 {
    const target_method = if (is_debug) "fmt_debug" else "fmt";
    const ty_node = emitter.input.pool.getNode(ty);
    if (ty_node.tag == .struct_ty or ty_node.tag == .enum_ty or ty_node.tag == .union_ty or ty_node.tag == .distinct_ty) {
        const sym_idx = SymbolIndex.fromInt(ty_node.rhs);
        if (!sym_idx.isNone() and sym_idx.asInt() < emitter.input.sym_table.symbols.items.len) {
            const nom_sym = emitter.input.sym_table.getSymbol(sym_idx).*;
            if (!nom_sym.target_scope.isNone()) {
                for (emitter.input.sym_table.getScopeMembers(nom_sym.target_scope)) |mem_idx| {
                    const mem_sym = emitter.input.sym_table.getSymbol(mem_idx).*;
                    if (mem_sym.kind == .fn_sym and std.mem.eql(u8, mem_sym.name_text, target_method)) {
                        if (resolveBodyIndex(emitter, mem_sym.def_id, mem_idx)) |found_b| {
                            if (emitter.input.bodies[found_b].param_count == 3) return found_b;
                        }
                    }
                }
            }
        }
    }
    const dot_suffix = if (is_debug) ".fmt_debug" else ".fmt";
    for (emitter.input.bodies, 0..) |*cand_b, b_idx| {
        if (cand_b.param_count != 3 or cand_b.locals.items.len < 4) continue;
        const fn_name = emitter.input.interner.get(cand_b.name);
        if (!std.mem.eql(u8, fn_name, target_method) and !std.mem.endsWith(u8, fn_name, dot_suffix)) continue;
        const p1_ty = emitter.input.pool.unwrapUnderlyingType(cand_b.locals.items[1].type_id);
        const p1_node = emitter.input.pool.getNode(p1_ty);
        const recv_ty = if (p1_node.tag == .ref_ty or p1_node.tag == .mut_ref_ty or p1_node.tag == .raw_ptr_ty)
            emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(p1_node.lhs))
        else
            p1_ty;
        if (recv_ty == ty) return @intCast(b_idx);
    }
    return null;
}

/// Invokes `FmtWriter.write_fn(ctx, &chunk_slice)` with exact CoreX ABI (`swiftcc` + `swifterror` / `wasm_mvp`).
fn emitInvokeWriteFnChunkLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    ctx_ptr_ssa: []const u8,
    write_fn_ssa: []const u8,
    write_fn_ty: TypeId,
    chunk_ptr_ssa: []const u8,
    chunk_len_ssa: []const u8,
    res_slot: []const u8,
    res_ty: TypeId,
    res_align: u32,
    err_label: []const u8,
) !void {
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const sig = emitter.input.pool.getFnSignatureView(write_fn_ty) orelse return;
    var w_rec = try classifyFnTypeAbi(emitter, write_fn_ty, false, false);
    defer w_rec.deinit(emitter.allocator);

    const chunk_slot = try state.allocEntryBytes(2 * ptr_bytes, @max(ptr_bytes, 8));
    defer emitter.allocator.free(chunk_slot);
    const t_id = state.nextTmp();
    try state.print(
        "  store ptr {s}, ptr {s}, align {d}\n" ++
            "  %_fw_clp_{d} = getelementptr inbounds {{ ptr, {s} }}, ptr {s}, i32 0, i32 1\n" ++
            "  store {s} {s}, ptr %_fw_clp_{d}, align {d}\n",
        .{ chunk_ptr_ssa, chunk_slot, ptr_bytes, t_id, ptr_int, chunk_slot, ptr_int, chunk_len_ssa, t_id, ptr_bytes },
    );

    var call_args: std.ArrayListUnmanaged(u8) = .empty;
    defer call_args.deinit(emitter.allocator);
    var arg_cnt: usize = 0;

    var sret_slot: ?[]u8 = null;
    defer if (sret_slot) |slot_buf| emitter.allocator.free(slot_buf);
    if (w_rec.has_sret) {
        const r_lay = try emitter.resolver.resolveType(res_ty);
        sret_slot = try state.allocEntryBytes(r_lay.size_bytes, @max(r_lay.alignBytes(), w_rec.sret_recipe.pointee_align_bytes));
        const sret_p = try formatAbiParamDeclPiece(emitter, res_ty, w_rec.sret_recipe, sret_slot.?);
        defer emitter.allocator.free(sret_p);
        try call_args.appendSlice(emitter.allocator, sret_p);
        arg_cnt += 1;
    }
    if (w_rec.has_implicit_context) {
        const ctx_op = if (state.has_ctx_param) "%_cx_ctx" else "@_cx_default_ctx";
        const ctx_p = try formatAbiParamDeclPiece(emitter, .usize_ty, w_rec.context_recipe, ctx_op);
        defer emitter.allocator.free(ctx_p);
        if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, ctx_p);
        arg_cnt += 1;
    }
    if (w_rec.param_recipes.len >= 2) {
        const p0 = try formatAbiParamDeclPiece(emitter, sig.getParamType(0), w_rec.param_recipes[0], ctx_ptr_ssa);
        defer emitter.allocator.free(p0);
        if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, p0);
        arg_cnt += 1;

        const p1_ty = sig.getParamType(1);
        const p1_rec = w_rec.param_recipes[1];
        const p1_op = if (p1_rec.pass_mode == .indirect_by_ref or p1_rec.pass_mode == .indirect_byval)
            try emitter.allocator.dupe(u8, chunk_slot)
        else blk_p1: {
            const p1_abi_ty = try formatAbiParamOrRetType(emitter, p1_ty, p1_rec);
            defer emitter.allocator.free(p1_abi_ty);
            try state.print(
                "  %_fw_p1_{d} = load {s}, ptr {s}, align {d}\n",
                .{ t_id, p1_abi_ty, chunk_slot, @max(ptr_bytes, 8) },
            );
            break :blk_p1 try std.fmt.allocPrint(emitter.allocator, "%_fw_p1_{d}", .{t_id});
        };
        defer emitter.allocator.free(p1_op);
        const p1 = try formatAbiParamDeclPiece(emitter, p1_ty, p1_rec, p1_op);
        defer emitter.allocator.free(p1);
        if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, p1);
        arg_cnt += 1;
    }
    if (w_rec.swifterror_kind != .none) {
        try state.ensureSwifterrorCallSlot();
        if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, "ptr swifterror %_cx_call_err");
        try state.writeAll("  store ptr null, ptr %_cx_call_err, align 8\n");
    }

    const ret_decl = try formatAbiReturnDecl(emitter, sig.ret_ty, &w_rec);
    defer emitter.allocator.free(ret_decl.full_decl);
    defer emitter.allocator.free(ret_decl.bare_ty);
    const is_void = std.mem.eql(u8, ret_decl.bare_ty, "void");

    if (is_void) {
        try state.print(
            "  call {s}void {s}({s})\n",
            .{ resolveCallingConvPrefix(&w_rec), write_fn_ssa, call_args.items },
        );
    } else {
        try state.print(
            "  %_fw_rv_{d} = call {s}{s} {s}({s})\n",
            .{ t_id, resolveCallingConvPrefix(&w_rec), ret_decl.full_decl, write_fn_ssa, call_args.items },
        );
    }

    if (w_rec.swifterror_kind != .none) {
        const sum_detail = (try emitter.resolver.getSumDetail(res_ty)).?;
        try state.print(
            "  %_fw_ce_{d} = load ptr, ptr %_cx_call_err, align 8\n" ++
                "  %_fw_he_{d} = icmp ne ptr %_fw_ce_{d}, null\n" ++
                "  br i1 %_fw_he_{d}, label %_fw_se_{d}, label %_fw_ok_{d}\n" ++
                "_fw_se_{d}:\n",
            .{ t_id, t_id, t_id, t_id, t_id, t_id, t_id },
        );
        const pay_ptr = if (sum_detail.payload_offset == 0)
            try emitter.allocator.dupe(u8, res_slot)
        else blk_p: {
            try state.print(
                "  %_fw_pp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                .{ t_id, res_slot, ptr_int, sum_detail.payload_offset },
            );
            break :blk_p try std.fmt.allocPrint(emitter.allocator, "%_fw_pp_{d}", .{t_id});
        };
        defer emitter.allocator.free(pay_ptr);
        const ce_s = try std.fmt.allocPrint(emitter.allocator, "%_fw_ce_{d}", .{t_id});
        defer emitter.allocator.free(ce_s);
        try emitDecodeSwifterrorToPayloadPtr(emitter, state, &w_rec, ce_s, pay_ptr);
        try emitWriteSumDiscriminantToPtr(emitter, state, res_ty, res_slot, res_align, 1);
        try state.print("  br label %{s}\n_fw_ok_{d}:\n", .{ err_label, t_id });
        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fw_ok_{d}", .{t_id}));
    } else {
        if (w_rec.has_sret) {
            const r_lay = try emitter.resolver.resolveType(res_ty);
            try emitMemcpyBytes(emitter, state, res_slot, res_align, sret_slot.?, res_align, r_lay.size_bytes);
        } else if (!is_void) {
            const rv_s = try std.fmt.allocPrint(emitter.allocator, "%_fw_rv_{d}", .{t_id});
            defer emitter.allocator.free(rv_s);
            const unpacked = try emitCoerceAbiToValue(emitter, state, res_ty, ret_decl.bare_ty, rv_s);
            defer emitter.allocator.free(unpacked);
            try emitStoreValueToPtr(emitter, state, res_ty, unpacked, res_slot, res_align, 0, 0, 0);
        }
        const discr_s = try emitReadSumDiscriminantFromPtr(emitter, state, res_ty, res_slot, res_align);
        defer emitter.allocator.free(discr_s);
        try state.print(
            "  %_fw_ie_{d} = icmp ne i32 {s}, 0\n" ++
                "  br i1 %_fw_ie_{d}, label %{s}, label %_fw_ok_{d}\n" ++
                "_fw_ok_{d}:\n",
            .{ t_id, discr_s, t_id, err_label, t_id, t_id },
        );
        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fw_ok_{d}", .{t_id}));
    }
}

/// Invokes a 3-parameter `Display.fmt` / `Debug.fmt_debug` body `target_b` directly in LLVM.
fn emitInvokeCustomFmtBodyLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    target_b: u32,
    cand_ty: TypeId,
    data_ptr_ssa: []const u8,
    writer_ptr_ssa: []const u8,
    spec_val_ssa: []const u8,
    res_slot: []const u8,
    res_ty: TypeId,
    res_align: u32,
    err_label: []const u8,
    done_hole_label: []const u8,
) !void {
    const ptr_int = ptrIntType(emitter);
    const fn_body = &emitter.input.bodies[target_b];
    const fn_rec = &emitter.body_recipes.items[target_b];
    const t_id = state.nextTmp();

    var call_args: std.ArrayListUnmanaged(u8) = .empty;
    defer call_args.deinit(emitter.allocator);
    var arg_cnt: usize = 0;

    var sret_slot: ?[]u8 = null;
    defer if (sret_slot) |slot_buf| emitter.allocator.free(slot_buf);
    if (fn_rec.has_sret) {
        const r_lay = try emitter.resolver.resolveType(res_ty);
        sret_slot = try state.allocEntryBytes(r_lay.size_bytes, @max(r_lay.alignBytes(), fn_rec.sret_recipe.pointee_align_bytes));
        const sret_p = try formatAbiParamDeclPiece(emitter, res_ty, fn_rec.sret_recipe, sret_slot.?);
        defer emitter.allocator.free(sret_p);
        try call_args.appendSlice(emitter.allocator, sret_p);
        arg_cnt += 1;
    }
    if (fn_rec.has_implicit_context) {
        const ctx_op = if (state.has_ctx_param) "%_cx_ctx" else "@_cx_default_ctx";
        const ctx_p = try formatAbiParamDeclPiece(emitter, .usize_ty, fn_rec.context_recipe, ctx_op);
        defer emitter.allocator.free(ctx_p);
        if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, ctx_p);
        arg_cnt += 1;
    }
    if (fn_rec.param_recipes.len >= 3) {
        // [1] Marshal param 0 (`&Self` or `Self`):
        const p0_decl = fn_body.locals.items[1];
        const p0_rec = fn_rec.param_recipes[0];
        if (p0_rec.pass_mode != .ignore_zst) {
            const p0_unwrapped = emitter.input.pool.unwrapUnderlyingType(p0_decl.type_id);
            const p0_tag = emitter.input.pool.getNode(p0_unwrapped).tag;
            const is_ptr_self = p0_decl.mode() == .inout_mode or
                p0_tag == .ref_ty or p0_tag == .mut_ref_ty or p0_tag == .raw_ptr_ty or
                p0_rec.pass_mode == .indirect_by_ref or p0_rec.pass_mode == .indirect_byval;
            const p0_op = if (is_ptr_self) blk_ptr: {
                if (p0_rec.pointee_align_bytes > 1) {
                    const c_lay = try emitter.resolver.resolveType(cand_ty);
                    if (c_lay.size_bytes > 0) {
                        const b_al = @max(c_lay.alignBytes(), p0_rec.pointee_align_bytes);
                        const b_slot = try state.allocEntryBytes(c_lay.size_bytes, b_al);
                        try emitMemcpyBytes(emitter, state, b_slot, b_al, data_ptr_ssa, 1, c_lay.size_bytes);
                        break :blk_ptr b_slot;
                    }
                }
                break :blk_ptr try emitter.allocator.dupe(u8, data_ptr_ssa);
            } else blk_val: {
                const loaded = try emitLoadValueFromPtr(emitter, state, cand_ty, data_ptr_ssa, 1, null, 0, 0, 0);
                defer emitter.allocator.free(loaded);
                const abi_ty = try formatAbiParamOrRetType(emitter, p0_decl.type_id, p0_rec);
                defer emitter.allocator.free(abi_ty);
                break :blk_val try emitCoerceValueToAbi(emitter, state, cand_ty, loaded, abi_ty);
            };
            defer emitter.allocator.free(p0_op);
            const p0_piece = try formatAbiParamDeclPiece(emitter, p0_decl.type_id, p0_rec, p0_op);
            defer emitter.allocator.free(p0_piece);
            if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
            try call_args.appendSlice(emitter.allocator, p0_piece);
            arg_cnt += 1;
        }
        // [2] Marshal param 1 (`&mut FmtWriter`):
        const p1_decl = fn_body.locals.items[2];
        const p1_rec = fn_rec.param_recipes[1];
        if (p1_rec.pass_mode != .ignore_zst) {
            const p1_piece = try formatAbiParamDeclPiece(emitter, p1_decl.type_id, p1_rec, writer_ptr_ssa);
            defer emitter.allocator.free(p1_piece);
            if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
            try call_args.appendSlice(emitter.allocator, p1_piece);
            arg_cnt += 1;
        }
        // [3] Marshal param 2 (`FmtSpec`):
        const p2_decl = fn_body.locals.items[3];
        const p2_rec = fn_rec.param_recipes[2];
        if (p2_rec.pass_mode != .ignore_zst) {
            const p2_abi_ty = try formatAbiParamOrRetType(emitter, p2_decl.type_id, p2_rec);
            defer emitter.allocator.free(p2_abi_ty);
            const p2_coerced = try emitCoerceValueToAbi(emitter, state, .fmt_spec_ty, spec_val_ssa, p2_abi_ty);
            defer emitter.allocator.free(p2_coerced);
            const p2_piece = try formatAbiParamDeclPiece(emitter, p2_decl.type_id, p2_rec, p2_coerced);
            defer emitter.allocator.free(p2_piece);
            if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
            try call_args.appendSlice(emitter.allocator, p2_piece);
            arg_cnt += 1;
        }
    }
    if (fn_rec.swifterror_kind != .none) {
        try state.ensureSwifterrorCallSlot();
        if (arg_cnt > 0) try call_args.appendSlice(emitter.allocator, ", ");
        try call_args.appendSlice(emitter.allocator, "ptr swifterror %_cx_call_err");
        try state.writeAll("  store ptr null, ptr %_cx_call_err, align 8\n");
    }

    const ret_decl = try formatAbiReturnDecl(emitter, fn_body.ret_ty, fn_rec);
    defer emitter.allocator.free(ret_decl.full_decl);
    defer emitter.allocator.free(ret_decl.bare_ty);
    const is_void = std.mem.eql(u8, ret_decl.bare_ty, "void");
    const fn_ident = try formatLlvmGlobalIdent(emitter.allocator, emitter.body_llvm_names.items[target_b]);
    defer emitter.allocator.free(fn_ident);

    if (is_void) {
        try state.print("  call {s}void {s}({s})\n", .{ resolveCallingConvPrefix(fn_rec), fn_ident, call_args.items });
    } else {
        try state.print(
            "  %_cf_rv_{d} = call {s}{s} {s}({s})\n",
            .{ t_id, resolveCallingConvPrefix(fn_rec), ret_decl.full_decl, fn_ident, call_args.items },
        );
    }

    if (fn_rec.swifterror_kind != .none) {
        const sum_detail = (try emitter.resolver.getSumDetail(res_ty)).?;
        try state.print(
            "  %_cf_ce_{d} = load ptr, ptr %_cx_call_err, align 8\n" ++
                "  %_cf_he_{d} = icmp ne ptr %_cf_ce_{d}, null\n" ++
                "  br i1 %_cf_he_{d}, label %_cf_se_{d}, label %{s}\n" ++
                "_cf_se_{d}:\n",
            .{ t_id, t_id, t_id, t_id, t_id, done_hole_label, t_id },
        );
        const pay_ptr = if (sum_detail.payload_offset == 0)
            try emitter.allocator.dupe(u8, res_slot)
        else blk_p: {
            try state.print(
                "  %_cf_pp_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n",
                .{ t_id, res_slot, ptr_int, sum_detail.payload_offset },
            );
            break :blk_p try std.fmt.allocPrint(emitter.allocator, "%_cf_pp_{d}", .{t_id});
        };
        defer emitter.allocator.free(pay_ptr);
        const ce_s = try std.fmt.allocPrint(emitter.allocator, "%_cf_ce_{d}", .{t_id});
        defer emitter.allocator.free(ce_s);
        try emitDecodeSwifterrorToPayloadPtr(emitter, state, fn_rec, ce_s, pay_ptr);
        try emitWriteSumDiscriminantToPtr(emitter, state, res_ty, res_slot, res_align, 1);
        try state.print("  br label %{s}\n", .{err_label});
    } else {
        if (fn_rec.has_sret) {
            const r_lay = try emitter.resolver.resolveType(res_ty);
            try emitMemcpyBytes(emitter, state, res_slot, res_align, sret_slot.?, res_align, r_lay.size_bytes);
        } else if (!is_void) {
            const rv_s = try std.fmt.allocPrint(emitter.allocator, "%_cf_rv_{d}", .{t_id});
            defer emitter.allocator.free(rv_s);
            const unpacked = try emitCoerceAbiToValue(emitter, state, res_ty, ret_decl.bare_ty, rv_s);
            defer emitter.allocator.free(unpacked);
            try emitStoreValueToPtr(emitter, state, res_ty, unpacked, res_slot, res_align, 0, 0, 0);
        }
        const discr_s = try emitReadSumDiscriminantFromPtr(emitter, state, res_ty, res_slot, res_align);
        defer emitter.allocator.free(discr_s);
        try state.print(
            "  %_cf_ie_{d} = icmp ne i32 {s}, 0\n" ++
                "  br i1 %_cf_ie_{d}, label %{s}, label %{s}\n",
            .{ t_id, discr_s, t_id, err_label, done_hole_label },
        );
    }
}

/// Emits streaming `@fmt_write(out, fmt_args) -> unit!FmtError` in LLVM IR.
fn emitFmtWriteOpLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    dst_raw: u32,
    inst: mir.MirInst,
    args: []const u32,
) !void {
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();
    const res_ty = try unwrapTransparentType(emitter, inst.type_id);
    const res_lay = try emitter.resolver.resolveType(res_ty);
    const res_align = @max(res_lay.alignBytes(), 1);
    const res_slot = try state.allocEntryBytes(@max(res_lay.size_bytes, 1), res_align);
    defer emitter.allocator.free(res_slot);
    try emitMemsetZero(emitter, state, res_slot, res_lay.size_bytes, res_align);
    try emitWriteSumDiscriminantToPtr(emitter, state, res_ty, res_slot, res_align, 0);

    if (args.len >= 2) {
        const writer_ref_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(args[0])).type_id);
        const writer_ty = try unwrapTransparentType(emitter, TypeId.fromInt(emitter.input.pool.getNode(writer_ref_ty).lhs));
        const ctx_fld_opt = try emitter.resolver.getFieldByDeclOrdinal(writer_ty, 0);
        const ctx_off: u64 = if (ctx_fld_opt) |cf| cf.byte_offset else 0;
        if (try emitter.resolver.getFieldByDeclOrdinal(writer_ty, 1)) |wfn_fld| {
            const wfn_off: u64 = wfn_fld.byte_offset;
            const write_fn_ty = wfn_fld.field_ty;
            const idx_slot = try state.allocEntryBytes(ptr_bytes, ptr_bytes);
            defer emitter.allocator.free(idx_slot);
            const tmp_id = state.nextTmp();
            const done_lbl = try std.fmt.allocPrint(emitter.allocator, "_fwo_done_{d}", .{tmp_id});
            defer emitter.allocator.free(done_lbl);
            const w_ptr_s = try std.fmt.allocPrint(emitter.allocator, "%_v_{d}", .{args[0]});
            defer emitter.allocator.free(w_ptr_s);
            const ctx_ssa = try std.fmt.allocPrint(emitter.allocator, "%_fwo_ctx_{d}", .{tmp_id});
            defer emitter.allocator.free(ctx_ssa);
            const wfn_ssa = try std.fmt.allocPrint(emitter.allocator, "%_fwo_wfn_{d}", .{tmp_id});
            defer emitter.allocator.free(wfn_ssa);

            try state.print(
                "  store {s} 0, ptr {s}, align {d}\n" ++
                    "  %_fwo_ctxp_{d} = getelementptr inbounds i8, ptr %_v_{d}, {s} {d}\n" ++
                    "  %_fwo_ctx_{d} = load ptr, ptr %_fwo_ctxp_{d}, align {d}\n" ++
                    "  %_fwo_wfnp_{d} = getelementptr inbounds i8, ptr %_v_{d}, {s} {d}\n" ++
                    "  %_fwo_wfn_{d} = load ptr, ptr %_fwo_wfnp_{d}, align {d}\n" ++
                    "  %_fwo_pp_{d} = extractvalue {{ ptr, {s}, ptr, {s} }} %_v_{d}, 0\n" ++
                    "  %_fwo_pl_{d} = extractvalue {{ ptr, {s}, ptr, {s} }} %_v_{d}, 1\n" ++
                    "  %_fwo_ap_{d} = extractvalue {{ ptr, {s}, ptr, {s} }} %_v_{d}, 2\n",
                .{
                    ptr_int,   idx_slot,  ptr_bytes,
                    tmp_id,    args[0],   ptr_int,
                    ctx_off,   tmp_id,    tmp_id,
                    ptr_bytes, tmp_id,    args[0],
                    ptr_int,   wfn_off,   tmp_id,
                    tmp_id,    ptr_bytes, tmp_id,
                    ptr_int,   ptr_int,   args[1],
                    tmp_id,    ptr_int,   ptr_int,
                    args[1],   tmp_id,    ptr_int,
                    ptr_int,   args[1],
                },
            );
            try state.print(
                "  %_fwo_al_{d} = extractvalue {{ ptr, {s}, ptr, {s} }} %_v_{d}, 3\n" ++
                    "  br label %_fwo_lp_{d}\n" ++
                    "_fwo_lp_{d}:\n" ++
                    "  %_fwo_i_{d} = load {s}, ptr {s}, align {d}\n" ++
                    "  %_fwo_lt_{d} = icmp ult {s} %_fwo_i_{d}, %_fwo_pl_{d}\n" ++
                    "  br i1 %_fwo_lt_{d}, label %_fwo_bd_{d}, label %{s}\n" ++
                    "_fwo_bd_{d}:\n" ++
                    "  %_fwo_pep_{d} = getelementptr inbounds {{ ptr, {s} }}, ptr %_fwo_pp_{d}, {s} %_fwo_i_{d}\n",
                .{
                    tmp_id,   ptr_int,   ptr_int, args[1],
                    tmp_id,   tmp_id,    tmp_id,  ptr_int,
                    idx_slot, ptr_bytes, tmp_id,  ptr_int,
                    tmp_id,   tmp_id,    tmp_id,  tmp_id,
                    done_lbl, tmp_id,    tmp_id,  ptr_int,
                    tmp_id,   ptr_int,   tmp_id,
                },
            );
            try state.print(
                "  %_fwo_pc_{d} = load {{ ptr, {s} }}, ptr %_fwo_pep_{d}, align {d}\n" ++
                    "  %_fwo_pcp_{d} = extractvalue {{ ptr, {s} }} %_fwo_pc_{d}, 0\n" ++
                    "  %_fwo_pcl_{d} = extractvalue {{ ptr, {s} }} %_fwo_pc_{d}, 1\n" ++
                    "  %_fwo_pnz_{d} = icmp ne {s} %_fwo_pcl_{d}, 0\n" ++
                    "  br i1 %_fwo_pnz_{d}, label %_fwo_wp_{d}, label %_fwo_ah_{d}\n" ++
                    "_fwo_wp_{d}:\n",
                .{
                    tmp_id,  ptr_int, tmp_id, ptr_bytes,
                    tmp_id,  ptr_int, tmp_id, tmp_id,
                    ptr_int, tmp_id,  tmp_id, ptr_int,
                    tmp_id,  tmp_id,  tmp_id, tmp_id,
                    tmp_id,
                },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_wp_{d}", .{tmp_id}));
            const pcp_s = try std.fmt.allocPrint(emitter.allocator, "%_fwo_pcp_{d}", .{tmp_id});
            defer emitter.allocator.free(pcp_s);
            const pcl_s = try std.fmt.allocPrint(emitter.allocator, "%_fwo_pcl_{d}", .{tmp_id});
            defer emitter.allocator.free(pcl_s);
            try emitInvokeWriteFnChunkLlvm(
                emitter,
                state,
                ctx_ssa,
                wfn_ssa,
                write_fn_ty,
                pcp_s,
                pcl_s,
                res_slot,
                res_ty,
                res_align,
                done_lbl,
            );
            try state.print("  br label %_fwo_ah_{d}\n_fwo_ah_{d}:\n", .{ tmp_id, tmp_id });
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_ah_{d}", .{tmp_id}));

            const arg_stride: u64 = std.mem.alignForward(u64, 2 * @as(u64, ptr_bytes) + 8, ptr_bytes);
            const next_lbl = try std.fmt.allocPrint(emitter.allocator, "_fwo_nx_{d}", .{tmp_id});
            defer emitter.allocator.free(next_lbl);
            try state.print(
                "  %_fwo_ha_{d} = icmp ult {s} %_fwo_i_{d}, %_fwo_al_{d}\n" ++
                    "  br i1 %_fwo_ha_{d}, label %_fwo_do_a_{d}, label %{s}\n" ++
                    "_fwo_do_a_{d}:\n" ++
                    "  %_fwo_abo_{d} = mul {s} %_fwo_i_{d}, {d}\n" ++
                    "  %_fwo_aep_{d} = getelementptr inbounds i8, ptr %_fwo_ap_{d}, {s} %_fwo_abo_{d}\n" ++
                    "  %_fwo_ad_{d} = load ptr, ptr %_fwo_aep_{d}, align {d}\n" ++
                    "  %_fwo_afp_{d} = getelementptr inbounds i8, ptr %_fwo_aep_{d}, {s} {d}\n" ++
                    "  %_fwo_afn_{d} = load ptr, ptr %_fwo_afp_{d}, align {d}\n",
                .{
                    tmp_id, ptr_int,   tmp_id,    tmp_id,
                    tmp_id, tmp_id,    next_lbl,  tmp_id,
                    tmp_id, ptr_int,   tmp_id,    arg_stride,
                    tmp_id, tmp_id,    ptr_int,   tmp_id,
                    tmp_id, tmp_id,    ptr_bytes, tmp_id,
                    tmp_id, ptr_int,   ptr_bytes, tmp_id,
                    tmp_id, ptr_bytes,
                },
            );
            try state.print(
                "  %_fwo_asp_{d} = getelementptr inbounds i8, ptr %_fwo_aep_{d}, {s} {d}\n" ++
                    "  %_fwo_asv_{d} = load {{ i32, i16, i16 }}, ptr %_fwo_asp_{d}, align 2\n" ++
                    "  %_fwo_slo_{d} = extractvalue {{ i32, i16, i16 }} %_fwo_asv_{d}, 0\n" ++
                    "  %_fwo_sw_{d} = extractvalue {{ i32, i16, i16 }} %_fwo_asv_{d}, 1\n" ++
                    "  %_fwo_sp_{d} = extractvalue {{ i32, i16, i16 }} %_fwo_asv_{d}, 2\n" ++
                    "  %_fwo_vb1_{d} = lshr i32 %_fwo_slo_{d}, 27\n" ++
                    "  %_fwo_vb_{d} = and i32 %_fwo_vb1_{d}, 15\n" ++
                    "  %_fwo_de_{d} = lshr i32 %_fwo_slo_{d}, 31\n",
                .{
                    tmp_id, tmp_id, ptr_int, 2 * ptr_bytes,
                    tmp_id, tmp_id, tmp_id,  tmp_id,
                    tmp_id, tmp_id, tmp_id,  tmp_id,
                    tmp_id, tmp_id, tmp_id,  tmp_id,
                    tmp_id, tmp_id,
                },
            );
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_do_a_{d}", .{tmp_id}));
            const ad_ssa = try std.fmt.allocPrint(emitter.allocator, "%_fwo_ad_{d}", .{tmp_id});
            defer emitter.allocator.free(ad_ssa);
            const asv_ssa = try std.fmt.allocPrint(emitter.allocator, "%_fwo_asv_{d}", .{tmp_id});
            defer emitter.allocator.free(asv_ssa);

            if (!emitter.cfg.target.isFreestanding()) {
                for (emitter.fmt_type_list.items) |raw_cand_ty| {
                    const cand_ty = try unwrapTransparentType(emitter, raw_cand_ty);
                    const disp_b = lookupCustomFmtBodyIndexLlvm(emitter, cand_ty, false);
                    const dbg_b = lookupCustomFmtBodyIndexLlvm(emitter, cand_ty, true);
                    if (disp_b == null and dbg_b == null) continue;

                    if (disp_b) |db_idx| {
                        const ct_id = state.nextTmp();
                        try state.print(
                            "  %_fwo_mfn_{d} = icmp eq ptr %_fwo_afn_{d}, @_cx_fmt_ty_{d}\n" ++
                                "  %_fwo_v0_{d} = icmp eq i32 %_fwo_vb_{d}, 0\n" ++
                                "  %_fwo_d0_{d} = icmp eq i32 %_fwo_de_{d}, 0\n" ++
                                "  %_fwo_c1_{d} = and i1 %_fwo_mfn_{d}, %_fwo_v0_{d}\n" ++
                                "  %_fwo_cd_{d} = and i1 %_fwo_c1_{d}, %_fwo_d0_{d}\n" ++
                                "  br i1 %_fwo_cd_{d}, label %_fwo_cd_do_{d}, label %_fwo_cd_nx_{d}\n" ++
                                "_fwo_cd_do_{d}:\n",
                            .{
                                ct_id,  tmp_id, cand_ty.toU32(),
                                ct_id,  tmp_id, ct_id,
                                tmp_id, ct_id,  ct_id,
                                ct_id,  ct_id,  ct_id,
                                ct_id,  ct_id,  ct_id,
                                ct_id,  ct_id,
                            },
                        );
                        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_cd_do_{d}", .{ct_id}));
                        try emitInvokeCustomFmtBodyLlvm(
                            emitter,
                            state,
                            db_idx,
                            cand_ty,
                            ad_ssa,
                            w_ptr_s,
                            asv_ssa,
                            res_slot,
                            res_ty,
                            res_align,
                            done_lbl,
                            next_lbl,
                        );
                        try state.print("_fwo_cd_nx_{d}:\n", .{ct_id});
                        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_cd_nx_{d}", .{ct_id}));
                    }
                    if (dbg_b) |gb_idx| {
                        const ct_id = state.nextTmp();
                        try state.print(
                            "  %_fwo_mfn_{d} = icmp eq ptr %_fwo_afn_{d}, @_cx_fmt_ty_{d}\n" ++
                                "  %_fwo_v1_{d} = icmp eq i32 %_fwo_vb_{d}, 1\n" ++
                                "  %_fwo_d1_{d} = icmp ne i32 %_fwo_de_{d}, 0\n" ++
                                "  %_fwo_isd_{d} = or i1 %_fwo_v1_{d}, %_fwo_d1_{d}\n" ++
                                "  %_fwo_cg_{d} = and i1 %_fwo_mfn_{d}, %_fwo_isd_{d}\n" ++
                                "  br i1 %_fwo_cg_{d}, label %_fwo_cg_do_{d}, label %_fwo_cg_nx_{d}\n" ++
                                "_fwo_cg_do_{d}:\n",
                            .{
                                ct_id,  tmp_id, cand_ty.toU32(),
                                ct_id,  tmp_id, ct_id,
                                tmp_id, ct_id,  ct_id,
                                ct_id,  ct_id,  ct_id,
                                ct_id,  ct_id,  ct_id,
                                ct_id,  ct_id,
                            },
                        );
                        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_cg_do_{d}", .{ct_id}));
                        try emitInvokeCustomFmtBodyLlvm(
                            emitter,
                            state,
                            gb_idx,
                            cand_ty,
                            ad_ssa,
                            w_ptr_s,
                            asv_ssa,
                            res_slot,
                            res_ty,
                            res_align,
                            done_lbl,
                            next_lbl,
                        );
                        try state.print("_fwo_cg_nx_{d}:\n", .{ct_id});
                        state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_cg_nx_{d}", .{ct_id}));
                    }
                }

                // Fallback: format into `{ ptr, i64, i64 }` scratch buffer via `%_fwo_afn` and stream:
                const hb_slot = try state.allocEntryBytes(24, 8);
                defer emitter.allocator.free(hb_slot);
                if (!emitter.declared_externs.contains("free")) {
                    try emitter.requireIntrinsicDecl("declare void @free(ptr) nounwind");
                }
                try state.print(
                    "  %_fwo_hfn_{d} = icmp ne ptr %_fwo_afn_{d}, null\n" ++
                        "  br i1 %_fwo_hfn_{d}, label %_fwo_fb_{d}, label %{s}\n" ++
                        "_fwo_fb_{d}:\n" ++
                        "  store {{ ptr, i64, i64 }} zeroinitializer, ptr {s}, align 8\n" ++
                        "  %_fwo_sw32_{d} = zext i16 %_fwo_sw_{d} to i32\n" ++
                        "  %_fwo_sp32_{d} = zext i16 %_fwo_sp_{d} to i32\n" ++
                        "  %_fwo_spsh_{d} = shl i32 %_fwo_sp32_{d}, 16\n" ++
                        "  %_fwo_shi_{d} = or i32 %_fwo_sw32_{d}, %_fwo_spsh_{d}\n",
                    .{
                        tmp_id,   tmp_id,
                        tmp_id,   tmp_id,
                        next_lbl, tmp_id,
                        hb_slot,  tmp_id,
                        tmp_id,   tmp_id,
                        tmp_id,   tmp_id,
                        tmp_id,   tmp_id,
                        tmp_id,   tmp_id,
                    },
                );
                try state.print(
                    "  call void %_fwo_afn_{d}(ptr {s}, ptr %_fwo_ad_{d}, i32 %_fwo_slo_{d}, i32 %_fwo_shi_{d})\n" ++
                        "  %_fwo_hbd_{d} = load ptr, ptr {s}, align 8\n" ++
                        "  %_fwo_hblp_{d} = getelementptr inbounds {{ ptr, i64, i64 }}, ptr {s}, i32 0, i32 1\n" ++
                        "  %_fwo_hbl64_{d} = load i64, ptr %_fwo_hblp_{d}, align 8\n" ++
                        "  %_fwo_hbnz_{d} = icmp ne i64 %_fwo_hbl64_{d}, 0\n" ++
                        "  br i1 %_fwo_hbnz_{d}, label %_fwo_hbw_{d}, label %_fwo_hbf_{d}\n" ++
                        "_fwo_hbw_{d}:\n",
                    .{
                        tmp_id, hb_slot, tmp_id, tmp_id,  tmp_id,
                        tmp_id, hb_slot, tmp_id, hb_slot, tmp_id,
                        tmp_id, tmp_id,  tmp_id, tmp_id,  tmp_id,
                        tmp_id, tmp_id,
                    },
                );
                state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_fwo_hbw_{d}", .{tmp_id}));
                const hbl_pt = if (ptr_bytes == 4) blk_tr: {
                    try state.print("  %_fwo_hbl32_{d} = trunc i64 %_fwo_hbl64_{d} to i32\n", .{ tmp_id, tmp_id });
                    break :blk_tr try std.fmt.allocPrint(emitter.allocator, "%_fwo_hbl32_{d}", .{tmp_id});
                } else try std.fmt.allocPrint(emitter.allocator, "%_fwo_hbl64_{d}", .{tmp_id});
                defer emitter.allocator.free(hbl_pt);
                const hbd_s = try std.fmt.allocPrint(emitter.allocator, "%_fwo_hbd_{d}", .{tmp_id});
                defer emitter.allocator.free(hbd_s);
                const free_err_lbl = try std.fmt.allocPrint(emitter.allocator, "_fwo_hbfe_{d}", .{tmp_id});
                defer emitter.allocator.free(free_err_lbl);
                try emitInvokeWriteFnChunkLlvm(
                    emitter,
                    state,
                    ctx_ssa,
                    wfn_ssa,
                    write_fn_ty,
                    hbd_s,
                    hbl_pt,
                    res_slot,
                    res_ty,
                    res_align,
                    free_err_lbl,
                );
                try state.print(
                    "  br label %_fwo_hbf_{d}\n" ++
                        "_fwo_hbfe_{d}:\n" ++
                        "  call void @free(ptr %_fwo_hbd_{d})\n" ++
                        "  br label %{s}\n" ++
                        "_fwo_hbf_{d}:\n" ++
                        "  call void @free(ptr %_fwo_hbd_{d})\n" ++
                        "  br label %{s}\n",
                    .{ tmp_id, tmp_id, tmp_id, done_lbl, tmp_id, tmp_id, next_lbl },
                );
            } else {
                try state.print("  br label %{s}\n", .{next_lbl});
            }

            try state.print(
                "{s}:\n" ++
                    "  %_fwo_ni_{d} = add {s} %_fwo_i_{d}, 1\n" ++
                    "  store {s} %_fwo_ni_{d}, ptr {s}, align {d}\n" ++
                    "  br label %_fwo_lp_{d}\n" ++
                    "{s}:\n",
                .{ next_lbl, tmp_id, ptr_int, tmp_id, ptr_int, tmp_id, idx_slot, ptr_bytes, tmp_id, done_lbl },
            );
            state.setLabelOwned(try emitter.allocator.dupe(u8, done_lbl));
        }
    }

    const loaded = try emitLoadValueFromPtr(emitter, state, res_ty, res_slot, res_align, null, 0, 0, 0);
    defer emitter.allocator.free(loaded);
    const val_ty = try formatLlvmValueType(emitter, res_ty);
    defer emitter.allocator.free(val_ty);
    try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, loaded, val_ty, loaded });
}

/// Emits `STD-01` (`MirIntrinsicKind` `52..109`) operations in LLVM IR.
fn emitStd01IntrinsicOpLlvm(
    emitter: *LlvmModuleEmitter,
    state: *BodyEmitState,
    body: *const MirBody,
    dst_raw: u32,
    kind: mir.MirIntrinsicKind,
    inst: mir.MirInst,
    args: []const u32,
) !void {
    const ptr_int = ptrIntType(emitter);
    const ptr_bytes: u32 = emitter.cfg.target.ptrBytes();

    switch (kind) {
        .implements => {
            const is_impl = evalImplementsStaticLlvm(
                emitter,
                TypeId.fromInt(inst.operands.lhs),
                TypeId.fromInt(inst.operands.rhs),
            );
            try state.print("  %_v_{d} = or i1 false, {s}\n", .{ dst_raw, if (is_impl) "true" else "false" });
        },
        .int_min, .int_max, .int_bits => {
            const target_ty = emitter.input.pool.unwrapUnderlyingType(TypeId.fromInt(inst.operands.lhs));
            const info = resolveIntegerInfo(emitter, target_ty) orelse IntScalarInfo{ .bits = 32, .is_signed = false };
            const dst_info = resolveIntegerInfo(emitter, inst.type_id) orelse info;
            if (kind == .int_bits) {
                try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, info.bits });
            } else if (kind == .int_min) {
                const min_i128: i128 = if (!info.is_signed)
                    0
                else if (info.bits >= 128)
                    std.math.minInt(i128)
                else
                    -(@as(i128, 1) << @intCast(info.bits - 1));
                try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, min_i128 });
            } else {
                if (!info.is_signed) {
                    const max_u128: u128 = if (info.bits >= 128)
                        std.math.maxInt(u128)
                    else
                        (@as(u128, 1) << @intCast(info.bits)) - 1;
                    try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, @as(i128, @bitCast(max_u128)) });
                } else {
                    const max_i128: i128 = if (info.bits >= 128)
                        std.math.maxInt(i128)
                    else
                        (@as(i128, 1) << @intCast(info.bits - 1)) - 1;
                    try state.print("  %_v_{d} = add i{d} 0, {d}\n", .{ dst_raw, dst_info.bits, max_i128 });
                }
            }
        },
        .scalar_clz, .scalar_ctz, .scalar_popcnt => {
            if (args.len < 1) {
                try state.print("  %_v_{d} = add i32 0, 0\n", .{dst_raw});
                return;
            }
            const val_ty = body.getInst(MirValueId.fromInt(args[0])).type_id;
            const info = resolveIntegerInfo(emitter, val_ty).?;
            const t_id = state.nextTmp();
            if (kind == .scalar_clz or kind == .scalar_ctz) {
                const intr_n = if (kind == .scalar_clz) "ctlz" else "cttz";
                const decl_s = try std.fmt.allocPrint(
                    emitter.allocator,
                    "declare i{d} @llvm.{s}.i{d}(i{d}, i1 immarg)",
                    .{ info.bits, intr_n, info.bits, info.bits },
                );
                defer emitter.allocator.free(decl_s);
                try emitter.requireIntrinsicDecl(decl_s);
                try state.print(
                    "  %_bit_r_{d} = call i{d} @llvm.{s}.i{d}(i{d} %_v_{d}, i1 false)\n",
                    .{ t_id, info.bits, intr_n, info.bits, info.bits, args[0] },
                );
            } else {
                const decl_s = try std.fmt.allocPrint(
                    emitter.allocator,
                    "declare i{d} @llvm.ctpop.i{d}(i{d})",
                    .{ info.bits, info.bits, info.bits },
                );
                defer emitter.allocator.free(decl_s);
                try emitter.requireIntrinsicDecl(decl_s);
                try state.print(
                    "  %_bit_r_{d} = call i{d} @llvm.ctpop.i{d}(i{d} %_v_{d})\n",
                    .{ t_id, info.bits, info.bits, info.bits, args[0] },
                );
            }
            if (info.bits == 32) {
                try state.print("  %_v_{d} = add i32 %_bit_r_{d}, 0\n", .{ dst_raw, t_id });
            } else if (info.bits < 32) {
                try state.print("  %_v_{d} = zext i{d} %_bit_r_{d} to i32\n", .{ dst_raw, info.bits, t_id });
            } else {
                try state.print("  %_v_{d} = trunc i{d} %_bit_r_{d} to i32\n", .{ dst_raw, info.bits, t_id });
            }
        },
        .scalar_bswap => {
            if (args.len < 1) return;
            const info = resolveIntegerInfo(emitter, inst.type_id).?;
            if (info.bits <= 8) {
                try state.print("  %_v_{d} = add i8 %_v_{d}, 0\n", .{ dst_raw, args[0] });
            } else {
                const decl_s = try std.fmt.allocPrint(
                    emitter.allocator,
                    "declare i{d} @llvm.bswap.i{d}(i{d})",
                    .{ info.bits, info.bits, info.bits },
                );
                defer emitter.allocator.free(decl_s);
                try emitter.requireIntrinsicDecl(decl_s);
                try state.print(
                    "  %_v_{d} = call i{d} @llvm.bswap.i{d}(i{d} %_v_{d})\n",
                    .{ dst_raw, info.bits, info.bits, info.bits, args[0] },
                );
            }
        },
        .scalar_rotl, .scalar_rotr => {
            if (args.len < 2) return;
            const info = resolveIntegerInfo(emitter, inst.type_id).?;
            const sh_info = resolveIntegerInfo(emitter, body.getInst(MirValueId.fromInt(args[1])).type_id).?;
            const intr_n = if (kind == .scalar_rotl) "fshl" else "fshr";
            const decl_s = try std.fmt.allocPrint(
                emitter.allocator,
                "declare i{d} @llvm.{s}.i{d}(i{d}, i{d}, i{d})",
                .{ info.bits, intr_n, info.bits, info.bits, info.bits, info.bits },
            );
            defer emitter.allocator.free(decl_s);
            try emitter.requireIntrinsicDecl(decl_s);
            const t_id = state.nextTmp();
            if (sh_info.bits == info.bits) {
                try state.print("  %_rot_a_{d} = add i{d} %_v_{d}, 0\n", .{ t_id, info.bits, args[1] });
            } else if (sh_info.bits < info.bits) {
                try state.print(
                    "  %_rot_a_{d} = zext i{d} %_v_{d} to i{d}\n",
                    .{ t_id, sh_info.bits, args[1], info.bits },
                );
            } else {
                try state.print(
                    "  %_rot_a_{d} = trunc i{d} %_v_{d} to i{d}\n",
                    .{ t_id, sh_info.bits, args[1], info.bits },
                );
            }
            try state.print(
                "  %_v_{d} = call i{d} @llvm.{s}.i{d}(i{d} %_v_{d}, i{d} %_v_{d}, i{d} %_rot_a_{d})\n",
                .{ dst_raw, info.bits, intr_n, info.bits, info.bits, args[0], info.bits, args[0], info.bits, t_id },
            );
        },
        .ptr_is_null => {
            if (args.len < 1) {
                try state.print("  %_v_{d} = or i1 false, true\n", .{dst_raw});
                return;
            }
            try state.print("  %_v_{d} = icmp eq ptr %_v_{d}, null\n", .{ dst_raw, args[0] });
        },
        .ptr_offset => {
            if (args.len < 3) {
                try state.print("  %_v_{d} = select i1 true, ptr null, ptr null\n", .{dst_raw});
                return;
            }
            const ptr_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(args[0])).type_id);
            const pointee_ty = try unwrapTransparentType(emitter, TypeId.fromInt(emitter.input.pool.getNode(ptr_ty).lhs));
            const stride: u64 = if (pointee_ty == .opaque_ty)
                1
            else
                (try emitter.resolver.resolveType(pointee_ty)).size_bytes;
            const ptr_bits: u16 = @intCast(ptr_bytes * 8);
            const d_info = resolveIntegerInfo(emitter, body.getInst(MirValueId.fromInt(args[1])).type_id) orelse
                IntScalarInfo{ .bits = ptr_bits, .is_signed = false };
            const t_id = state.nextTmp();
            if (d_info.bits == ptr_bits) {
                try state.print("  %_po_d_{d} = add {s} %_v_{d}, 0\n", .{ t_id, ptr_int, args[1] });
            } else if (d_info.bits < ptr_bits) {
                const ext_op = if (d_info.is_signed) "sext" else "zext";
                try state.print("  %_po_d_{d} = {s} i{d} %_v_{d} to {s}\n", .{ t_id, ext_op, d_info.bits, args[1], ptr_int });
            } else {
                try state.print("  %_po_d_{d} = trunc i{d} %_v_{d} to {s}\n", .{ t_id, d_info.bits, args[1], ptr_int });
            }
            const mode_val = extractConstU32Llvm(body, args[2]) orelse 0;
            try state.print("  %_po_b_{d} = mul {s} %_po_d_{d}, {d}\n", .{ t_id, ptr_int, t_id, stride });
            if (mode_val == 1) {
                try state.print("  %_po_s_{d} = sub {s} 0, %_po_b_{d}\n", .{ t_id, ptr_int, t_id });
                try state.print("  %_v_{d} = getelementptr i8, ptr %_v_{d}, {s} %_po_s_{d}\n", .{ dst_raw, args[0], ptr_int, t_id });
            } else {
                try state.print("  %_v_{d} = getelementptr i8, ptr %_v_{d}, {s} %_po_b_{d}\n", .{ dst_raw, args[0], ptr_int, t_id });
            }
        },
        .slice_split_at => {
            if (args.len < 2) return;
            const tup_ty = try unwrapTransparentType(emitter, inst.type_id);
            const tup_lay = try emitter.resolver.resolveType(tup_ty);
            const tup_elems = emitter.input.pool.getTupleElements(tup_ty);
            const half_ref_ty = try unwrapTransparentType(emitter, TypeId.fromInt(tup_elems[0]));
            const sl_ty = try unwrapTransparentType(emitter, TypeId.fromInt(emitter.input.pool.getNode(half_ref_ty).lhs));
            const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(emitter.input.pool.getNode(sl_ty).lhs));
            const elem_lay = try emitter.resolver.resolveType(elem_ty);
            const elem_align = @max(elem_lay.alignBytes(), 1);
            const tup_slot = try state.allocEntryBytes(tup_lay.size_bytes, tup_lay.alignBytes());
            defer emitter.allocator.free(tup_slot);
            const src_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(args[0])).type_id);
            const t_id = state.nextTmp();
            if (emitter.input.pool.isSliceRefType(src_ty)) {
                try state.print(
                    "  %_ssa_f_{d} = select i1 true, {{ ptr, {s} }} %_v_{d}, {{ ptr, {s} }} %_v_{d}\n",
                    .{ t_id, ptr_int, args[0], ptr_int, args[0] },
                );
            } else {
                try state.print(
                    "  %_ssa_f_{d} = load {{ ptr, {s} }}, ptr %_v_{d}, align {d}\n",
                    .{ t_id, ptr_int, args[0], ptr_bytes },
                );
            }
            try state.print(
                "  %_ssa_p_{d} = extractvalue {{ ptr, {s} }} %_ssa_f_{d}, 0\n" ++
                    "  %_ssa_l_{d} = extractvalue {{ ptr, {s} }} %_ssa_f_{d}, 1\n" ++
                    "  %_ssa_oob_{d} = icmp ugt {s} %_v_{d}, %_ssa_l_{d}\n" ++
                    "  br i1 %_ssa_oob_{d}, label %_ssa_tr_{d}, label %_ssa_ok_{d}\n" ++
                    "_ssa_tr_{d}:\n" ++
                    "  call void @_cx_rt_trap(i32 2)\n" ++
                    "  unreachable\n" ++
                    "_ssa_ok_{d}:\n" ++
                    "  %_ssa_rl_{d} = sub {s} %_ssa_l_{d}, %_v_{d}\n" ++
                    "  %_ssa_mb_{d} = mul {s} %_v_{d}, {d}\n",
                .{
                    t_id,    ptr_int, t_id,                  t_id,
                    ptr_int, t_id,    t_id,                  ptr_int,
                    args[1], t_id,    t_id,                  t_id,
                    t_id,    t_id,    t_id,                  t_id,
                    ptr_int, t_id,    args[1],               t_id,
                    ptr_int, args[1], elem_lay.stride_bytes,
                },
            );
            try state.print(
                "  %_ssa_rp0_{d} = getelementptr inbounds i8, ptr %_ssa_p_{d}, {s} %_ssa_mb_{d}\n" ++
                    "  %_ssa_rz_{d} = icmp eq {s} %_ssa_rl_{d}, 0\n" ++
                    "  %_ssa_pn_{d} = icmp eq ptr %_ssa_p_{d}, null\n" ++
                    "  %_ssa_rd_{d} = and i1 %_ssa_rz_{d}, %_ssa_pn_{d}\n" ++
                    "  %_ssa_rp_{d} = select i1 %_ssa_rd_{d}, ptr inttoptr ({s} {d} to ptr), ptr %_ssa_rp0_{d}\n" ++
                    "  %_ssa_lp_{d} = select i1 %_ssa_pn_{d}, ptr inttoptr ({s} {d} to ptr), ptr %_ssa_p_{d}\n",
                .{
                    t_id,       t_id,    ptr_int, t_id,
                    t_id,       ptr_int, t_id,    t_id,
                    t_id,       t_id,    t_id,    t_id,
                    t_id,       t_id,    ptr_int, elem_align,
                    t_id,       t_id,    t_id,    ptr_int,
                    elem_align, t_id,
                },
            );
            try state.print(
                "  %_ssa_lv0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %_ssa_lp_{d}, 0\n" ++
                    "  %_ssa_lv_{d} = insertvalue {{ ptr, {s} }} %_ssa_lv0_{d}, {s} %_v_{d}, 1\n" ++
                    "  %_ssa_rv0_{d} = insertvalue {{ ptr, {s} }} zeroinitializer, ptr %_ssa_rp_{d}, 0\n" ++
                    "  %_ssa_rv_{d} = insertvalue {{ ptr, {s} }} %_ssa_rv0_{d}, {s} %_ssa_rl_{d}, 1\n",
                .{
                    t_id,    ptr_int, t_id,    t_id,
                    ptr_int, t_id,    ptr_int, args[1],
                    t_id,    ptr_int, t_id,    t_id,
                    ptr_int, t_id,    ptr_int, t_id,
                },
            );
            if (emitter.input.pool.isSliceRefType(half_ref_ty)) {
                try state.print(
                    "  store {{ ptr, {s} }} %_ssa_lv_{d}, ptr {s}, align {d}\n" ++
                        "  %_ssa_tf1_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                        "  store {{ ptr, {s} }} %_ssa_rv_{d}, ptr %_ssa_tf1_{d}, align {d}\n",
                    .{
                        ptr_int, t_id,     tup_slot, ptr_bytes,
                        t_id,    tup_slot, ptr_int,  2 * ptr_bytes,
                        ptr_int, t_id,     t_id,     ptr_bytes,
                    },
                );
            } else {
                const left_slot = try state.allocEntryBytes(2 * ptr_bytes, ptr_bytes);
                defer emitter.allocator.free(left_slot);
                const right_slot = try state.allocEntryBytes(2 * ptr_bytes, ptr_bytes);
                defer emitter.allocator.free(right_slot);
                try state.print(
                    "  store {{ ptr, {s} }} %_ssa_lv_{d}, ptr {s}, align {d}\n" ++
                        "  store {{ ptr, {s} }} %_ssa_rv_{d}, ptr {s}, align {d}\n" ++
                        "  store ptr {s}, ptr {s}, align {d}\n" ++
                        "  %_ssa_tf1_{d} = getelementptr inbounds i8, ptr {s}, {s} {d}\n" ++
                        "  store ptr {s}, ptr %_ssa_tf1_{d}, align {d}\n",
                    .{
                        ptr_int,   t_id,      left_slot,  ptr_bytes,
                        ptr_int,   t_id,      right_slot, ptr_bytes,
                        left_slot, tup_slot,  ptr_bytes,  t_id,
                        tup_slot,  ptr_int,   ptr_bytes,  right_slot,
                        t_id,      ptr_bytes,
                    },
                );
            }
            state.setLabelOwned(try std.fmt.allocPrint(emitter.allocator, "_ssa_ok_{d}", .{t_id}));
            const loaded = try emitLoadValueFromPtr(emitter, state, tup_ty, tup_slot, tup_lay.alignBytes(), null, 0, 0, 0);
            defer emitter.allocator.free(loaded);
            const val_ty = try formatLlvmValueType(emitter, tup_ty);
            defer emitter.allocator.free(val_ty);
            try state.print("  %_v_{d} = select i1 true, {s} {s}, {s} {s}\n", .{ dst_raw, val_ty, loaded, val_ty, loaded });
        },
        .slice_reverse => {
            if (args.len < 1) {
                try state.print("  %_v_{d} = add i8 0, 0\n", .{dst_raw});
                return;
            }
            const ref_ty = try unwrapTransparentType(emitter, body.getInst(MirValueId.fromInt(args[0])).type_id);
            const sl_ty = try unwrapTransparentType(emitter, TypeId.fromInt(emitter.input.pool.getNode(ref_ty).lhs));
            const elem_ty = try unwrapTransparentType(emitter, TypeId.fromInt(emitter.input.pool.getNode(sl_ty).lhs));
            const elem_lay = try emitter.resolver.resolveType(elem_ty);
            if (elem_lay.size_bytes > 0) {
                const lo_slot = try state.allocEntryBytes(ptr_bytes, ptr_bytes);
                defer emitter.allocator.free(lo_slot);
                const hi_slot = try state.allocEntryBytes(ptr_bytes, ptr_bytes);
                defer emitter.allocator.free(hi_slot);
                const sw_slot = try state.allocEntryBytes(elem_lay.size_bytes, elem_lay.alignBytes());
                defer emitter.allocator.free(sw_slot);
                const t_id = state.nextTmp();
                if (emitter.input.pool.isSliceRefType(ref_ty)) {
                    try state.print(
                        "  %_srev_f_{d} = select i1 true, {{ ptr, {s} }} %_v_{d}, {{ ptr, {s} }} %_v_{d}\n",
                        .{ t_id, ptr_int, args[0], ptr_int, args[0] },
                    );
                } else {
                    try state.print(
